INSERT OR IGNORE INTO 'article_ai_view'('id', 'article_ai_id', 'difficulty', 'from_lang', 'to_lang', 'title_from', 'title_to', 'summary_from', 'summary_to', 'optimized_html_from', 'optimized_html_to', 'cleaned_text_from', 'cleaned_text_to', 'legacy_explanation_json', 'created_at', 'updated_at') VALUES (3, 9, 'EASY', 'zh-TW', 'ja-JP', '蘇格蘭政府計畫於2026-27年發行首批公債', '蘇格蘭政府は2026–27年に初めて公債を発行する計畫', replace('- 蘇格蘭政府計畫在2026–27財政年度首次發行公債，但仍須視五月議會選舉與市場條件決定時程。\n- 發行公債可讓政府向投資人借款，資金用於基礎建設與資本支出，投資人會定期收取利息。\n- 評級機構目前給予蘇格蘭與英國相同評級，但若朝獨立方向發展，評級可能下調。\n- 政府將依市場情況決定細節，選定聯合主承銷商，強調「借得更好，不是借得更多」。','\n', char(10)), replace('- 蘇格蘭政府は2026–27財政年度に初めて公債を発行する計畫だが、5月の議會選舉や市場條件で時程が決まる。\n- 公債発行は投資家から借入れを行い、資金は基礎建設や資本支出に使われ、投資家は定期的に利息を受け取る。\n- 評級機關は現時点で蘇格蘭と英國に同じ評級を與えているが、獨立に進めば評級が下がる可能性がある。\n- 政府は市場情況に応じて詳細を決定し、聯合主承銷商を選ぶ予定で、「より良く借りること」を目標としている。','\n', char(10)), '<article><h1>蘇格蘭政府計畫於2026-27年發行首批公債</h1><figure><img src="https://ichef.bbci.co.uk/news/480/cpsprodpb/5ebf/live/24076500-87ff-11f0-be14-b712a0c48110.jpg.webp" alt="交易員在交易大廳觀察上漲下跌的股價" /><figcaption>圖片來源：Getty Images</figcaption></figure><p>蘇格蘭政府表示，已在路上準備於下一財政年度首次發行公債。首相約翰·斯溫尼指出，目標時程為2026–27年，但這仍要視五月的議會選舉結果與其他外在條件而定。</p><p>政府計畫藉由發行公債向投資人借款，投資人會定期收到利息，政府則把資金用於基礎建設和資本支出。蘇格蘭自2016年起取得發行公債的權限，但過去多依賴英國中央基金借款。</p><p>兩家國際評級機構給予蘇格蘭與英國相同的評級：穆迪為Aa3，標普為AA。評等理由包括財政管理謹慎與經濟穩定，但兩機構也警告，如果朝獨立方向發展，評級可能面臨下調風險。</p><p>公債是政府借款的一種工具，政府承諾在約定年限如五年、十年或三十年後還本，並在期間定期支付利息。在英國，政府公債稱為gilt，蘇格蘭的公債有時被戲稱為「kilts」。</p><p>斯溫尼表示，發行的具體細節會依市場情況決定，政府也會與銀行接洽，選出聯合主承銷商，以便讓下一屆政府能無縫接手。他強調，目標是「借得更好，而不是借得更多」，以提升資金運用的彈性與效率。</p><p>總的來說，若計畫順利推進，發行公債可為蘇格蘭提供新的融資來源，但選舉、獨立議題與市場條件仍會左右最終時程與評級走向。</p></article>', '<article><h1>スコットランド政府、2026–27年度に初の国債発行を目指す</h1><figure><img src="https://ichef.bbci.co.uk/news/480/cpsprodpb/5ebf/live/24076500-87ff-11f0-be14-b712a0c48110.jpg.webp" alt="取引フロアのトレーダーが株価の上下を見ている" /><figcaption>画像提供�', '', '', '', 0, 0);
INSERT OR IGNORE INTO 'article_ai_view'('id', 'article_ai_id', 'difficulty', 'from_lang', 'to_lang', 'title_from', 'title_to', 'summary_from', 'summary_to', 'optimized_html_from', 'optimized_html_to', 'cleaned_text_from', 'cleaned_text_to', 'legacy_explanation_json', 'created_at', 'updated_at') VALUES (1, 7, 'NORMAL', 'en', 'zh-TW', 'Naked mole rats'' DNA May Hold Clues to Their Long Lives', '裸鼴鼠的 DNA 可能蘊含長壽關鍵', replace('- Researchers discovered that naked mole rats have a modified DNA repair pathway that may explain their exceptional longevity and resistance to age-related diseases.\n- The protein cGAS, which in humans can interfere with DNA repair, functions differently in naked mole rats and appears to promote genomic maintenance.\n- Scientists see this rewiring of a common protein as evidence that evolution can repurpose molecular tools and hope the findings could inform future therapies for ageing.\n- Further research is needed to determine whether these changes are unique to naked mole rats and how they might translate to human health.','\n', char(10)), replace('- 研究發現裸鼴鼠擁有被改變的 DNA 修復通路，這可能解釋牠們非凡的長壽以及對年齡相關疾病的抵抗力。\n- 蛋白質 cGAS 在人類會干擾 DNA 修復，但在裸鼴鼠中具不同功能，似乎促進基因組維護。\n- 科學家認為這種對共同蛋白質的重新用途顯示演化可以改變分子工具，並希望此發現能啟發未來的老齡化療法。\n- 仍需更多研究以確認這些變化是否為裸鼴鼠特有，及其如何應用於人類健康。','\n', char(10)), replace('<article>\n<h1>Naked mole rats'' DNA could hold key to long life</h1>\n<p>9 October 2025 — Victoria Gill, Science correspondent, BBC News</p>\n<figure>\n<img src="https://ichef.bbci.co.uk/news/480/cpsprodpb/d1e4/live/bb740ed0-a4fa-11f0-b741-177e3e2c2fc7.jpg.webp" alt="Close-up of a naked mole rat being held; small pink hairless rodent with prominent front teeth and tiny eyes" />\n<figcaption>Washington Post via Getty Images</figcaption>\n</figure>\n<p>They are unusual, hairless rodents that live underground and have now revealed a genetic clue linked to their exceptional longevity.</p>\n<p>A new study of the naked mole rat shows that these animals have evolved a DNA repair mechanism that could help explain their long lives.</p>\n<p>These burrow-dwelling rodents can live for almost 40 years, making them the longest-lived rodents known to science.</p>\n<p>The findings, published in the journal Science, may also help explain why naked mole rats resist many age-related diseases.</p>\n<p>The animals are resistant to cancer, neurodegeneration and arthritis, which has driven interest in how their bodies maintain health over decades.</p>\n<p>For this study, led by a team at Tonji University in Shanghai, researchers focused on DNA repair. When DNA strands are damaged, cells use an undamaged template strand to mend breaks through coordinated repair pathways.</p>\n<p>The research concentrated on a protein involved in detecting damage and coordinating repair.</p>\n<p>When a cell senses DNA damage it produces several molecules, including a protein called cGAS. In humans, cGAS interferes with the process that stitches DNA back together.</p>\n<p>Scientists have suggested that the interfering action of human cGAS could contribute to cancer development and reduced lifespan.</p>\n<p>In naked mole rats, however, the researchers found the same protein functions differently: it promotes repair and helps maintain genomic integrity.</p>\n<figure>\n<img src="https://ichef.bbci.co.uk/news/480/cpsprodpb/608c/live/34ffa0c0-a4fb-11f0-928c-71dbb8619e94.jpg.webp" alt="Naked mole rat in an underground burrow eating a piece of corn" />\n<figcaption>Chicago Tribune via Getty Images</figcaption>\n</figure>\n<p>Professor Gabriel Balmus, who studies DNA repair and ageing at the University of Cambridge, described the discovery as exciting and likely "the tip of the iceberg" for understanding the species'' longevity.</p>\n<p>He compared cGAS to a biological Lego piece: the basic shape is sim','\n', char(10)), '', '', '', '', 0, 0);
INSERT OR IGNORE INTO 'article_ai_view'('id', 'article_ai_id', 'difficulty', 'from_lang', 'to_lang', 'title_from', 'title_to', 'summary_from', 'summary_to', 'optimized_html_from', 'optimized_html_to', 'cleaned_text_from', 'cleaned_text_to', 'legacy_explanation_json', 'created_at', 'updated_at') VALUES (2, 8, 'NORMAL', 'en', 'zh-TW', 'Conservatives’ struggle to prove they still matter', '保守黨努力證明自己仍有影響力', replace('- The Conservative party faces clear unpopularity after long government rule, leadership turnover and recent defections to Reform UK.\n- Kemi Badenoch’s leadership has not yet produced a visible improvement in public opinion; internal criticisms focus on her style and strategic direction.\n- Competition from Reform UK forces the Conservatives to choose between chasing right‑leaning voters or moving toward the centre, each with trade‑offs.\n- The upcoming party conference is a limited but crucial chance for the party to present coherent policies and show it still matters to voters, donors and activists.','\n', char(10)), replace('- 保守黨在長期執政、領導層頻繁更替以及近期多名議員倒戈至改革黨後，明顯面臨民意低迷。\n- Kemi Badenoch 上任後在民意上尚未出現明顯回升；黨內批評集中於她的風格與策略方向。\n- 改革黨的競爭迫使保守黨在爭取右傾選民或回到中間路線間抉擇，兩者都有利弊。\n- 即將到來的黨大會提供一個有限但關鍵的機會，讓黨展現具體政策與說服力，證明對選民、捐款人和支持者仍具重要性。','\n', char(10)), replace('<article>\n  <h2>The battle is on for the Conservatives to show they matter</h2>\n  <p>4 October 2025 — Laura Kuenssberg, Presenter, Sunday with Laura Kuenssberg</p>\n  <figure>\n    <img src="https://ichef.bbci.co.uk/news/480/cpsprodpb/b399/live/8c37cb40-9f67-11f0-b741-177e3e2c2fc7.png.webp" srcset="https://ichef.bbci.co.uk/news/240/cpsprodpb/b399/live/8c37cb40-9f67-11f0-b741-177e3e2c2fc7.png.webp 240w, https://ichef.bbci.co.uk/news/320/cpsprodpb/b399/live/8c37cb40-9f67-11f0-b741-177e3e2c2fc7.png.webp 320w, https://ichef.bbci.co.uk/news/480/cpsprodpb/b399/live/8c37cb40-9f67-11f0-b741-177e3e2c2fc7.png.webp 480w, https://ichef.bbci.co.uk/news/640/cpsprodpb/b399/live/8c37cb40-9f67-11f0-b741-177e3e2c2fc7.png.webp 640w" alt="Laura Kuenssberg profile image" />\n    <figcaption>Laura Kuenssberg</figcaption>\n  </figure>\n  <figure>\n    <img src="https://ichef.bbci.co.uk/news/480/cpsprodpb/d6e5/live/ba232d60-a02f-11f0-92db-77261a15b9d2.jpg.webp" srcset="https://ichef.bbci.co.uk/news/240/cpsprodpb/d6e5/live/ba232d60-a02f-11f0-92db-77261a15b9d2.jpg.webp 240w, https://ichef.bbci.co.uk/news/320/cpsprodpb/d6e5/live/ba232d60-a02f-11f0-92db-77261a15b9d2.jpg.webp 320w, https://ichef.bbci.co.uk/news/480/cpsprodpb/d6e5/live/ba232d60-a02f-11f0-92db-77261a15b9d2.jpg.webp 480w" alt="A treated image of Kemi Badenoch" />\n    <figcaption>BBC</figcaption>\n  </figure>\n  <p>When a senior Conservative told me there were reasons to hope the party could recover from an electoral rout, the immediate response elsewhere within the party was the opposite: another MP defected to Reform UK. The individual case matters far less than the pattern; over a dozen current or former Conservatives have switched allegiance in recent times. The more relevant question is whether the Conservatives still have a coherent role in British politics, and whether they can convince voters of that role.</p>\n  <p>The party’s unpopularity is obvious and deep. After being in government for 14 years and enduring rapid leadership turnover, the Conservatives were vulnerable to a severe backlash. But their standing has declined further since the recent general election, and the leadership change to Kemi Badenoch has not produced a visible bounce in public opinion. The Tories remain formally the main opposition, ','\n', char(10)), '', '', '', '', 0, 0);
INSERT OR IGNORE INTO 'ai_vocabulary_item'('id', 'article_ai_view_id', 'sort_order', 'pos', 'word_from', 'word_to', 'definition_from', 'definition_to', 'example_from', 'example_to', 'created_at', 'updated_at') VALUES (23, 3, 6, '名詞', '融資', '融資', '提供資金給需要者，常指銀行或市場提供的借款。', '資金を必要な人に提供すること。銀行や市場からの借入れを指すことが多い。', '發行公債是政府取得長期融資的一種方式。', '公債の發行は政府が長期融資を得る一つの方法だ。', 1763607808017, 1763607808017);
INSERT OR IGNORE INTO 'ai_vocabulary_item'('id', 'article_ai_view_id', 'sort_order', 'pos', 'word_from', 'word_to', 'definition_from', 'definition_to', 'example_from', 'example_to', 'created_at', 'updated_at') VALUES (24, 3, 7, '動詞', '左右', '左右', '影響或決定結果，表示某些因素會改變情況。', '結果に影響を与える、または決定すること。特定の要因が状況を変えることを指す。', '選舉結果會左右發行時程。', '選挙結果が發行時程に左右される。', 1763607808017, 1763607808017);
INSERT OR IGNORE INTO 'ai_vocabulary_item'('id', 'article_ai_view_id', 'sort_order', 'pos', 'word_from', 'word_to', 'definition_from', 'definition_to', 'example_from', 'example_to', 'created_at', 'updated_at') VALUES (1, 1, 0, 'noun', 'longevity', '長壽／壽命', 'The length of time that something or someone lives or continues to function.', '某事物或某人存活或持續運作的時間長度。', 'Naked mole rats are famous for their longevity, living almost 40 years in some cases.', '裸鼴鼠以長壽著稱，有些個體可以活將近 40 年。', 1763604216012, 1763604216012);
INSERT OR IGNORE INTO 'ai_vocabulary_item'('id', 'article_ai_view_id', 'sort_order', 'pos', 'word_from', 'word_to', 'definition_from', 'definition_to', 'example_from', 'example_to', 'created_at', 'updated_at') VALUES (2, 1, 1, 'verb', 'reveal', '揭示／顯示', 'To make something known that was previously hidden or unknown.', '使先前被隱藏或未知的事物為人所知。', 'The study revealed a genetic clue linked to their exceptional longevity.', '這項研究揭示了一個與牠們非凡長壽相關的基因線索。', 1763604216012, 1763604216012);
INSERT OR IGNORE INTO 'ai_vocabulary_item'('id', 'article_ai_view_id', 'sort_order', 'pos', 'word_from', 'word_to', 'definition_from', 'definition_to', 'example_from', 'example_to', 'created_at', 'updated_at') VALUES (3, 1, 2, 'verb', 'evolve', '演化／逐步發展', 'To develop gradually over time, especially by natural processes.', '透過自然過程逐步發展或演變。', 'These animals seem to have evolved a DNA repair mechanism that helps preserve their health.', '這些動物似乎已演化出一套有助於維持健康的 DNA 修復機制。', 1763604216012, 1763604216012);
INSERT OR IGNORE INTO 'ai_vocabulary_item'('id', 'article_ai_view_id', 'sort_order', 'pos', 'word_from', 'word_to', 'definition_from', 'definition_to', 'example_from', 'example_to', 'created_at', 'updated_at') VALUES (4, 1, 3, 'noun', 'mechanism', '機制', 'A system of parts or processes that work together in a machine, organism, or method.', '在機器、有機體或方法中共同運作的一套構造或過程。', 'Scientists focused on the repair mechanism that mends broken DNA strands.', '科學家將焦點放在修補斷裂 DNA 链的修復機制上。', 1763604216012, 1763604216012);
INSERT OR IGNORE INTO 'ai_vocabulary_item'('id', 'article_ai_view_id', 'sort_order', 'pos', 'word_from', 'word_to', 'definition_from', 'definition_to', 'example_from', 'example_to', 'created_at', 'updated_at') VALUES (5, 1, 4, 'verb', 'resist', '抵抗／抗拒', 'To withstand the action or effect of something; to not be affected by.', '抵擋某事物的作用或影響；不受其影響。', 'Naked mole rats resist many age-related diseases such as cancer and arthritis.', '裸鼴鼠能抵抗許多與年齡相關的疾病，例如癌症與關節炎。', 1763604216012, 1763604216012);
INSERT OR IGNORE INTO 'ai_vocabulary_item'('id', 'article_ai_view_id', 'sort_order', 'pos', 'word_from', 'word_to', 'definition_from', 'definition_to', 'example_from', 'example_to', 'created_at', 'updated_at') VALUES (6, 1, 5, 'noun', 'integrity', '完整性／健全性', 'The condition of being whole and not damaged; in genetics, the accuracy and stability of the genome.', '保持完整且未受損的狀態；在基因學上指基因組的準確性與穩定性。', 'Maintaining genomic integrity is essential to prevent diseases related to ageing.', '維持基因組的完整性對預防與老化相關的疾病至關重要。', 1763604216012, 1763604216012);
INSERT OR IGNORE INTO 'ai_vocabulary_item'('id', 'article_ai_view_id', 'sort_order', 'pos', 'word_from', 'word_to', 'definition_from', 'definition_to', 'example_from', 'example_to', 'created_at', 'updated_at') VALUES (7, 1, 6, 'verb', 'coordinate', '協調／配合', 'To organize different elements so that they work together effectively.', '組織不同要素以使其有效協同運作。', 'The protein helps coordinate multiple repair pathways when DNA is damaged.', '該蛋白在 DNA 受損時協調多條修復路徑。', 1763604216012, 1763604216012);
INSERT OR IGNORE INTO 'ai_vocabulary_item'('id', 'article_ai_view_id', 'sort_order', 'pos', 'word_from', 'word_to', 'definition_from', 'definition_to', 'example_from', 'example_to', 'created_at', 'updated_at') VALUES (8, 1, 7, 'verb', 'reconfigure', '重新配置／改組', 'To change the arrangement or structure of something.', '改變某物的排列或結構。', 'Over millions of years, the pathway appears to have been reconfigured to favour genome maintenance.', '經過數百萬年，該路徑似乎被重新配置以有利於基因組的維護。', 1763604216012, 1763604216012);
INSERT OR IGNORE INTO 'ai_vocabulary_item'('id', 'article_ai_view_id', 'sort_order', 'pos', 'word_from', 'word_to', 'definition_from', 'definition_to', 'example_from', 'example_to', 'created_at', 'updated_at') VALUES (9, 2, 0, 'noun', 'rout', '慘敗', 'A decisive and overwhelming defeat, especially in an election or battle.', '決定性且大幅的失敗，常用於選舉或戰役中。', 'The senior Conservative mentioned reasons to hope the party could recover from an electoral rout.', '這位資深保守黨人士提到，該黨有可能從選舉上的慘敗中恢復過來。', 1763604997088, 1763604997088);
INSERT OR IGNORE INTO 'ai_vocabulary_item'('id', 'article_ai_view_id', 'sort_order', 'pos', 'word_from', 'word_to', 'definition_from', 'definition_to', 'example_from', 'example_to', 'created_at', 'updated_at') VALUES (10, 2, 1, 'noun', 'allegiance', '效忠 / 支持', 'Loyalty or commitment of an individual to a group, cause or leader.', '個人對團體、事業或領袖的忠誠或支持。', 'Over a dozen current or former Conservatives have switched allegiance in recent times.', '近期有十多名現任或前任保守黨議員改變了支持對象。', 1763604997088, 1763604997088);
INSERT OR IGNORE INTO 'ai_vocabulary_item'('id', 'article_ai_view_id', 'sort_order', 'pos', 'word_from', 'word_to', 'definition_from', 'definition_to', 'example_from', 'example_to', 'created_at', 'updated_at') VALUES (11, 2, 2, 'adjective', 'coherent', '有條理的；前後一致的', 'Logical and consistent; forming a unified whole.', '合乎邏輯且前後一致；形成完整一致的整體。', 'The more relevant question is whether the Conservatives still have a coherent role in British politics.', '更重要的問題是保守黨在英國政治中是否仍然有一個有條理且一致的角色。', 1763604997088, 1763604997088);
INSERT OR IGNORE INTO 'ai_vocabulary_item'('id', 'article_ai_view_id', 'sort_order', 'pos', 'word_from', 'word_to', 'definition_from', 'definition_to', 'example_from', 'example_to', 'created_at', 'updated_at') VALUES (12, 2, 3, 'noun', 'backlash', '強烈反彈 / 反應', 'A strong negative reaction by a large number of people, especially to a political or social change.', '大量人群對政治或社會變動產生的強烈負面反應。', 'After being in government for 14 years...the Conservatives were vulnerable to a severe backlash.', '執政十四年後，保守黨容易遭受劇烈的反彈。', 1763604997088, 1763604997088);
INSERT OR IGNORE INTO 'ai_vocabulary_item'('id', 'article_ai_view_id', 'sort_order', 'pos', 'word_from', 'word_to', 'definition_from', 'definition_to', 'example_from', 'example_to', 'created_at', 'updated_at') VALUES (13, 2, 4, 'noun', 'forthrightness', '直率；坦率', 'The quality of being direct and outspoken in speech or manner.', '說話或態度直接坦率的特質。', 'Some colleagues praise her forthrightness on free speech and culture issues.', '一些同僚讚賞她在言論自由與文化議題上的直率。', 1763604997088, 1763604997088);
INSERT OR IGNORE INTO 'ai_vocabulary_item'('id', 'article_ai_view_id', 'sort_order', 'pos', 'word_from', 'word_to', 'definition_from', 'definition_to', 'example_from', 'example_to', 'created_at', 'updated_at') VALUES (14, 2, 5, 'verb', 'reclaim', '奪回 / 重新獲得', 'To take back something that was lost or to recover a position or reputation.', '奪回失去的事物，或恢復一個地位或聲譽。', 'Critics argue the party has been slow to define itself against Labour or to reclaim the centre-right ground it once held.', '批評者認為該黨在與工黨區分或奪回曾占據的中右翼立場上行動太慢。', 1763604997088, 1763604997088);
INSERT OR IGNORE INTO 'ai_vocabulary_item'('id', 'article_ai_view_id', 'sort_order', 'pos', 'word_from', 'word_to', 'definition_from', 'definition_to', 'example_from', 'example_to', 'created_at', 'updated_at') VALUES (15, 2, 6, 'noun', 'electorate', '選民 / 選舉人', 'All the people in a country or area who are entitled to vote in an election.', '在某國家或地區有投票權的全部人群。', 'Reform’s unambiguous messaging...has attracted disaffected voters.', '改革黨明確的訊息吸引了心灰意冷的選民。', 1763604997088, 1763604997088);
INSERT OR IGNORE INTO 'ai_vocabulary_item'('id', 'article_ai_view_id', 'sort_order', 'pos', 'word_from', 'word_to', 'definition_from', 'definition_to', 'example_from', 'example_to', 'created_at', 'updated_at') VALUES (16, 2, 7, 'noun', 'coalition', '聯盟 / 聯合陣營', 'An alliance for combined action, especially among political parties or groups.', '為了共同採取行動而形成的聯盟，尤指政黨或團體之間的合作。', 'The Tories must decide whether to compete for the same electorate or seek a different coalition of support.', '保守黨必須決定是與改革黨爭奪同樣的選民，還是尋求不同的支持聯盟。', 1763604997088, 1763604997088);
INSERT OR IGNORE INTO 'ai_vocabulary_item'('id', 'article_ai_view_id', 'sort_order', 'pos', 'word_from', 'word_to', 'definition_from', 'definition_to', 'example_from', 'example_to', 'created_at', 'updated_at') VALUES (17, 3, 0, '動詞', '發行', '發行', '公開發出有價證券或文件，例如政府發行公債給投資人。', '有價證券や書類を市場に出すこと。政府が公債を市場に出すことを指す。', '政府計畫下個月發行新公債來資助道路工程。', '政府は來月新しい公債を發行して道路工事を資金調達する計畫だ。', 1763607808017, 1763607808017);
INSERT OR IGNORE INTO 'ai_vocabulary_item'('id', 'article_ai_view_id', 'sort_order', 'pos', 'word_from', 'word_to', 'definition_from', 'definition_to', 'example_from', 'example_to', 'created_at', 'updated_at') VALUES (18, 3, 1, '名詞', '公債', '公債', '政府為籌措資金向投資人借款的證券，會定期支付利息並於到期時還本。', '政府が資金を調達するために投資家から借りる証券。定期的に利息を支払い、満期で元本を返す。', '發行公債可以支持學校和醫院的建設。', '公債の發行は學校や病院の建設を支援できる。', 1763607808017, 1763607808017);
INSERT OR IGNORE INTO 'ai_vocabulary_item'('id', 'article_ai_view_id', 'sort_order', 'pos', 'word_from', 'word_to', 'definition_from', 'definition_to', 'example_from', 'example_to', 'created_at', 'updated_at') VALUES (19, 3, 2, '名詞', '利息', '利息', '借款的使用費，貸方按一定比率定期收到的報酬。', 'お金を借りるときの使用料。貸した側が定期的に受け取る報酬。', '投資人會每半年收到一次利息。', '投資家は半年ごとに利息を受け取る。', 1763607808017, 1763607808017);
INSERT OR IGNORE INTO 'ai_vocabulary_item'('id', 'article_ai_view_id', 'sort_order', 'pos', 'word_from', 'word_to', 'definition_from', 'definition_to', 'example_from', 'example_to', 'created_at', 'updated_at') VALUES (20, 3, 3, '名詞', '評級', '評級', '評估政府或公司償還債務能力的等級，常由評級機構給出。', '政府や企業の債務返済能力を評価する格付けのこと。格付け機関が付与する。', '評級下調可能會增加借款成本。', '評級が下がると借入成本が上がる可能性がある。', 1763607808017, 1763607808017);
INSERT OR IGNORE INTO 'ai_vocabulary_item'('id', 'article_ai_view_id', 'sort_order', 'pos', 'word_from', 'word_to', 'definition_from', 'definition_to', 'example_from', 'example_to', 'created_at', 'updated_at') VALUES (21, 3, 4, '名詞', '基礎建設', '基礎建設', '公共設施如道路、橋樑、學校與醫院等基礎工程。', '道路や橋、学校、病院などの公共インフラのこと。', '政府希望用借來的錢改善基礎建設。', '政府は借入金で基礎建設を改善したいと考えている。', 1763607808017, 1763607808017);
INSERT OR IGNORE INTO 'ai_vocabulary_item'('id', 'article_ai_view_id', 'sort_order', 'pos', 'word_from', 'word_to', 'definition_from', 'definition_to', 'example_from', 'example_to', 'created_at', 'updated_at') VALUES (22, 3, 5, '名詞', '承銷商', '承銷商', '協助發行證券並向投資人銷售的金融機構，通常由銀行擔任。', '証券の発行を支援し、投資家に販売する金融機関。通常は銀行が担当する。', '政府會選出聯合主承銷商來協助發行公債。', '政府は公債発行を支援するために聯合主承銷商を選ぶ。', 1763607808017, 1763607808017);
INSERT OR IGNORE INTO 'ai_grammar_item'('id', 'article_ai_view_id', 'sort_order', 'rule_from', 'rule_to', 'explanation_from', 'explanation_to', 'example_from', 'example_to', 'created_at', 'updated_at') VALUES (6, 2, 1, 'Noun clauses with ''whether'' for indirect questions and alternatives', '''whether'' 的名詞子句用於間接問句與表示兩者間的選擇', '''Whether'' introduces an indirect yes/no question or alternatives. Example in the article: ''The more relevant question is whether the Conservatives still have a coherent role...'' It functions as the complement of ''is''.', '''whether'' 引導的是間接的是/否問句或選擇。文中例句「The more relevant question is whether...」做為動詞 ''is'' 的補語。', 'I don''t know whether she will attend the conference. → (indirect question)', '我不知道她是否會參加這次黨大會。→（間接問句）', 1763604997088, 1763604997088);
INSERT OR IGNORE INTO 'ai_grammar_item'('id', 'article_ai_view_id', 'sort_order', 'rule_from', 'rule_to', 'explanation_from', 'explanation_to', 'example_from', 'example_to', 'created_at', 'updated_at') VALUES (7, 2, 2, 'Gerunds as subjects and infinitive for purpose (e.g., ''chasing Reform voters risks alienating...'' / ''use the platform to present'')', '動名詞作主詞與不定詞表示目的（例如：「chasing Reform voters risks alienating...」／「use the platform to present」）', 'Gerunds (-ing nouns) can act as subjects: ''Chasing Reform voters risks alienating moderate conservatives.'' Infinitives (to + verb) often express purpose: ''Badenoch can use the platform to present a coherent set of policies.'' Pay attention to verb patterns after certain verbs (e.g., ''risk'' + gerund, ''use'' + to-infinitive).', '動名詞（-ing 名詞）可作主詞：『Chasing Reform voters risks alienating...』。不定詞（to + 動詞）通常表目的：『Badenoch can use the platform to present...』。注意不同動詞後接不同結構（如 ''risk'' 後接動名詞，''use'' 常與不定詞表目的）。', 'Smoking increases health risks. / He stayed late to finish the report.', '吸菸提高健康風險。／他加班是為了完成報告。', 1763604997088, 1763604997088);
INSERT OR IGNORE INTO 'ai_grammar_item'('id', 'article_ai_view_id', 'sort_order', 'rule_from', 'rule_to', 'explanation_from', 'explanation_to', 'example_from', 'example_to', 'created_at', 'updated_at') VALUES (8, 3, 0, '表示計畫或未來時：會 / 將 / 計畫 + 動詞', '計畫や未来を表す「會 / 將 / 計畫 + 動詞」', '中文用「會、將、計畫」等詞表示未來或計畫。例如：政府會在明年發行公債。這種用法簡單、常見，適合談論已決定或預期會發生的事。', '中國語では「會、將、計畫」などで未来や計畫を表す。例：「政府會在明年發行公債。」これは既に決まっているか予想される事柄について使う表現だ。', '蘇格蘭政府計畫在2026–27年發行公債。', '蘇格蘭政府は2026–27年に公債を發行する計畫だ。', 1763607808017, 1763607808017);
INSERT OR IGNORE INTO 'ai_grammar_item'('id', 'article_ai_view_id', 'sort_order', 'rule_from', 'rule_to', 'explanation_from', 'explanation_to', 'example_from', 'example_to', 'created_at', 'updated_at') VALUES (9, 3, 1, '條件句：如果...（就/會）... / 只要...就...', '条件文：「如果...就/會...」や「只要...就...」', '中文常用「如果...就...」表達條件與結果。當前提成立時，結果才會發生。例如：如果市場情況穩定，政府就會發行公債。', '中國語では「如果...就...」で条件と結果を表す。前提が成り立つと結果が起こる。例：「如果市場情況穩定，政府就會發行公債。」', '如果五月選舉結果明朗，發行時程就能確定。', 'もし5月の選舉結果が明確になれば、發行時程は確定するだろう。', 1763607808017, 1763607808017);
INSERT OR IGNORE INTO 'ai_grammar_item'('id', 'article_ai_view_id', 'sort_order', 'rule_from', 'rule_to', 'explanation_from', 'explanation_to', 'example_from', 'example_to', 'created_at', 'updated_at') VALUES (1, 1, 0, 'Modal verbs for possibility (could / may / might)', '表示可能性的情態動詞（could / may / might）', 'Use modals like ''could'', ''may'', or ''might'' to express possibility or theoretical outcomes without certainty. In scientific writing they soften claims.', '使用 ''could''、''may'' 或 ''might'' 等情態動詞表達可能性或理論結果，表示不確定性。在科學寫作中常用來謹慎陳述結論。', 'The mechanism could help explain naked mole rats'' long lives. (This suggests a possible explanation, not a definitive one.)', '該機制可能幫助解釋裸鼴鼠的長壽。（表示一種可能的解釋，而非確定結論。）', 1763604216013, 1763604216013);
INSERT OR IGNORE INTO 'ai_grammar_item'('id', 'article_ai_view_id', 'sort_order', 'rule_from', 'rule_to', 'explanation_from', 'explanation_to', 'example_from', 'example_to', 'created_at', 'updated_at') VALUES (2, 1, 1, 'Passive voice and past participle clauses', '被動語態與過去分詞子句', 'Scientific texts often use passive voice or reduced past-participial clauses to focus on results or processes (e.g. ''findings published in the journal...''). The agent is optional.', '科學文本常用被動語態或縮寫的過去分詞子句以強調結果或過程（如 ''findings published in the journal...''）。施事可省略。', 'The findings, published in the journal Science, may help explain why they resist diseases.', '該研究結果刊登於《Science》期刊，可能有助解釋為何牠們能抵抗疾病。', 1763604216013, 1763604216013);
INSERT OR IGNORE INTO 'ai_grammar_item'('id', 'article_ai_view_id', 'sort_order', 'rule_from', 'rule_to', 'explanation_from', 'explanation_to', 'example_from', 'example_to', 'created_at', 'updated_at') VALUES (3, 1, 2, 'Reduced relative clauses / participial phrases', '縮減關係子句 / 分詞短語', 'A relative clause can be reduced by using a present or past participle: ''a protein involved in detecting damage'' instead of ''a protein that is involved in detecting damage''. This makes sentences more concise.', '關係子句可用現在或過去分詞縮減：''a protein involved in detecting damage'' 取代 ''a protein that is involved in detecting damage''，使句子更簡潔。', 'They studied a protein responsible for coordinating repair → They studied a protein coordinating repair.', '他們研究一個負責協調修復的蛋白 → 他們研究一個協調修復的蛋白。', 1763604216013, 1763604216013);
INSERT OR IGNORE INTO 'ai_grammar_item'('id', 'article_ai_view_id', 'sort_order', 'rule_from', 'rule_to', 'explanation_from', 'explanation_to', 'example_from', 'example_to', 'created_at', 'updated_at') VALUES (4, 1, 3, 'Perfect infinitive after verbs of appearance (appear to have + past participle)', '表現/看起來動詞後的完成不定式（appear to have + 過去分詞）', '''Appear to have + past participle'' shows that something seems to have happened before now. It expresses an inference about a past action based on current evidence.', '''appear to have + 過去分詞'' 表示某事似乎已在過去發生，根據現有證據對過去行為的推論。', 'Naked mole rats appear to have reconfigured this pathway over millions of years.', '裸鼴鼠似乎在數百萬年中已重新配置了這條路徑。', 1763604216013, 1763604216013);
INSERT OR IGNORE INTO 'ai_grammar_item'('id', 'article_ai_view_id', 'sort_order', 'rule_from', 'rule_to', 'explanation_from', 'explanation_to', 'example_from', 'example_to', 'created_at', 'updated_at') VALUES (5, 2, 0, 'Participle clauses to show time/reason (e.g., ''After being in government...'')', '分詞子句表示時間或原因（例如：「After being in government...」）', 'Participle clauses (present participle -ing or past participle) can compress information and show time, reason or result. In the article, ''After being in government for 14 years and enduring rapid leadership turnover...'' uses an -ing clause to give background information.', '分詞子句（現在分詞 -ing 或過去分詞）可簡化資訊並表示時間、原因或結果。文中「After being in government...」用 -ing 子句提供背景資訊。', 'After being in government for many years, the party faced voter fatigue. → (background/time)', '執政多年後，該黨面臨選民疲勞。→（背景／時間）', 1763604997088, 1763604997088);
INSERT OR IGNORE INTO 'ai_sentence_pattern_item'('id', 'article_ai_view_id', 'sort_order', 'pattern_from', 'pattern_to', 'explanation_from', 'explanation_to', 'example_from', 'example_to', 'created_at', 'updated_at') VALUES (8, 3, 0, 'X 取決於 Y', 'X は Y に依存する（取決於）', '用來說明某件事的結果或安排會被另一個因素影響或決定。', 'ある事柄の結果や予定が別の要因によって左右されることを説明する表現だ。', '發行時程取決於選舉結果與市場情況。', '發行時程は選舉結果と市場情況に依存する。', 1763607808017, 1763607808017);
INSERT OR IGNORE INTO 'ai_sentence_pattern_item'('id', 'article_ai_view_id', 'sort_order', 'pattern_from', 'pattern_to', 'explanation_from', 'explanation_to', 'example_from', 'example_to', 'created_at', 'updated_at') VALUES (9, 3, 1, '以便 + 動詞', '〜するために（以便）', '表示目標或目的，說明做某事的原因或用途。', '目的を示す表現。何かをする理由や用途を説明する。', '政府與銀行接洽，以便選出承銷商。', '政府は銀行と協議して、承銷商を選ぶためだ。', 1763607808017, 1763607808017);
INSERT OR IGNORE INTO 'ai_sentence_pattern_item'('id', 'article_ai_view_id', 'sort_order', 'pattern_from', 'pattern_to', 'explanation_from', 'explanation_to', 'example_from', 'example_to', 'created_at', 'updated_at') VALUES (10, 3, 2, '目標是 + 子句', '目標は〜だ（目標是）', '說明重點或想達到的結果，可以接名詞或完整子句。', NULL, '目標是借得更好，而不是借得更多。', '目標はより良く借りることであって、より多く借りることではない。', 1763607808017, 1763607808017);
INSERT OR IGNORE INTO 'ai_sentence_pattern_item'('id', 'article_ai_view_id', 'sort_order', 'pattern_from', 'pattern_to', 'explanation_from', 'explanation_to', 'example_from', 'example_to', 'created_at', 'updated_at') VALUES (1, 1, 0, 'While + clause, + clause (contrast)', 'While + 子句，+ 子句（對比）', 'Use ''while'' to contrast two ideas in one sentence. It often replaces ''although'' or ''whereas'' to show simultaneous but differing conditions.', '使用 ''while'' 在同一句中對比兩個觀點。它常用來取代 ''although'' 或 ''whereas''，表示同時存在但有差異的情況。', 'While human cGAS interferes with repair, naked mole‑rat cGAS promotes it.', '在人類中 cGAS 會干擾修復，而在裸鼴鼠中 cGAS 則促進修復。', 1763604216013, 1763604216013);
INSERT OR IGNORE INTO 'ai_sentence_pattern_item'('id', 'article_ai_view_id', 'sort_order', 'pattern_from', 'pattern_to', 'explanation_from', 'explanation_to', 'example_from', 'example_to', 'created_at', 'updated_at') VALUES (2, 1, 1, 'Not only + X, but also + Y (addition + emphasis)', 'Not only + X, but also + Y（附加並強調）', 'Use this pattern to add two related points and emphasize that both are true. Maintain parallel structure after ''not only'' and ''but also''.', '使用此句型加入兩個相關點並強調兩者皆為真。在 ''not only'' 和 ''but also'' 之後保持相同的語法結構。', 'The animals are not only long‑lived but also resistant to several diseases.', '這些動物不僅壽命長，還能抵抗多種疾病。', 1763604216013, 1763604216013);
INSERT OR IGNORE INTO 'ai_sentence_pattern_item'('id', 'article_ai_view_id', 'sort_order', 'pattern_from', 'pattern_to', 'explanation_from', 'explanation_to', 'example_from', 'example_to', 'created_at', 'updated_at') VALUES (3, 1, 2, 'Subject + may/might/could + verb (speculation)', '主詞 + may/might/could + 動詞（推測）', 'Use modals with the base verb to express a tentative conclusion or hypothesis in scientific contexts.', '在科學語境中用情態動詞加原形動詞表達暫定結論或假設。', 'This discovery could inspire new therapies for ageing populations.', '這一發現可能會啟發針對老齡族群的新療法。', 1763604216013, 1763604216013);
INSERT OR IGNORE INTO 'ai_sentence_pattern_item'('id', 'article_ai_view_id', 'sort_order', 'pattern_from', 'pattern_to', 'explanation_from', 'explanation_to', 'example_from', 'example_to', 'created_at', 'updated_at') VALUES (4, 1, 3, 'X, which + verb, + verb (non-defining relative clause giving extra info)', 'X, which + 動詞，+ 動詞（非限定關係子句提供補充資訊）', 'Use a non-defining relative clause to add background information; set it off with commas because it is not essential to identify the noun.', '使用非限定關係子句補充背景資訊；以逗號隔開，因為該資訊非識別該名詞所必需。', 'They live underground, which has driven interest in how they stay healthy for decades.', '牠們生活在地下，這一點促使人們對牠們如何維持數十年的健康產生興趣。', 1763604216013, 1763604216013);
INSERT OR IGNORE INTO 'ai_sentence_pattern_item'('id', 'article_ai_view_id', 'sort_order', 'pattern_from', 'pattern_to', 'explanation_from', 'explanation_to', 'example_from', 'example_to', 'created_at', 'updated_at') VALUES (5, 2, 0, 'X offers Y but also Z', 'X 提供 Y，但也有 Z', 'A common pattern to present two contrasting outcomes or benefits/costs of one option. The article: ''Each route offers potential gains but also clear limitations.''', '一個常用來呈現兩種相反結果或一個選項的利弊的句型。文中：『Each route offers potential gains but also clear limitations.』', 'Moving to the centre offers broader appeal but also risks disappointing core supporters.', '轉向中間路線能吸引更廣泛的支持，但也可能讓核心支持者感到失望。', 1763604997088, 1763604997088);
INSERT OR IGNORE INTO 'ai_sentence_pattern_item'('id', 'article_ai_view_id', 'sort_order', 'pattern_from', 'pattern_to', 'explanation_from', 'explanation_to', 'example_from', 'example_to', 'created_at', 'updated_at') VALUES (6, 2, 1, 'The immediate test is whether + clause', '眼前的考驗是是否 + 子句', 'Use this pattern to define a short-term key criterion or challenge. Example: ''The immediate test is whether the Conservatives can use the conference to show they still matter.''', '用來定義短期的關鍵標準或挑戰。例如：『眼前的考驗是保守黨是否能利用黨大會證明仍然重要。』', 'The central question is whether the team can recover before the finals.', '核心問題是這支隊伍是否能在決賽前恢復狀態。', 1763604997088, 1763604997088);
INSERT OR IGNORE INTO 'ai_sentence_pattern_item'('id', 'article_ai_view_id', 'sort_order', 'pattern_from', 'pattern_to', 'explanation_from', 'explanation_to', 'example_from', 'example_to', 'created_at', 'updated_at') VALUES (7, 2, 2, 'to decide whether to + verb', '決定是否要 + 動詞', 'This pattern expresses a choice between two actions. From the article: ''that has forced the Tories to decide whether to compete for the same electorate or seek a different coalition.''', '這個句型表示在兩個行動之間做抉擇。出自文章：『迫使保守黨決定是否與對方競爭同一選民，或尋求不同聯盟。』', 'She needs to decide whether to accept the job or keep looking.', '她需要決定是接受這份工作還是繼續尋找。', 1763604997088, 1763604997088);
INSERT OR IGNORE INTO 'ai_phrase_idiom_item'('id', 'article_ai_view_id', 'sort_order', 'phrase_from', 'phrase_to', 'explanation_from', 'explanation_to', 'example_from', 'example_to', 'created_at', 'updated_at') VALUES (10, 3, 0, '無縫接手', '無縫接手', '表示一個新的團隊或政府能夠順利承接前任的工作，沒有明顯中斷。', '新しいチームや政府が前任者の仕事をスムーズに引き継ぐことを表す言葉だ。', '政府要安排好程序，讓下一屆政府能無縫接手。', '政府は次の政権が無縫接手できるように手続きを整える。', 1763607808017, 1763607808017);
INSERT OR IGNORE INTO 'ai_phrase_idiom_item'('id', 'article_ai_view_id', 'sort_order', 'phrase_from', 'phrase_to', 'explanation_from', 'explanation_to', 'example_from', 'example_to', 'created_at', 'updated_at') VALUES (11, 3, 1, '借得更好，而不是借得更多', '借得更好，而不是借得更多', '強調借款品質與條件比借款總量更重要，追求效率與彈性。', '借入条件や質を重視し、単に借入額を増やすのではなく効率と柔軟性を求めるという意味だ。', '他們強調要借得更好，而不是借得更多，以提升效率。', '彼らは効率を高めるために借得更好，而不是借得更多と強調している。', 1763607808017, 1763607808017);
INSERT OR IGNORE INTO 'ai_phrase_idiom_item'('id', 'article_ai_view_id', 'sort_order', 'phrase_from', 'phrase_to', 'explanation_from', 'explanation_to', 'example_from', 'example_to', 'created_at', 'updated_at') VALUES (12, 3, 2, '左右', '左右', '指影響或決定事物的走向或結果，可以用於中性或負面情境。', NULL, '選舉可能左右評級機構的判斷。', '選挙は評級機構の判斷に左右される可能性がある。', 1763607808017, 1763607808017);
INSERT OR IGNORE INTO 'ai_phrase_idiom_item'('id', 'article_ai_view_id', 'sort_order', 'phrase_from', 'phrase_to', 'explanation_from', 'explanation_to', 'example_from', 'example_to', 'created_at', 'updated_at') VALUES (1, 1, 0, 'the tip of the iceberg', '冰山一角', 'An expression meaning a small, visible part of a much larger problem or situation.', '比喻更大問題或情況中一小部分可見的面向。', 'Professor Balmus said the finding was likely ''the tip of the iceberg'', implying many more discoveries may follow.', 'Balmus 教授表示這項發現可能是「冰山一角」，暗示可能還有更多發現。', 1763604216013, 1763604216013);
INSERT OR IGNORE INTO 'ai_phrase_idiom_item'('id', 'article_ai_view_id', 'sort_order', 'phrase_from', 'phrase_to', 'explanation_from', 'explanation_to', 'example_from', 'example_to', 'created_at', 'updated_at') VALUES (2, 1, 1, 'reverse-engineer', '逆向工程／反向模仿', 'To analyse a system to discover its components and working principles so you can recreate or adapt it.', '分析一個系統以發現其構成與原理，從而重建或改良它。', 'Scientists hope to reverse-engineer aspects of mole‑rat biology to inspire therapies.', '科學家希望逆向工程裸鼴鼠的一些生物特性以啟發療法。', 1763604216013, 1763604216013);
INSERT OR IGNORE INTO 'ai_phrase_idiom_item'('id', 'article_ai_view_id', 'sort_order', 'phrase_from', 'phrase_to', 'explanation_from', 'explanation_to', 'example_from', 'example_to', 'created_at', 'updated_at') VALUES (3, 1, 2, 'drive interest', '引起興趣／促使關注', 'To cause people to be interested in something; often used about research or findings that motivate further study.', '使人們對某事產生興趣；常用於描述促使進一步研究的發現或結果。', 'Their resistance to disease has driven interest in how their bodies maintain health.', '牠們對疾病的抵抗力引起了人們對其身體如何維持健康的關注。', 1763604216013, 1763604216013);
INSERT OR IGNORE INTO 'ai_phrase_idiom_item'('id', 'article_ai_view_id', 'sort_order', 'phrase_from', 'phrase_to', 'explanation_from', 'explanation_to', 'example_from', 'example_to', 'created_at', 'updated_at') VALUES (4, 1, 3, 'genomic integrity', '基因組完整性', 'Refers to the overall stability and accuracy of an organism''s DNA; maintaining it prevents mutations and disease.', '指生物體 DNA 的整體穩定性與準確性；維持完整性可防止突變與疾病。', 'The mole‑rat version of cGAS helps maintain genomic integrity by promoting repair.', '裸鼴鼠版本的 cGAS 透過促進修復來維持基因組完整性。', 1763604216013, 1763604216013);
INSERT OR IGNORE INTO 'ai_phrase_idiom_item'('id', 'article_ai_view_id', 'sort_order', 'phrase_from', 'phrase_to', 'explanation_from', 'explanation_to', 'example_from', 'example_to', 'created_at', 'updated_at') VALUES (5, 2, 0, 'fill a space', '填補空缺（市場或政治位置）', 'To occupy a role or niche that was previously unserved. In politics, it means attracting voters in an area another party ignored.', '佔據先前未被服務的角色或利基。在政治上代表吸引先前被對手忽視的選民群。', 'Reform UK filled a space that the Conservatives either neglected or failed to secure.', '改革黨填補了保守黨忽視或未能鞏固的政治空缺。', 1763604997088, 1763604997088);
INSERT OR IGNORE INTO 'ai_phrase_idiom_item'('id', 'article_ai_view_id', 'sort_order', 'phrase_from', 'phrase_to', 'explanation_from', 'explanation_to', 'example_from', 'example_to', 'created_at', 'updated_at') VALUES (6, 2, 1, 'miss a crucial window', '錯過關鍵時機', 'Fail to act within an important time period when an opportunity is available.', '未能在有機會的關鍵時段內採取行動。', 'Some fear she missed a crucial initial window to establish herself with the public.', '有人擔心她錯過了在公眾面前確立自己的重要初期時機。', 1763604997088, 1763604997088);
INSERT OR IGNORE INTO 'ai_phrase_idiom_item'('id', 'article_ai_view_id', 'sort_order', 'phrase_from', 'phrase_to', 'explanation_from', 'explanation_to', 'example_from', 'example_to', 'created_at', 'updated_at') VALUES (7, 2, 2, 'bread-and-butter', '基本民生 / 生活費用相關的議題', 'Everyday practical issues that most voters care about, such as household budgets, jobs or cost of living.', '大多數選民關心的日常務實議題，如家庭開支、就業或生活成本。', 'Strategists recommend focusing on bread-and-butter economic issues: household budgets, cost of living, growth.', '策略家建議聚焦於基本民生的經濟議題：家庭預算、生活成本、經濟成長。', 1763604997088, 1763604997088);
INSERT OR IGNORE INTO 'ai_phrase_idiom_item'('id', 'article_ai_view_id', 'sort_order', 'phrase_from', 'phrase_to', 'explanation_from', 'explanation_to', 'example_from', 'example_to', 'created_at', 'updated_at') VALUES (8, 2, 3, 'written off', '被宣判失敗 / 被認為不可能恢復', 'Considered beyond recovery or no longer viable. The article notes Conservatives have been written off before but recovered.', '被認為無法復原或不再有希望。文章提到保守黨曾被宣判失敗但仍有恢復的先例。', 'Conservatives have been written off before and recovered; recovery requires coherent strategy.', '保守黨過去曾被認為無望但後來復甦；復甦需要有條理的策略。', 1763604997088, 1763604997088);
INSERT OR IGNORE INTO 'ai_phrase_idiom_item'('id', 'article_ai_view_id', 'sort_order', 'phrase_from', 'phrase_to', 'explanation_from', 'explanation_to', 'example_from', 'example_to', 'created_at', 'updated_at') VALUES (9, 2, 4, 'show they matter', '證明自己重要 / 有所作為', 'To demonstrate relevance or impact to a target audience, such as voters or supporters.', '向目標族群（如選民或支持者）顯示自身具有影響力或重要性。', 'The immediate test is whether the Conservatives can use the conference to show they still matter.', '眼前的考驗是保守黨是否能透過黨大會證明自己仍然重要。', 1763604997088, 1763604997088);
INSERT OR IGNORE INTO 'ai_comprehension_mcq'('id', 'article_ai_view_id', 'sort_order', 'question_from', 'question_to', 'answer', 'explanation_from', 'explanation_to', 'created_at', 'updated_at') VALUES (8, 2, 3, 'What does the phrase ''written off before and recovered'' imply about political fortunes?', '片語「written off before and recovered」對政治命運有何含意？', 'C', 'The sentence suggests that although Conservatives have been dismissed in the past, they managed to recover; recovery depends on coherent strategy, credible policies and circumstances such as opponents'' mistakes or economic changes.', '該句指出過去保守黨曾被看扁但仍然復甦；復甦取決於清晰策略、可信政策以及對手失誤或經濟轉機等因素。', 1763604997088, 1763604997088);
INSERT OR IGNORE INTO 'ai_comprehension_mcq'('id', 'article_ai_view_id', 'sort_order', 'question_from', 'question_to', 'answer', 'explanation_from', 'explanation_to', 'created_at', 'updated_at') VALUES (9, 3, 0, '蘇格蘭政府計畫何時首次發行公債？', '蘇格蘭政府はいつ初めて公債を發行する計畫か？', 'B', '文章提到目標時程為2026–27年，但也說明會受選舉與市場條件影響。注意不要選擇文中未提及的年份。', '本文では2026–27年が目標時程と書かれている。ただし選挙や市場条件によって変わる可能性があるので、他の年は誤りだ。', 1763607808017, 1763607808017);
INSERT OR IGNORE INTO 'ai_comprehension_mcq'('id', 'article_ai_view_id', 'sort_order', 'question_from', 'question_to', 'answer', 'explanation_from', 'explanation_to', 'created_at', 'updated_at') VALUES (10, 3, 1, '發行公債的主要目的是什麼？', '公債發行の主な目的は何か？', 'A', '文章指出政府發行公債是向投資人借款，並用於基礎建設和資本支出。其他選項與原文不符或過度推論。', '本文では公債は投資家からの借入であり、基礎建設や資本支出に使われると述べられている。その他の選択肢は本文に書かれていない。', 1763607808017, 1763607808017);
INSERT OR IGNORE INTO 'ai_comprehension_mcq'('id', 'article_ai_view_id', 'sort_order', 'question_from', 'question_to', 'answer', 'explanation_from', 'explanation_to', 'created_at', 'updated_at') VALUES (11, 3, 2, '評級機構對蘇格蘭的評價說明了什麼？', '評級機關は蘇格蘭について何を示しているか？', 'B', '文中提到兩家機構給予相同評級，並說明原因是財政管理謹慎與經濟穩定，但也警告獨立議題可能影響評級。', '本文では兩つの機関が同じ評級を與えており、理由は財政管理の慎重さと経済の安定と書かれている。', 1763607808017, 1763607808017);
INSERT OR IGNORE INTO 'ai_comprehension_mcq'('id', 'article_ai_view_id', 'sort_order', 'question_from', 'question_to', 'answer', 'explanation_from', 'explanation_to', 'created_at', 'updated_at') VALUES (12, 3, 3, '下列哪一項不是文章強調的重點？', '次のうち本文が強調していない点はどれか？', 'C', '文章提到在英國政府公債稱為gilt，並說蘇格蘭有時被戲稱為「kilts」，但沒有說公債名稱總是叫做gilt，選項 C 的描述過於絕對，與原文不符。', '本文では英國では公債をgiltと呼ぶと書かれており、蘇格蘭は時に「kilts」と冗談めかして呼ばれるとあるが、「總是叫做gilt」と断定するのは本文の内容と合わない。', 1763607808017, 1763607808017);
INSERT OR IGNORE INTO 'ai_comprehension_mcq'('id', 'article_ai_view_id', 'sort_order', 'question_from', 'question_to', 'answer', 'explanation_from', 'explanation_to', 'created_at', 'updated_at') VALUES (1, 1, 0, 'What main discovery did the study of naked mole rats report?', '這項對裸鼴鼠的研究主要發現是什麼？', 'A', 'The article states researchers found that cGAS in naked mole rats promotes repair and helps maintain genomic integrity—this is the key discovery. Options B and C contradict the text; D is opposite to the article''s implication that mole rats are valuable for ageing research.', '文章指出研究人員發現裸鼴鼠的 cGAS 促進修復並有助維持基因組完整性——這是主要發現。選項 B 與 C 與原文相矛盾；D 則與文章暗示裸鼴鼠對老化研究有價值的說法相反。', 1763604216013, 1763604216013);
INSERT OR IGNORE INTO 'ai_comprehension_mcq'('id', 'article_ai_view_id', 'sort_order', 'question_from', 'question_to', 'answer', 'explanation_from', 'explanation_to', 'created_at', 'updated_at') VALUES (2, 1, 1, 'How does human cGAS differ from naked mole‑rat cGAS according to the text?', '根據文章，人類的 cGAS 與裸鼴鼠的 cGAS 有何不同？', 'B', 'The article explicitly contrasts human cGAS (which can interfere with DNA stitching) with naked mole‑rat cGAS (which promotes repair). That matches option B.', '文章明確對比人類 cGAS（可能干擾 DNA 拼接）與裸鼴鼠 cGAS（促進修復）。這與選項 B 相符。', 1763604216013, 1763604216013);
INSERT OR IGNORE INTO 'ai_comprehension_mcq'('id', 'article_ai_view_id', 'sort_order', 'question_from', 'question_to', 'answer', 'explanation_from', 'explanation_to', 'created_at', 'updated_at') VALUES (3, 1, 2, 'What future application do researchers hope the findings might support?', '研究人員希望這些發現未來可以支持什麼應用？', 'A', 'The article notes scientists hope to ''inspire new therapies for ageing populations'' by understanding mole‑rat biology. Options B–D are unrealistic or contradict the cautious wording about needing much more research.', '文章指出科學家希望透過了解裸鼴鼠生物學來「啟發針對老齡族群的新療法」。選項 B–D 不切實際或與文章所述需更多研究的保守說法相矛盾。', 1763604216013, 1763604216013);
INSERT OR IGNORE INTO 'ai_comprehension_mcq'('id', 'article_ai_view_id', 'sort_order', 'question_from', 'question_to', 'answer', 'explanation_from', 'explanation_to', 'created_at', 'updated_at') VALUES (4, 1, 3, 'What does Professor Balmus mean by calling the discovery ''the tip of the iceberg''?', 'Balmus 教授稱此發現為「冰山一角」是什麼意思？', 'A', 'Calling something ''the tip of the iceberg'' implies that what we see is only a small part of a larger issue — more discoveries are likely. The article uses this to suggest additional research will reveal more about longevity.', '稱某事為「冰山一角」表示我們目前看到的只是更大問題的一小部分——很可能還有更多發現。文章用此說法表示需要進一步研究以揭示更多有關長壽的資訊。', 1763604216013, 1763604216013);
INSERT OR IGNORE INTO 'ai_comprehension_mcq'('id', 'article_ai_view_id', 'sort_order', 'question_from', 'question_to', 'answer', 'explanation_from', 'explanation_to', 'created_at', 'updated_at') VALUES (5, 2, 0, 'What is the main concern expressed about the Conservative party in the article?', '本文對保守黨的主要擔憂是什麼？', 'B', 'The article repeatedly questions whether the Conservatives still have a coherent role and can convince voters, especially after an electoral rout and multiple defections. This expresses concern about relevance and coherence.', '文章多次質疑保守黨在慘敗與多名議員倒戈後，是否仍有一致的角色並能說服選民，顯示對其相關性與一致性的擔憂。', 1763604997088, 1763604997088);
INSERT OR IGNORE INTO 'ai_comprehension_mcq'('id', 'article_ai_view_id', 'sort_order', 'question_from', 'question_to', 'answer', 'explanation_from', 'explanation_to', 'created_at', 'updated_at') VALUES (6, 2, 1, 'Which strategic dilemma does the article highlight for the Conservatives?', '文中突顯了保守黨哪項策略兩難？', 'C', 'The article explains Reform UK has taken a space on the right, forcing Conservatives to choose between chasing those voters or seeking a different, more centrist coalition—each with trade-offs.', '文章說明改革黨在右側佔據空間，迫使保守黨在爭取那些選民或尋求更中間的支持聯盟間抉擇，兩者皆有利弊。', 1763604997088, 1763604997088);
INSERT OR IGNORE INTO 'ai_comprehension_mcq'('id', 'article_ai_view_id', 'sort_order', 'question_from', 'question_to', 'answer', 'explanation_from', 'explanation_to', 'created_at', 'updated_at') VALUES (7, 2, 2, 'What role does the party conference in Manchester play, according to the article?', '根據文章，曼徹斯特的黨大會扮演什麼角色？', 'B', 'The article describes the conference as offering a limited but critical chance for leadership to present policies and show pace and clarity to voters and activists.', '文章將黨大會描述為一個有限但關鍵的機會，讓領導層提出政策並向選民與支持者展現速度與清晰度。', 1763604997088, 1763604997088);
INSERT OR IGNORE INTO 'ai_comprehension_option'('id', 'mcq_id', 'label', 'text_from', 'text_to', 'created_at', 'updated_at') VALUES (28, 7, 'D', 'A chance to merge with Reform UK.', '與改革黨合併的機會。', 1763604997088, 1763604997088);
INSERT OR IGNORE INTO 'ai_comprehension_option'('id', 'mcq_id', 'label', 'text_from', 'text_to', 'created_at', 'updated_at') VALUES (29, 8, 'A', 'Once a party is written off, it can never return.', '一旦被宣判無望，該黨永遠不可能復甦。', 1763604997088, 1763604997088);
INSERT OR IGNORE INTO 'ai_comprehension_option'('id', 'mcq_id', 'label', 'text_from', 'text_to', 'created_at', 'updated_at') VALUES (30, 8, 'B', 'Political decline is permanent and predictable.', '政治衰落是永久且可預測的。', 1763604997088, 1763604997088);
INSERT OR IGNORE INTO 'ai_comprehension_option'('id', 'mcq_id', 'label', 'text_from', 'text_to', 'created_at', 'updated_at') VALUES (31, 8, 'C', 'Parties can be declared hopeless at times but may still recover with strategy and luck.', '政黨有時會被認為無望，但仍可能藉策略與運氣復甦。', 1763604997088, 1763604997088);
INSERT OR IGNORE INTO 'ai_comprehension_option'('id', 'mcq_id', 'label', 'text_from', 'text_to', 'created_at', 'updated_at') VALUES (32, 8, 'D', 'Recovery happens only when opponents disappear.', '只有在對手消失時才會復甦。', 1763604997088, 1763604997088);
INSERT OR IGNORE INTO 'ai_comprehension_option'('id', 'mcq_id', 'label', 'text_from', 'text_to', 'created_at', 'updated_at') VALUES (33, 9, 'A', '2024–25 年', '2024–25 年', 1763607808017, 1763607808017);
INSERT OR IGNORE INTO 'ai_comprehension_option'('id', 'mcq_id', 'label', 'text_from', 'text_to', 'created_at', 'updated_at') VALUES (34, 9, 'B', '2026–27 年', '2026–27 年', 1763607808017, 1763607808017);
INSERT OR IGNORE INTO 'ai_comprehension_option'('id', 'mcq_id', 'label', 'text_from', 'text_to', 'created_at', 'updated_at') VALUES (35, 9, 'C', '2030–31 年', '2030–31 年', 1763607808017, 1763607808017);
INSERT OR IGNORE INTO 'ai_comprehension_option'('id', 'mcq_id', 'label', 'text_from', 'text_to', 'created_at', 'updated_at') VALUES (36, 9, 'D', '尚未計畫發行', 'まだ發行を計畫していない', 1763607808017, 1763607808017);
INSERT OR IGNORE INTO 'ai_comprehension_option'('id', 'mcq_id', 'label', 'text_from', 'text_to', 'created_at', 'updated_at') VALUES (37, 10, 'A', '向投資人借款，用於基礎建設和資本支出', '投資家から借入れ、基礎建設や資本支出に使う', 1763607808017, 1763607808017);
INSERT OR IGNORE INTO 'ai_comprehension_option'('id', 'mcq_id', 'label', 'text_from', 'text_to', 'created_at', 'updated_at') VALUES (38, 10, 'B', '提高稅收收入', '税収を増やす', 1763607808017, 1763607808017);
INSERT OR IGNORE INTO 'ai_comprehension_option'('id', 'mcq_id', 'label', 'text_from', 'text_to', 'created_at', 'updated_at') VALUES (39, 10, 'C', '減少通膨', 'インフレを下げる', 1763607808017, 1763607808017);
INSERT OR IGNORE INTO 'ai_comprehension_option'('id', 'mcq_id', 'label', 'text_from', 'text_to', 'created_at', 'updated_at') VALUES (40, 10, 'D', '取代所有中央基金借款', '全ての中央基金借款に取って代わる', 1763607808017, 1763607808017);
INSERT OR IGNORE INTO 'ai_comprehension_option'('id', 'mcq_id', 'label', 'text_from', 'text_to', 'created_at', 'updated_at') VALUES (41, 11, 'A', '評級很低，風險高', '評級が非常に低くリスクが高い', 1763607808017, 1763607808017);
INSERT OR IGNORE INTO 'ai_comprehension_option'('id', 'mcq_id', 'label', 'text_from', 'text_to', 'created_at', 'updated_at') VALUES (42, 11, 'B', '與英國相同評級，理由包括財政管理與經濟穩定', '英國と同じ評級で、財政管理と経済の安定が理由だ', 1763607808017, 1763607808017);
INSERT OR IGNORE INTO 'ai_comprehension_option'('id', 'mcq_id', 'label', 'text_from', 'text_to', 'created_at', 'updated_at') VALUES (43, 11, 'C', '建議立即停止所有借款', 'すぐに全ての借入を止めることを勧めている', 1763607808017, 1763607808017);
INSERT OR IGNORE INTO 'ai_comprehension_option'('id', 'mcq_id', 'label', 'text_from', 'text_to', 'created_at', 'updated_at') VALUES (44, 11, 'D', '評級只看政治因素，不看經濟', '評級は政治要因のみを見て経済は見ない', 1763607808017, 1763607808017);
INSERT OR IGNORE INTO 'ai_comprehension_option'('id', 'mcq_id', 'label', 'text_from', 'text_to', 'created_at', 'updated_at') VALUES (45, 12, 'A', '發行時程會受選舉影響', '發行時程は選挙に影響される', 1763607808017, 1763607808017);
INSERT OR IGNORE INTO 'ai_comprehension_option'('id', 'mcq_id', 'label', 'text_from', 'text_to', 'created_at', 'updated_at') VALUES (46, 12, 'B', '政府會與銀行接洽，選出承銷商', '政府は銀行と協議し承銷商を選ぶ', 1763607808017, 1763607808017);
INSERT OR IGNORE INTO 'ai_comprehension_option'('id', 'mcq_id', 'label', 'text_from', 'text_to', 'created_at', 'updated_at') VALUES (47, 12, 'C', '公債名稱總是叫做gilt', '公債の名前はいつもgiltである', 1763607808017, 1763607808017);
INSERT OR IGNORE INTO 'ai_comprehension_option'('id', 'mcq_id', 'label', 'text_from', 'text_to', 'created_at', 'updated_at') VALUES (48, 12, 'D', '發行可增加融資來源，但市場條件會左右結果', '發行は資金調達の來源を増やすが、市場条件が結果を左右する', 1763607808017, 1763607808017);
INSERT OR IGNORE INTO 'ai_comprehension_option'('id', 'mcq_id', 'label', 'text_from', 'text_to', 'created_at', 'updated_at') VALUES (1, 1, 'A', 'They evolved a DNA repair mechanism involving cGAS that promotes genomic maintenance.', '牠們演化出一套包含 cGAS 的 DNA 修復機制，可促進基因組維護。', 1763604216013, 1763604216013);
INSERT OR IGNORE INTO 'ai_comprehension_option'('id', 'mcq_id', 'label', 'text_from', 'text_to', 'created_at', 'updated_at') VALUES (2, 1, 'B', 'They have no DNA damage, which explains their long lifespan.', '牠們沒有 DNA 損傷，因而解釋了牠們的長壽。', 1763604216013, 1763604216013);
INSERT OR IGNORE INTO 'ai_comprehension_option'('id', 'mcq_id', 'label', 'text_from', 'text_to', 'created_at', 'updated_at') VALUES (3, 1, 'C', 'They share the exact same cGAS function as humans do.', '牠們與人類的 cGAS 功能完全相同。', 1763604216013, 1763604216013);
INSERT OR IGNORE INTO 'ai_comprehension_option'('id', 'mcq_id', 'label', 'text_from', 'text_to', 'created_at', 'updated_at') VALUES (4, 1, 'D', 'They cannot be used to study ageing because their biology is too different.', '牠們無法用來研究老化，因為牠們的生物學太不同。', 1763604216013, 1763604216013);
INSERT OR IGNORE INTO 'ai_comprehension_option'('id', 'mcq_id', 'label', 'text_from', 'text_to', 'created_at', 'updated_at') VALUES (5, 2, 'A', 'Human cGAS promotes repair while mole‑rat cGAS interferes with repair.', '人類的 cGAS 促進修復，而裸鼴鼠的 cGAS 干擾修復。', 1763604216013, 1763604216013);
INSERT OR IGNORE INTO 'ai_comprehension_option'('id', 'mcq_id', 'label', 'text_from', 'text_to', 'created_at', 'updated_at') VALUES (6, 2, 'B', 'Human cGAS interferes with repair; mole‑rat cGAS promotes repair.', '人類的 cGAS 會干擾修復；裸鼴鼠的 cGAS 則促進修復。', 1763604216013, 1763604216013);
INSERT OR IGNORE INTO 'ai_comprehension_option'('id', 'mcq_id', 'label', 'text_from', 'text_to', 'created_at', 'updated_at') VALUES (7, 2, 'C', 'Both function identically in detecting DNA damage.', '兩者在偵測 DNA 損傷方面功能相同。', 1763604216013, 1763604216013);
INSERT OR IGNORE INTO 'ai_comprehension_option'('id', 'mcq_id', 'label', 'text_from', 'text_to', 'created_at', 'updated_at') VALUES (8, 2, 'D', 'Neither species uses cGAS in any DNA processes.', '兩個物種都不在任何 DNA 過程中使用 cGAS。', 1763604216013, 1763604216013);
INSERT OR IGNORE INTO 'ai_comprehension_option'('id', 'mcq_id', 'label', 'text_from', 'text_to', 'created_at', 'updated_at') VALUES (9, 3, 'A', 'Inspiring new therapies to preserve function and reduce disease in ageing humans.', '啟發新的療法以保護功能並減少人類老化相關疾病。', 1763604216013, 1763604216013);
INSERT OR IGNORE INTO 'ai_comprehension_option'('id', 'mcq_id', 'label', 'text_from', 'text_to', 'created_at', 'updated_at') VALUES (10, 3, 'B', 'Proving that humans already have the same DNA repair mechanism.', '證明人類已經擁有相同的 DNA 修復機制。', 1763604216013, 1763604216013);
INSERT OR IGNORE INTO 'ai_comprehension_option'('id', 'mcq_id', 'label', 'text_from', 'text_to', 'created_at', 'updated_at') VALUES (11, 3, 'C', 'Showing that mole rats do not age at all.', '證明裸鼴鼠根本不會老化。', 1763604216013, 1763604216013);
INSERT OR IGNORE INTO 'ai_comprehension_option'('id', 'mcq_id', 'label', 'text_from', 'text_to', 'created_at', 'updated_at') VALUES (12, 3, 'D', 'Replacing all human genes with mole‑rat genes immediately.', '立即用裸鼴鼠的基因替換所有人類基因。', 1763604216013, 1763604216013);
INSERT OR IGNORE INTO 'ai_comprehension_option'('id', 'mcq_id', 'label', 'text_from', 'text_to', 'created_at', 'updated_at') VALUES (13, 4, 'A', 'The finding is a small, visible part of a much larger set of unknowns to be explored.', '此發現只是更大未知領域中可見的一小部分，還有很多需探索的內容。', 1763604216013, 1763604216013);
INSERT OR IGNORE INTO 'ai_comprehension_option'('id', 'mcq_id', 'label', 'text_from', 'text_to', 'created_at', 'updated_at') VALUES (14, 4, 'B', 'The finding is the only important discovery about mole rats.', '此發現是關於裸鼴鼠的唯一重要發現。', 1763604216013, 1763604216013);
INSERT OR IGNORE INTO 'ai_comprehension_option'('id', 'mcq_id', 'label', 'text_from', 'text_to', 'created_at', 'updated_at') VALUES (15, 4, 'C', 'The discovery disproves any further research on the species.', '此發現否定了對該物種進一步研究的必要性。', 1763604216013, 1763604216013);
INSERT OR IGNORE INTO 'ai_comprehension_option'('id', 'mcq_id', 'label', 'text_from', 'text_to', 'created_at', 'updated_at') VALUES (16, 4, 'D', 'The discovery is irrelevant to understanding longevity.', '此發現與理解長壽無關。', 1763604216013, 1763604216013);
INSERT OR IGNORE INTO 'ai_comprehension_option'('id', 'mcq_id', 'label', 'text_from', 'text_to', 'created_at', 'updated_at') VALUES (17, 5, 'A', 'That the party has become too popular and must slow down reform.', '該黨變得過於受歡迎，必須放慢改革腳步。', 1763604997088, 1763604997088);
INSERT OR IGNORE INTO 'ai_comprehension_option'('id', 'mcq_id', 'label', 'text_from', 'text_to', 'created_at', 'updated_at') VALUES (18, 5, 'B', 'That its relevance and coherent political role are unclear after defeats and defections.', '在敗選與議員倒戈之後，其相關性與一致的政治角色不清楚。', 1763604997088, 1763604997088);
INSERT OR IGNORE INTO 'ai_comprehension_option'('id', 'mcq_id', 'label', 'text_from', 'text_to', 'created_at', 'updated_at') VALUES (19, 5, 'C', 'That Kemi Badenoch has already solved the party''s problems.', 'Kemi Badenoch 已經解決了黨的問題。', 1763604997088, 1763604997088);
INSERT OR IGNORE INTO 'ai_comprehension_option'('id', 'mcq_id', 'label', 'text_from', 'text_to', 'created_at', 'updated_at') VALUES (20, 5, 'D', 'That Reform UK will merge with the Conservatives soon.', '改革黨很快就會與保守黨合併。', 1763604997088, 1763604997088);
INSERT OR IGNORE INTO 'ai_comprehension_option'('id', 'mcq_id', 'label', 'text_from', 'text_to', 'created_at', 'updated_at') VALUES (21, 6, 'A', 'Whether to disband the party and join Labour.', '是否解散黨並加入工黨。', 1763604997088, 1763604997088);
INSERT OR IGNORE INTO 'ai_comprehension_option'('id', 'mcq_id', 'label', 'text_from', 'text_to', 'created_at', 'updated_at') VALUES (22, 6, 'B', 'Whether to adopt Reform UK''s policies wholesale or stay completely unchanged.', '是否完全採用改革黨的政策或完全維持不變。', 1763604997088, 1763604997088);
INSERT OR IGNORE INTO 'ai_comprehension_option'('id', 'mcq_id', 'label', 'text_from', 'text_to', 'created_at', 'updated_at') VALUES (23, 6, 'C', 'Whether to compete for Reform''s right‑leaning voters or shift toward the centre to attract moderates.', '是與改革黨爭奪右傾選民，或轉向中間以吸引溫和派。', 1763604997088, 1763604997088);
INSERT OR IGNORE INTO 'ai_comprehension_option'('id', 'mcq_id', 'label', 'text_from', 'text_to', 'created_at', 'updated_at') VALUES (24, 6, 'D', 'Whether to avoid all public appearances until the next election.', '是否在下次選舉前避免所有公開露面。', 1763604997088, 1763604997088);
INSERT OR IGNORE INTO 'ai_comprehension_option'('id', 'mcq_id', 'label', 'text_from', 'text_to', 'created_at', 'updated_at') VALUES (25, 7, 'A', 'An unlimited guarantee that the party will win the next election.', '保證該黨一定會贏得下一次選舉。', 1763604997088, 1763604997088);
INSERT OR IGNORE INTO 'ai_comprehension_option'('id', 'mcq_id', 'label', 'text_from', 'text_to', 'created_at', 'updated_at') VALUES (26, 7, 'B', 'A critical but limited opportunity to present coherent policies and a clearer narrative.', '一個關鍵但有限的機會，用來提出具一致性的政策與更清楚的說法。', 1763604997088, 1763604997088);
INSERT OR IGNORE INTO 'ai_comprehension_option'('id', 'mcq_id', 'label', 'text_from', 'text_to', 'created_at', 'updated_at') VALUES (27, 7, 'C', 'A social event with no political significance.', '一個沒有政治意義的社交活動。', 1763604997088, 1763604997088);
