INSERT INTO lost_and_found VALUES(49, 49, 14, 1, 1178, 1763020369984, NULL, 1763012753000, 1, 1763020369984, 'en-GB', 'I can&#039;t take any more of this, Andrew told Epstein, released emails show', 'https://www.bbc.com/news/articles/cglgj08erywo?at_medium=RSS&at_campaign=rss', 'https://www.bbc.com/news/articles/cglgj08erywo?at_medium=RSS&at_campaign=rss', NULL, '<div data-component="headline-block" class="sc-3b6b161a-0 hNbOGD"><h1 class="sc-f98b1ad2-0 idLnWK">I can''t take any more of this, Andrew told Epstein, released emails show</h1></div><div data-component="byline-block" class="sc-3b6b161a-0 dPVOKT"><div data-testid="byline-new" class="sc-7bfdb3c2-0 fYJjWP"><div class="sc-7bfdb3c2-1 jqWinX"><time datetime="2025-11-13T05:45:53.309Z" class="sc-7bfdb3c2-2 dQuPjg">2 hours ago</time><div class="sc-7bfdb3c2-3 dVvYwG"></div></div><span data-testid="byline-new-contributors" class="sc-7bfdb3c2-11 ljQVMv"><span class="sc-7bfdb3c2-7 byKoUE">Sean Dilley,</span><span data-testid="byline-new-contributors-contributor-0-role-location" class="sc-7bfdb3c2-8 gTWlHk">North America Correspondent</span><span class="sc-7bfdb3c2-9 bTXCSY">, </span></span></div><div data-testid="byline-new-contributors-contributor-1" class="sc-7bfdb3c2-5 fMReXM"><span class="sc-7bfdb3c2-7 byKoUE">Ed Campbell,</span><span data-testid="byline-new-contributors-contributor-1-role-location" class="sc-7bfdb3c2-8 gTWlHk">BBC News Investigations</span><span class="sc-7bfdb3c2-9 bTXCSY"> and </span></div><div data-testid="byline-new-contributors-contributor-2" class="sc-7bfdb3c2-5 fMReXM"><span class="sc-7bfdb3c2-7 byKoUE">Chris Graham</span></div><div class="sc-7bfdb3c2-4 haycoC"></div></div><figure><div data-component="image-block" class="sc-3b6b161a-0 gtLOOD"><div data-testid="hero-image" class="sc-5340b511-1 cMIbKV"><img srcset="https://ichef.bbci.co.uk/news/240/cpsprodpb/24f2/live/b9cd45c0-c05b-11f0-8669-5560f5c90fbe.jpg.webp 240w, https://ichef.bbci.co.uk/news/320/cpsprodpb/24f2/live/b9cd45c0-c05b-11f0-8669-5560f5c90fbe.jpg.webp 320w, https://ichef.bbci.co.uk/news/480/cpsprodpb/24f2/live/b9cd45c0-c05b-11f0-8669-5560f5c90fbe.jpg.webp 480w, https://ichef.bbci.co.uk/news/640/cpsprodpb/24f2/live/b9cd45c0-c05b-11f0-8669-5560f5c90fbe.jpg.webp 640w, https://ichef.bbci.co.uk/news/800/cpsprodpb/24f2/live/b9cd45c0-c05b-11f0-8669-5560f5c90fbe.jpg.webp 800w, https://ichef.bbci.co.uk/news/1024/cpsprodpb/24f2/live/b9cd45c0-c05b-11f0-8669-5560f5c90fbe.jpg.webp 1024w, https://ichef.bbci.co.uk/news/1536/cpsprodpb/24f2/live/b9cd45c0-c05b-11f0-8669-5560f5c90fbe.jpg.webp 1536w" src="https://ichef.bbci.co.uk/news/480/cpsprodpb/24f2/live/b9cd45c0-c05b-11f0-8669-5560f5c90fbe.jpg.webp" alt="Indigo / Getty Images A close head and shoulders crop shows Andrew looking down towards the floor while wearing a suit and red tie against a neutral green background with heavy bokeh, in Ascot in 2019." class="sc-5340b511-0 hLdNfA" /><span class="sc-5340b511-2 jVqbAn">Indigo / Getty Images</span></div></div><div data-component="caption-block" class="sc-3b6b161a-0 Qwxkf"></div></figure><div data-component="text-block" class="sc-3b6b161a-0 dPVOKT"><p class="sc-9a00e533-0 eZyhnA">Andrew Mountbatten-Windsor told Jeffrey Epstein and Ghislaine Maxwell "I can''t take any more of this",<b id="" class="sc-d16436d-0 gnUCoQ"> </b>when he was first alerted 14 years ago that a British newspaper was about to run a report about the trio.</p><p class="sc-9a00e533-0 eZyhnA">His email conversation with the US-based pair was among documents from the estate of the convicted sex offender Epstein that were released on Wednesday, including some mentioning Donald Trump. </p><p class="sc-9a00e533-0 eZyhnA">The former prince''s response came after he was forwarded a right-of-reply email that the Mail on Sunday had sent Maxwell in March 2011, which made numerous claims about Andrew.</p><p class="sc-9a00e533-0 eZyhnA">According to files released on Wednesday, Andrew''s reply reads: "What''s all this? I don''t know anything about this! You must SAY so please. This has NOTHING to do with me. I can''t take any more of this."</p></div><div data-testid="ad-unit" data-component="ad-slot" class="sc-1b734f04-0 kNNIux"><div data-testid="dotcom-mid_1" id="dotcom-mid_1" class="dotcom-ad"></div></div><div data-component="text-block" class="sc-3b6b161a-0 dPVOKT"><p class="sc-9a00e533-0 eZyhnA">The latest release comes after Andrew was requested by Democrats in US Congress to answer questions as part of its investigation into Epstein, who died in jail in 2019 while awaiting trial on sex trafficking offences.</p><p class="sc-9a00e533-0 eZyhnA">Democratic member of the House Oversight Committee, Congressman Suhas Subramanyam, told BBC Two''s Newsnight that Andrew had not yet responded to the Committee''s invitation to testify before the committee. </p><p class="sc-9a00e533-0 eZyhnA">He said the former prince "doesn''t have to get on a plane to testify, he can do it remotely". </p><p class="sc-9a00e533-0 eZyhnA">Virginia Giuffre - a prominent accuser of Jeffrey Epstein - <a target="_self" href="https://www.bbc.com/news/articles/c1e3leqx89zo" class="sc-f9178328-0 iCaRzc">alleged Andrew had sex with her three times as a teenager</a>. </p><p class="sc-9a00e533-0 eZyhnA">Andrew, who has denied the allegations, reached an out-of-court settlement with Giuffre in 2022 which contained no admission of liability or apology.</p><p class="sc-9a00e533-0 eZyhnA">He <a target="_self" href="https://www.bbc.com/news/articles/cvgmkm8516ko" class="sc-f9178328-0 iCaRzc">was stripped of all his titles</a> earlier this month after Giuffre''s posthumous memoir threw new focus on Andrew''s ties to Epstein and Maxwell.</p></div><div data-component="subheadline-block" class="sc-3b6b161a-0 hNbOGD"><h2 class="sc-f98b1ad2-0 gXmhTb">Trump mentioned in emails</h2></div><div data-component="video-block" data-testid="fabl-video-container" class="sc-3b6b161a-0 gXrNRM"><div class="sc-2218ed0c-1 fiqjXZ"><div data-testid="" class="sc-2218ed0c-2 bgTyRA"></div></div></div><div data-component="caption-block" class="sc-3b6b161a-0 Qwxkf"></div><div data-testid="ad-unit" data-component="ad-slot" class="sc-1b734f04-0 kNNIux"><div data-testid="dotcom-mid_2" id="dotcom-mid_2" class="dotcom-ad"></div></div><div data-component="text-block" class="sc-3b6b161a-0 dPVOKT"><p class="sc-9a00e533-0 eZyhnA">Three emails from the Epstein estate, <a target="_self" href="https://www.bbc.com/news/articles/c3rj0d97ynvo" class="sc-f9178328-0 iCaRzc">released by Democrats on the Congressional House Oversight Committee</a>, indicate that Trump was mentioned several times by Epstein in emails exchanged with Maxwell, who is currently serving a 20-year prison sentence for sex trafficking. </p><p class="sc-9a00e533-0 eZyhnA">They also released emails between Epstein and the author Michael Wolff, who has written numerous books about Trump.</p><p class="sc-9a00e533-0 eZyhnA">One email from Epstein to Maxwell, sent in April 2011, claims that Trump spent hours at Epstein''s house with a person whose name was redacted.</p><p class="sc-9a00e533-0 eZyhnA">Epstein wrote: "I want you to realize that the dog that hasn''t barked is Trump.. [VICTIM] spent hours at my house with him."</p><p class="sc-9a00e533-0 eZyhnA">The White House later said the unnamed "victim" referenced was Giuffre, who died by suicide earlier this year. </p><p class="sc-9a00e533-0 eZyhnA">In a statement, the White House said Giuffre "repeatedly said President Trump was not involved in any wrongdoing whatsoever and ''couldn''t have been friendlier'' to her in their limited interactions".</p><p class="sc-9a00e533-0 eZyhnA">Giuffre said in a 2016 deposition that she never saw Trump participate in any abuse. And in a memoir released this year, she did not accuse the president of any wrongdoing.</p><p class="sc-9a00e533-0 eZyhnA">Within hours, House Republicans then released thousands more documents to counter what they said was a Democratic effort to "cherry-pick" documents. They also said it had been an attempt to "create a fake narrative to slander President Trump".</p><p class="sc-9a00e533-0 eZyhnA">Hours after the latest publication of emails, the newly-sworn in Democratic Congresswoman Adelita Grijalva signed a petition, meaning it now has sufficient numbers to force a House vote that could require the US Department of Justice to release all the Epstein files.</p><p class="sc-9a00e533-0 eZyhnA">The office of House of Representatives Speaker Mike Johnson said the House would hold that vote next week.</p></div><div data-component="subheadline-block" class="sc-3b6b161a-0 hNbOGD"><h2 class="sc-f98b1ad2-0 gXmhTb">Epstein on Andrew photo</h2></div><figure><div data-component="image-block" class="sc-3b6b161a-0 gXrNRM"><div data-testid="image" class="sc-5340b511-1 cMIbKV"><img srcset="https://ichef.bbci.co.uk/news/240/cpsprodpb/7f2d/live/b8fc2b30-c03c-11f0-8456-eff94716b162.jpg.webp 240w, https://ichef.bbci.co.uk/news/320/cpsprodpb/7f2d/live/b8fc2b30-c03c-11f0-8456-eff94716b162.jpg.webp 320w, https://ichef.bbci.co.uk/news/480/cpsprodpb/7f2d/live/b8fc2b30-c03c-11f0-8456-eff94716b162.jpg.webp 480w, https://ichef.bbci.co.uk/news/640/cpsprodpb/7f2d/live/b8fc2b30-c03c-11f0-8456-eff94716b162.jpg.webp 640w, https://ichef.bbci.co.uk/news/800/cpsprodpb/7f2d/live/b8fc2b30-c03c-11f0-8456-eff94716b162.jpg.webp 800w, https://ichef.bbci.co.uk/news/1024/cpsprodpb/7f2d/live/b8fc2b30-c03c-11f0-8456-eff94716b162.jpg.webp 1024w, https://ichef.bbci.co.uk/news/1536/cpsprodpb/7f2d/live/b8fc2b30-c03c-11f0-8456-eff94716b162.jpg.webp 1536w" src="https://ichef.bbci.co.uk/news/480/cpsprodpb/7f2d/live/b8fc2b30-c03c-11f0-8456-eff94716b162.jpg.webp" alt="PA Media Andrew is seen with his arm around Virginia Giuffre, with Ghislaine Maxwell in the background." class="sc-5340b511-0 hLdNfA" /><span class="sc-5340b511-2 jVqbAn">PA Media</span></div></div><div data-component="caption-block" class="sc-3b6b161a-0 Qwxkf"></div></figure><div data-testid="ad-unit" data-component="ad-slot" class="sc-1b734f04-0 kNNIux"><div data-testid="dotcom-mid_3" id="dotcom-mid_3" class="dotcom-ad"></div></div><div data-component="text-block" class="sc-3b6b161a-0 dPVOKT"><p class="sc-9a00e533-0 eZyhnA">The latest files shed further light on the relationship between Andrew and Epstein, with one email appearing to confirm a photograph of Andrew with his arm around a 17-year-old Giuffre was real. </p><p class="sc-9a00e533-0 eZyhnA">In an exchange with a journalist in July 2011, Epstein appeared to discuss Giuffre and her photograph with Andrew. </p><p class="sc-9a00e533-0 eZyhnA">"Yes she was on my plane, and yes she had her picture taken with Andrew, as many of my employees have," he wrote. </p><p class="sc-9a00e533-0 eZyhnA">Andrew said in his 2019 Newsnight interview that he had no recollection of that photo being taken and has suggested it might be fake.</p><p class="sc-9a00e533-0 eZyhnA">That exchange came four months after the purported "right of reply" email from the Mail on Sunday on 4 March 2011. </p><p class="sc-9a00e533-0 eZyhnA">The email states that a woman, whose name is redacted in the released document, was introduced to Andrew by the disgraced financier in 2001, at Maxwell''s house in London where she had sex with Andrew.</p><p class="sc-9a00e533-0 eZyhnA">On 6 March 2011 the Mail on Sunday published a story including the now infamous photograph of Andrew and Giuffre.</p><p class="sc-9a00e533-0 eZyhnA">The email goes on to say that the masseuse and another girl were directed to sit on Andrew''s knee in Epstein''s New York flat, and that he groped both girls. </p><p class="sc-9a00e533-0 eZyhnA">The email says that one of the girls was directed by Maxwell to have sex with Andrew. It also states she was directed to participate in an orgy with Andrew at Little St James - Epstein''s private Caribbean island. It requests a reply by noon the next day.</p><p class="sc-9a00e533-0 eZyhnA">It appears that the email is sent to Maxwell by her representative, forwarded on to Epstein and then to a redacted email address marked "The Duke".</p><p class="sc-9a00e533-0 eZyhnA">On 6 March 2011, the day the Mail on Sunday published its Giuffre story, Epstein emails "The Duke", asking: "You ok?". He add: "These stories are complete and utter fantasy".</p><p class="sc-9a00e533-0 eZyhnA">In an email to his publicist in July that year, Epstein writes: "The girl who accused Prince Andrew can also easily be proven to be a liar.</p><p class="sc-9a00e533-0 eZyhnA">"I think Buckingham Palace would love it. You should task someone to investigate the girl Virginia Roberts, that has caused the Queen''s son all this agro (sic).</p><p class="sc-9a00e533-0 eZyhnA">"I promise you she is a fraud. You and I will be able to go to ascot (sic) for the rest of our lives."</p></div><div data-component="subheadline-block" class="sc-3b6b161a-0 hNbOGD"><h2 class="sc-f98b1ad2-0 gXmhTb">Mandelson in contact in 2016</h2></div><figure><div data-component="image-block" class="sc-3b6b161a-0 gXrNRM"><div data-testid="image" class="sc-5340b511-1 cMIbKV"><img srcset="https://ichef.bbci.co.uk/news/240/cpsprodpb/82f6/live/f26fa530-c038-11f0-ae46-bd64331f0fd4.jpg.webp 240w, https://ichef.bbci.co.uk/news/320/cpsprodpb/82f6/live/f26fa530-c038-11f0-ae46-bd64331f0fd4.jpg.webp 320w, https://ichef.bbci.co.uk/news/480/cpsprodpb/82f6/live/f26fa530-c038-11f0-ae46-bd64331f0fd4.jpg.webp 480w, https://ichef.bbci.co.uk/news/640/cpsprodpb/82f6/live/f26fa530-c038-11f0-ae46-bd64331f0fd4.jpg.webp 640w, https://ichef.bbci.co.uk/news/800/cpsprodpb/82f6/live/f26fa530-c038-11f0-ae46-bd64331f0fd4.jpg.webp 800w, https://ichef.bbci.co.uk/news/1024/cpsprodpb/82f6/live/f26fa530-c038-11f0-ae46-bd64331f0fd4.jpg.webp 1024w, https://ichef.bbci.co.uk/news/1536/cpsprodpb/82f6/live/f26fa530-c038-11f0-ae46-bd64331f0fd4.jpg.webp 1536w" src="https://ichef.bbci.co.uk/news/480/cpsprodpb/82f6/live/f26fa530-c038-11f0-ae46-bd64331f0fd4.jpg.webp" alt="PA Media Peter Mandelson, wearing black framed glasses, a black suit, shite shirt, and blue tie" class="sc-5340b511-0 hLdNfA" /><span class="sc-5340b511-2 jVqbAn">PA Media</span></div></div><div data-component="caption-block" class="sc-3b6b161a-0 Qwxkf"></div></figure><div data-component="text-block" class="sc-3b6b161a-0 dPVOKT"><p class="sc-9a00e533-0 eZyhnA">Lord Mandelson <a target="_self" href="https://www.bbc.com/news/articles/c0jdl8wzvnvo" class="sc-f9178328-0 iCaRzc">also appears in the newly released documents</a>, which show he had contact with Epstein as late as 2016.</p><p class="sc-9a00e533-0 eZyhnA">The latest previous reported contact between the pair was when the then-business secretary took advice from Epstein in a banking deal in March 2010, just months after the American businessman''s release from prison for child sex offences, as reported by the Daily Telegraph.</p><p class="sc-9a00e533-0 eZyhnA">The new documents include an email from Epstein to Lord Mandelson on 6 November 2016, shortly after the peer''s birthday, saying "63 years old. You made it".</p><p class="sc-9a00e533-0 eZyhnA">Lord Mandelson replies less than 90 minutes later saying: "Just. I have decided to extend my life by spending more of it in the US".</p><p class="sc-9a00e533-0 eZyhnA">Epstein then replies "in the Donald White House", referring to the US presidential election due later that week.</p><p class="sc-9a00e533-0 eZyhnA">Lord Mandelson was sacked as the UK''s ambassador to the US in September over his links to Epstein, after emails showed the peer sent him supportive messages after he pleaded guilty to soliciting a minor in 2008.</p><p class="sc-9a00e533-0 eZyhnA">Lord Mandelson, who has repeatedly said he regrets his relationship with Epstein,  declined to comment on the emails when approached by the BBC.</p></div><div data-component="links-block" class="sc-3b6b161a-0 djqsWD"><div class="sc-666b6d83-0 sc-c4fb5674-0 jYmMqa kGPvxx"><div data-testid="links-grid" class="sc-666b6d83-0 sc-c4fb5674-1 gEjRXC jkjVgq"><div data-testid="chester-card" data-indexcard="true" class="sc-225578b-0 ezQaGx"><div data-testid="anchor-inner-wrapper"><a href="https://www.bbc.com/news/articles/c0jdl8wzvnvo" data-testid="external-anchor" target="_self" class="sc-8a623a54-0 huZCWi"><div data-testid="chester-article" class="sc-cf565bcc-0 kwPVOm"><div class="sc-fa814188-1 iRoJZi"><div class="sc-fa814188-0 hPhBqv"><h2 data-testid="card-headline" class="sc-fa814188-3 iCfgww">Mandelson still in contact with Epstein in 2016, emails show</h2></div></div></div></a></div></div><div data-testid="chester-card" data-indexcard="true" class="sc-225578b-0 ezQaGx"><div data-testid="anchor-inner-wrapper"><a href="https://www.bbc.com/news/articles/c3rj0d97ynvo" data-testid="external-anchor" target="_self" class="sc-8a623a54-0 huZCWi"><div data-testid="chester-article" class="sc-cf565bcc-0 kwPVOm"><div class="sc-fa814188-1 iRoJZi"><div class="sc-fa814188-0 hPhBqv"><h2 data-testid="card-headline" class="sc-fa814188-3 iCfgww">What we know about new Epstein emails that mention Trump</h2></div></div></div></a></div></div></div></div></div><div data-component="tags" class="sc-3b6b161a-0 djqsWD"><div class="sc-6bf80075-0 lllwyY"><div data-testid="anchor-inner-wrapper"><a href="https://www.bbc.com/news/topics/c28511xee27t" data-testid="internal-link" class="sc-57521d02-0 jsVxCb">Andrew Mountbatten Windsor</a></div><div data-testid="anchor-inner-wrapper"><a href="https://www.bbc.com/news/topics/ck8vkvd8q9dt" data-testid="internal-link" class="sc-57521d02-0 jsVxCb">Ghislaine Maxwell</a></div><div data-testid="anchor-inner-wrapper"><a href="https://www.bbc.com/news/topics/cl7003r72r4t" data-testid="internal-link" class="sc-57521d02-0 jsVxCb">Jeffrey Epstein</a></div><div data-testid="anchor-inner-wrapper"><a href="https://www.bbc.com/news/topics/cp7r8vgl2lgt" data-testid="internal-link" class="sc-57521d02-0 jsVxCb">Donald Trump</a></div><div data-testid="anchor-inner-wrapper"><a href="https://www.bbc.com/news/topics/cx1m7zg01xyt" data-testid="internal-link" class="sc-57521d02-0 jsVxCb">United States</a></div></div></div>', NULL, '<div data-component="headline-block" class="sc-3b6b161a-0 hNbOGD"><h1 class="sc-f98b1ad2-0 idLnWK">I can''t take any more of this, Andrew told Epstein, released emails show</h1></div><div data-component="byline-block" class="sc-3b6b161a-0 dPVOKT"><div data-testid="byline-new" class="sc-7bfdb3c2-0 fYJjWP"><div class="sc-7bfdb3c2-1 jqWinX"><time datetime="2025-11-13T05:45:53.309Z" class="sc-7bfdb3c2-2 dQuPjg">2 hours ago</time><div class="sc-7bfdb3c2-3 dVvYwG"></div></div><span data-testid="byline-new-contributors" class="sc-7bfdb3c2-11 ljQVMv"><div data-testid="byline-new-contributors-contributor-0" class="sc-7bfdb3c2-5 fMReXM"><span class="sc-7bfdb3c2-7 byKoUE">Sean Dilley,</span><span data-testid="byline-new-contributors-contributor-0-role-location" class="sc-7bfdb3c2-8 gTWlHk">North America Correspondent</span><span class="sc-7bfdb3c2-9 bTXCSY">, </span></div><div data-testid="byline-new-contributors-contributor-1" class="sc-7bfdb3c2-5 fMReXM"><span class="sc-7bfdb3c2-7 byKoUE">Ed Campbell,</span><span data-testid="byline-new-contributors-contributor-1-role-location" class="sc-7bfdb3c2-8 gTWlHk">BBC News Investigations</span><span class="sc-7bfdb3c2-9 bTXCSY"> and </span></div><div data-testid="byline-new-contributors-contributor-2" class="sc-7bfdb3c2-5 fMReXM"><span class="sc-7bfdb3c2-7 byKoUE">Chris Graham</span></div></span><div class="sc-7bfdb3c2-4 haycoC"></div></div></div><figure><div data-component="image-block" class="sc-3b6b161a-0 gtLOOD"><div data-testid="hero-image" class="sc-5340b511-1 cMIbKV"><img sizes="(min-width: 1280px) 50vw, (min-width: 1008px) 66vw, 96vw" srcset="https://ichef.bbci.co.uk/news/240/cpsprodpb/24f2/live/b9cd45c0-c05b-11f0-8669-5560f5c90fbe.jpg.webp 240w,https://ichef.bbci.co.uk/news/320/cpsprodpb/24f2/live/b9cd45c0-c05b-11f0-8669-5560f5c90fbe.jpg.webp 320w,https://ichef.bbci.co.uk/news/480/cpsprodpb/24f2/live/b9cd45c0-c05b-11f0-8669-5560f5c90fbe.jpg.webp 480w,https://ichef.bbci.co.uk/news/640/cpsprodpb/24f2/live/b9cd45c0-c05b-11f0-8669-5560f5c90fbe.jpg.webp 640w,https://ichef.bbci.co.uk/news/800/cpsprodpb/24f2/live/b9cd45c0-c05b-11f0-8669-5560f5c90fbe.jpg.webp 800w,https://ichef.bbci.co.uk/news/1024/cpsprodpb/24f2/live/b9cd45c0-c05b-11f0-8669-5560f5c90fbe.jpg.webp 1024w,https://ichef.bbci.co.uk/news/1536/cpsprodpb/24f2/live/b9cd45c0-c05b-11f0-8669-5560f5c90fbe.jpg.webp 1536w" src="https://ichef.bbci.co.uk/news/480/cpsprodpb/24f2/live/b9cd45c0-c05b-11f0-8669-5560f5c90fbe.jpg.webp" loading="eager" alt="Indigo / Getty Images A close head and shoulders crop shows Andrew looking down towards the floor while wearing a suit and red tie against a neutral green background with heavy bokeh, in Ascot in 2019." class="sc-5340b511-0 hLdNfA"><span class="sc-5340b511-2 jVqbAn">Indigo / Getty Images</span></div></div><div data-component="caption-block" class="sc-3b6b161a-0 Qwxkf"></div></figure><div data-component="text-block" class="sc-3b6b161a-0 dPVOKT"><p class="sc-9a00e533-0 eZyhnA">Andrew Mountbatten-Windsor told Jeffrey Epstein and Ghislaine Maxwell "I can''t take any more of this",<b id class="sc-d16436d-0 gnUCoQ"> </b>when he was first alerted 14 years ago that a British newspaper was about to run a report about the trio.</p><p class="sc-9a00e533-0 eZyhnA">His email conversation with the US-based pair was among documents from the estate of the convicted sex offender Epstein that were released on Wednesday, including some mentioning Donald Trump. </p><p class="sc-9a00e533-0 eZyhnA">The former prince''s response came after he was forwarded a right-of-reply email that the Mail on Sunday had sent Maxwell in March 2011, which made numerous claims about Andrew.</p><p class="sc-9a00e533-0 eZyhnA">According to files released on Wednesday, Andrew''s reply reads: "What''s all this? I don''t know anything about this! You must SAY so please. This has NOTHING to do with me. I can''t take any more of this."</p></div><div data-testid="ad-unit" data-component="ad-slot" class="sc-1b734f04-0 kNNIux"><div data-testid="dotcom-mid_1" id="dotcom-mid_1" class="dotcom-ad"></div></div><div data-component="text-block" class="sc-3b6b161a-0 dPVOKT"><p class="sc-9a00e533-0 eZyhnA">The latest release comes after Andrew was requested by Democrats in US Congress to answer questions as part of its investigation into Epstein, who died in jail in 2019 while awaiting trial on sex trafficking offences.</p><p class="sc-9a00e533-0 eZyhnA">Democratic member of the House Oversight Committee, Congressman Suhas Subramanyam, told BBC Two''s Newsnight that Andrew had not yet responded to the Committee''s invitation to testify before the committee. </p><p class="sc-9a00e533-0 eZyhnA">He said the former prince "doesn''t have to get on a plane to testify, he can do it remotely". </p><p class="sc-9a00e533-0 eZyhnA">Virginia Giuffre - a prominent accuser of Jeffrey Epstein - <a target="_self" href="https://www.bbc.com/news/articles/c1e3leqx89zo" class="sc-f9178328-0 iCaRzc">alleged Andrew had sex with her three times as a teenager</a>. </p><p class="sc-9a00e533-0 eZyhnA">Andrew, who has denied the allegations, reached an out-of-court settlement with Giuffre in 2022 which contained no admission of liability or apology.</p><p class="sc-9a00e533-0 eZyhnA">He <a target="_self" href="https://www.bbc.com/news/articles/cvgmkm8516ko" class="sc-f9178328-0 iCaRzc">was stripped of all his titles</a> earlier this month after Giuffre''s posthumous memoir threw new focus on Andrew''s ties to Epstein and Maxwell.</p></div><div data-component="subheadline-block" class="sc-3b6b161a-0 hNbOGD"><h2 class="sc-f98b1ad2-0 gXmhTb">Trump mentioned in emails</h2></div><div data-component="video-block" data-testid="fabl-video-container" class="sc-3b6b161a-0 gXrNRM"><div class="sc-2218ed0c-1 fiqjXZ"><div data-testid style="visibility:hidden" class="sc-2218ed0c-2 bgTyRA"></div></div></div><div data-component="caption-block" class="sc-3b6b161a-0 Qwxkf"></div><div data-testid="ad-unit" data-component="ad-slot" class="sc-1b734f04-0 kNNIux"><div data-testid="dotcom-mid_2" id="dotcom-mid_2" class="dotcom-ad"></div></div><div data-component="text-block" class="sc-3b6b161a-0 dPVOKT"><p class="sc-9a00e533-0 eZyhnA">Three emails from the Epstein estate, <a target="_self" href="https://www.bbc.com/news/articles/c3rj0d97ynvo" class="sc-f9178328-0 iCaRzc">released by Democrats on the Congressional House Oversight Committee</a>, indicate that Trump was mentioned several times by Epstein in emails exchanged with Maxwell, who is currently serving a 20-year prison sentence for sex trafficking. </p><p class="sc-9a00e533-0 eZyhnA">They also released emails between Epstein and the author Michael Wolff, who has written numerous books about Trump.</p><p class="sc-9a00e533-0 eZyhnA">One email from Epstein to Maxwell, sent in April 2011, claims that Trump spent hours at Epstein''s house with a person whose name was redacted.</p><p class="sc-9a00e533-0 eZyhnA">Epstein wrote: "I want you to realize that the dog that hasn''t barked is Trump.. [VICTIM] spent hours at my house with him."</p><p class="sc-9a00e533-0 eZyhnA">The White House later said the unnamed "victim" referenced was Giuffre, who died by suicide earlier this year. </p><p class="sc-9a00e533-0 eZyhnA">In a statement, the White House said Giuffre "repeatedly said President Trump was not involved in any wrongdoing whatsoever and ''couldn''t have been friendlier'' to her in their limited interactions".</p><p class="sc-9a00e533-0 eZyhnA">Giuffre said in a 2016 deposition that she never saw Trump participate in any abuse. And in a memoir released this year, she did not accuse the president of any wrongdoing.</p><p class="sc-9a00e533-0 eZyhnA">Within hours, House Republicans then released thousands more documents to counter what they said was a Democratic effort to "cherry-pick" documents. They also said it had been an attempt to "create a fake narrative to slander President Trump".</p><p class="sc-9a00e533-0 eZyhnA">Hours after the latest publication of emails, the newly-sworn in Democratic Congresswoman Adelita Grijalva signed a petition, meaning it now has sufficient numbers to force a House vote that could require the US Department of Justice to release all the Epstein files.</p><p class="sc-9a00e533-0 eZyhnA">The office of House of Representatives Speaker Mike Johnson said the House would hold that vote next week.</p></div><div data-component="subheadline-block" class="sc-3b6b161a-0 hNbOGD"><h2 class="sc-f98b1ad2-0 gXmhTb">Epstein on Andrew photo</h2></div><figure><div data-component="image-block" class="sc-3b6b161a-0 gXrNRM"><div data-testid="image" class="sc-5340b511-1 cMIbKV"><img sizes="(min-width: 1280px) 50vw, (min-width: 1008px) 66vw, 96vw" srcset="https://ichef.bbci.co.uk/news/240/cpsprodpb/7f2d/live/b8fc2b30-c03c-11f0-8456-eff94716b162.jpg.webp 240w,https://ichef.bbci.co.uk/news/320/cpsprodpb/7f2d/live/b8fc2b30-c03c-11f0-8456-eff94716b162.jpg.webp 320w,https://ichef.bbci.co.uk/news/480/cpsprodpb/7f2d/live/b8fc2b30-c03c-11f0-8456-eff94716b162.jpg.webp 480w,https://ichef.bbci.co.uk/news/640/cpsprodpb/7f2d/live/b8fc2b30-c03c-11f0-8456-eff94716b162.jpg.webp 640w,https://ichef.bbci.co.uk/news/800/cpsprodpb/7f2d/live/b8fc2b30-c03c-11f0-8456-eff94716b162.jpg.webp 800w,https://ichef.bbci.co.uk/news/1024/cpsprodpb/7f2d/live/b8fc2b30-c03c-11f0-8456-eff94716b162.jpg.webp 1024w,https://ichef.bbci.co.uk/news/1536/cpsprodpb/7f2d/live/b8fc2b30-c03c-11f0-8456-eff94716b162.jpg.webp 1536w" src="https://ichef.bbci.co.uk/news/480/cpsprodpb/7f2d/live/b8fc2b30-c03c-11f0-8456-eff94716b162.jpg.webp" loading="lazy" alt="PA Media Andrew is seen with his arm around Virginia Giuffre, with Ghislaine Maxwell in the background." class="sc-5340b511-0 hLdNfA"><span class="sc-5340b511-2 jVqbAn">PA Media</span></div></div><div data-component="caption-block" class="sc-3b6b161a-0 Qwxkf"></div></figure><div data-testid="ad-unit" data-component="ad-slot" class="sc-1b734f04-0 kNNIux"><div data-testid="dotcom-mid_3" id="dotcom-mid_3" class="dotcom-ad"></div></div><div data-component="text-block" class="sc-3b6b161a-0 dPVOKT"><p class="sc-9a00e533-0 eZyhnA">The latest files shed further light on the relationship between Andrew and Epstein, with one email appearing to confirm a photograph of Andrew with his arm around a 17-year-old Giuffre was real. </p><p class="sc-9a00e533-0 eZyhnA">In an exchange with a journalist in July 2011, Epstein appeared to discuss Giuffre and her photograph with Andrew. </p><p class="sc-9a00e533-0 eZyhnA">"Yes she was on my plane, and yes she had her picture taken with Andrew, as many of my employees have," he wrote. </p><p class="sc-9a00e533-0 eZyhnA">Andrew said in his 2019 Newsnight interview that he had no recollection of that photo being taken and has suggested it might be fake.</p><p class="sc-9a00e533-0 eZyhnA">That exchange came four months after the purported "right of reply" email from the Mail on Sunday on 4 March 2011. </p><p class="sc-9a00e533-0 eZyhnA">The email states that a woman, whose name is redacted in the released document, was introduced to Andrew by the disgraced financier in 2001, at Maxwell''s house in London where she had sex with Andrew.</p><p class="sc-9a00e533-0 eZyhnA">On 6 March 2011 the Mail on Sunday published a story including the now infamous photograph of Andrew and Giuffre.</p><p class="sc-9a00e533-0 eZyhnA">The email goes on to say that the masseuse and another girl were directed to sit on Andrew''s knee in Epstein''s New York flat, and that he groped both girls. </p><p class="sc-9a00e533-0 eZyhnA">The email says that one of the girls was directed by Maxwell to have sex with Andrew. It also states she was directed to participate in an orgy with Andrew at Little St James - Epstein''s private Caribbean island. It requests a reply by noon the next day.</p><p class="sc-9a00e533-0 eZyhnA">It appears that the email is sent to Maxwell by her representative, forwarded on to Epstein and then to a redacted email address marked "The Duke".</p><p class="sc-9a00e533-0 eZyhnA">On 6 March 2011, the day the Mail on Sunday published its Giuffre story, Epstein emails "The Duke", asking: "You ok?". He add: "These stories are complete and utter fantasy".</p><p class="sc-9a00e533-0 eZyhnA">In an email to his publicist in July that year, Epstein writes: "The girl who accused Prince Andrew can also easily be proven to be a liar.</p><p class="sc-9a00e533-0 eZyhnA">"I think Buckingham Palace would love it. You should task someone to investigate the girl Virginia Roberts, that has caused the Queen''s son all this agro (sic).</p><p class="sc-9a00e533-0 eZyhnA">"I promise you she is a fraud. You and I will be able to go to ascot (sic) for the rest of our lives."</p></div><div data-component="subheadline-block" class="sc-3b6b161a-0 hNbOGD"><h2 class="sc-f98b1ad2-0 gXmhTb">Mandelson in contact in 2016</h2></div><figure><div data-component="image-block" class="sc-3b6b161a-0 gXrNRM"><div data-testid="image" class="sc-5340b511-1 cMIbKV"><img sizes="(min-width: 1280px) 50vw, (min-width: 1008px) 66vw, 96vw" srcset="https://ichef.bbci.co.uk/news/240/cpsprodpb/82f6/live/f26fa530-c038-11f0-ae46-bd64331f0fd4.jpg.webp 240w,https://ichef.bbci.co.uk/news/320/cpsprodpb/82f6/live/f26fa530-c038-11f0-ae46-bd64331f0fd4.jpg.webp 320w,https://ichef.bbci.co.uk/news/480/cpsprodpb/82f6/live/f26fa530-c038-11f0-ae46-bd64331f0fd4.jpg.webp 480w,https://ichef.bbci.co.uk/news/640/cpsprodpb/82f6/live/f26fa530-c038-11f0-ae46-bd64331f0fd4.jpg.webp 640w,https://ichef.bbci.co.uk/news/800/cpsprodpb/82f6/live/f26fa530-c038-11f0-ae46-bd64331f0fd4.jpg.webp 800w,https://ichef.bbci.co.uk/news/1024/cpsprodpb/82f6/live/f26fa530-c038-11f0-ae46-bd64331f0fd4.jpg.webp 1024w,https://ichef.bbci.co.uk/news/1536/cpsprodpb/82f6/live/f26fa530-c038-11f0-ae46-bd64331f0fd4.jpg.webp 1536w" src="https://ichef.bbci.co.uk/news/480/cpsprodpb/82f6/live/f26fa530-c038-11f0-ae46-bd64331f0fd4.jpg.webp" loading="lazy" alt="PA Media Peter Mandelson, wearing black framed glasses, a black suit, shite shirt, and blue tie" class="sc-5340b511-0 hLdNfA"><span class="sc-5340b511-2 jVqbAn">PA Media</span></div></div><div data-component="caption-block" class="sc-3b6b161a-0 Qwxkf"></div></figure><div data-component="text-block" class="sc-3b6b161a-0 dPVOKT"><p class="sc-9a00e533-0 eZyhnA">Lord Mandelson <a target="_self" href="https://www.bbc.com/news/articles/c0jdl8wzvnvo" class="sc-f9178328-0 iCaRzc">also appears in the newly released documents</a>, which show he had contact with Epstein as late as 2016.</p><p class="sc-9a00e533-0 eZyhnA">The latest previous reported contact between the pair was when the then-business secretary took advice from Epstein in a banking deal in March 2010, just months after the American businessman''s release from prison for child sex offences, as reported by the Daily Telegraph.</p><p class="sc-9a00e533-0 eZyhnA">The new documents include an email from Epstein to Lord Mandelson on 6 November 2016, shortly after the peer''s birthday, saying "63 years old. You made it".</p><p class="sc-9a00e533-0 eZyhnA">Lord Mandelson replies less than 90 minutes later saying: "Just. I have decided to extend my life by spending more of it in the US".</p><p class="sc-9a00e533-0 eZyhnA">Epstein then replies "in the Donald White House", referring to the US presidential election due later that week.</p><p class="sc-9a00e533-0 eZyhnA">Lord Mandelson was sacked as the UK''s ambassador to the US in September over his links to Epstein, after emails showed the peer sent him supportive messages after he pleaded guilty to soliciting a minor in 2008.</p><p class="sc-9a00e533-0 eZyhnA">Lord Mandelson, who has repeatedly said he regrets his relationship with Epstein,  declined to comment on the emails when approached by the BBC.</p></div><div data-component="links-block" class="sc-3b6b161a-0 djqsWD"><div class="sc-666b6d83-0 sc-c4fb5674-0 jYmMqa kGPvxx"><div data-testid="links-grid" class="sc-666b6d83-0 sc-c4fb5674-1 gEjRXC jkjVgq"><div data-testid="chester-card" data-indexcard="true" class="sc-225578b-0 ezQaGx"><div data-testid="anchor-inner-wrapper"><a href="https://www.bbc.com/news/articles/c0jdl8wzvnvo" data-testid="external-anchor" target="_self" class="sc-8a623a54-0 huZCWi"><div data-testid="chester-article" class="sc-cf565bcc-0 kwPVOm"><div class="sc-fa814188-1 iRoJZi"><div class="sc-fa814188-0 hPhBqv"><h2 data-testid="card-headline" class="sc-fa814188-3 iCfgww">Mandelson still in contact with Epstein in 2016, emails show</h2></div></div></div></a></div></div><div data-testid="chester-card" data-indexcard="true" class="sc-225578b-0 ezQaGx"><div data-testid="anchor-inner-wrapper"><a href="https://www.bbc.com/news/articles/c3rj0d97ynvo" data-testid="external-anchor" target="_self" class="sc-8a623a54-0 huZCWi"><div data-testid="chester-article" class="sc-cf565bcc-0 kwPVOm"><div class="sc-fa814188-1 iRoJZi"><div class="sc-fa814188-0 hPhBqv"><h2 data-testid="card-headline" class="sc-fa814188-3 iCfgww">What we know about new Epstein emails that mention Trump</h2></div></div></div></a></div></div></div></div></div><div data-component="tags" class="sc-3b6b161a-0 djqsWD"><div class="sc-6bf80075-0 lllwyY"><div data-testid="anchor-inner-wrapper"><a href="https://www.bbc.com/news/topics/c28511xee27t" data-testid="internal-link" class="sc-57521d02-0 jsVxCb">Andrew Mountbatten Windsor</a></div><div data-testid="anchor-inner-wrapper"><a href="https://www.bbc.com/news/topics/ck8vkvd8q9dt" data-testid="internal-link" class="sc-57521d02-0 jsVxCb">Ghislaine Maxwell</a></div><div data-testid="anchor-inner-wrapper"><a href="https://www.bbc.com/news/topics/cl7003r72r4t" data-testid="internal-link" class="sc-57521d02-0 jsVxCb">Jeffrey Epstein</a></div><div data-testid="anchor-inner-wrapper"><a href="https://www.bbc.com/news/topics/cp7r8vgl2lgt" data-testid="internal-link" class="sc-57521d02-0 jsVxCb">Donald Trump</a></div><div data-testid="anchor-inner-wrapper"><a href="https://www.bbc.com/news/topics/cx1m7zg01xyt" data-testid="internal-link" class="sc-57521d02-0 jsVxCb">United States</a></div></div></div>', NULL, NULL);
INSERT INTO lost_and_found VALUES(50, 50, 14, 2, 1268, 1763020370605, NULL, 1763018493000, 1, 1763020370605, 'en-GB', 'What emails in the Epstein document release say about Donald Trump', 'https://www.bbc.com/news/articles/c3rj0d97ynvo?at_medium=RSS&at_campaign=rss', 'https://www.bbc.com/news/articles/c3rj0d97ynvo?at_medium=RSS&at_campaign=rss', NULL, '<div data-component="headline-block" class="sc-3b6b161a-0 hNbOGD"><h1 class="sc-f98b1ad2-0 idLnWK">What we know about new Epstein emails that mention Trump</h1></div><div data-component="byline-block" class="sc-3b6b161a-0 dPVOKT"><div data-testid="byline-new" class="sc-7bfdb3c2-0 fYJjWP"><div class="sc-7bfdb3c2-1 jqWinX"><time datetime="2025-11-13T07:21:33.568Z" class="sc-7bfdb3c2-2 dQuPjg">31 minutes ago</time><div class="sc-7bfdb3c2-3 dVvYwG"></div></div><span data-testid="byline-new-contributors" class="sc-7bfdb3c2-11 ljQVMv"><span class="sc-7bfdb3c2-7 djOqvY">Nadine Yousif</span></span></div></div><div class="sc-7bfdb3c2-4 haycoC"></div><figure><div data-component="image-block" class="sc-3b6b161a-0 gtLOOD"><div data-testid="hero-image" class="sc-5340b511-1 cMIbKV"><img srcset="https://ichef.bbci.co.uk/news/240/cpsprodpb/8e9a/live/de408d30-bfdf-11f0-bbea-2df62eb90585.jpg.webp 240w, https://ichef.bbci.co.uk/news/320/cpsprodpb/8e9a/live/de408d30-bfdf-11f0-bbea-2df62eb90585.jpg.webp 320w, https://ichef.bbci.co.uk/news/480/cpsprodpb/8e9a/live/de408d30-bfdf-11f0-bbea-2df62eb90585.jpg.webp 480w, https://ichef.bbci.co.uk/news/640/cpsprodpb/8e9a/live/de408d30-bfdf-11f0-bbea-2df62eb90585.jpg.webp 640w, https://ichef.bbci.co.uk/news/800/cpsprodpb/8e9a/live/de408d30-bfdf-11f0-bbea-2df62eb90585.jpg.webp 800w, https://ichef.bbci.co.uk/news/1024/cpsprodpb/8e9a/live/de408d30-bfdf-11f0-bbea-2df62eb90585.jpg.webp 1024w, https://ichef.bbci.co.uk/news/1536/cpsprodpb/8e9a/live/de408d30-bfdf-11f0-bbea-2df62eb90585.jpg.webp 1536w" src="https://ichef.bbci.co.uk/news/480/cpsprodpb/8e9a/live/de408d30-bfdf-11f0-bbea-2df62eb90585.jpg.webp" alt="Getty Images A photo of Jeffrey Epstein and Donald Trump at a 1997 event." class="sc-5340b511-0 hLdNfA" /><span class="sc-5340b511-2 jVqbAn">Getty Images</span></div></div><div data-component="caption-block" class="sc-3b6b161a-0 Qwxkf"></div></figure><div data-component="text-block" class="sc-3b6b161a-0 dPVOKT"><p class="sc-9a00e533-0 eZyhnA">US lawmakers have released more than 20,000 pages of documents from the estate of the disgraced financier and convicted sex offender Jeffrey Epstein, including some that mention President Donald Trump.</p><p class="sc-9a00e533-0 eZyhnA">Early on Wednesday, Democrats on the House Oversight Committee published three email exchanges, including correspondence between Epstein, who died in 2019 in prison, and his long-time associate Ghislaine Maxwell, who is currently serving a 20-year prison sentence for sex trafficking.</p><p class="sc-9a00e533-0 eZyhnA">They also released emails between Epstein and the author Michael Wolff, who has written numerous books about Trump.</p><p class="sc-9a00e533-0 eZyhnA">Within hours, House Republicans released a massive tranche of documents to counter what they said was a Democratic effort to "cherry-pick" documents. They also said it was an attempt to "create a fake narrative to slander President Trump".</p><p class="sc-9a00e533-0 eZyhnA">White House Press Secretary Karoline Leavitt said the emails were "selectively leaked" by House Democrats to "liberal media to create a fake narrative to smear President Trump".</p><p class="sc-9a00e533-0 eZyhnA">"The fact remains that President Trump kicked Jeffrey Epstein out of his club decades ago for being a creep to his female employees, including Giuffre," she said.</p><p class="sc-9a00e533-0 eZyhnA">Trump was a friend of Epstein''s for years, but the president has said they fell out in the early 2000s, two years before Epstein was first arrested. Trump has consistently denied any wrongdoing in relation to Epstein.</p></div><div data-testid="ad-unit" data-component="ad-slot" class="sc-1b734f04-0 kNNIux"><div data-testid="dotcom-mid_1" id="dotcom-mid_1" class="dotcom-ad"></div></div><div data-component="subheadline-block" class="sc-3b6b161a-0 hNbOGD"><h2 class="sc-f98b1ad2-0 gXmhTb">What the Epstein-Maxwell email says</h2></div><div data-component="text-block" class="sc-3b6b161a-0 dPVOKT"><p class="sc-9a00e533-0 eZyhnA">The first email released by Democrats is from 2011 and is between Epstein and Maxwell. </p><p class="sc-9a00e533-0 eZyhnA">In it, Epstein writes to Maxwell: "I want you to realize that that dog that hasn''t barked is Trump.. [VICTIM] spent hours at my house with him". </p><p class="sc-9a00e533-0 eZyhnA">Epstein goes on to write that Trump "has never once been mentioned", including by a "police chief".</p><p class="sc-9a00e533-0 eZyhnA">Maxwell responded: "I have been thinking about that..."</p><p class="sc-9a00e533-0 eZyhnA">The victim''s name was redacted in the email the Democrats released, although the unredacted version is in the tranche released by the committee. That shows the name "Virginia". </p><p class="sc-9a00e533-0 eZyhnA">The White House said it refers to the late Virginia Giuffre, <a target="_self" href="https://www.bbc.com/news/articles/cql67qk0dd3o" class="sc-f9178328-0 iCaRzc">a prominent Epstein accuser who died by suicide earlier this year</a>. In a statement, the White House said Giuffre "repeatedly said President Trump was not involved in any wrongdoing whatsoever and ''couldn''t have been friendlier'' to her in their limited interactions". </p><p class="sc-9a00e533-0 eZyhnA">Giuffre said in a 2016 deposition that she never saw Trump participate in any abuse. <a target="_self" href="https://www.bbc.com/news/articles/c5ylepx85nxo" class="sc-f9178328-0 iCaRzc">And in a memoir released this year</a>, she did not accuse the president of any wrongdoing.</p><p class="sc-9a00e533-0 eZyhnA">Asked why the name was originally redacted, Representative Robert Garcia - the leading Democrat on the US House Oversight Committee - said the party will never release names of victims in line with the wishes of the families.</p></div><figure><div data-component="image-block" class="sc-3b6b161a-0 GunZh"><div data-testid="image" class="sc-5340b511-1 cMIbKV"><img srcset="https://ichef.bbci.co.uk/news/240/cpsprodpb/cf24/live/bae649c0-c001-11f0-8456-eff94716b162.jpg.webp 240w, https://ichef.bbci.co.uk/news/320/cpsprodpb/cf24/live/bae649c0-c001-11f0-8456-eff94716b162.jpg.webp 320w, https://ichef.bbci.co.uk/news/480/cpsprodpb/cf24/live/bae649c0-c001-11f0-8456-eff94716b162.jpg.webp 480w, https://ichef.bbci.co.uk/news/640/cpsprodpb/cf24/live/bae649c0-c001-11f0-8456-eff94716b162.jpg.webp 640w, https://ichef.bbci.co.uk/news/800/cpsprodpb/cf24/live/bae649c0-c001-11f0-8456-eff94716b162.jpg.webp 800w, https://ichef.bbci.co.uk/news/1024/cpsprodpb/cf24/live/bae649c0-c001-11f0-8456-eff94716b162.jpg.webp 1024w, https://ichef.bbci.co.uk/news/1536/cpsprodpb/cf24/live/bae649c0-c001-11f0-8456-eff94716b162.jpg.webp 1536w" src="https://ichef.bbci.co.uk/news/480/cpsprodpb/cf24/live/bae649c0-c001-11f0-8456-eff94716b162.jpg.webp" alt="Image shows an email exchange released as part of the files, with a highlighted line reading: &quot;that dog that hasn''t barked is Trump.. [VICTIM] spent hours at my house with him&quot;." class="sc-5340b511-0 hLdNfA" /></div></div></figure><div data-testid="ad-unit" data-component="ad-slot" class="sc-1b734f04-0 kNNIux"><div data-testid="dotcom-mid_2" id="dotcom-mid_2" class="dotcom-ad"></div></div><div data-component="subheadline-block" class="sc-3b6b161a-0 hNbOGD"><h2 class="sc-f98b1ad2-0 gXmhTb">What the Epstein-Wolff emails say</h2></div><div data-component="text-block" class="sc-3b6b161a-0 dPVOKT"><p class="sc-9a00e533-0 eZyhnA">In exchanges with Wolff, the author, Epstein discusses his connection to Trump, who<b id="" class="sc-d16436d-0 gnUCoQ"> </b>- at the time - was campaigning for the presidency ahead of his first term in office. </p><p class="sc-9a00e533-0 eZyhnA">In a second email exchange released by Democrats, Wolff writes to Epstein in 2015 to notify him that CNN is planning to ask Trump about their relationship, "either on air or in scrum afterwards".</p><p class="sc-9a00e533-0 eZyhnA">Epstein responds: "If we were able to craft an answer for him, what do you think it should be?"</p><p class="sc-9a00e533-0 eZyhnA">Wolff writes: "I think you should let him hang himself. If he says he hasn''t been on the plane or to the house, then that gives you a valuable PR and political currency. You can hang him in a way that potentially generates a positive benefit for you, or, if it really looks like he could win, you could save him, generating a debt."</p><p class="sc-9a00e533-0 eZyhnA">He adds: "Of course, it is possible that, when asked, he''ll say Jeffrey is a great guy and has gotten a raw deal and is a victim of political correctness, which is to be outlawed in a Trump regime."</p></div><figure><div data-component="image-block" class="sc-3b6b161a-0 gXrNRM"><div data-testid="image" class="sc-5340b511-1 cMIbKV"><img srcset="https://ichef.bbci.co.uk/news/240/cpsprodpb/f6fa/live/a45b6e60-c01f-11f0-8456-eff94716b162.jpg.webp 240w, https://ichef.bbci.co.uk/news/320/cpsprodpb/f6fa/live/a45b6e60-c01f-11f0-8456-eff94716b162.jpg.webp 320w, https://ichef.bbci.co.uk/news/480/cpsprodpb/f6fa/live/a45b6e60-c01f-11f0-8456-eff94716b162.jpg.webp 480w, https://ichef.bbci.co.uk/news/640/cpsprodpb/f6fa/live/a45b6e60-c01f-11f0-8456-eff94716b162.jpg.webp 640w, https://ichef.bbci.co.uk/news/800/cpsprodpb/f6fa/live/a45b6e60-c01f-11f0-8456-eff94716b162.jpg.webp 800w, https://ichef.bbci.co.uk/news/1024/cpsprodpb/f6fa/live/a45b6e60-c01f-11f0-8456-eff94716b162.jpg.webp 1024w, https://ichef.bbci.co.uk/news/1536/cpsprodpb/f6fa/live/a45b6e60-c01f-11f0-8456-eff94716b162.jpg.webp 1536w" src="https://ichef.bbci.co.uk/news/480/cpsprodpb/f6fa/live/a45b6e60-c01f-11f0-8456-eff94716b162.jpg.webp" alt="Reuters Author Michael Wolff is seen on the set of NBC''s ''Today''  in 2018" class="sc-5340b511-0 hLdNfA" /><span class="sc-5340b511-2 jVqbAn">Reuters</span></div></div><div data-component="caption-block" class="sc-3b6b161a-0 Qwxkf"></div></figure><div data-testid="ad-unit" data-component="ad-slot" class="sc-1b734f04-0 kNNIux"><div data-testid="dotcom-mid_3" id="dotcom-mid_3" class="dotcom-ad"></div></div><div data-component="text-block" class="sc-3b6b161a-0 dPVOKT"><p class="sc-9a00e533-0 eZyhnA">In a separate email from October 2016, days before the US presidential election, Wolff offers Epstein a chance to sit for an interview that could "finish" Trump. </p><p class="sc-9a00e533-0 eZyhnA">"There''s an opportunity to come forward this week and talk about Trump in such a way that could garner you great sympathy and help finish him. Interested?", Wolff writes to Epstein.</p><p class="sc-9a00e533-0 eZyhnA">A third email released by Democrats is dated January 2019, during Trump''s first term in office.  </p><p class="sc-9a00e533-0 eZyhnA">In it, Epstein tells Wolff: "Trump said he asked me to resign" apparently referring to his membership at the president''s Mar-a-Lago club, adding, he was "never a member ever". </p><p class="sc-9a00e533-0 eZyhnA">Epstein adds that "of course he knew about the girls as he asked Ghislaine to stop". </p><p class="sc-9a00e533-0 eZyhnA">Responding to the release in a video he posted to Instagram, Wolff said: "Some of those emails are between Epstein and me, with Epstein discussing his relationship with Donald Trump."</p><p class="sc-9a00e533-0 eZyhnA">"I have been trying to talk about this story for a very long time now," he added.</p></div><div data-component="subheadline-block" class="sc-3b6b161a-0 hNbOGD"><h2 class="sc-f98b1ad2-0 gXmhTb">Andrew emailed Epstein in 2011</h2></div><div data-component="text-block" class="sc-3b6b161a-0 dPVOKT"><p class="sc-9a00e533-0 eZyhnA">As well as Trump, a released document also mentions Andrew Mountbatten-Windsor, formerly Prince Andrew.</p><p class="sc-9a00e533-0 eZyhnA">He responded to an email forwarded by Ghislaine Maxwell via Jeffrey Epstein in March 2011 about alleged sexual activity with a masseuse working for Epstein.</p><p class="sc-9a00e533-0 eZyhnA">Andrew''s reply reads: "Hey there! What''s all this? I don''t know anything about this! You must SAY so please. This has NOTHING to do with me. I can''t take any more of this."</p><p class="sc-9a00e533-0 eZyhnA">Maxwell had forwarded a "right of reply" email from the Mail on Sunday on 4 March, making numerous allegations about Maxwell, Epstein, and then-Prince Andrew.</p><p class="sc-9a00e533-0 eZyhnA">The right of reply email states that a woman, whose name is redacted in the released document, was introduced to Andrew by the disgraced financier in 2001, at Maxwell''s house in London where she had sex with Andrew.</p><p class="sc-9a00e533-0 eZyhnA">On 6 March 2011 the Mail on Sunday published a story including a photograph of Prince Andrew and Virginia Guiffre.</p><p class="sc-9a00e533-0 eZyhnA">Andrew has always denied any wrongdoing and has not faced any charges.</p></div><div data-testid="ad-unit" data-component="ad-slot" class="sc-1b734f04-0 kNNIux"><div data-testid="dotcom-mid_4" id="dotcom-mid_4" class="dotcom-ad"></div></div><div data-component="video-block" data-testid="fabl-video-container" class="sc-3b6b161a-0 gXrNRM"><div class="sc-2218ed0c-1 fiqjXZ"><div data-testid="" class="sc-2218ed0c-2 bgTyRA"></div></div></div><div data-component="caption-block" class="sc-3b6b161a-0 Qwxkf"></div><div data-component="subheadline-block" class="sc-3b6b161a-0 hNbOGD"><h2 class="sc-f98b1ad2-0 gXmhTb">Peter Mandelson contacted Epstein in 2016</h2></div><div data-component="text-block" class="sc-3b6b161a-0 dPVOKT"><p class="sc-9a00e533-0 eZyhnA">Lord Peter Mandelson, who was sacked as the UK''s ambassador to the US in September over his links to Epstein, is also mentioned in the new documents.</p><p class="sc-9a00e533-0 eZyhnA"><a target="_self" href="https://www.bbc.com/news/articles/c0jdl8wzvnvo" class="sc-f9178328-0 iCaRzc">They show he was in contact with Epstein as late as 2016</a>, according to the documents.</p><p class="sc-9a00e533-0 eZyhnA">The latest previous reported contact between the pair was when the then-business secretary took advice from Epstein in a banking deal in March 2010, just months after the American businessman''s release from prison for child sex offences, as reported by the Daily Telegraph.</p><p class="sc-9a00e533-0 eZyhnA">An email from Epstein to Lord Mandelson on 6 November 2015, shortly after the peer''s birthday, reads: "63 years old. You made it".</p><p class="sc-9a00e533-0 eZyhnA">Lord Mandelson replies less than 90 minutes later saying: "Just. I have decided to extend my life by spending more of it in the US".</p><p class="sc-9a00e533-0 eZyhnA">Epstein then replies "in the Donald White House", referring to the US presidential election due later that week.</p><p class="sc-9a00e533-0 eZyhnA">Epstein goes on to say "you were right about staying away from Andrew. I was right in your staying with Rinaldo [sic]", a reference to Lord Mandelson''s now-husband Reinaldo Avilda da Silva.</p><p class="sc-9a00e533-0 eZyhnA">Lord Mandelson has repeatedly said he regrets his relationship with Epstein. He declined to comment on the emails when approached by the BBC.</p></div><div data-component="subheadline-block" class="sc-3b6b161a-0 hNbOGD"><h2 class="sc-f98b1ad2-0 gXmhTb">What the survivors have said</h2></div><div data-component="text-block" class="sc-3b6b161a-0 dPVOKT"><p class="sc-9a00e533-0 eZyhnA">Annie Farmer, one of Epstein''s accusers and a key witness in Maxwell''s sex trafficking trial, shared a statement after the emails were released. </p><p class="sc-9a00e533-0 eZyhnA">In it she said: "The more information that comes out about Jeffrey Epstein, the more questions we''re left with. Survivors deserve more than a trickle of information."</p><p class="sc-9a00e533-0 eZyhnA">Farmer demanded the "full release" of the so-called Epstein files and said "the estimated one thousand women and girls who were harmed by Epstein and his associates deserve full transparency".</p></div><div data-component="links-block" class="sc-3b6b161a-0 djqsWD"><div class="sc-666b6d83-0 sc-c4fb5674-0 jYmMqa kGPvxx"><div data-testid="links-grid" class="sc-666b6d83-0 sc-c4fb5674-1 gEjRXC jkjVgq"><div data-testid="chester-card" data-indexcard="true" class="sc-225578b-0 ezQaGx"><div data-testid="anchor-inner-wrapper"><a href="https://www.bbc.com/news/articles/cp8j3e5g74no" data-testid="external-anchor" target="_self" class="sc-8a623a54-0 huZCWi"><div data-testid="chester-article" class="sc-cf565bcc-0 kwPVOm"><div class="sc-fa814188-1 iRoJZi"><div class="sc-fa814188-0 hPhBqv"><h2 data-testid="card-headline" class="sc-fa814188-3 iCfgww">Trump is used to shaking off criticism - but the Epstein story is different</h2></div></div></div></a></div></div><div data-testid="chester-card" data-indexcard="true" class="sc-225578b-0 ezQaGx"><div data-testid="anchor-inner-wrapper"><a href="https://www.bbc.com/news/articles/cdx5xzy8kn1o" data-testid="external-anchor" target="_self" class="sc-8a623a54-0 huZCWi"><div data-testid="chester-article" class="sc-cf565bcc-0 kwPVOm"><div class="sc-fa814188-1 iRoJZi"><div class="sc-fa814188-0 hPhBqv"><h2 data-testid="card-headline" class="sc-fa814188-3 iCfgww">How Epstein case is tearing apart Maga''s online conspiracy wing</h2></div></div></div></a></div></div><div data-testid="chester-card" data-indexcard="true" class="sc-225578b-0 ezQaGx"><div data-testid="anchor-inner-wrapper"><a href="https://www.bbc.com/news/world-us-canada-48913377" data-testid="external-anchor" target="_self" class="sc-8a623a54-0 huZCWi"><div data-testid="chester-article" class="sc-cf565bcc-0 kwPVOm"><div class="sc-fa814188-1 iRoJZi"><div class="sc-fa814188-0 hPhBqv"><h2 data-testid="card-headline" class="sc-fa814188-3 iCfgww">Who was Jeffrey Epstein?</h2></div></div></div></a></div></div></div></div></div><div data-component="tags" class="sc-3b6b161a-0 djqsWD"><div class="sc-6bf80075-0 lllwyY"><div data-testid="anchor-inner-wrapper"><a href="https://www.bbc.com/news/topics/cl7003r72r4t" data-testid="internal-link" class="sc-57521d02-0 jsVxCb">Jeffrey Epstein</a></div><div data-testid="anchor-inner-wrapper"><a href="https://www.bbc.com/news/topics/cp7r8vgl2lgt" data-testid="internal-link" class="sc-57521d02-0 jsVxCb">Donald Trump</a></div><div data-testid="anchor-inner-wrapper"><a href="https://www.bbc.com/news/topics/cwnpxwzd269t" data-testid="internal-link" class="sc-57521d02-0 jsVxCb">US politics</a></div><div data-testid="anchor-inner-wrapper"><a href="https://www.bbc.com/news/topics/cx1m7zg01xyt" data-testid="internal-link" class="sc-57521d02-0 jsVxCb">United States</a></div></div></div>', NULL, '<div data-component="headline-block" class="sc-3b6b161a-0 hNbOGD"><h1 class="sc-f98b1ad2-0 idLnWK">What we know about new Epstein emails that mention Trump</h1></div><div data-component="byline-block" class="sc-3b6b161a-0 dPVOKT"><div data-testid="byline-new" class="sc-7bfdb3c2-0 fYJjWP"><div class="sc-7bfdb3c2-1 jqWinX"><time datetime="2025-11-13T07:21:33.568Z" class="sc-7bfdb3c2-2 dQuPjg">31 minutes ago</time><div class="sc-7bfdb3c2-3 dVvYwG"></div></div><span data-testid="byline-new-contributors" class="sc-7bfdb3c2-11 ljQVMv"><div data-testid="byline-new-contributors-contributor-0" class="sc-7bfdb3c2-5 xGeVU"><div><span class="sc-7bfdb3c2-7 djOqvY">Nadine Yousif</span></div></div></span><div class="sc-7bfdb3c2-4 haycoC"></div></div></div><figure><div data-component="image-block" class="sc-3b6b161a-0 gtLOOD"><div data-testid="hero-image" class="sc-5340b511-1 cMIbKV"><img sizes="(min-width: 1280px) 50vw, (min-width: 1008px) 66vw, 96vw" srcset="https://ichef.bbci.co.uk/news/240/cpsprodpb/8e9a/live/de408d30-bfdf-11f0-bbea-2df62eb90585.jpg.webp 240w,https://ichef.bbci.co.uk/news/320/cpsprodpb/8e9a/live/de408d30-bfdf-11f0-bbea-2df62eb90585.jpg.webp 320w,https://ichef.bbci.co.uk/news/480/cpsprodpb/8e9a/live/de408d30-bfdf-11f0-bbea-2df62eb90585.jpg.webp 480w,https://ichef.bbci.co.uk/news/640/cpsprodpb/8e9a/live/de408d30-bfdf-11f0-bbea-2df62eb90585.jpg.webp 640w,https://ichef.bbci.co.uk/news/800/cpsprodpb/8e9a/live/de408d30-bfdf-11f0-bbea-2df62eb90585.jpg.webp 800w,https://ichef.bbci.co.uk/news/1024/cpsprodpb/8e9a/live/de408d30-bfdf-11f0-bbea-2df62eb90585.jpg.webp 1024w,https://ichef.bbci.co.uk/news/1536/cpsprodpb/8e9a/live/de408d30-bfdf-11f0-bbea-2df62eb90585.jpg.webp 1536w" src="https://ichef.bbci.co.uk/news/480/cpsprodpb/8e9a/live/de408d30-bfdf-11f0-bbea-2df62eb90585.jpg.webp" loading="eager" alt="Getty Images A photo of Jeffrey Epstein and Donald Trump at a 1997 event. " class="sc-5340b511-0 hLdNfA"><span class="sc-5340b511-2 jVqbAn">Getty Images</span></div></div><div data-component="caption-block" class="sc-3b6b161a-0 Qwxkf"></div></figure><div data-component="text-block" class="sc-3b6b161a-0 dPVOKT"><p class="sc-9a00e533-0 eZyhnA">US lawmakers have released more than 20,000 pages of documents from the estate of the disgraced financier and convicted sex offender Jeffrey Epstein, including some that mention President Donald Trump.</p><p class="sc-9a00e533-0 eZyhnA">Early on Wednesday, Democrats on the House Oversight Committee published three email exchanges, including correspondence between Epstein, who died in 2019 in prison, and his long-time associate Ghislaine Maxwell, who is currently serving a 20-year prison sentence for sex trafficking.</p><p class="sc-9a00e533-0 eZyhnA">They also released emails between Epstein and the author Michael Wolff, who has written numerous books about Trump.</p><p class="sc-9a00e533-0 eZyhnA">Within hours, House Republicans released a massive tranche of documents to counter what they said was a Democratic effort to "cherry-pick" documents. They also said it was an attempt to "create a fake narrative to slander President Trump".</p><p class="sc-9a00e533-0 eZyhnA">White House Press Secretary Karoline Leavitt said the emails were "selectively leaked" by House Democrats to "liberal media to create a fake narrative to smear President Trump".</p><p class="sc-9a00e533-0 eZyhnA">"The fact remains that President Trump kicked Jeffrey Epstein out of his club decades ago for being a creep to his female employees, including Giuffre," she said.</p><p class="sc-9a00e533-0 eZyhnA">Trump was a friend of Epstein''s for years, but the president has said they fell out in the early 2000s, two years before Epstein was first arrested. Trump has consistently denied any wrongdoing in relation to Epstein.</p></div><div data-testid="ad-unit" data-component="ad-slot" class="sc-1b734f04-0 kNNIux"><div data-testid="dotcom-mid_1" id="dotcom-mid_1" class="dotcom-ad"></div></div><div data-component="subheadline-block" class="sc-3b6b161a-0 hNbOGD"><h2 class="sc-f98b1ad2-0 gXmhTb">What the Epstein-Maxwell email says</h2></div><div data-component="text-block" class="sc-3b6b161a-0 dPVOKT"><p class="sc-9a00e533-0 eZyhnA">The first email released by Democrats is from 2011 and is between Epstein and Maxwell. </p><p class="sc-9a00e533-0 eZyhnA">In it, Epstein writes to Maxwell: "I want you to realize that that dog that hasn''t barked is Trump.. [VICTIM] spent hours at my house with him". </p><p class="sc-9a00e533-0 eZyhnA">Epstein goes on to write that Trump "has never once been mentioned", including by a "police chief".</p><p class="sc-9a00e533-0 eZyhnA">Maxwell responded: "I have been thinking about that..."</p><p class="sc-9a00e533-0 eZyhnA">The victim''s name was redacted in the email the Democrats released, although the unredacted version is in the tranche released by the committee. That shows the name "Virginia". </p><p class="sc-9a00e533-0 eZyhnA">The White House said it refers to the late Virginia Giuffre, <a target="_self" href="https://www.bbc.com/news/articles/cql67qk0dd3o" class="sc-f9178328-0 iCaRzc">a prominent Epstein accuser who died by suicide earlier this year</a>. In a statement, the White House said Giuffre "repeatedly said President Trump was not involved in any wrongdoing whatsoever and ''couldn''t have been friendlier'' to her in their limited interactions". </p><p class="sc-9a00e533-0 eZyhnA">Giuffre said in a 2016 deposition that she never saw Trump participate in any abuse. <a target="_self" href="https://www.bbc.com/news/articles/c5ylepx85nxo" class="sc-f9178328-0 iCaRzc">And in a memoir released this year</a>, she did not accuse the president of any wrongdoing.</p><p class="sc-9a00e533-0 eZyhnA">Asked why the name was originally redacted, Representative Robert Garcia - the leading Democrat on the US House Oversight Committee - said the party will never release names of victims in line with the wishes of the families.</p></div><figure><div data-component="image-block" class="sc-3b6b161a-0 GunZh"><div data-testid="image" class="sc-5340b511-1 cMIbKV"><img sizes="(min-width: 1280px) 50vw, (min-width: 1008px) 66vw, 96vw" srcset="https://ichef.bbci.co.uk/news/240/cpsprodpb/cf24/live/bae649c0-c001-11f0-8456-eff94716b162.jpg.webp 240w,https://ichef.bbci.co.uk/news/320/cpsprodpb/cf24/live/bae649c0-c001-11f0-8456-eff94716b162.jpg.webp 320w,https://ichef.bbci.co.uk/news/480/cpsprodpb/cf24/live/bae649c0-c001-11f0-8456-eff94716b162.jpg.webp 480w,https://ichef.bbci.co.uk/news/640/cpsprodpb/cf24/live/bae649c0-c001-11f0-8456-eff94716b162.jpg.webp 640w,https://ichef.bbci.co.uk/news/800/cpsprodpb/cf24/live/bae649c0-c001-11f0-8456-eff94716b162.jpg.webp 800w,https://ichef.bbci.co.uk/news/1024/cpsprodpb/cf24/live/bae649c0-c001-11f0-8456-eff94716b162.jpg.webp 1024w,https://ichef.bbci.co.uk/news/1536/cpsprodpb/cf24/live/bae649c0-c001-11f0-8456-eff94716b162.jpg.webp 1536w" src="https://ichef.bbci.co.uk/news/480/cpsprodpb/cf24/live/bae649c0-c001-11f0-8456-eff94716b162.jpg.webp" loading="lazy" alt="Image shows an email exchange released as part of the files, with a highlighted line reading: &quot;that dog that hasn''t barked is Trump.. [VICTIM] spent hours at my house with him&quot;. " class="sc-5340b511-0 hLdNfA"></div></div></figure><div data-testid="ad-unit" data-component="ad-slot" class="sc-1b734f04-0 kNNIux"><div data-testid="dotcom-mid_2" id="dotcom-mid_2" class="dotcom-ad"></div></div><div data-component="subheadline-block" class="sc-3b6b161a-0 hNbOGD"><h2 class="sc-f98b1ad2-0 gXmhTb">What the Epstein-Wolff emails say</h2></div><div data-component="text-block" class="sc-3b6b161a-0 dPVOKT"><p class="sc-9a00e533-0 eZyhnA">In exchanges with Wolff, the author, Epstein discusses his connection to Trump, who<b id class="sc-d16436d-0 gnUCoQ"> </b>- at the time - was campaigning for the presidency ahead of his first term in office. </p><p class="sc-9a00e533-0 eZyhnA">In a second email exchange released by Democrats, Wolff writes to Epstein in 2015 to notify him that CNN is planning to ask Trump about their relationship, "either on air or in scrum afterwards".</p><p class="sc-9a00e533-0 eZyhnA">Epstein responds: "If we were able to craft an answer for him, what do you think it should be?"</p><p class="sc-9a00e533-0 eZyhnA">Wolff writes: "I think you should let him hang himself. If he says he hasn''t been on the plane or to the house, then that gives you a valuable PR and political currency. You can hang him in a way that potentially generates a positive benefit for you, or, if it really looks like he could win, you could save him, generating a debt."</p><p class="sc-9a00e533-0 eZyhnA">He adds: "Of course, it is possible that, when asked, he''ll say Jeffrey is a great guy and has gotten a raw deal and is a victim of political correctness, which is to be outlawed in a Trump regime."</p></div><figure><div data-component="image-block" class="sc-3b6b161a-0 gXrNRM"><div data-testid="image" class="sc-5340b511-1 cMIbKV"><img sizes="(min-width: 1280px) 50vw, (min-width: 1008px) 66vw, 96vw" srcset="https://ichef.bbci.co.uk/news/240/cpsprodpb/f6fa/live/a45b6e60-c01f-11f0-8456-eff94716b162.jpg.webp 240w,https://ichef.bbci.co.uk/news/320/cpsprodpb/f6fa/live/a45b6e60-c01f-11f0-8456-eff94716b162.jpg.webp 320w,https://ichef.bbci.co.uk/news/480/cpsprodpb/f6fa/live/a45b6e60-c01f-11f0-8456-eff94716b162.jpg.webp 480w,https://ichef.bbci.co.uk/news/640/cpsprodpb/f6fa/live/a45b6e60-c01f-11f0-8456-eff94716b162.jpg.webp 640w,https://ichef.bbci.co.uk/news/800/cpsprodpb/f6fa/live/a45b6e60-c01f-11f0-8456-eff94716b162.jpg.webp 800w,https://ichef.bbci.co.uk/news/1024/cpsprodpb/f6fa/live/a45b6e60-c01f-11f0-8456-eff94716b162.jpg.webp 1024w,https://ichef.bbci.co.uk/news/1536/cpsprodpb/f6fa/live/a45b6e60-c01f-11f0-8456-eff94716b162.jpg.webp 1536w" src="https://ichef.bbci.co.uk/news/480/cpsprodpb/f6fa/live/a45b6e60-c01f-11f0-8456-eff94716b162.jpg.webp" loading="lazy" alt="Reuters Author Michael Wolff is seen on the set of NBC''s ''Today''  in 2018" class="sc-5340b511-0 hLdNfA"><span class="sc-5340b511-2 jVqbAn">Reuters</span></div></div><div data-component="caption-block" class="sc-3b6b161a-0 Qwxkf"></div></figure><div data-testid="ad-unit" data-component="ad-slot" class="sc-1b734f04-0 kNNIux"><div data-testid="dotcom-mid_3" id="dotcom-mid_3" class="dotcom-ad"></div></div><div data-component="text-block" class="sc-3b6b161a-0 dPVOKT"><p class="sc-9a00e533-0 eZyhnA">In a separate email from October 2016, days before the US presidential election, Wolff offers Epstein a chance to sit for an interview that could "finish" Trump. </p><p class="sc-9a00e533-0 eZyhnA">"There''s an opportunity to come forward this week and talk about Trump in such a way that could garner you great sympathy and help finish him. Interested?", Wolff writes to Epstein.</p><p class="sc-9a00e533-0 eZyhnA">A third email released by Democrats is dated January 2019, during Trump''s first term in office.  </p><p class="sc-9a00e533-0 eZyhnA">In it, Epstein tells Wolff: "Trump said he asked me to resign" apparently referring to his membership at the president''s Mar-a-Lago club, adding, he was "never a member ever". </p><p class="sc-9a00e533-0 eZyhnA">Epstein adds that "of course he knew about the girls as he asked Ghislaine to stop". </p><p class="sc-9a00e533-0 eZyhnA">Responding to the release in a video he posted to Instagram, Wolff said: "Some of those emails are between Epstein and me, with Epstein discussing his relationship with Donald Trump."</p><p class="sc-9a00e533-0 eZyhnA">"I have been trying to talk about this story for a very long time now," he added.</p></div><div data-component="subheadline-block" class="sc-3b6b161a-0 hNbOGD"><h2 class="sc-f98b1ad2-0 gXmhTb">Andrew emailed Epstein in 2011</h2></div><div data-component="text-block" class="sc-3b6b161a-0 dPVOKT"><p class="sc-9a00e533-0 eZyhnA">As well as Trump, a released document also mentions Andrew Mountbatten-Windsor, formerly Prince Andrew.</p><p class="sc-9a00e533-0 eZyhnA">He responded to an email forwarded by Ghislaine Maxwell via Jeffrey Epstein in March 2011 about alleged sexual activity with a masseuse working for Epstein.</p><p class="sc-9a00e533-0 eZyhnA">Andrew''s reply reads: "Hey there! What''s all this? I don''t know anything about this! You must SAY so please. This has NOTHING to do with me. I can''t take any more of this."</p><p class="sc-9a00e533-0 eZyhnA">Maxwell had forwarded a "right of reply" email from the Mail on Sunday on 4 March, making numerous allegations about Maxwell, Epstein, and then-Prince Andrew.</p><p class="sc-9a00e533-0 eZyhnA">The right of reply email states that a woman, whose name is redacted in the released document, was introduced to Andrew by the disgraced financier in 2001, at Maxwell''s house in London where she had sex with Andrew.</p><p class="sc-9a00e533-0 eZyhnA">On 6 March 2011 the Mail on Sunday published a story including a photograph of Prince Andrew and Virginia Guiffre.</p><p class="sc-9a00e533-0 eZyhnA">Andrew has always denied any wrongdoing and has not faced any charges.</p></div><div data-testid="ad-unit" data-component="ad-slot" class="sc-1b734f04-0 kNNIux"><div data-testid="dotcom-mid_4" id="dotcom-mid_4" class="dotcom-ad"></div></div><div data-component="video-block" data-testid="fabl-video-container" class="sc-3b6b161a-0 gXrNRM"><div class="sc-2218ed0c-1 fiqjXZ"><div data-testid style="visibility:hidden" class="sc-2218ed0c-2 bgTyRA"></div></div></div><div data-component="caption-block" class="sc-3b6b161a-0 Qwxkf"></div><div data-component="subheadline-block" class="sc-3b6b161a-0 hNbOGD"><h2 class="sc-f98b1ad2-0 gXmhTb">Peter Mandelson contacted Epstein in 2016</h2></div><div data-component="text-block" class="sc-3b6b161a-0 dPVOKT"><p class="sc-9a00e533-0 eZyhnA">Lord Peter Mandelson, who was sacked as the UK''s ambassador to the US in September over his links to Epstein, is also mentioned in the new documents.</p><p class="sc-9a00e533-0 eZyhnA"><a target="_self" href="https://www.bbc.com/news/articles/c0jdl8wzvnvo" class="sc-f9178328-0 iCaRzc">They show he was in contact with Epstein as late as 2016</a>, according to the documents.</p><p class="sc-9a00e533-0 eZyhnA">The latest previous reported contact between the pair was when the then-business secretary took advice from Epstein in a banking deal in March 2010, just months after the American businessman''s release from prison for child sex offences, as reported by the Daily Telegraph.</p><p class="sc-9a00e533-0 eZyhnA">An email from Epstein to Lord Mandelson on 6 November 2015, shortly after the peer''s birthday, reads: "63 years old. You made it".</p><p class="sc-9a00e533-0 eZyhnA">Lord Mandelson replies less than 90 minutes later saying: "Just. I have decided to extend my life by spending more of it in the US".</p><p class="sc-9a00e533-0 eZyhnA">Epstein then replies "in the Donald White House", referring to the US presidential election due later that week.</p><p class="sc-9a00e533-0 eZyhnA">Epstein goes on to say "you were right about staying away from Andrew. I was right in your staying with Rinaldo [sic]", a reference to Lord Mandelson''s now-husband Reinaldo Avilda da Silva.</p><p class="sc-9a00e533-0 eZyhnA">Lord Mandelson has repeatedly said he regrets his relationship with Epstein. He declined to comment on the emails when approached by the BBC.</p></div><div data-component="subheadline-block" class="sc-3b6b161a-0 hNbOGD"><h2 class="sc-f98b1ad2-0 gXmhTb">What the survivors have said</h2></div><div data-component="text-block" class="sc-3b6b161a-0 dPVOKT"><p class="sc-9a00e533-0 eZyhnA">Annie Farmer, one of Epstein''s accusers and a key witness in Maxwell''s sex trafficking trial, shared a statement after the emails were released. </p><p class="sc-9a00e533-0 eZyhnA">In it she said: "The more information that comes out about Jeffrey Epstein, the more questions we''re left with. Survivors deserve more than a trickle of information."</p><p class="sc-9a00e533-0 eZyhnA">Farmer demanded the "full release" of the so-called Epstein files and said "the estimated one thousand women and girls who were harmed by Epstein and his associates deserve full transparency".</p></div><div data-component="links-block" class="sc-3b6b161a-0 djqsWD"><div class="sc-666b6d83-0 sc-c4fb5674-0 jYmMqa kGPvxx"><div data-testid="links-grid" class="sc-666b6d83-0 sc-c4fb5674-1 gEjRXC jkjVgq"><div data-testid="chester-card" data-indexcard="true" class="sc-225578b-0 ezQaGx"><div data-testid="anchor-inner-wrapper"><a href="https://www.bbc.com/news/articles/cp8j3e5g74no" data-testid="external-anchor" target="_self" class="sc-8a623a54-0 huZCWi"><div data-testid="chester-article" class="sc-cf565bcc-0 kwPVOm"><div class="sc-fa814188-1 iRoJZi"><div class="sc-fa814188-0 hPhBqv"><h2 data-testid="card-headline" class="sc-fa814188-3 iCfgww">Trump is used to shaking off criticism - but the Epstein story is different</h2></div></div></div></a></div></div><div data-testid="chester-card" data-indexcard="true" class="sc-225578b-0 ezQaGx"><div data-testid="anchor-inner-wrapper"><a href="https://www.bbc.com/news/articles/cdx5xzy8kn1o" data-testid="external-anchor" target="_self" class="sc-8a623a54-0 huZCWi"><div data-testid="chester-article" class="sc-cf565bcc-0 kwPVOm"><div class="sc-fa814188-1 iRoJZi"><div class="sc-fa814188-0 hPhBqv"><h2 data-testid="card-headline" class="sc-fa814188-3 iCfgww">How Epstein case is tearing apart Maga''s online conspiracy wing</h2></div></div></div></a></div></div><div data-testid="chester-card" data-indexcard="true" class="sc-225578b-0 ezQaGx"><div data-testid="anchor-inner-wrapper"><a href="https://www.bbc.com/news/world-us-canada-48913377" data-testid="external-anchor" target="_self" class="sc-8a623a54-0 huZCWi"><div data-testid="chester-article" class="sc-cf565bcc-0 kwPVOm"><div class="sc-fa814188-1 iRoJZi"><div class="sc-fa814188-0 hPhBqv"><h2 data-testid="card-headline" class="sc-fa814188-3 iCfgww">Who was Jeffrey Epstein?</h2></div></div></div></a></div></div></div></div></div><div data-component="tags" class="sc-3b6b161a-0 djqsWD"><div class="sc-6bf80075-0 lllwyY"><div data-testid="anchor-inner-wrapper"><a href="https://www.bbc.com/news/topics/cl7003r72r4t" data-testid="internal-link" class="sc-57521d02-0 jsVxCb">Jeffrey Epstein</a></div><div data-testid="anchor-inner-wrapper"><a href="https://www.bbc.com/news/topics/cp7r8vgl2lgt" data-testid="internal-link" class="sc-57521d02-0 jsVxCb">Donald Trump</a></div><div data-testid="anchor-inner-wrapper"><a href="https://www.bbc.com/news/topics/cwnpxwzd269t" data-testid="internal-link" class="sc-57521d02-0 jsVxCb">US politics</a></div><div data-testid="anchor-inner-wrapper"><a href="https://www.bbc.com/news/topics/cx1m7zg01xyt" data-testid="internal-link" class="sc-57521d02-0 jsVxCb">United States</a></div></div></div>', NULL, NULL);
INSERT INTO lost_and_found VALUES(50, 50, 14, 3, 1059, 1763020371263, NULL, 1763014529000, 1, 1763020371263, 'en-GB', 'UK&#039;s first small nuclear power station to be built in north Wales ', 'https://www.bbc.com/news/articles/c051y3d7myzo?at_medium=RSS&at_campaign=rss', 'https://www.bbc.com/news/articles/c051y3d7myzo?at_medium=RSS&at_campaign=rss', NULL, '<div data-component="headline-block" class="sc-3b6b161a-0 hNbOGD"><h1 class="sc-f98b1ad2-0 idLnWK">UK''s first small nuclear power station to be built in north Wales </h1></div><div data-component="byline-block" class="sc-3b6b161a-0 dPVOKT"><div data-testid="byline-new" class="sc-7bfdb3c2-0 fYJjWP"><div class="sc-7bfdb3c2-1 jqWinX"><time datetime="2025-11-13T06:15:29.314Z" class="sc-7bfdb3c2-2 dQuPjg">2 hours ago</time><div class="sc-7bfdb3c2-3 dVvYwG"></div></div><span data-testid="byline-new-contributors" class="sc-7bfdb3c2-11 ljQVMv"><span class="sc-7bfdb3c2-7 byKoUE">Gareth Lewis,</span><span data-testid="byline-new-contributors-contributor-0-role-location" class="sc-7bfdb3c2-8 gTWlHk">Wales political editor</span><span class="sc-7bfdb3c2-9 bTXCSY"> and </span></span></div><div data-testid="byline-new-contributors-contributor-1" class="sc-7bfdb3c2-5 fMReXM"><span class="sc-7bfdb3c2-7 byKoUE">Steffan Messenger,</span><span data-testid="byline-new-contributors-contributor-1-role-location" class="sc-7bfdb3c2-8 gTWlHk">Wales environment correspondent</span></div><div class="sc-7bfdb3c2-4 haycoC"></div></div><figure><div data-component="image-block" class="sc-3b6b161a-0 gtLOOD"><div data-testid="hero-image" class="sc-5340b511-1 cMIbKV"><img srcset="https://ichef.bbci.co.uk/news/240/cpsprodpb/cac0/live/8f637330-bfe9-11f0-99d4-1742bdf50d15.jpg.webp 240w, https://ichef.bbci.co.uk/news/320/cpsprodpb/cac0/live/8f637330-bfe9-11f0-99d4-1742bdf50d15.jpg.webp 320w, https://ichef.bbci.co.uk/news/480/cpsprodpb/cac0/live/8f637330-bfe9-11f0-99d4-1742bdf50d15.jpg.webp 480w, https://ichef.bbci.co.uk/news/640/cpsprodpb/cac0/live/8f637330-bfe9-11f0-99d4-1742bdf50d15.jpg.webp 640w, https://ichef.bbci.co.uk/news/800/cpsprodpb/cac0/live/8f637330-bfe9-11f0-99d4-1742bdf50d15.jpg.webp 800w, https://ichef.bbci.co.uk/news/1024/cpsprodpb/cac0/live/8f637330-bfe9-11f0-99d4-1742bdf50d15.jpg.webp 1024w, https://ichef.bbci.co.uk/news/1536/cpsprodpb/cac0/live/8f637330-bfe9-11f0-99d4-1742bdf50d15.jpg.webp 1536w" src="https://ichef.bbci.co.uk/news/480/cpsprodpb/cac0/live/8f637330-bfe9-11f0-99d4-1742bdf50d15.jpg.webp" alt="BBC The Wylfa site, taken from a road with part of the tarmac visible as well as hedges and grass." class="sc-5340b511-0 hLdNfA" /><span class="sc-5340b511-2 jVqbAn">BBC</span></div></div><div data-component="caption-block" class="sc-3b6b161a-0 Qwxkf"></div></figure><div data-component="text-block" class="sc-3b6b161a-0 dPVOKT"><p class="sc-9a00e533-0 eZyhnA">A first-of-its-kind nuclear power station is to be built on Anglesey, bringing up to 3,000 jobs and billions of pounds of investment.</p><p class="sc-9a00e533-0 eZyhnA">The plant at Wylfa, on the Welsh island''s northern coast, will have the UK''s first three small modular reactors (SMR), although the site could potentially hold up to eight.</p><p class="sc-9a00e533-0 eZyhnA">Work is due to start next year with the aim of generating power by the mid 2030s.</p><p class="sc-9a00e533-0 eZyhnA">Prime Minister Sir Keir Starmer said: "Britain was once a world leader in nuclear power, but years of neglect and inertia has meant places like Anglesey have been let down and left behind. Today, that changes."</p></div><div data-testid="ad-unit" data-component="ad-slot" class="sc-1b734f04-0 kNNIux"><div data-testid="dotcom-mid_1" id="dotcom-mid_1" class="dotcom-ad"></div></div><div data-component="text-block" class="sc-3b6b161a-0 dPVOKT"><p class="sc-9a00e533-0 eZyhnA">The news was also welcomed by First Minister Eluned Morgan, who said she had been "pressing the case at every opportunity for Wylfa''s incredible benefits".</p><p class="sc-9a00e533-0 eZyhnA">Using the Welsh name for Anglesey, she described it as "the moment Ynys Môn and the whole of Wales has been waiting for".</p><p class="sc-9a00e533-0 eZyhnA">The project, which could power about three million homes, will be built by publicly owned Great British Energy-Nuclear and is backed by a £2.5bn investment from the UK government.</p><p class="sc-9a00e533-0 eZyhnA"><a target="_self" href="https://www.bbc.co.uk/news/articles/c62614wejk5o" class="sc-f9178328-0 iCaRzc">SMRs work similarly to large reactors</a>, using a nuclear reaction to generate heat that produces electricity - but are a fraction of the size, with about a third of the generating output.</p><p class="sc-9a00e533-0 eZyhnA">Simon Bowen, chair of Great British Energy-Nuclear, said: "This is a historic moment for the UK, and is another momentous step in realising Britain''s potential in leading the way on nuclear energy.</p><p class="sc-9a00e533-0 eZyhnA">"These first SMRs at Wylfa will lay the groundwork for a fleet-based approach to nuclear development, strengthening the UK''s energy independence and bringing long-term investment to the local economy."</p></div><figure><div data-component="image-block" class="sc-3b6b161a-0 GunZh"><div data-testid="image" class="sc-5340b511-1 cMIbKV"><img srcset="https://ichef.bbci.co.uk/news/240/cpsprodpb/8298/live/2a2d4df0-bfea-11f0-8456-eff94716b162.png.webp 240w, https://ichef.bbci.co.uk/news/320/cpsprodpb/8298/live/2a2d4df0-bfea-11f0-8456-eff94716b162.png.webp 320w, https://ichef.bbci.co.uk/news/480/cpsprodpb/8298/live/2a2d4df0-bfea-11f0-8456-eff94716b162.png.webp 480w, https://ichef.bbci.co.uk/news/640/cpsprodpb/8298/live/2a2d4df0-bfea-11f0-8456-eff94716b162.png.webp 640w, https://ichef.bbci.co.uk/news/800/cpsprodpb/8298/live/2a2d4df0-bfea-11f0-8456-eff94716b162.png.webp 800w, https://ichef.bbci.co.uk/news/1024/cpsprodpb/8298/live/2a2d4df0-bfea-11f0-8456-eff94716b162.png.webp 1024w, https://ichef.bbci.co.uk/news/1536/cpsprodpb/8298/live/2a2d4df0-bfea-11f0-8456-eff94716b162.png.webp 1536w" src="https://ichef.bbci.co.uk/news/480/cpsprodpb/8298/live/2a2d4df0-bfea-11f0-8456-eff94716b162.png.webp" alt="Map showing the location of nuclear power stations in the UK" class="sc-5340b511-0 hLdNfA" /></div></div></figure><div data-testid="ad-unit" data-component="ad-slot" class="sc-1b734f04-0 kNNIux"><div data-testid="dotcom-mid_2" id="dotcom-mid_2" class="dotcom-ad"></div></div><div data-component="text-block" class="sc-3b6b161a-0 dPVOKT"><p class="sc-9a00e533-0 eZyhnA">The company has also been tasked with identifying potential sites for another large-scale nuclear power plant, similar to those being built at Hinkley Point in Somerset and Sizewell in Suffolk, which have the potential to power the equivalent of six million homes.</p><p class="sc-9a00e533-0 eZyhnA">It will report back by autumn 2026, and has been requested by Energy Secretary Ed Miliband to consider sites across the UK, including in Scotland, officials said.</p><p class="sc-9a00e533-0 eZyhnA">It is not clear whether the SMR plans, which are smaller and more straightforward to build, rule Wylfa out from being considered after it was designated the preferred location in 2024 by the previous UK Conservative government.</p><p class="sc-9a00e533-0 eZyhnA">The decision to opt for small modular reactors at Wylfa was criticised by the US ambassador Warren Stephens, who said he was "extremely disappointed" by the decision.</p><p class="sc-9a00e533-0 eZyhnA">He had been urging ministers to commit to a large-scale plant, with US firm Westinghouse having reportedly presented plans to build a new gigawatt station at the site.</p><p class="sc-9a00e533-0 eZyhnA">"If you want to get shovels in the ground as soon as possible and take a big step in addressing energy prices and availability, there is a different path, and we look forward to decisions soon on large-scale nuclear projects," Mr Stephens said.</p></div><figure><div data-component="image-block" class="sc-3b6b161a-0 GunZh"><div data-testid="image" class="sc-5340b511-1 cMIbKV"><img srcset="https://ichef.bbci.co.uk/news/240/cpsprodpb/865e/live/60898420-c05a-11f0-ae46-bd64331f0fd4.png.webp 240w, https://ichef.bbci.co.uk/news/320/cpsprodpb/865e/live/60898420-c05a-11f0-ae46-bd64331f0fd4.png.webp 320w, https://ichef.bbci.co.uk/news/480/cpsprodpb/865e/live/60898420-c05a-11f0-ae46-bd64331f0fd4.png.webp 480w, https://ichef.bbci.co.uk/news/640/cpsprodpb/865e/live/60898420-c05a-11f0-ae46-bd64331f0fd4.png.webp 640w, https://ichef.bbci.co.uk/news/800/cpsprodpb/865e/live/60898420-c05a-11f0-ae46-bd64331f0fd4.png.webp 800w, https://ichef.bbci.co.uk/news/1024/cpsprodpb/865e/live/60898420-c05a-11f0-ae46-bd64331f0fd4.png.webp 1024w, https://ichef.bbci.co.uk/news/1536/cpsprodpb/865e/live/60898420-c05a-11f0-ae46-bd64331f0fd4.png.webp 1536w" src="https://ichef.bbci.co.uk/news/480/cpsprodpb/865e/live/60898420-c05a-11f0-ae46-bd64331f0fd4.png.webp" alt="Graphic showing the difference between SMRs and large nuclear reactors" class="sc-5340b511-0 hLdNfA" /></div></div></figure><div data-testid="ad-unit" data-component="ad-slot" class="sc-1b734f04-0 kNNIux"><div data-testid="dotcom-mid_3" id="dotcom-mid_3" class="dotcom-ad"></div></div><div data-component="subheadline-block" class="sc-3b6b161a-0 hNbOGD"><h2 class="sc-f98b1ad2-0 gXmhTb">''Nuclear equivalent of an Ikea chair''</h2></div><div data-component="text-block" class="sc-3b6b161a-0 dPVOKT"><p class="sc-9a00e533-0 eZyhnA">One industry expert described the announcement as "incredible".</p><p class="sc-9a00e533-0 eZyhnA">Prof Simon Middleburgh, director of the Nuclear Futures Institute at Bangor University, said: "They''re smaller than the average reactor, built in a modular manner in factories and shipped to the site to be put together a bit like an Ikea chair."</p><p class="sc-9a00e533-0 eZyhnA">The planned SMRs "fit nicely" with the existing grid capacity at the Wylfa site, offering a similar electricity output as the old power plant currently being decommissioned, he added.</p><p class="sc-9a00e533-0 eZyhnA">There were "a few more hurdles to go through", he cautioned - from securing regulatory approval, building the factories required to construct the SMRs and training the workforce that will run them.</p><p class="sc-9a00e533-0 eZyhnA">Opponents of the project point to the fact that a long-term storage facility for the UK''s nuclear waste is yet to be agreed upon and say investment in renewable energy schemes - wind, wave and tidal - is what Anglesey needs.</p><p class="sc-9a00e533-0 eZyhnA">Dylan Morgan of campaign group People Against Wylfa-B told BBC Wales the proposed SMRs were far from "small" and were in fact "an unnecessarily big development of an unproven technology".</p><p class="sc-9a00e533-0 eZyhnA">"Modular reactor technologies have been touted by many companies internationally but are still only plans on paper," he said.</p><p class="sc-9a00e533-0 eZyhnA">The government sees them as a secure, reliable, affordable and low carbon energy system and is convinced that, with investment, SMRs will create thousands of jobs and boost manufacturing.</p></div><div data-component="embed-block" class="sc-3b6b161a-0 djqsWD"></div><div data-testid="ad-unit" data-component="ad-slot" class="sc-1b734f04-0 kNNIux"><div data-testid="dotcom-mid_4" id="dotcom-mid_4" class="dotcom-ad"></div></div><div data-component="text-block" class="sc-3b6b161a-0 dPVOKT"><p class="sc-9a00e533-0 eZyhnA">Wylfa beat off competition from another site at Oldbury in Gloucestershire, with the reactors designed by British engineering firm Rolls-Royce, subject to final contracts, which are expected later this year.</p><p class="sc-9a00e533-0 eZyhnA">The UK government said the plant would help provide energy independence.</p><p class="sc-9a00e533-0 eZyhnA">The old nuclear power plant at Wylfa was switched off in 2015 and previous plans for a large-scale replacement fell through in 2021.</p><p class="sc-9a00e533-0 eZyhnA">The company behind the scheme – the Japanese industrial giant Hitachi - cited spiralling costs and a failure to reach agreement with the UK government over funding.</p><p class="sc-9a00e533-0 eZyhnA">Sasha Wynn Davies - now chairwoman of the Wales Nuclear Forum - worked as a senior manager on those plans.</p><p class="sc-9a00e533-0 eZyhnA">"I will never forget going to the secondary school in Amlwch and speaking to some of the young students and pupils there to unfortunately say that we were not progressing as a project," she said.</p><p class="sc-9a00e533-0 eZyhnA">"I will never forget their faces as they were so sad on behalf of their hopes for the future but also for their parents and what it meant for the area economically and socially.</p><p class="sc-9a00e533-0 eZyhnA">"So now let''s hope our time has come again and there''s hope for our young people in particular."</p></div><div data-component="text-block" class="sc-3b6b161a-0 dPVOKT"><p class="sc-9a00e533-0 eZyhnA">There is a huge political component to the announcement, with Labour''s leadership in Westminster keen to show that it means business when it comes to big investment in infrastructure projects</p><p class="sc-9a00e533-0 eZyhnA">In Wales, the first minister has been pushing hard for Wylfa - and the announcement comes just six months before the Senedd election.</p><p class="sc-9a00e533-0 eZyhnA">Eluned Morgan has been trying to strike a balance: differentiating the Welsh party from UK Labour, but also pushing for extra funding, further devolution of powers and big investment announcements from her UK colleagues.</p><p class="sc-9a00e533-0 eZyhnA">She has certainly got the latter, although plenty of other issues such as reform to the way Wales is funded and devolution of the Crown Estate – the body which owns much of the Welsh coastline and vital to future wind power – remain unresolved.</p></div><div data-component="links-block" class="sc-3b6b161a-0 djqsWD"><div class="sc-666b6d83-0 sc-c4fb5674-0 jYmMqa kGPvxx"><span data-testid="links-title" class="sc-c4fb5674-2 bBuHEW">More top stories</span><div data-testid="links-grid" class="sc-666b6d83-0 sc-c4fb5674-1 gEjRXC jkjVgq"><div data-testid="chester-card" data-indexcard="true" class="sc-225578b-0 ezQaGx"><div data-testid="anchor-inner-wrapper"><a href="https://www.bbc.co.uk/news/articles/c62e1p7lv5vo" data-testid="external-anchor" target="_self" class="sc-8a623a54-0 huZCWi"><div data-testid="chester-article" class="sc-cf565bcc-0 kwPVOm"><div class="sc-fa814188-1 iRoJZi"><div class="sc-fa814188-0 hPhBqv"><h2 data-testid="card-headline" class="sc-fa814188-3 iCfgww">Injured motorcyclists rescued after bike sent SOS alert</h2></div></div></div></a></div></div><div data-testid="chester-card" data-indexcard="true" class="sc-225578b-0 ezQaGx"><div data-testid="anchor-inner-wrapper"><a href="https://www.bbc.co.uk/news/articles/c9d62zj2vnzo" data-testid="external-anchor" target="_self" class="sc-8a623a54-0 huZCWi"><div data-testid="chester-article" class="sc-cf565bcc-0 kwPVOm"><div class="sc-fa814188-1 iRoJZi"><div class="sc-fa814188-0 hPhBqv"><h2 data-testid="card-headline" class="sc-fa814188-3 iCfgww">Charlotte Church''s son makes acting debut in short film</h2></div></div></div></a></div></div><div data-testid="chester-card" data-indexcard="true" class="sc-225578b-0 ezQaGx"><div data-testid="anchor-inner-wrapper"><a href="https://www.bbc.co.uk/news/articles/c986v50088go" data-testid="external-anchor" target="_self" class="sc-8a623a54-0 huZCWi"><div data-testid="chester-article" class="sc-cf565bcc-0 kwPVOm"><div class="sc-fa814188-1 iRoJZi"><div class="sc-fa814188-0 hPhBqv"><h2 data-testid="card-headline" class="sc-fa814188-3 iCfgww">City''s overnight visitors could face £1.30 per night tax</h2></div></div></div></a></div></div></div></div></div><div data-component="tags" class="sc-3b6b161a-0 djqsWD"><div class="sc-6bf80075-0 lllwyY"><div data-testid="anchor-inner-wrapper"><a href="https://www.bbc.com/news/topics/c03654x4n8nt" data-testid="internal-link" class="sc-57521d02-0 jsVxCb">Wylfa nuclear power project</a></div><div data-testid="anchor-inner-wrapper"><a href="https://www.bbc.com/news/wales" data-testid="internal-link" class="sc-57521d02-0 jsVxCb">Wales</a></div><div data-testid="anchor-inner-wrapper"><a href="https://www.bbc.com/news/topics/c6ly3zw499nt" data-testid="internal-link" class="sc-57521d02-0 jsVxCb">UK government</a></div><div data-testid="anchor-inner-wrapper"><a href="https://www.bbc.com/news/topics/cmj34zmwm52t" data-testid="internal-link" class="sc-57521d02-0 jsVxCb">Nuclear power</a></div></div></div>', NULL, '<div data-component="headline-block" class="sc-3b6b161a-0 hNbOGD"><h1 class="sc-f98b1ad2-0 idLnWK">UK''s first small nuclear power station to be built in north Wales </h1></div><div data-component="byline-block" class="sc-3b6b161a-0 dPVOKT"><div data-testid="byline-new" class="sc-7bfdb3c2-0 fYJjWP"><div class="sc-7bfdb3c2-1 jqWinX"><time datetime="2025-11-13T06:15:29.314Z" class="sc-7bfdb3c2-2 dQuPjg">2 hours ago</time><div class="sc-7bfdb3c2-3 dVvYwG"></div></div><span data-testid="byline-new-contributors" class="sc-7bfdb3c2-11 ljQVMv"><div data-testid="byline-new-contributors-contributor-0" class="sc-7bfdb3c2-5 fMReXM"><span class="sc-7bfdb3c2-7 byKoUE">Gareth Lewis,</span><span data-testid="byline-new-contributors-contributor-0-role-location" class="sc-7bfdb3c2-8 gTWlHk">Wales political editor</span><span class="sc-7bfdb3c2-9 bTXCSY"> and </span></div><div data-testid="byline-new-contributors-contributor-1" class="sc-7bfdb3c2-5 fMReXM"><span class="sc-7bfdb3c2-7 byKoUE">Steffan Messenger,</span><span data-testid="byline-new-contributors-contributor-1-role-location" class="sc-7bfdb3c2-8 gTWlHk">Wales environment correspondent</span></div></span><div class="sc-7bfdb3c2-4 haycoC"></div></div></div><figure><div data-component="image-block" class="sc-3b6b161a-0 gtLOOD"><div data-testid="hero-image" class="sc-5340b511-1 cMIbKV"><img sizes="(min-width: 1280px) 50vw, (min-width: 1008px) 66vw, 96vw" srcset="https://ichef.bbci.co.uk/news/240/cpsprodpb/cac0/live/8f637330-bfe9-11f0-99d4-1742bdf50d15.jpg.webp 240w,https://ichef.bbci.co.uk/news/320/cpsprodpb/cac0/live/8f637330-bfe9-11f0-99d4-1742bdf50d15.jpg.webp 320w,https://ichef.bbci.co.uk/news/480/cpsprodpb/cac0/live/8f637330-bfe9-11f0-99d4-1742bdf50d15.jpg.webp 480w,https://ichef.bbci.co.uk/news/640/cpsprodpb/cac0/live/8f637330-bfe9-11f0-99d4-1742bdf50d15.jpg.webp 640w,https://ichef.bbci.co.uk/news/800/cpsprodpb/cac0/live/8f637330-bfe9-11f0-99d4-1742bdf50d15.jpg.webp 800w,https://ichef.bbci.co.uk/news/1024/cpsprodpb/cac0/live/8f637330-bfe9-11f0-99d4-1742bdf50d15.jpg.webp 1024w,https://ichef.bbci.co.uk/news/1536/cpsprodpb/cac0/live/8f637330-bfe9-11f0-99d4-1742bdf50d15.jpg.webp 1536w" src="https://ichef.bbci.co.uk/news/480/cpsprodpb/cac0/live/8f637330-bfe9-11f0-99d4-1742bdf50d15.jpg.webp" loading="eager" alt="BBC The Wylfa site, taken from a road with part of the tarmac visible as well as hedges and grass." class="sc-5340b511-0 hLdNfA"><span class="sc-5340b511-2 jVqbAn">BBC</span></div></div><div data-component="caption-block" class="sc-3b6b161a-0 Qwxkf"></div></figure><div data-component="text-block" class="sc-3b6b161a-0 dPVOKT"><p class="sc-9a00e533-0 eZyhnA">A first-of-its-kind nuclear power station is to be built on Anglesey, bringing up to 3,000 jobs and billions of pounds of investment.</p><p class="sc-9a00e533-0 eZyhnA">The plant at Wylfa, on the Welsh island''s northern coast, will have the UK''s first three small modular reactors (SMR), although the site could potentially hold up to eight.</p><p class="sc-9a00e533-0 eZyhnA">Work is due to start next year with the aim of generating power by the mid 2030s.</p><p class="sc-9a00e533-0 eZyhnA">Prime Minister Sir Keir Starmer said: "Britain was once a world leader in nuclear power, but years of neglect and inertia has meant places like Anglesey have been let down and left behind. Today, that changes."</p></div><div data-testid="ad-unit" data-component="ad-slot" class="sc-1b734f04-0 kNNIux"><div data-testid="dotcom-mid_1" id="dotcom-mid_1" class="dotcom-ad"></div></div><div data-component="text-block" class="sc-3b6b161a-0 dPVOKT"><p class="sc-9a00e533-0 eZyhnA">The news was also welcomed by First Minister Eluned Morgan, who said she had been "pressing the case at every opportunity for Wylfa''s incredible benefits".</p><p class="sc-9a00e533-0 eZyhnA">Using the Welsh name for Anglesey, she described it as "the moment Ynys Môn and the whole of Wales has been waiting for".</p><p class="sc-9a00e533-0 eZyhnA">The project, which could power about three million homes, will be built by publicly owned Great British Energy-Nuclear and is backed by a £2.5bn investment from the UK government.</p><p class="sc-9a00e533-0 eZyhnA"><a target="_self" href="https://www.bbc.co.uk/news/articles/c62614wejk5o" class="sc-f9178328-0 iCaRzc">SMRs work similarly to large reactors</a>, using a nuclear reaction to generate heat that produces electricity - but are a fraction of the size, with about a third of the generating output.</p><p class="sc-9a00e533-0 eZyhnA">Simon Bowen, chair of Great British Energy-Nuclear, said: "This is a historic moment for the UK, and is another momentous step in realising Britain''s potential in leading the way on nuclear energy.</p><p class="sc-9a00e533-0 eZyhnA">"These first SMRs at Wylfa will lay the groundwork for a fleet-based approach to nuclear development, strengthening the UK''s energy independence and bringing long-term investment to the local economy."</p></div><figure><div data-component="image-block" class="sc-3b6b161a-0 GunZh"><div data-testid="image" class="sc-5340b511-1 cMIbKV"><img sizes="(min-width: 1280px) 50vw, (min-width: 1008px) 66vw, 96vw" srcset="https://ichef.bbci.co.uk/news/240/cpsprodpb/8298/live/2a2d4df0-bfea-11f0-8456-eff94716b162.png.webp 240w,https://ichef.bbci.co.uk/news/320/cpsprodpb/8298/live/2a2d4df0-bfea-11f0-8456-eff94716b162.png.webp 320w,https://ichef.bbci.co.uk/news/480/cpsprodpb/8298/live/2a2d4df0-bfea-11f0-8456-eff94716b162.png.webp 480w,https://ichef.bbci.co.uk/news/640/cpsprodpb/8298/live/2a2d4df0-bfea-11f0-8456-eff94716b162.png.webp 640w,https://ichef.bbci.co.uk/news/800/cpsprodpb/8298/live/2a2d4df0-bfea-11f0-8456-eff94716b162.png.webp 800w,https://ichef.bbci.co.uk/news/1024/cpsprodpb/8298/live/2a2d4df0-bfea-11f0-8456-eff94716b162.png.webp 1024w,https://ichef.bbci.co.uk/news/1536/cpsprodpb/8298/live/2a2d4df0-bfea-11f0-8456-eff94716b162.png.webp 1536w" src="https://ichef.bbci.co.uk/news/480/cpsprodpb/8298/live/2a2d4df0-bfea-11f0-8456-eff94716b162.png.webp" loading="lazy" alt="Map showing the location of nuclear power stations in the UK" class="sc-5340b511-0 hLdNfA"></div></div></figure><div data-testid="ad-unit" data-component="ad-slot" class="sc-1b734f04-0 kNNIux"><div data-testid="dotcom-mid_2" id="dotcom-mid_2" class="dotcom-ad"></div></div><div data-component="text-block" class="sc-3b6b161a-0 dPVOKT"><p class="sc-9a00e533-0 eZyhnA">The company has also been tasked with identifying potential sites for another large-scale nuclear power plant, similar to those being built at Hinkley Point in Somerset and Sizewell in Suffolk, which have the potential to power the equivalent of six million homes.</p><p class="sc-9a00e533-0 eZyhnA">It will report back by autumn 2026, and has been requested by Energy Secretary Ed Miliband to consider sites across the UK, including in Scotland, officials said.</p><p class="sc-9a00e533-0 eZyhnA">It is not clear whether the SMR plans, which are smaller and more straightforward to build, rule Wylfa out from being considered after it was designated the preferred location in 2024 by the previous UK Conservative government.</p><p class="sc-9a00e533-0 eZyhnA">The decision to opt for small modular reactors at Wylfa was criticised by the US ambassador Warren Stephens, who said he was "extremely disappointed" by the decision.</p><p class="sc-9a00e533-0 eZyhnA">He had been urging ministers to commit to a large-scale plant, with US firm Westinghouse having reportedly presented plans to build a new gigawatt station at the site.</p><p class="sc-9a00e533-0 eZyhnA">"If you want to get shovels in the ground as soon as possible and take a big step in addressing energy prices and availability, there is a different path, and we look forward to decisions soon on large-scale nuclear projects," Mr Stephens said.</p></div><figure><div data-component="image-block" class="sc-3b6b161a-0 GunZh"><div data-testid="image" class="sc-5340b511-1 cMIbKV"><img sizes="(min-width: 1280px) 50vw, (min-width: 1008px) 66vw, 96vw" srcset="https://ichef.bbci.co.uk/news/240/cpsprodpb/865e/live/60898420-c05a-11f0-ae46-bd64331f0fd4.png.webp 240w,https://ichef.bbci.co.uk/news/320/cpsprodpb/865e/live/60898420-c05a-11f0-ae46-bd64331f0fd4.png.webp 320w,https://ichef.bbci.co.uk/news/480/cpsprodpb/865e/live/60898420-c05a-11f0-ae46-bd64331f0fd4.png.webp 480w,https://ichef.bbci.co.uk/news/640/cpsprodpb/865e/live/60898420-c05a-11f0-ae46-bd64331f0fd4.png.webp 640w,https://ichef.bbci.co.uk/news/800/cpsprodpb/865e/live/60898420-c05a-11f0-ae46-bd64331f0fd4.png.webp 800w,https://ichef.bbci.co.uk/news/1024/cpsprodpb/865e/live/60898420-c05a-11f0-ae46-bd64331f0fd4.png.webp 1024w,https://ichef.bbci.co.uk/news/1536/cpsprodpb/865e/live/60898420-c05a-11f0-ae46-bd64331f0fd4.png.webp 1536w" src="https://ichef.bbci.co.uk/news/480/cpsprodpb/865e/live/60898420-c05a-11f0-ae46-bd64331f0fd4.png.webp" loading="lazy" alt="Graphic showing the difference between SMRs and large nuclear reactors" class="sc-5340b511-0 hLdNfA"></div></div></figure><div data-testid="ad-unit" data-component="ad-slot" class="sc-1b734f04-0 kNNIux"><div data-testid="dotcom-mid_3" id="dotcom-mid_3" class="dotcom-ad"></div></div><div data-component="subheadline-block" class="sc-3b6b161a-0 hNbOGD"><h2 class="sc-f98b1ad2-0 gXmhTb">''Nuclear equivalent of an Ikea chair''</h2></div><div data-component="text-block" class="sc-3b6b161a-0 dPVOKT"><p class="sc-9a00e533-0 eZyhnA">One industry expert described the announcement as "incredible".</p><p class="sc-9a00e533-0 eZyhnA">Prof Simon Middleburgh, director of the Nuclear Futures Institute at Bangor University, said: "They''re smaller than the average reactor, built in a modular manner in factories and shipped to the site to be put together a bit like an Ikea chair."</p><p class="sc-9a00e533-0 eZyhnA">The planned SMRs "fit nicely" with the existing grid capacity at the Wylfa site, offering a similar electricity output as the old power plant currently being decommissioned, he added.</p><p class="sc-9a00e533-0 eZyhnA">There were "a few more hurdles to go through", he cautioned - from securing regulatory approval, building the factories required to construct the SMRs and training the workforce that will run them.</p><p class="sc-9a00e533-0 eZyhnA">Opponents of the project point to the fact that a long-term storage facility for the UK''s nuclear waste is yet to be agreed upon and say investment in renewable energy schemes - wind, wave and tidal - is what Anglesey needs.</p><p class="sc-9a00e533-0 eZyhnA">Dylan Morgan of campaign group People Against Wylfa-B told BBC Wales the proposed SMRs were far from "small" and were in fact "an unnecessarily big development of an unproven technology".</p><p class="sc-9a00e533-0 eZyhnA">"Modular reactor technologies have been touted by many companies internationally but are still only plans on paper," he said.</p><p class="sc-9a00e533-0 eZyhnA">The government sees them as a secure, reliable, affordable and low carbon energy system and is convinced that, with investment, SMRs will create thousands of jobs and boost manufacturing.</p></div><div data-component="embed-block" class="sc-3b6b161a-0 djqsWD"></div><div data-testid="ad-unit" data-component="ad-slot" class="sc-1b734f04-0 kNNIux"><div data-testid="dotcom-mid_4" id="dotcom-mid_4" class="dotcom-ad"></div></div><div data-component="text-block" class="sc-3b6b161a-0 dPVOKT"><p class="sc-9a00e533-0 eZyhnA">Wylfa beat off competition from another site at Oldbury in Gloucestershire, with the reactors designed by British engineering firm Rolls-Royce, subject to final contracts, which are expected later this year.</p><p class="sc-9a00e533-0 eZyhnA">The UK government said the plant would help provide energy independence.</p><p class="sc-9a00e533-0 eZyhnA">The old nuclear power plant at Wylfa was switched off in 2015 and previous plans for a large-scale replacement fell through in 2021.</p><p class="sc-9a00e533-0 eZyhnA">The company behind the scheme – the Japanese industrial giant Hitachi - cited spiralling costs and a failure to reach agreement with the UK government over funding.</p><p class="sc-9a00e533-0 eZyhnA">Sasha Wynn Davies - now chairwoman of the Wales Nuclear Forum - worked as a senior manager on those plans.</p><p class="sc-9a00e533-0 eZyhnA">"I will never forget going to the secondary school in Amlwch and speaking to some of the young students and pupils there to unfortunately say that we were not progressing as a project," she said.</p><p class="sc-9a00e533-0 eZyhnA">"I will never forget their faces as they were so sad on behalf of their hopes for the future but also for their parents and what it meant for the area economically and socially.</p><p class="sc-9a00e533-0 eZyhnA">"So now let''s hope our time has come again and there''s hope for our young people in particular."</p></div><div data-component="text-block" class="sc-3b6b161a-0 dPVOKT"><p class="sc-9a00e533-0 eZyhnA">There is a huge political component to the announcement, with Labour''s leadership in Westminster keen to show that it means business when it comes to big investment in infrastructure projects</p><p class="sc-9a00e533-0 eZyhnA">In Wales, the first minister has been pushing hard for Wylfa - and the announcement comes just six months before the Senedd election.</p><p class="sc-9a00e533-0 eZyhnA">Eluned Morgan has been trying to strike a balance: differentiating the Welsh party from UK Labour, but also pushing for extra funding, further devolution of powers and big investment announcements from her UK colleagues.</p><p class="sc-9a00e533-0 eZyhnA">She has certainly got the latter, although plenty of other issues such as reform to the way Wales is funded and devolution of the Crown Estate – the body which owns much of the Welsh coastline and vital to future wind power – remain unresolved.</p></div><div data-component="links-block" class="sc-3b6b161a-0 djqsWD"><div class="sc-666b6d83-0 sc-c4fb5674-0 jYmMqa kGPvxx"><span data-testid="links-title" class="sc-c4fb5674-2 bBuHEW">More top stories</span><div data-testid="links-grid" class="sc-666b6d83-0 sc-c4fb5674-1 gEjRXC jkjVgq"><div data-testid="chester-card" data-indexcard="true" class="sc-225578b-0 ezQaGx"><div data-testid="anchor-inner-wrapper"><a href="https://www.bbc.co.uk/news/articles/c62e1p7lv5vo" data-testid="external-anchor" target="_self" class="sc-8a623a54-0 huZCWi"><div data-testid="chester-article" class="sc-cf565bcc-0 kwPVOm"><div class="sc-fa814188-1 iRoJZi"><div class="sc-fa814188-0 hPhBqv"><h2 data-testid="card-headline" class="sc-fa814188-3 iCfgww">Injured motorcyclists rescued after bike sent SOS alert</h2></div></div></div></a></div></div><div data-testid="chester-card" data-indexcard="true" class="sc-225578b-0 ezQaGx"><div data-testid="anchor-inner-wrapper"><a href="https://www.bbc.co.uk/news/articles/c9d62zj2vnzo" data-testid="external-anchor" target="_self" class="sc-8a623a54-0 huZCWi"><div data-testid="chester-article" class="sc-cf565bcc-0 kwPVOm"><div class="sc-fa814188-1 iRoJZi"><div class="sc-fa814188-0 hPhBqv"><h2 data-testid="card-headline" class="sc-fa814188-3 iCfgww">Charlotte Church''s son makes acting debut in short film</h2></div></div></div></a></div></div><div data-testid="chester-card" data-indexcard="true" class="sc-225578b-0 ezQaGx"><div data-testid="anchor-inner-wrapper"><a href="https://www.bbc.co.uk/news/articles/c986v50088go" data-testid="external-anchor" target="_self" class="sc-8a623a54-0 huZCWi"><div data-testid="chester-article" class="sc-cf565bcc-0 kwPVOm"><div class="sc-fa814188-1 iRoJZi"><div class="sc-fa814188-0 hPhBqv"><h2 data-testid="card-headline" class="sc-fa814188-3 iCfgww">City''s overnight visitors could face £1.30 per night tax</h2></div></div></div></a></div></div></div></div></div><div data-component="tags" class="sc-3b6b161a-0 djqsWD"><div class="sc-6bf80075-0 lllwyY"><div data-testid="anchor-inner-wrapper"><a href="https://www.bbc.com/news/topics/c03654x4n8nt" data-testid="internal-link" class="sc-57521d02-0 jsVxCb">Wylfa nuclear power project</a></div><div data-testid="anchor-inner-wrapper"><a href="https://www.bbc.com/news/wales" data-testid="internal-link" class="sc-57521d02-0 jsVxCb">Wales</a></div><div data-testid="anchor-inner-wrapper"><a href="https://www.bbc.com/news/topics/c6ly3zw499nt" data-testid="internal-link" class="sc-57521d02-0 jsVxCb">UK government</a></div><div data-testid="anchor-inner-wrapper"><a href="https://www.bbc.com/news/topics/cmj34zmwm52t" data-testid="internal-link" class="sc-57521d02-0 jsVxCb">Nuclear power</a></div></div></div>', NULL, NULL);
INSERT INTO lost_and_found VALUES(50, 50, 14, 4, 731, 1763020371868, NULL, 1763012339000, 1, 1763020371868, 'en-GB', 'Chris Mason: Unpicking a messy day for the government', 'https://www.bbc.com/news/articles/c5yl60yp9g6o?at_medium=RSS&at_campaign=rss', 'https://www.bbc.com/news/articles/c5yl60yp9g6o?at_medium=RSS&at_campaign=rss', NULL, '<div data-component="headline-block" class="sc-3b6b161a-0 hNbOGD"><h1 class="sc-f98b1ad2-0 idLnWK">Chris Mason: Unpicking a messy day for the government</h1></div><div data-component="byline-block" class="sc-3b6b161a-0 dPVOKT"><div data-testid="byline-new" class="sc-7bfdb3c2-0 fYJjWP"><div class="sc-7bfdb3c2-1 jqWinX"><time datetime="2025-11-13T05:38:59.885Z" class="sc-7bfdb3c2-2 dQuPjg">2 hours ago</time><div class="sc-7bfdb3c2-3 dVvYwG"></div></div><span data-testid="byline-new-contributors" class="sc-7bfdb3c2-11 ljQVMv"><span class="sc-7bfdb3c2-7 djOqvY">Chris Mason</span><span data-testid="byline-new-contributors-contributor-0-role-location" class="sc-7bfdb3c2-8 gvcwmG">Political editor</span></span></div></div><div class="sc-7bfdb3c2-4 haycoC"></div><figure><div data-component="image-block" class="sc-3b6b161a-0 eRlINq"><div data-testid="hero-image" class="sc-5340b511-1 cMIbKV"><img srcset="https://ichef.bbci.co.uk/news/240/cpsprodpb/6b25/live/e627e4b0-c031-11f0-9c25-7d417a285f78.jpg.webp 240w, https://ichef.bbci.co.uk/news/320/cpsprodpb/6b25/live/e627e4b0-c031-11f0-9c25-7d417a285f78.jpg.webp 320w, https://ichef.bbci.co.uk/news/480/cpsprodpb/6b25/live/e627e4b0-c031-11f0-9c25-7d417a285f78.jpg.webp 480w, https://ichef.bbci.co.uk/news/640/cpsprodpb/6b25/live/e627e4b0-c031-11f0-9c25-7d417a285f78.jpg.webp 640w, https://ichef.bbci.co.uk/news/800/cpsprodpb/6b25/live/e627e4b0-c031-11f0-9c25-7d417a285f78.jpg.webp 800w, https://ichef.bbci.co.uk/news/1024/cpsprodpb/6b25/live/e627e4b0-c031-11f0-9c25-7d417a285f78.jpg.webp 1024w, https://ichef.bbci.co.uk/news/1536/cpsprodpb/6b25/live/e627e4b0-c031-11f0-9c25-7d417a285f78.jpg.webp 1536w" src="https://ichef.bbci.co.uk/news/480/cpsprodpb/6b25/live/e627e4b0-c031-11f0-9c25-7d417a285f78.jpg.webp" alt="Getty Images UK Prime Minister Keir Starmer pictured in front of the Union Jack at 10 Downing Street. He wears a dark suit, dark tie and his customary black-framed glasses." class="sc-5340b511-0 hLdNfA" /><span class="sc-5340b511-2 jVqbAn">Getty Images</span></div></div></figure><div data-component="text-block" class="sc-3b6b161a-0 dPVOKT"><p class="sc-9a00e533-0 eZyhnA">"It''s not been our finest 24 hours in government," one senior figure in government acknowledged to me, after mudslinging one way and another, some in public, plenty more in private.</p><p class="sc-9a00e533-0 eZyhnA">I have been making loads of phone calls to patch together the anatomy of another bumpy few days for Downing Street: what those close to the Prime Minister hoped to achieve, what ended up happening and where all this leaves them.</p><p class="sc-9a00e533-0 eZyhnA">There are two key facts at the heart of all of this: the government is unpopular and so is the Prime Minister.</p><p class="sc-9a00e533-0 eZyhnA">These facts are the rocket fuel behind the constant conversations I hear about what Labour is trying to do about it and what it might mean for how long Sir Keir Starmer carries on in Downing Street.</p><p class="sc-9a00e533-0 eZyhnA">But let''s get to the aftermath of all that mudslinging.</p></div><div data-testid="ad-unit" data-component="ad-slot" class="sc-1b734f04-0 kNNIux"><div data-testid="dotcom-mid_1" id="dotcom-mid_1" class="dotcom-ad"></div></div><div data-component="text-block" class="sc-3b6b161a-0 dPVOKT"><ul class="sc-6f869981-0 diUlgm"><li class="sc-734a601e-0 cRgahm"><a target="_self" href="https://www.bbc.com/news/articles/c3vnyg1q503o" class="sc-f9178328-0 kgTYQp">I have never authorised attacks on ministers, says PM</a></li><li class="sc-734a601e-0 cRgahm"><a target="_self" href="http://bbc.com/news/articles/c9v124znrgmo" class="sc-f9178328-0 kgTYQp">Streeting denies plotting against PM after leadership claims</a></li><li class="sc-734a601e-0 cRgahm"><a target="_self" href="https://www.bbc.com/news/articles/c5y0z2q2g2ro" class="sc-f9178328-0 kgTYQp">Starmer will fight attempts to replace him, allies say</a></li></ul></div><div data-component="text-block" class="sc-3b6b161a-0 dPVOKT"><p class="sc-9a00e533-0 eZyhnA">The prime minister and Health Secretary Wes Streeting spoke on the phone on Wednesday evening to patch things up.</p><p class="sc-9a00e533-0 eZyhnA">I hear Sir Keir apologised to Streeting in the brief call and they agreed to talk in further detail "soon".</p><p class="sc-9a00e533-0 eZyhnA">They didn''t talk about Morgan McSweeney, the prime minister''s chief of staff - who has become a lightning rod for criticism from everyone including the Conservative leader Kemi Badenoch in public to Labour figures junior and senior in private.</p><p class="sc-9a00e533-0 eZyhnA">Widely credited as the mastermind of Labour''s election landslide and the political brain behind Sir Keir''s quick rise since switching from Director of Public Prosecutions, McSweeney is also among the first to face criticism when the Downing Street machine is perceived to have stuttered, stumbled or outright failed.</p><p class="sc-9a00e533-0 eZyhnA">He is not responding to requests for comment, as some call for his head on a stick.</p><p class="sc-9a00e533-0 eZyhnA">His critics argue that in a Downing Street where McSweeney is called on to make plenty of big political judgements, he should take responsibility for how all of this unfolded.</p><p class="sc-9a00e533-0 eZyhnA">Others in the building insist no-one who works there was behind any briefing against a cabinet minister, after Wes Streeting said whoever was responsible should be sacked.</p><p class="sc-9a00e533-0 eZyhnA">In No 10, there is a tacit acknowledgement that the health secretary handled a round of pre-arranged interviews on Wednesday morning with dignity, aplomb and humour - despite being confronted by incessant questions about his own ambitions because those briefings about him came just hours before.</p><p class="sc-9a00e533-0 eZyhnA">For some Labour MPs, he demonstrated a nimbleness and knack for communication they only wish the Prime Minister shared.</p><p class="sc-9a00e533-0 eZyhnA">It also won''t have gone unnoticed that at least some of those briefings that attempted to shore up the prime minister ended up creating an opportunity for Streeting to say he shared the sentiment of his colleagues who have described Downing Street as toxic and sexist and that those who were behind the briefings should be sacked.</p><p class="sc-9a00e533-0 eZyhnA">What a mess.</p></div><div data-testid="ad-unit" data-component="ad-slot" class="sc-1b734f04-0 kNNIux"><div data-testid="dotcom-mid_2" id="dotcom-mid_2" class="dotcom-ad"></div></div><div data-component="video-block" data-testid="fabl-video-container" class="sc-3b6b161a-0 gXrNRM"><div class="sc-2218ed0c-1 fiqjXZ"><div data-testid="" class="sc-2218ed0c-2 bgTyRA"></div></div></div><div data-component="caption-block" class="sc-3b6b161a-0 Qwxkf"></div><div data-component="text-block" class="sc-3b6b161a-0 dPVOKT"><p class="sc-9a00e533-0 eZyhnA">The prime minister, I am told, is "incandescent" at how all of this has played out and is looking into how it all happened.</p><p class="sc-9a00e533-0 eZyhnA">What appears to have gone awry, from No 10''s perspective, is both volume and emphasis.</p><p class="sc-9a00e533-0 eZyhnA">Firstly, they had, perhaps naively, imagined that the briefings would generate some news, but not wall-to-wall headline news. </p><p class="sc-9a00e533-0 eZyhnA">It turned out to be much louder than they had anticipated.</p><p class="sc-9a00e533-0 eZyhnA">I''d say a prime minister letting this kind of thing be known, via supporters, less than 18 months after a landslide general election win, was always going to be front page, top of bulletins stuff – as it turned out to be, on these pages and others.</p><p class="sc-9a00e533-0 eZyhnA">And secondly, on emphasis, they insist they hadn''t expected so much talk about Wes Streeting, which was then massively magnified by all those interviews he was booked in to do on Wednesday morning. </p><p class="sc-9a00e533-0 eZyhnA">Others, it must be said, concluded that that was precisely the intention.</p><p class="sc-9a00e533-0 eZyhnA">It has been another few days where Labour folk in government talk about lessons being learnt and on the backbenches plenty are irritated at what they see as an absurd spectacle playing out that they have to firstly witness and then attempt to defend.</p><p class="sc-9a00e533-0 eZyhnA">And they would rather not do either.</p><p class="sc-9a00e533-0 eZyhnA">But a government and a prime minister whose nervousness about their predicament is even bigger than their big majority will likely see repeats of this saga, unless they can quickly address the deep lack of popularity that drives it.</p></div><div data-component="tags" class="sc-3b6b161a-0 djqsWD"><div class="sc-6bf80075-0 lllwyY"><div data-testid="anchor-inner-wrapper"><a href="https://www.bbc.com/news/topics/c50znx8v8rwt" data-testid="internal-link" class="sc-57521d02-0 jsVxCb">Keir Starmer</a></div><div data-testid="anchor-inner-wrapper"><a href="https://www.bbc.com/news/topics/cp8420zjek3t" data-testid="internal-link" class="sc-57521d02-0 jsVxCb">Wes Streeting</a></div><div data-testid="anchor-inner-wrapper"><a href="https://www.bbc.com/news/topics/crr7mlg0dg1t" data-testid="internal-link" class="sc-57521d02-0 jsVxCb">Labour Party</a></div></div></div>', NULL, '<div data-component="headline-block" class="sc-3b6b161a-0 hNbOGD"><h1 class="sc-f98b1ad2-0 idLnWK">Chris Mason: Unpicking a messy day for the government</h1></div><div data-component="byline-block" class="sc-3b6b161a-0 dPVOKT"><div data-testid="byline-new" class="sc-7bfdb3c2-0 fYJjWP"><div class="sc-7bfdb3c2-1 jqWinX"><time datetime="2025-11-13T05:38:59.885Z" class="sc-7bfdb3c2-2 dQuPjg">2 hours ago</time><div class="sc-7bfdb3c2-3 dVvYwG"></div></div><span data-testid="byline-new-contributors" class="sc-7bfdb3c2-11 ljQVMv"><div data-testid="byline-new-contributors-contributor-0" class="sc-7bfdb3c2-5 xGeVU"><div><span class="sc-7bfdb3c2-7 djOqvY">Chris Mason</span><span data-testid="byline-new-contributors-contributor-0-role-location" class="sc-7bfdb3c2-8 gvcwmG">Political editor</span></div></div></span><div class="sc-7bfdb3c2-4 haycoC"></div></div></div><figure><div data-component="image-block" class="sc-3b6b161a-0 eRlINq"><div data-testid="hero-image" class="sc-5340b511-1 cMIbKV"><img sizes="(min-width: 1280px) 50vw, (min-width: 1008px) 66vw, 96vw" srcset="https://ichef.bbci.co.uk/news/240/cpsprodpb/6b25/live/e627e4b0-c031-11f0-9c25-7d417a285f78.jpg.webp 240w,https://ichef.bbci.co.uk/news/320/cpsprodpb/6b25/live/e627e4b0-c031-11f0-9c25-7d417a285f78.jpg.webp 320w,https://ichef.bbci.co.uk/news/480/cpsprodpb/6b25/live/e627e4b0-c031-11f0-9c25-7d417a285f78.jpg.webp 480w,https://ichef.bbci.co.uk/news/640/cpsprodpb/6b25/live/e627e4b0-c031-11f0-9c25-7d417a285f78.jpg.webp 640w,https://ichef.bbci.co.uk/news/800/cpsprodpb/6b25/live/e627e4b0-c031-11f0-9c25-7d417a285f78.jpg.webp 800w,https://ichef.bbci.co.uk/news/1024/cpsprodpb/6b25/live/e627e4b0-c031-11f0-9c25-7d417a285f78.jpg.webp 1024w,https://ichef.bbci.co.uk/news/1536/cpsprodpb/6b25/live/e627e4b0-c031-11f0-9c25-7d417a285f78.jpg.webp 1536w" src="https://ichef.bbci.co.uk/news/480/cpsprodpb/6b25/live/e627e4b0-c031-11f0-9c25-7d417a285f78.jpg.webp" loading="eager" alt="Getty Images UK Prime Minister Keir Starmer pictured in front of the Union Jack at 10 Downing Street. He wears a dark suit, dark tie and his customary black-framed glasses." class="sc-5340b511-0 hLdNfA"><span class="sc-5340b511-2 jVqbAn">Getty Images</span></div></div></figure><div data-component="text-block" class="sc-3b6b161a-0 dPVOKT"><p class="sc-9a00e533-0 eZyhnA">"It''s not been our finest 24 hours in government," one senior figure in government acknowledged to me, after mudslinging one way and another, some in public, plenty more in private.</p><p class="sc-9a00e533-0 eZyhnA">I have been making loads of phone calls to patch together the anatomy of another bumpy few days for Downing Street: what those close to the Prime Minister hoped to achieve, what ended up happening and where all this leaves them.</p><p class="sc-9a00e533-0 eZyhnA">There are two key facts at the heart of all of this: the government is unpopular and so is the Prime Minister.</p><p class="sc-9a00e533-0 eZyhnA">These facts are the rocket fuel behind the constant conversations I hear about what Labour is trying to do about it and what it might mean for how long Sir Keir Starmer carries on in Downing Street.</p><p class="sc-9a00e533-0 eZyhnA">But let''s get to the aftermath of all that mudslinging.</p></div><div data-testid="ad-unit" data-component="ad-slot" class="sc-1b734f04-0 kNNIux"><div data-testid="dotcom-mid_1" id="dotcom-mid_1" class="dotcom-ad"></div></div><div data-component="text-block" class="sc-3b6b161a-0 dPVOKT"><ul class="sc-6f869981-0 diUlgm"><li class="sc-734a601e-0 cRgahm"><a target="_self" href="https://www.bbc.com/news/articles/c3vnyg1q503o" class="sc-f9178328-0 kgTYQp">I have never authorised attacks on ministers, says PM</a></li><li class="sc-734a601e-0 cRgahm"><a target="_self" href="http://bbc.com/news/articles/c9v124znrgmo" class="sc-f9178328-0 kgTYQp">Streeting denies plotting against PM after leadership claims</a></li><li class="sc-734a601e-0 cRgahm"><a target="_self" href="https://www.bbc.com/news/articles/c5y0z2q2g2ro" class="sc-f9178328-0 kgTYQp">Starmer will fight attempts to replace him, allies say</a></li></ul></div><div data-component="text-block" class="sc-3b6b161a-0 dPVOKT"><p class="sc-9a00e533-0 eZyhnA">The prime minister and Health Secretary Wes Streeting spoke on the phone on Wednesday evening to patch things up.</p><p class="sc-9a00e533-0 eZyhnA">I hear Sir Keir apologised to Streeting in the brief call and they agreed to talk in further detail "soon".</p><p class="sc-9a00e533-0 eZyhnA">They didn''t talk about Morgan McSweeney, the prime minister''s chief of staff - who has become a lightning rod for criticism from everyone including the Conservative leader Kemi Badenoch in public to Labour figures junior and senior in private.</p><p class="sc-9a00e533-0 eZyhnA">Widely credited as the mastermind of Labour''s election landslide and the political brain behind Sir Keir''s quick rise since switching from Director of Public Prosecutions, McSweeney is also among the first to face criticism when the Downing Street machine is perceived to have stuttered, stumbled or outright failed.</p><p class="sc-9a00e533-0 eZyhnA">He is not responding to requests for comment, as some call for his head on a stick.</p><p class="sc-9a00e533-0 eZyhnA">His critics argue that in a Downing Street where McSweeney is called on to make plenty of big political judgements, he should take responsibility for how all of this unfolded.</p><p class="sc-9a00e533-0 eZyhnA">Others in the building insist no-one who works there was behind any briefing against a cabinet minister, after Wes Streeting said whoever was responsible should be sacked.</p><p class="sc-9a00e533-0 eZyhnA">In No 10, there is a tacit acknowledgement that the health secretary handled a round of pre-arranged interviews on Wednesday morning with dignity, aplomb and humour - despite being confronted by incessant questions about his own ambitions because those briefings about him came just hours before.</p><p class="sc-9a00e533-0 eZyhnA">For some Labour MPs, he demonstrated a nimbleness and knack for communication they only wish the Prime Minister shared.</p><p class="sc-9a00e533-0 eZyhnA">It also won''t have gone unnoticed that at least some of those briefings that attempted to shore up the prime minister ended up creating an opportunity for Streeting to say he shared the sentiment of his colleagues who have described Downing Street as toxic and sexist and that those who were behind the briefings should be sacked.</p><p class="sc-9a00e533-0 eZyhnA">What a mess.</p></div><div data-testid="ad-unit" data-component="ad-slot" class="sc-1b734f04-0 kNNIux"><div data-testid="dotcom-mid_2" id="dotcom-mid_2" class="dotcom-ad"></div></div><div data-component="video-block" data-testid="fabl-video-container" class="sc-3b6b161a-0 gXrNRM"><div class="sc-2218ed0c-1 fiqjXZ"><div data-testid style="visibility:hidden" class="sc-2218ed0c-2 bgTyRA"></div></div></div><div data-component="caption-block" class="sc-3b6b161a-0 Qwxkf"></div><div data-component="text-block" class="sc-3b6b161a-0 dPVOKT"><p class="sc-9a00e533-0 eZyhnA">The prime minister, I am told, is "incandescent" at how all of this has played out and is looking into how it all happened.</p><p class="sc-9a00e533-0 eZyhnA">What appears to have gone awry, from No 10''s perspective, is both volume and emphasis.</p><p class="sc-9a00e533-0 eZyhnA">Firstly, they had, perhaps naively, imagined that the briefings would generate some news, but not wall-to-wall headline news. </p><p class="sc-9a00e533-0 eZyhnA">It turned out to be much louder than they had anticipated.</p><p class="sc-9a00e533-0 eZyhnA">I''d say a prime minister letting this kind of thing be known, via supporters, less than 18 months after a landslide general election win, was always going to be front page, top of bulletins stuff – as it turned out to be, on these pages and others.</p><p class="sc-9a00e533-0 eZyhnA">And secondly, on emphasis, they insist they hadn''t expected so much talk about Wes Streeting, which was then massively magnified by all those interviews he was booked in to do on Wednesday morning. </p><p class="sc-9a00e533-0 eZyhnA">Others, it must be said, concluded that that was precisely the intention.</p><p class="sc-9a00e533-0 eZyhnA">It has been another few days where Labour folk in government talk about lessons being learnt and on the backbenches plenty are irritated at what they see as an absurd spectacle playing out that they have to firstly witness and then attempt to defend.</p><p class="sc-9a00e533-0 eZyhnA">And they would rather not do either.</p><p class="sc-9a00e533-0 eZyhnA">But a government and a prime minister whose nervousness about their predicament is even bigger than their big majority will likely see repeats of this saga, unless they can quickly address the deep lack of popularity that drives it.</p></div><div data-component="tags" class="sc-3b6b161a-0 djqsWD"><div class="sc-6bf80075-0 lllwyY"><div data-testid="anchor-inner-wrapper"><a href="https://www.bbc.com/news/topics/c50znx8v8rwt" data-testid="internal-link" class="sc-57521d02-0 jsVxCb">Keir Starmer</a></div><div data-testid="anchor-inner-wrapper"><a href="https://www.bbc.com/news/topics/cp8420zjek3t" data-testid="internal-link" class="sc-57521d02-0 jsVxCb">Wes Streeting</a></div><div data-testid="anchor-inner-wrapper"><a href="https://www.bbc.com/news/topics/crr7mlg0dg1t" data-testid="internal-link" class="sc-57521d02-0 jsVxCb">Labour Party</a></div></div></div>', NULL, NULL);
INSERT INTO lost_and_found VALUES(73, 73, 14, 5, 1697, 1763020372586, NULL, 1762984803000, 1, 1763020372586, 'en-GB', 'Hospitals knew a heart device led to more patients&#039; deaths - but they kept using it', 'https://www.bbc.com/news/articles/cqjwg197855o?at_medium=RSS&at_campaign=rss', 'https://www.bbc.com/news/articles/cqjwg197855o?at_medium=RSS&at_campaign=rss', NULL, '<div data-component="headline-block" class="sc-3b6b161a-0 hNbOGD"><h1 class="sc-f98b1ad2-0 idLnWK">Hospitals knew a heart device led to more patients'' deaths - but they kept using it</h1></div><div data-component="byline-block" class="sc-3b6b161a-0 dPVOKT"><div data-testid="byline-new" class="sc-7bfdb3c2-0 fYJjWP"><div class="sc-7bfdb3c2-1 jqWinX"><time datetime="2025-11-12T22:00:03.539Z" class="sc-7bfdb3c2-2 dQuPjg">10 hours ago</time><div class="sc-7bfdb3c2-3 dVvYwG"></div></div><span data-testid="byline-new-contributors" class="sc-7bfdb3c2-11 ljQVMv"><span class="sc-7bfdb3c2-7 byKoUE">Michael Buchanan,</span><span data-testid="byline-new-contributors-contributor-0-role-location" class="sc-7bfdb3c2-8 gTWlHk">Social affairs correspondent</span><span class="sc-7bfdb3c2-9 bTXCSY"> and </span></span></div><div data-testid="byline-new-contributors-contributor-1" class="sc-7bfdb3c2-5 fMReXM"><span class="sc-7bfdb3c2-7 byKoUE">Adam Eley,</span><span data-testid="byline-new-contributors-contributor-1-role-location" class="sc-7bfdb3c2-8 gTWlHk">BBC News</span></div><div class="sc-7bfdb3c2-4 haycoC"></div></div><figure><div data-component="image-block" class="sc-3b6b161a-0 gtLOOD"><div data-testid="hero-image" class="sc-5340b511-1 cMIbKV"><img srcset="https://ichef.bbci.co.uk/news/240/cpsprodpb/eba1/live/d6e84180-be28-11f0-ae46-bd64331f0fd4.jpg.webp 240w, https://ichef.bbci.co.uk/news/320/cpsprodpb/eba1/live/d6e84180-be28-11f0-ae46-bd64331f0fd4.jpg.webp 320w, https://ichef.bbci.co.uk/news/480/cpsprodpb/eba1/live/d6e84180-be28-11f0-ae46-bd64331f0fd4.jpg.webp 480w, https://ichef.bbci.co.uk/news/640/cpsprodpb/eba1/live/d6e84180-be28-11f0-ae46-bd64331f0fd4.jpg.webp 640w, https://ichef.bbci.co.uk/news/800/cpsprodpb/eba1/live/d6e84180-be28-11f0-ae46-bd64331f0fd4.jpg.webp 800w, https://ichef.bbci.co.uk/news/1024/cpsprodpb/eba1/live/d6e84180-be28-11f0-ae46-bd64331f0fd4.jpg.webp 1024w, https://ichef.bbci.co.uk/news/1536/cpsprodpb/eba1/live/d6e84180-be28-11f0-ae46-bd64331f0fd4.jpg.webp 1536w" src="https://ichef.bbci.co.uk/news/480/cpsprodpb/eba1/live/d6e84180-be28-11f0-ae46-bd64331f0fd4.jpg.webp" alt="Family handout A young man with short dark hair and stubble looks directly at the camera in front of a dark blue background." class="sc-5340b511-0 hLdNfA" /><span class="sc-5340b511-2 jVqbAn">Family handout</span></div></div><div data-component="caption-block" class="sc-3b6b161a-0 Qwxkf"></div></figure><div data-component="text-block" class="sc-3b6b161a-0 dPVOKT"><p class="sc-9a00e533-0 eZyhnA">Dozens of patients were put at risk after two of the UK''s leading transplant centres continued fitting a heart device - despite knowing of concerns it had a higher mortality rate than its rival product.</p><p class="sc-9a00e533-0 eZyhnA">Concerns were raised by the NHS about the device in 2018. Of the patients who were subsequently fitted with the mechanical pump, half went on to die within three years.</p><p class="sc-9a00e533-0 eZyhnA">The mother of Greg Marshall - one of the patients who received the device after concerns were known and who subsequently died - told us she was "disgusted and appalled".</p><p class="sc-9a00e533-0 eZyhnA">The BBC has also learned that leading cardiologists at both hospitals were paid consultants for the device''s manufacturer. The hospitals were aware of this.</p></div><div data-testid="ad-unit" data-component="ad-slot" class="sc-1b734f04-0 kNNIux"><div data-testid="dotcom-mid_1" id="dotcom-mid_1" class="dotcom-ad"></div></div><div data-component="text-block" class="sc-3b6b161a-0 dPVOKT"><p class="sc-9a00e533-0 eZyhnA">Both hospitals - the Freeman in Newcastle and Harefield in London - continued to use the pump for years, and questioned the reliability of the data flagged by the NHS. The pump''s manufacturer, Medtronic, eventually withdrew it on safety grounds.</p><p class="sc-9a00e533-0 eZyhnA">Patients with a weakened heart, who may be waiting for a transplant or deemed not suitable for one, can be offered a machine called an LVAD, a Left Ventricular Assist Device. It helps the heart pump blood around the body and, for many patients, this is their only chance of survival until a transplant becomes available.</p><p class="sc-9a00e533-0 eZyhnA">The device is implanted into the heart, with an external wire coming out of the body - usually at the abdomen - that connects to a controller and external batteries.</p><p class="sc-9a00e533-0 eZyhnA">LVADs have been life-savers for decades and, for a number of years, hospitals had a choice of two devices - the HeartWare HVAD, sold by the Irish-American company Medtronic, and the Heartmate III, sold by US manufacturer Abbott.</p></div><figure><div data-component="image-block" class="sc-3b6b161a-0 gXrNRM"><div data-testid="image" class="sc-5340b511-1 cMIbKV"><img srcset="https://ichef.bbci.co.uk/news/240/cpsprodpb/97d8/live/82015f60-beed-11f0-ae46-bd64331f0fd4.jpg.webp 240w, https://ichef.bbci.co.uk/news/320/cpsprodpb/97d8/live/82015f60-beed-11f0-ae46-bd64331f0fd4.jpg.webp 320w, https://ichef.bbci.co.uk/news/480/cpsprodpb/97d8/live/82015f60-beed-11f0-ae46-bd64331f0fd4.jpg.webp 480w, https://ichef.bbci.co.uk/news/640/cpsprodpb/97d8/live/82015f60-beed-11f0-ae46-bd64331f0fd4.jpg.webp 640w, https://ichef.bbci.co.uk/news/800/cpsprodpb/97d8/live/82015f60-beed-11f0-ae46-bd64331f0fd4.jpg.webp 800w, https://ichef.bbci.co.uk/news/1024/cpsprodpb/97d8/live/82015f60-beed-11f0-ae46-bd64331f0fd4.jpg.webp 1024w, https://ichef.bbci.co.uk/news/1536/cpsprodpb/97d8/live/82015f60-beed-11f0-ae46-bd64331f0fd4.jpg.webp 1536w" src="https://ichef.bbci.co.uk/news/480/cpsprodpb/97d8/live/82015f60-beed-11f0-ae46-bd64331f0fd4.jpg.webp" alt="Medtronic An illustration of a man in a white T-shirt wearing a black belt holding four small black devices with wires protruding; higher up, we see a scan of his heart, from which a small pump with a tube emerges. A wire links the device and one of the black devices on his belt." class="sc-5340b511-0 hLdNfA" /><span class="sc-5340b511-2 jVqbAn">Medtronic</span></div></div><div data-component="caption-block" class="sc-3b6b161a-0 Qwxkf"></div></figure><div data-testid="ad-unit" data-component="ad-slot" class="sc-1b734f04-0 kNNIux"><div data-testid="dotcom-mid_2" id="dotcom-mid_2" class="dotcom-ad"></div></div><div data-component="text-block" class="sc-3b6b161a-0 dPVOKT"><p class="sc-9a00e533-0 eZyhnA">In October 2018, NHS Blood and Transplant (NHSBT), which oversees transplants in the UK, conducted a preliminary audit comparing how the two pumps had performed. A more detailed analysis followed in April 2019.</p><p class="sc-9a00e533-0 eZyhnA">The results were stark. Of the 119 patients who had received the Medtronic device, 45% - or 54 patients - had died within two years. In contrast, just 15% - 15 out of 97 patients - who were given the Abbott pump had died over the same period. Similarly, the number of complications - such as strokes or needing a new pump - were significantly higher for the Medtronic device. The audit said there were "no significant differences" between the types of patients who received each device.</p><p class="sc-9a00e533-0 eZyhnA">One of the UK''s six transplant centres, the Royal Papworth Hospital in Cambridge, did not wait for the NHS analysis. It had picked up on the growing international concerns and had stopped using the Medtronic device in February 2018 "after considering the results of two randomised controlled trials", as their clinicians "considered the Heartmate III as superior".</p><p class="sc-9a00e533-0 eZyhnA">However, Harefield Hospital continued to solely use the Medtronic device until early 2021, shortly after the manufacturer had issued a safety notice. The Freeman Hospital continued until June 2021, when the manufacturer withdrew it from sale "in the interest of patient safety".</p><p class="sc-9a00e533-0 eZyhnA">The regulator, the Medicines and Healthcare products Regulatory Agency (MHRA), continued to approve the device for use after the 2019 analysis, though it had not been informed by the NHS of the data''s existence.</p><p class="sc-9a00e533-0 eZyhnA">Throughout this time, patients fitted with the Medtronic device continued to die at a higher rate than those with the Abbott device. </p><p class="sc-9a00e533-0 eZyhnA">Between October 2018, when the first set of NHS data was produced, and June 2021, when Medtronic discontinued its pump, the mortality rate of the Medtronic device was two-and-a-half times higher than the Abbott device, figures released under the Freedom of Information Act show.</p><p class="sc-9a00e533-0 eZyhnA">Forty-nine percent of those who received the Medtronic device (39 of 80 patients) in that time died within three years. By comparison, 19% of recipients of the Abbott device (20 of 106 patients) died during the same timeframe.</p></div><figure><div data-component="image-block" class="sc-3b6b161a-0 gXrNRM"><div data-testid="image" class="sc-5340b511-1 cMIbKV"><img srcset="https://ichef.bbci.co.uk/news/240/cpsprodpb/9a54/live/ddb6aeb0-bf19-11f0-ae46-bd64331f0fd4.jpg.webp 240w, https://ichef.bbci.co.uk/news/320/cpsprodpb/9a54/live/ddb6aeb0-bf19-11f0-ae46-bd64331f0fd4.jpg.webp 320w, https://ichef.bbci.co.uk/news/480/cpsprodpb/9a54/live/ddb6aeb0-bf19-11f0-ae46-bd64331f0fd4.jpg.webp 480w, https://ichef.bbci.co.uk/news/640/cpsprodpb/9a54/live/ddb6aeb0-bf19-11f0-ae46-bd64331f0fd4.jpg.webp 640w, https://ichef.bbci.co.uk/news/800/cpsprodpb/9a54/live/ddb6aeb0-bf19-11f0-ae46-bd64331f0fd4.jpg.webp 800w, https://ichef.bbci.co.uk/news/1024/cpsprodpb/9a54/live/ddb6aeb0-bf19-11f0-ae46-bd64331f0fd4.jpg.webp 1024w, https://ichef.bbci.co.uk/news/1536/cpsprodpb/9a54/live/ddb6aeb0-bf19-11f0-ae46-bd64331f0fd4.jpg.webp 1536w" src="https://ichef.bbci.co.uk/news/480/cpsprodpb/9a54/live/ddb6aeb0-bf19-11f0-ae46-bd64331f0fd4.jpg.webp" alt="Family handout Three people - a smiling young man in green woollen hat on the left; a middle-aged woman in the centre in a green and yellow hat that says &quot;Saints&quot;; a young man on the right smiles with short brown hair." class="sc-5340b511-0 hLdNfA" /><span class="sc-5340b511-2 jVqbAn">Family handout</span></div></div><div data-component="caption-block" class="sc-3b6b161a-0 Qwxkf"></div></figure><div data-testid="ad-unit" data-component="ad-slot" class="sc-1b734f04-0 kNNIux"><div data-testid="dotcom-mid_3" id="dotcom-mid_3" class="dotcom-ad"></div></div><div data-component="text-block" class="sc-3b6b161a-0 dPVOKT"><p class="sc-9a00e533-0 eZyhnA">Medtronic decided to withdraw the device in June 2021 after growing evidence that its pump had a higher frequency of strokes and deaths compared with other devices. It also cited a specific malfunction where pumps would experience a delay or fail to restart after they were stopped.</p><p class="sc-9a00e533-0 eZyhnA">Greg Marshall was one of the patients fitted with the Medtronic device, unaware of the studies about its effectiveness compared with the rival product. A fit and healthy young man, he had ambitions of joining the Royal Marines but he suffered acute heart failure in 2019.</p><p class="sc-9a00e533-0 eZyhnA">"It was a massive shock to us all," his mother Tessa Marshall remembers.</p><p class="sc-9a00e533-0 eZyhnA">By June of that year, Greg was offered the Medtronic device by the Freeman Hospital, several months after the first set of NHS data was known about.</p><p class="sc-9a00e533-0 eZyhnA">His family say they were not presented with the long-term risks associated with the device, though an existing patient was brought in to tell them of its benefits.</p><p class="sc-9a00e533-0 eZyhnA">Greg agreed to the surgery, but a significant complication in theatre - which the family say was never fully explained to them - led to a stroke. Greg lost movement down the left-hand side of his body, and his speech was significantly impaired.</p><p class="sc-9a00e533-0 eZyhnA">Over time, his health slowly began to recover, but a year later, in July 2020, the heart device suddenly stopped working. When he tried to restart it, it failed to switch back on.</p><p class="sc-9a00e533-0 eZyhnA">"The pump was not pumping, and he just slowly went blue," Tessa says.</p><p class="sc-9a00e533-0 eZyhnA">Greg was rushed to hospital, but the device could not be fixed. He was told he could have it removed, but, terrified of having another stroke, he refused the surgery.</p><p class="sc-9a00e533-0 eZyhnA">The broken device remained inside him, switched off, as his heart continued to function for a further three years, during which time he was on a transplant waiting list.</p><p class="sc-9a00e533-0 eZyhnA">In September 2023, while in hospital, he unexpectedly went into cardiac arrest. By the time Tessa had reached the Freeman, Greg had died aged 26.</p><p class="sc-9a00e533-0 eZyhnA">His family, devastated by his loss, say they want answers.  </p><p class="sc-9a00e533-0 eZyhnA">"We said ''Look, Greg, this is the only option you''ve got, you have got to go with it,''" said Tessa. "I kick myself now, for not doing any more research." </p><p class="sc-9a00e533-0 eZyhnA">Three patients may have died of this failure, the NHS Trust in Newcastle told the Department of Health and Social Care in a letter seen by the BBC.</p><p class="sc-9a00e533-0 eZyhnA">The trust has since told the BBC the issue of the device failing to restart in patients first came to light in December 2020 - five months after Greg encountered the issue - when Medtronic published a safety notice.</p></div><figure><div data-component="image-block" class="sc-3b6b161a-0 gXrNRM"><div data-testid="image" class="sc-5340b511-1 cMIbKV"><img srcset="https://ichef.bbci.co.uk/news/240/cpsprodpb/fecd/live/c8e3edc0-beee-11f0-ae46-bd64331f0fd4.jpg.webp 240w, https://ichef.bbci.co.uk/news/320/cpsprodpb/fecd/live/c8e3edc0-beee-11f0-ae46-bd64331f0fd4.jpg.webp 320w, https://ichef.bbci.co.uk/news/480/cpsprodpb/fecd/live/c8e3edc0-beee-11f0-ae46-bd64331f0fd4.jpg.webp 480w, https://ichef.bbci.co.uk/news/640/cpsprodpb/fecd/live/c8e3edc0-beee-11f0-ae46-bd64331f0fd4.jpg.webp 640w, https://ichef.bbci.co.uk/news/800/cpsprodpb/fecd/live/c8e3edc0-beee-11f0-ae46-bd64331f0fd4.jpg.webp 800w, https://ichef.bbci.co.uk/news/1024/cpsprodpb/fecd/live/c8e3edc0-beee-11f0-ae46-bd64331f0fd4.jpg.webp 1024w, https://ichef.bbci.co.uk/news/1536/cpsprodpb/fecd/live/c8e3edc0-beee-11f0-ae46-bd64331f0fd4.jpg.webp 1536w" src="https://ichef.bbci.co.uk/news/480/cpsprodpb/fecd/live/c8e3edc0-beee-11f0-ae46-bd64331f0fd4.jpg.webp" alt="ISHLT An older man with sharp white hair, wearing a navy blue suit, light blue shirt and crimson tie, is being interviewed by another man with white hair, whose head we see the back of." class="sc-5340b511-0 hLdNfA" /><span class="sc-5340b511-2 jVqbAn">ISHLT</span></div></div><div data-component="caption-block" class="sc-3b6b161a-0 Qwxkf"></div></figure><div data-testid="ad-unit" data-component="ad-slot" class="sc-1b734f04-0 kNNIux"><div data-testid="dotcom-mid_4" id="dotcom-mid_4" class="dotcom-ad"></div></div><div data-component="text-block" class="sc-3b6b161a-0 dPVOKT"><p class="sc-9a00e533-0 eZyhnA">Hospital documents show Greg''s responsible health professional was Prof Stephan Schueler, who until recently was head of the Freeman''s cardiothoracic department. Described by a former colleague as "king of the castle" in the transplant unit, Prof Schueler had a decade-long relationship with the manufacturer of the Medtronic device, public records show.</p><p class="sc-9a00e533-0 eZyhnA">Greg''s family say he did not declare to them his financial relationship with the heart device''s manufacturer, despite such a disclosure being a requirement of the doctor''s regulator, the General Medical Council (GMC).</p><p class="sc-9a00e533-0 eZyhnA">In a statement to the BBC, Prof Schueler said that "there was never a financial incentive nor any salary arrangements with Medtronic for me or anybody else in our team to choose one device over the other". He did not respond to a direct question about what he had told Greg Marshall about his relationship with Medtronic but said that he "always worked within GMC standards for good medical practice" and that consenting patients for a procedure was "carried out by a whole team of specialised colleagues".</p><p class="sc-9a00e533-0 eZyhnA">It is common for clinicians to work as consultants for medical manufacturer and pharmaceutical companies. Such arrangements are recognised as being mutually beneficial and can lead to better outcomes for patients, though there are rules around what medics need to declare to patients.</p><p class="sc-9a00e533-0 eZyhnA">The Freeman said in a statement to the BBC that it offered its "sincere condolences" to Greg''s family and it was investigating his case.</p><p class="sc-9a00e533-0 eZyhnA">It said that, although it was "aware" of the NHS data in April 2019, it felt its scientific value was not reliable, and pointed out that it was not accepted in any national or international scientific publication. It said there were other publications at that time which indicated "excellent outcomes" for the Medtronic device.</p><p class="sc-9a00e533-0 eZyhnA">Robbie Burns, a patient representative with NHS Blood and Transplant, obtained many of the documents relating to the hospitals'' continued use of the Medtronic device. He believes there should be an external investigation into how it was allowed to happen.</p><p class="sc-9a00e533-0 eZyhnA">"It was entirely preventable," he said.</p><p class="sc-9a00e533-0 eZyhnA">"If I had been in the position of receiving this [Medtronic] device, and looked back at the data, I would be going, ''Why on earth did you do this?''"</p><p class="sc-9a00e533-0 eZyhnA">Prof Schueler said the Medtronic device had several benefits, including being more suitable for children and small adults. He said the decision to continue using the pump was taken after internal discussions had considered all the risk and benefits carefully.</p><p class="sc-9a00e533-0 eZyhnA">Another doctor, André Simon, the director of heart and lung transplantation and ventricular assist devices at Harefield Hospital, had a similarly long-standing relationship with HeartWare and Medtronic, going back to 2014.</p><p class="sc-9a00e533-0 eZyhnA">The man who replaced him at the hospital on the edge of west London, Dr John Dunning, told the BBC that Harefield had continued to use the Medtronic device as "it was the preference" of his predecessor.</p><p class="sc-9a00e533-0 eZyhnA">Dr Simon, who no longer works at the hospital, did not respond to the BBC''s questions. In its statement, the Harefield said it was "aware" of his work for Medtronic and that this had been declared in multiple papers. The hospital added that he was one of a number of senior people "involved" in choosing which devices were used, and that "the continued use of the [Medtronic device] had collective support of clinicians at Harefield" until the manufacturer issued a safety notice in early 2021.</p><p class="sc-9a00e533-0 eZyhnA">In separate statements to the BBC, both the Freeman and Harefield hospitals said their decisions to continue using the Medtronic device were based on "complex clinical decisions" and stressed that there were "no clear grounds" at the time to believe the Medtronic device was significantly inferior to the Abbott device.</p><p class="sc-9a00e533-0 eZyhnA">Harefield said it commissioned an external review of its services in 2019 from the then-chair of the NHSBT''s Cardiothoracic Advisory Group, and this made no comment on its selection of devices.</p></div><div data-component="embed-block" class="sc-3b6b161a-0 djqsWD"></div><div data-component="tags" class="sc-3b6b161a-0 djqsWD"><div class="sc-6bf80075-0 lllwyY"><div data-testid="anchor-inner-wrapper"><a href="https://www.bbc.com/news/topics/cr0mejz7ng6t" data-testid="internal-link" class="sc-57521d02-0 jsVxCb">Newcastle upon Tyne</a></div><div data-testid="anchor-inner-wrapper"><a href="https://www.bbc.com/news/topics/cw1qqk0emrrt" data-testid="internal-link" class="sc-57521d02-0 jsVxCb">Heart</a></div><div data-testid="anchor-inner-wrapper"><a href="https://www.bbc.com/news/topics/cwdnm99j0r6t" data-testid="internal-link" class="sc-57521d02-0 jsVxCb">Harefield</a></div></div></div>', NULL, '<div data-component="headline-block" class="sc-3b6b161a-0 hNbOGD"><h1 class="sc-f98b1ad2-0 idLnWK">Hospitals knew a heart device led to more patients'' deaths - but they kept using it</h1></div><div data-component="byline-block" class="sc-3b6b161a-0 dPVOKT"><div data-testid="byline-new" class="sc-7bfdb3c2-0 fYJjWP"><div class="sc-7bfdb3c2-1 jqWinX"><time datetime="2025-11-12T22:00:03.539Z" class="sc-7bfdb3c2-2 dQuPjg">10 hours ago</time><div class="sc-7bfdb3c2-3 dVvYwG"></div></div><span data-testid="byline-new-contributors" class="sc-7bfdb3c2-11 ljQVMv"><div data-testid="byline-new-contributors-contributor-0" class="sc-7bfdb3c2-5 fMReXM"><span class="sc-7bfdb3c2-7 byKoUE">Michael Buchanan,</span><span data-testid="byline-new-contributors-contributor-0-role-location" class="sc-7bfdb3c2-8 gTWlHk">Social affairs correspondent</span><span class="sc-7bfdb3c2-9 bTXCSY"> and </span></div><div data-testid="byline-new-contributors-contributor-1" class="sc-7bfdb3c2-5 fMReXM"><span class="sc-7bfdb3c2-7 byKoUE">Adam Eley,</span><span data-testid="byline-new-contributors-contributor-1-role-location" class="sc-7bfdb3c2-8 gTWlHk">BBC News</span></div></span><div class="sc-7bfdb3c2-4 haycoC"></div></div></div><figure><div data-component="image-block" class="sc-3b6b161a-0 gtLOOD"><div data-testid="hero-image" class="sc-5340b511-1 cMIbKV"><img sizes="(min-width: 1280px) 50vw, (min-width: 1008px) 66vw, 96vw" srcset="https://ichef.bbci.co.uk/news/240/cpsprodpb/eba1/live/d6e84180-be28-11f0-ae46-bd64331f0fd4.jpg.webp 240w,https://ichef.bbci.co.uk/news/320/cpsprodpb/eba1/live/d6e84180-be28-11f0-ae46-bd64331f0fd4.jpg.webp 320w,https://ichef.bbci.co.uk/news/480/cpsprodpb/eba1/live/d6e84180-be28-11f0-ae46-bd64331f0fd4.jpg.webp 480w,https://ichef.bbci.co.uk/news/640/cpsprodpb/eba1/live/d6e84180-be28-11f0-ae46-bd64331f0fd4.jpg.webp 640w,https://ichef.bbci.co.uk/news/800/cpsprodpb/eba1/live/d6e84180-be28-11f0-ae46-bd64331f0fd4.jpg.webp 800w,https://ichef.bbci.co.uk/news/1024/cpsprodpb/eba1/live/d6e84180-be28-11f0-ae46-bd64331f0fd4.jpg.webp 1024w,https://ichef.bbci.co.uk/news/1536/cpsprodpb/eba1/live/d6e84180-be28-11f0-ae46-bd64331f0fd4.jpg.webp 1536w" src="https://ichef.bbci.co.uk/news/480/cpsprodpb/eba1/live/d6e84180-be28-11f0-ae46-bd64331f0fd4.jpg.webp" loading="eager" alt="Family handout A young man with short dark hair and stubble looks directly at the camera in front of a dark blue background." class="sc-5340b511-0 hLdNfA"><span class="sc-5340b511-2 jVqbAn">Family handout</span></div></div><div data-component="caption-block" class="sc-3b6b161a-0 Qwxkf"></div></figure><div data-component="text-block" class="sc-3b6b161a-0 dPVOKT"><p class="sc-9a00e533-0 eZyhnA">Dozens of patients were put at risk after two of the UK''s leading transplant centres continued fitting a heart device - despite knowing of concerns it had a higher mortality rate than its rival product.</p><p class="sc-9a00e533-0 eZyhnA">Concerns were raised by the NHS about the device in 2018. Of the patients who were subsequently fitted with the mechanical pump, half went on to die within three years.</p><p class="sc-9a00e533-0 eZyhnA">The mother of Greg Marshall - one of the patients who received the device after concerns were known and who subsequently died - told us she was "disgusted and appalled".</p><p class="sc-9a00e533-0 eZyhnA">The BBC has also learned that leading cardiologists at both hospitals were paid consultants for the device''s manufacturer. The hospitals were aware of this.</p></div><div data-testid="ad-unit" data-component="ad-slot" class="sc-1b734f04-0 kNNIux"><div data-testid="dotcom-mid_1" id="dotcom-mid_1" class="dotcom-ad"></div></div><div data-component="text-block" class="sc-3b6b161a-0 dPVOKT"><p class="sc-9a00e533-0 eZyhnA">Both hospitals - the Freeman in Newcastle and Harefield in London - continued to use the pump for years, and questioned the reliability of the data flagged by the NHS. The pump''s manufacturer, Medtronic, eventually withdrew it on safety grounds.</p><p class="sc-9a00e533-0 eZyhnA">Patients with a weakened heart, who may be waiting for a transplant or deemed not suitable for one, can be offered a machine called an LVAD, a Left Ventricular Assist Device. It helps the heart pump blood around the body and, for many patients, this is their only chance of survival until a transplant becomes available.</p><p class="sc-9a00e533-0 eZyhnA">The device is implanted into the heart, with an external wire coming out of the body - usually at the abdomen - that connects to a controller and external batteries.</p><p class="sc-9a00e533-0 eZyhnA">LVADs have been life-savers for decades and, for a number of years, hospitals had a choice of two devices - the HeartWare HVAD, sold by the Irish-American company Medtronic, and the Heartmate III, sold by US manufacturer Abbott.</p></div><figure><div data-component="image-block" class="sc-3b6b161a-0 gXrNRM"><div data-testid="image" class="sc-5340b511-1 cMIbKV"><img sizes="(min-width: 1280px) 50vw, (min-width: 1008px) 66vw, 96vw" srcset="https://ichef.bbci.co.uk/news/240/cpsprodpb/97d8/live/82015f60-beed-11f0-ae46-bd64331f0fd4.jpg.webp 240w,https://ichef.bbci.co.uk/news/320/cpsprodpb/97d8/live/82015f60-beed-11f0-ae46-bd64331f0fd4.jpg.webp 320w,https://ichef.bbci.co.uk/news/480/cpsprodpb/97d8/live/82015f60-beed-11f0-ae46-bd64331f0fd4.jpg.webp 480w,https://ichef.bbci.co.uk/news/640/cpsprodpb/97d8/live/82015f60-beed-11f0-ae46-bd64331f0fd4.jpg.webp 640w,https://ichef.bbci.co.uk/news/800/cpsprodpb/97d8/live/82015f60-beed-11f0-ae46-bd64331f0fd4.jpg.webp 800w,https://ichef.bbci.co.uk/news/1024/cpsprodpb/97d8/live/82015f60-beed-11f0-ae46-bd64331f0fd4.jpg.webp 1024w,https://ichef.bbci.co.uk/news/1536/cpsprodpb/97d8/live/82015f60-beed-11f0-ae46-bd64331f0fd4.jpg.webp 1536w" src="https://ichef.bbci.co.uk/news/480/cpsprodpb/97d8/live/82015f60-beed-11f0-ae46-bd64331f0fd4.jpg.webp" loading="lazy" alt="Medtronic An illustration of a man in a white T-shirt wearing a black belt holding four small black devices with wires protruding; higher up, we see a scan of his heart, from which a small pump with a tube emerges. A wire links the device and one of the black devices on his belt." class="sc-5340b511-0 hLdNfA"><span class="sc-5340b511-2 jVqbAn">Medtronic</span></div></div><div data-component="caption-block" class="sc-3b6b161a-0 Qwxkf"></div></figure><div data-testid="ad-unit" data-component="ad-slot" class="sc-1b734f04-0 kNNIux"><div data-testid="dotcom-mid_2" id="dotcom-mid_2" class="dotcom-ad"></div></div><div data-component="text-block" class="sc-3b6b161a-0 dPVOKT"><p class="sc-9a00e533-0 eZyhnA">In October 2018, NHS Blood and Transplant (NHSBT), which oversees transplants in the UK, conducted a preliminary audit comparing how the two pumps had performed. A more detailed analysis followed in April 2019.</p><p class="sc-9a00e533-0 eZyhnA">The results were stark. Of the 119 patients who had received the Medtronic device, 45% - or 54 patients - had died within two years. In contrast, just 15% - 15 out of 97 patients - who were given the Abbott pump had died over the same period. Similarly, the number of complications - such as strokes or needing a new pump - were significantly higher for the Medtronic device. The audit said there were "no significant differences" between the types of patients who received each device.</p><p class="sc-9a00e533-0 eZyhnA">One of the UK''s six transplant centres, the Royal Papworth Hospital in Cambridge, did not wait for the NHS analysis. It had picked up on the growing international concerns and had stopped using the Medtronic device in February 2018 "after considering the results of two randomised controlled trials", as their clinicians "considered the Heartmate III as superior".</p><p class="sc-9a00e533-0 eZyhnA">However, Harefield Hospital continued to solely use the Medtronic device until early 2021, shortly after the manufacturer had issued a safety notice. The Freeman Hospital continued until June 2021, when the manufacturer withdrew it from sale "in the interest of patient safety".</p><p class="sc-9a00e533-0 eZyhnA">The regulator, the Medicines and Healthcare products Regulatory Agency (MHRA), continued to approve the device for use after the 2019 analysis, though it had not been informed by the NHS of the data''s existence.</p><p class="sc-9a00e533-0 eZyhnA">Throughout this time, patients fitted with the Medtronic device continued to die at a higher rate than those with the Abbott device. </p><p class="sc-9a00e533-0 eZyhnA">Between October 2018, when the first set of NHS data was produced, and June 2021, when Medtronic discontinued its pump, the mortality rate of the Medtronic device was two-and-a-half times higher than the Abbott device, figures released under the Freedom of Information Act show.</p><p class="sc-9a00e533-0 eZyhnA">Forty-nine percent of those who received the Medtronic device (39 of 80 patients) in that time died within three years. By comparison, 19% of recipients of the Abbott device (20 of 106 patients) died during the same timeframe.</p></div><figure><div data-component="image-block" class="sc-3b6b161a-0 gXrNRM"><div data-testid="image" class="sc-5340b511-1 cMIbKV"><img sizes="(min-width: 1280px) 50vw, (min-width: 1008px) 66vw, 96vw" srcset="https://ichef.bbci.co.uk/news/240/cpsprodpb/9a54/live/ddb6aeb0-bf19-11f0-ae46-bd64331f0fd4.jpg.webp 240w,https://ichef.bbci.co.uk/news/320/cpsprodpb/9a54/live/ddb6aeb0-bf19-11f0-ae46-bd64331f0fd4.jpg.webp 320w,https://ichef.bbci.co.uk/news/480/cpsprodpb/9a54/live/ddb6aeb0-bf19-11f0-ae46-bd64331f0fd4.jpg.webp 480w,https://ichef.bbci.co.uk/news/640/cpsprodpb/9a54/live/ddb6aeb0-bf19-11f0-ae46-bd64331f0fd4.jpg.webp 640w,https://ichef.bbci.co.uk/news/800/cpsprodpb/9a54/live/ddb6aeb0-bf19-11f0-ae46-bd64331f0fd4.jpg.webp 800w,https://ichef.bbci.co.uk/news/1024/cpsprodpb/9a54/live/ddb6aeb0-bf19-11f0-ae46-bd64331f0fd4.jpg.webp 1024w,https://ichef.bbci.co.uk/news/1536/cpsprodpb/9a54/live/ddb6aeb0-bf19-11f0-ae46-bd64331f0fd4.jpg.webp 1536w" src="https://ichef.bbci.co.uk/news/480/cpsprodpb/9a54/live/ddb6aeb0-bf19-11f0-ae46-bd64331f0fd4.jpg.webp" loading="lazy" alt="Family handout Three people - a smiling young man in green woollen hat on the left; a middle-aged woman in the centre in a green and yellow hat that says &quot;Saints&quot;; a young man on the right smiles with short brown hair." class="sc-5340b511-0 hLdNfA"><span class="sc-5340b511-2 jVqbAn">Family handout</span></div></div><div data-component="caption-block" class="sc-3b6b161a-0 Qwxkf"></div></figure><div data-testid="ad-unit" data-component="ad-slot" class="sc-1b734f04-0 kNNIux"><div data-testid="dotcom-mid_3" id="dotcom-mid_3" class="dotcom-ad"></div></div><div data-component="text-block" class="sc-3b6b161a-0 dPVOKT"><p class="sc-9a00e533-0 eZyhnA">Medtronic decided to withdraw the device in June 2021 after growing evidence that its pump had a higher frequency of strokes and deaths compared with other devices. It also cited a specific malfunction where pumps would experience a delay or fail to restart after they were stopped.</p><p class="sc-9a00e533-0 eZyhnA">Greg Marshall was one of the patients fitted with the Medtronic device, unaware of the studies about its effectiveness compared with the rival product. A fit and healthy young man, he had ambitions of joining the Royal Marines but he suffered acute heart failure in 2019.</p><p class="sc-9a00e533-0 eZyhnA">"It was a massive shock to us all," his mother Tessa Marshall remembers.</p><p class="sc-9a00e533-0 eZyhnA">By June of that year, Greg was offered the Medtronic device by the Freeman Hospital, several months after the first set of NHS data was known about.</p><p class="sc-9a00e533-0 eZyhnA">His family say they were not presented with the long-term risks associated with the device, though an existing patient was brought in to tell them of its benefits.</p><p class="sc-9a00e533-0 eZyhnA">Greg agreed to the surgery, but a significant complication in theatre - which the family say was never fully explained to them - led to a stroke. Greg lost movement down the left-hand side of his body, and his speech was significantly impaired.</p><p class="sc-9a00e533-0 eZyhnA">Over time, his health slowly began to recover, but a year later, in July 2020, the heart device suddenly stopped working. When he tried to restart it, it failed to switch back on.</p><p class="sc-9a00e533-0 eZyhnA">"The pump was not pumping, and he just slowly went blue," Tessa says.</p><p class="sc-9a00e533-0 eZyhnA">Greg was rushed to hospital, but the device could not be fixed. He was told he could have it removed, but, terrified of having another stroke, he refused the surgery.</p><p class="sc-9a00e533-0 eZyhnA">The broken device remained inside him, switched off, as his heart continued to function for a further three years, during which time he was on a transplant waiting list.</p><p class="sc-9a00e533-0 eZyhnA">In September 2023, while in hospital, he unexpectedly went into cardiac arrest. By the time Tessa had reached the Freeman, Greg had died aged 26.</p><p class="sc-9a00e533-0 eZyhnA">His family, devastated by his loss, say they want answers.  </p><p class="sc-9a00e533-0 eZyhnA">"We said ''Look, Greg, this is the only option you''ve got, you have got to go with it,''" said Tessa. "I kick myself now, for not doing any more research." </p><p class="sc-9a00e533-0 eZyhnA">Three patients may have died of this failure, the NHS Trust in Newcastle told the Department of Health and Social Care in a letter seen by the BBC.</p><p class="sc-9a00e533-0 eZyhnA">The trust has since told the BBC the issue of the device failing to restart in patients first came to light in December 2020 - five months after Greg encountered the issue - when Medtronic published a safety notice.</p></div><figure><div data-component="image-block" class="sc-3b6b161a-0 gXrNRM"><div data-testid="image" class="sc-5340b511-1 cMIbKV"><img sizes="(min-width: 1280px) 50vw, (min-width: 1008px) 66vw, 96vw" srcset="https://ichef.bbci.co.uk/news/240/cpsprodpb/fecd/live/c8e3edc0-beee-11f0-ae46-bd64331f0fd4.jpg.webp 240w,https://ichef.bbci.co.uk/news/320/cpsprodpb/fecd/live/c8e3edc0-beee-11f0-ae46-bd64331f0fd4.jpg.webp 320w,https://ichef.bbci.co.uk/news/480/cpsprodpb/fecd/live/c8e3edc0-beee-11f0-ae46-bd64331f0fd4.jpg.webp 480w,https://ichef.bbci.co.uk/news/640/cpsprodpb/fecd/live/c8e3edc0-beee-11f0-ae46-bd64331f0fd4.jpg.webp 640w,https://ichef.bbci.co.uk/news/800/cpsprodpb/fecd/live/c8e3edc0-beee-11f0-ae46-bd64331f0fd4.jpg.webp 800w,https://ichef.bbci.co.uk/news/1024/cpsprodpb/fecd/live/c8e3edc0-beee-11f0-ae46-bd64331f0fd4.jpg.webp 1024w,https://ichef.bbci.co.uk/news/1536/cpsprodpb/fecd/live/c8e3edc0-beee-11f0-ae46-bd64331f0fd4.jpg.webp 1536w" src="https://ichef.bbci.co.uk/news/480/cpsprodpb/fecd/live/c8e3edc0-beee-11f0-ae46-bd64331f0fd4.jpg.webp" loading="lazy" alt="ISHLT An older man with sharp white hair, wearing a navy blue suit, light blue shirt and crimson tie, is being interviewed by another man with white hair, whose head we see the back of." class="sc-5340b511-0 hLdNfA"><span class="sc-5340b511-2 jVqbAn">ISHLT</span></div></div><div data-component="caption-block" class="sc-3b6b161a-0 Qwxkf"></div></figure><div data-testid="ad-unit" data-component="ad-slot" class="sc-1b734f04-0 kNNIux"><div data-testid="dotcom-mid_4" id="dotcom-mid_4" class="dotcom-ad"></div></div><div data-component="text-block" class="sc-3b6b161a-0 dPVOKT"><p class="sc-9a00e533-0 eZyhnA">Hospital documents show Greg''s responsible health professional was Prof Stephan Schueler, who until recently was head of the Freeman''s cardiothoracic department. Described by a former colleague as "king of the castle" in the transplant unit, Prof Schueler had a decade-long relationship with the manufacturer of the Medtronic device, public records show.</p><p class="sc-9a00e533-0 eZyhnA">Greg''s family say he did not declare to them his financial relationship with the heart device''s manufacturer, despite such a disclosure being a requirement of the doctor''s regulator, the General Medical Council (GMC).</p><p class="sc-9a00e533-0 eZyhnA">In a statement to the BBC, Prof Schueler said that "there was never a financial incentive nor any salary arrangements with Medtronic for me or anybody else in our team to choose one device over the other". He did not respond to a direct question about what he had told Greg Marshall about his relationship with Medtronic but said that he "always worked within GMC standards for good medical practice" and that consenting patients for a procedure was "carried out by a whole team of specialised colleagues".</p><p class="sc-9a00e533-0 eZyhnA">It is common for clinicians to work as consultants for medical manufacturer and pharmaceutical companies. Such arrangements are recognised as being mutually beneficial and can lead to better outcomes for patients, though there are rules around what medics need to declare to patients.</p><p class="sc-9a00e533-0 eZyhnA">The Freeman said in a statement to the BBC that it offered its "sincere condolences" to Greg''s family and it was investigating his case.</p><p class="sc-9a00e533-0 eZyhnA">It said that, although it was "aware" of the NHS data in April 2019, it felt its scientific value was not reliable, and pointed out that it was not accepted in any national or international scientific publication. It said there were other publications at that time which indicated "excellent outcomes" for the Medtronic device.</p><p class="sc-9a00e533-0 eZyhnA">Robbie Burns, a patient representative with NHS Blood and Transplant, obtained many of the documents relating to the hospitals'' continued use of the Medtronic device. He believes there should be an external investigation into how it was allowed to happen.</p><p class="sc-9a00e533-0 eZyhnA">"It was entirely preventable," he said.</p><p class="sc-9a00e533-0 eZyhnA">"If I had been in the position of receiving this [Medtronic] device, and looked back at the data, I would be going, ''Why on earth did you do this?''"</p><p class="sc-9a00e533-0 eZyhnA">Prof Schueler said the Medtronic device had several benefits, including being more suitable for children and small adults. He said the decision to continue using the pump was taken after internal discussions had considered all the risk and benefits carefully.</p><p class="sc-9a00e533-0 eZyhnA">Another doctor, André Simon, the director of heart and lung transplantation and ventricular assist devices at Harefield Hospital, had a similarly long-standing relationship with HeartWare and Medtronic, going back to 2014.</p><p class="sc-9a00e533-0 eZyhnA">The man who replaced him at the hospital on the edge of west London, Dr John Dunning, told the BBC that Harefield had continued to use the Medtronic device as "it was the preference" of his predecessor.</p><p class="sc-9a00e533-0 eZyhnA">Dr Simon, who no longer works at the hospital, did not respond to the BBC''s questions. In its statement, the Harefield said it was "aware" of his work for Medtronic and that this had been declared in multiple papers. The hospital added that he was one of a number of senior people "involved" in choosing which devices were used, and that "the continued use of the [Medtronic device] had collective support of clinicians at Harefield" until the manufacturer issued a safety notice in early 2021.</p><p class="sc-9a00e533-0 eZyhnA">In separate statements to the BBC, both the Freeman and Harefield hospitals said their decisions to continue using the Medtronic device were based on "complex clinical decisions" and stressed that there were "no clear grounds" at the time to believe the Medtronic device was significantly inferior to the Abbott device.</p><p class="sc-9a00e533-0 eZyhnA">Harefield said it commissioned an external review of its services in 2019 from the then-chair of the NHSBT''s Cardiothoracic Advisory Group, and this made no comment on its selection of devices.</p></div><div data-component="embed-block" class="sc-3b6b161a-0 djqsWD"></div><div data-component="tags" class="sc-3b6b161a-0 djqsWD"><div class="sc-6bf80075-0 lllwyY"><div data-testid="anchor-inner-wrapper"><a href="https://www.bbc.com/news/topics/cr0mejz7ng6t" data-testid="internal-link" class="sc-57521d02-0 jsVxCb">Newcastle upon Tyne</a></div><div data-testid="anchor-inner-wrapper"><a href="https://www.bbc.com/news/topics/cw1qqk0emrrt" data-testid="internal-link" class="sc-57521d02-0 jsVxCb">Heart</a></div><div data-testid="anchor-inner-wrapper"><a href="https://www.bbc.com/news/topics/cwdnm99j0r6t" data-testid="internal-link" class="sc-57521d02-0 jsVxCb">Harefield</a></div></div></div>', NULL, NULL);
INSERT INTO lost_and_found VALUES(73, 73, 14, 6, 803, 1763020373270, NULL, 1763008023000, 1, 1763020373270, 'en-GB', '&#039;It&#039;s a great day&#039; - Trump signs spending bill to end longest shutdown in US history', 'https://www.bbc.com/news/articles/c891nvwvg2zo?at_medium=RSS&at_campaign=rss', 'https://www.bbc.com/news/articles/c891nvwvg2zo?at_medium=RSS&at_campaign=rss', NULL, '<div data-component="headline-block" class="sc-3b6b161a-0 hNbOGD"><h1 class="sc-f98b1ad2-0 idLnWK">Trump signs spending bill to end longest shutdown in US history</h1></div><div data-component="byline-block" class="sc-3b6b161a-0 dPVOKT"><div data-testid="byline-new" class="sc-7bfdb3c2-0 fYJjWP"><div class="sc-7bfdb3c2-1 jqWinX"><time datetime="2025-11-13T04:27:03.168Z" class="sc-7bfdb3c2-2 dQuPjg">3 hours ago</time><div class="sc-7bfdb3c2-3 dVvYwG"></div></div><span data-testid="byline-new-contributors" class="sc-7bfdb3c2-11 ljQVMv"><span class="sc-7bfdb3c2-7 djOqvY">Ana Faguy</span><span data-testid="byline-new-contributors-contributor-0-role-location" class="sc-7bfdb3c2-8 gvcwmG">on Capitol Hill</span></span></div></div><div class="sc-7bfdb3c2-4 haycoC"></div><div data-component="video-block" data-testid="fabl-video-container" class="sc-3b6b161a-0 gXrNRM"><div class="sc-2218ed0c-1 fiqjXZ"><div data-testid="" class="sc-2218ed0c-2 bgTyRA"></div></div></div><div data-component="caption-block" class="sc-3b6b161a-0 Qwxkf"></div><div data-component="text-block" class="sc-3b6b161a-0 dPVOKT"><p class="sc-9a00e533-0 eZyhnA">President Donald Trump has signed a spending bill to reopen the government and end the longest shutdown in US history.</p><p class="sc-9a00e533-0 eZyhnA">He signed the short-term budget into law just hours after the House of Representatives voted 222-209 to approve it on Wednesday night, and two days after the Senate narrowly approved the same package.</p><p class="sc-9a00e533-0 eZyhnA">In the Oval Office, Trump said the government would now "resume normal operations" after "people were hurt so badly" from the 43-day shutdown.</p><p class="sc-9a00e533-0 eZyhnA">Many government services have been suspended since October, and around 1.4 million federal employees have been on unpaid leave or working without pay. Food aid has also been left in limbo and air travel has been disrupted nationwide.</p></div><div data-testid="ad-unit" data-component="ad-slot" class="sc-1b734f04-0 kNNIux"><div data-testid="dotcom-mid_1" id="dotcom-mid_1" class="dotcom-ad"></div></div><div data-component="text-block" class="sc-3b6b161a-0 dPVOKT"><p class="sc-9a00e533-0 eZyhnA">Government services are expected to reopen in the coming days, while disruptions to air travel will likely ease ahead of the looming Thanksgiving holiday. The Federal Aviation Administration (FAA) had reduced air traffic because of staff shortages owing to the shutdown.</p><ul class="sc-6f869981-0 diUlgm"><li class="sc-734a601e-0 cRgahm"><b id="analysis:" class="sc-d16436d-0 gnUCoQ">ANALYSIS: </b><a target="_self" href="https://www.bbc.com/news/articles/cz917nvj7qeo" class="sc-f9178328-0 kgTYQp">Democrats left bruised after historic shutdown yields little</a></li></ul><p class="sc-9a00e533-0 eZyhnA">That had direct impacts on members of Congress attempting to reach the nation’s capital on Wednesday for the House vote. </p><p class="sc-9a00e533-0 eZyhnA">Derrick Van Orden, a Wisconsin Republican, rode his motorcycle nearly 1,000 miles (1,609km) across the country to cast his vote in the House before it was sent to the president''s desk.</p><p class="sc-9a00e533-0 eZyhnA">The bill only provides funding to keep the government open until 30 January, when lawmakers will once again need to find a way to fund the government. </p><p class="sc-9a00e533-0 eZyhnA">Before he signed it into law, Trump repeatedly cast blame for the shutdown on the Democratic Party. "They did it purely for political reasons," he said.</p><p class="sc-9a00e533-0 eZyhnA">"When we come up to midterms and other things, don''t forget what they''ve done to our country," he added.</p></div><div data-component="embed-block" class="sc-3b6b161a-0 djqsWD"></div><div data-testid="ad-unit" data-component="ad-slot" class="sc-1b734f04-0 kNNIux"><div data-testid="dotcom-mid_2" id="dotcom-mid_2" class="dotcom-ad"></div></div><div data-component="text-block" class="sc-3b6b161a-0 dPVOKT"><p class="sc-9a00e533-0 eZyhnA">Senate Democrats were able to trigger the shutdown despite being a minority in the chamber, because Republicans were still seven short of the 60-vote threshold required to pass a funding bill. </p><p class="sc-9a00e533-0 eZyhnA">They initially refused to support the bill, demanding that Republicans agree to extend health insurance subsidies for low-income Americans that are set to expire at the end of the year.</p><p class="sc-9a00e533-0 eZyhnA">Republicans maintained that a healthcare discussion could come after the government was reopened.</p><p class="sc-9a00e533-0 eZyhnA">But on Sunday, <a target="_self" href="https://www.bbc.com/news/articles/c7974x7248go" class="sc-f9178328-0 iCaRzc">a group of eight Senate Democrats broke from the party</a> and helped pass the spending package. They voted for it in exchange for a promise of a vote on those healthcare subsidies in December.</p><p class="sc-9a00e533-0 eZyhnA">It led to fury within the Democratic Party, and public criticism from figures such as House Minority Leader Hakeem Jeffries and California Governor Gavin Newsom.</p></div><div data-component="video-block" data-testid="fabl-video-container" class="sc-3b6b161a-0 gXrNRM"><div class="sc-2218ed0c-1 fiqjXZ"><div data-testid="" class="sc-2218ed0c-2 bgTyRA"></div></div></div><div data-component="caption-block" class="sc-3b6b161a-0 Qwxkf"></div><div data-testid="ad-unit" data-component="ad-slot" class="sc-1b734f04-0 kNNIux"><div data-testid="dotcom-mid_3" id="dotcom-mid_3" class="dotcom-ad"></div></div><div data-component="text-block" class="sc-3b6b161a-0 dPVOKT"><p class="sc-9a00e533-0 eZyhnA">Senator Chuck Schumer, the minority leader in the chamber, said the package "fails to do anything of substance to fix America''s healthcare crisis".</p><p class="sc-9a00e533-0 eZyhnA">Virginia Senator Tim Kaine was among the group of Democrats who voted in favour of the compromise. He pushed back on that criticism, and said the federal workers he represents were "saying thank you" for agreeing the deal.</p><p class="sc-9a00e533-0 eZyhnA">Hours before the House voted to reopen the government, Democrats in Congress watched as their newest lawmaker was sworn into office. </p><p class="sc-9a00e533-0 eZyhnA">The addition did not provide enough leverage to impact whether healthcare subsidies were included in the government funding bill, but Democrats welcomed Adelita Grijalva into their ranks with applause on the floor of the chamber. </p><p class="sc-9a00e533-0 eZyhnA">The Democratic representative for Arizona was elected on 23 September, but the House has not been in session since 19 September, delaying her swearing in. She is stepping into the seat once held by her father, Raul Grijalva, who died earlier this year.</p><p class="sc-9a00e533-0 eZyhnA">Democrats immediately tapped their newest member to back a petition to force a vote on legislation requiring the release of files related to the late paedophile financier Jeffrey Epstein. </p><p class="sc-9a00e533-0 eZyhnA">The petition will need to sit for seven legislative days before it can be called up for floor consideration - and then House leadership will be required to schedule a vote within two legislative days.</p><p class="sc-9a00e533-0 eZyhnA">House Speaker Mike Johnson surprised many on Wednesday and said he would schedule a vote for next week. </p></div><div data-component="subheadline-block" class="sc-3b6b161a-0 hNbOGD"><h2 class="sc-f98b1ad2-0 gXmhTb">What''s in the spending deal?</h2></div><div data-component="text-block" class="sc-3b6b161a-0 dPVOKT"><p class="sc-9a00e533-0 eZyhnA">The deal negotiated over the weekend extends funding for the federal government until 30 January.</p><p class="sc-9a00e533-0 eZyhnA">It also includes full-year funding for the Department of Agriculture, as well as funding for military construction and legislative agencies.</p><p class="sc-9a00e533-0 eZyhnA">Guarantees that all federal workers will be paid for time during the shutdown, and funding for the Supplemental Nutrition Assistance Program (SNAP) - which provides food aid to one in eight Americans - until next September are also included in the bill.</p><p class="sc-9a00e533-0 eZyhnA">The package includes an agreement for a vote in December on extending the healthcare subsidies which Democrats had been holding out for concessions on.</p><p class="sc-9a00e533-0 eZyhnA"></p></div><div data-testid="ad-unit" data-component="ad-slot" class="sc-1b734f04-0 kNNIux"><div data-testid="dotcom-mid_4" id="dotcom-mid_4" class="dotcom-ad"></div></div><figure><div data-component="image-block" class="sc-3b6b161a-0 GunZh"><div data-testid="image" class="sc-5340b511-1 cMIbKV"><img srcset="https://ichef.bbci.co.uk/news/240/cpsprodpb/bac3/live/67a60360-beb0-11f0-8456-eff94716b162.png.webp 240w, https://ichef.bbci.co.uk/news/320/cpsprodpb/bac3/live/67a60360-beb0-11f0-8456-eff94716b162.png.webp 320w, https://ichef.bbci.co.uk/news/480/cpsprodpb/bac3/live/67a60360-beb0-11f0-8456-eff94716b162.png.webp 480w, https://ichef.bbci.co.uk/news/640/cpsprodpb/bac3/live/67a60360-beb0-11f0-8456-eff94716b162.png.webp 640w, https://ichef.bbci.co.uk/news/800/cpsprodpb/bac3/live/67a60360-beb0-11f0-8456-eff94716b162.png.webp 800w, https://ichef.bbci.co.uk/news/1024/cpsprodpb/bac3/live/67a60360-beb0-11f0-8456-eff94716b162.png.webp 1024w, https://ichef.bbci.co.uk/news/1536/cpsprodpb/bac3/live/67a60360-beb0-11f0-8456-eff94716b162.png.webp 1536w" src="https://ichef.bbci.co.uk/news/480/cpsprodpb/bac3/live/67a60360-beb0-11f0-8456-eff94716b162.png.webp" alt="A thin, grey banner promoting the US Politics Unspun newsletter. On the right, there is an image of the Capitol Building against a background of vertical red, grey and blue stripes. The banner reads: &quot;The newsletter that cuts through the noise.”" class="sc-5340b511-0 hLdNfA" /></div></div></figure><div data-component="text-block" class="sc-3b6b161a-0 dPVOKT"><p class="sc-9a00e533-0 eZyhnA">Follow the twists and turns of Trump''s second term with North America correspondent Anthony Zurcher''s weekly <a target="_self" href="https://www.bbc.co.uk/news/world-us-canada-68093155" class="sc-f9178328-0 iCaRzc">US Politics Unspun</a> newsletter. Readers in the UK can <a target="_self" href="https://www.bbc.co.uk/newsletters/zgmn46f" class="sc-f9178328-0 iCaRzc">sign up here</a>. Those outside the UK can <a target="_self" href="https://cloud.email.bbc.com/US_Politics_Unspun_Newsletter_Signup" class="sc-f9178328-0 iCaRzc">sign up here</a>.</p></div><div data-component="tags" class="sc-3b6b161a-0 djqsWD"><div class="sc-6bf80075-0 lllwyY"><div data-testid="anchor-inner-wrapper"><a href="https://www.bbc.com/news/topics/cwnpxwzd269t" data-testid="internal-link" class="sc-57521d02-0 jsVxCb">US politics</a></div><div data-testid="anchor-inner-wrapper"><a href="https://www.bbc.com/news/topics/cwwlxznll4lt" data-testid="internal-link" class="sc-57521d02-0 jsVxCb">US Congress</a></div><div data-testid="anchor-inner-wrapper"><a href="https://www.bbc.com/news/topics/cx1m7zg01xyt" data-testid="internal-link" class="sc-57521d02-0 jsVxCb">United States</a></div></div></div>', NULL, '<div data-component="headline-block" class="sc-3b6b161a-0 hNbOGD"><h1 class="sc-f98b1ad2-0 idLnWK">Trump signs spending bill to end longest shutdown in US history</h1></div><div data-component="byline-block" class="sc-3b6b161a-0 dPVOKT"><div data-testid="byline-new" class="sc-7bfdb3c2-0 fYJjWP"><div class="sc-7bfdb3c2-1 jqWinX"><time datetime="2025-11-13T04:27:03.168Z" class="sc-7bfdb3c2-2 dQuPjg">3 hours ago</time><div class="sc-7bfdb3c2-3 dVvYwG"></div></div><span data-testid="byline-new-contributors" class="sc-7bfdb3c2-11 ljQVMv"><div data-testid="byline-new-contributors-contributor-0" class="sc-7bfdb3c2-5 xGeVU"><div><span class="sc-7bfdb3c2-7 djOqvY">Ana Faguy</span><span data-testid="byline-new-contributors-contributor-0-role-location" class="sc-7bfdb3c2-8 gvcwmG">on Capitol Hill</span></div></div></span><div class="sc-7bfdb3c2-4 haycoC"></div></div></div><div data-component="video-block" data-testid="fabl-video-container" class="sc-3b6b161a-0 gXrNRM"><div class="sc-2218ed0c-1 fiqjXZ"><div data-testid style="visibility:hidden" class="sc-2218ed0c-2 bgTyRA"></div></div></div><div data-component="caption-block" class="sc-3b6b161a-0 Qwxkf"></div><div data-component="text-block" class="sc-3b6b161a-0 dPVOKT"><p class="sc-9a00e533-0 eZyhnA">President Donald Trump has signed a spending bill to reopen the government and end the longest shutdown in US history.</p><p class="sc-9a00e533-0 eZyhnA">He signed the short-term budget into law just hours after the House of Representatives voted 222-209 to approve it on Wednesday night, and two days after the Senate narrowly approved the same package.</p><p class="sc-9a00e533-0 eZyhnA">In the Oval Office, Trump said the government would now "resume normal operations" after "people were hurt so badly" from the 43-day shutdown.</p><p class="sc-9a00e533-0 eZyhnA">Many government services have been suspended since October, and around 1.4 million federal employees have been on unpaid leave or working without pay. Food aid has also been left in limbo and air travel has been disrupted nationwide.</p></div><div data-testid="ad-unit" data-component="ad-slot" class="sc-1b734f04-0 kNNIux"><div data-testid="dotcom-mid_1" id="dotcom-mid_1" class="dotcom-ad"></div></div><div data-component="text-block" class="sc-3b6b161a-0 dPVOKT"><p class="sc-9a00e533-0 eZyhnA">Government services are expected to reopen in the coming days, while disruptions to air travel will likely ease ahead of the looming Thanksgiving holiday. The Federal Aviation Administration (FAA) had reduced air traffic because of staff shortages owing to the shutdown.</p><ul class="sc-6f869981-0 diUlgm"><li class="sc-734a601e-0 cRgahm"><b id="analysis:" class="sc-d16436d-0 gnUCoQ">ANALYSIS: </b><a target="_self" href="https://www.bbc.com/news/articles/cz917nvj7qeo" class="sc-f9178328-0 kgTYQp">Democrats left bruised after historic shutdown yields little</a></li></ul><p class="sc-9a00e533-0 eZyhnA">That had direct impacts on members of Congress attempting to reach the nation’s capital on Wednesday for the House vote. </p><p class="sc-9a00e533-0 eZyhnA">Derrick Van Orden, a Wisconsin Republican, rode his motorcycle nearly 1,000 miles (1,609km) across the country to cast his vote in the House before it was sent to the president''s desk.</p><p class="sc-9a00e533-0 eZyhnA">The bill only provides funding to keep the government open until 30 January, when lawmakers will once again need to find a way to fund the government. </p><p class="sc-9a00e533-0 eZyhnA">Before he signed it into law, Trump repeatedly cast blame for the shutdown on the Democratic Party. "They did it purely for political reasons," he said.</p><p class="sc-9a00e533-0 eZyhnA">"When we come up to midterms and other things, don''t forget what they''ve done to our country," he added.</p></div><div data-component="embed-block" class="sc-3b6b161a-0 djqsWD"></div><div data-testid="ad-unit" data-component="ad-slot" class="sc-1b734f04-0 kNNIux"><div data-testid="dotcom-mid_2" id="dotcom-mid_2" class="dotcom-ad"></div></div><div data-component="text-block" class="sc-3b6b161a-0 dPVOKT"><p class="sc-9a00e533-0 eZyhnA">Senate Democrats were able to trigger the shutdown despite being a minority in the chamber, because Republicans were still seven short of the 60-vote threshold required to pass a funding bill. </p><p class="sc-9a00e533-0 eZyhnA">They initially refused to support the bill, demanding that Republicans agree to extend health insurance subsidies for low-income Americans that are set to expire at the end of the year.</p><p class="sc-9a00e533-0 eZyhnA">Republicans maintained that a healthcare discussion could come after the government was reopened.</p><p class="sc-9a00e533-0 eZyhnA">But on Sunday, <a target="_self" href="https://www.bbc.com/news/articles/c7974x7248go" class="sc-f9178328-0 iCaRzc">a group of eight Senate Democrats broke from the party</a> and helped pass the spending package. They voted for it in exchange for a promise of a vote on those healthcare subsidies in December.</p><p class="sc-9a00e533-0 eZyhnA">It led to fury within the Democratic Party, and public criticism from figures such as House Minority Leader Hakeem Jeffries and California Governor Gavin Newsom.</p></div><div data-component="video-block" data-testid="fabl-video-container" class="sc-3b6b161a-0 gXrNRM"><div class="sc-2218ed0c-1 fiqjXZ"><div data-testid style="visibility:hidden" class="sc-2218ed0c-2 bgTyRA"></div></div></div><div data-component="caption-block" class="sc-3b6b161a-0 Qwxkf"></div><div data-testid="ad-unit" data-component="ad-slot" class="sc-1b734f04-0 kNNIux"><div data-testid="dotcom-mid_3" id="dotcom-mid_3" class="dotcom-ad"></div></div><div data-component="text-block" class="sc-3b6b161a-0 dPVOKT"><p class="sc-9a00e533-0 eZyhnA">Senator Chuck Schumer, the minority leader in the chamber, said the package "fails to do anything of substance to fix America''s healthcare crisis".</p><p class="sc-9a00e533-0 eZyhnA">Virginia Senator Tim Kaine was among the group of Democrats who voted in favour of the compromise. He pushed back on that criticism, and said the federal workers he represents were "saying thank you" for agreeing the deal.</p><p class="sc-9a00e533-0 eZyhnA">Hours before the House voted to reopen the government, Democrats in Congress watched as their newest lawmaker was sworn into office. </p><p class="sc-9a00e533-0 eZyhnA">The addition did not provide enough leverage to impact whether healthcare subsidies were included in the government funding bill, but Democrats welcomed Adelita Grijalva into their ranks with applause on the floor of the chamber. </p><p class="sc-9a00e533-0 eZyhnA">The Democratic representative for Arizona was elected on 23 September, but the House has not been in session since 19 September, delaying her swearing in. She is stepping into the seat once held by her father, Raul Grijalva, who died earlier this year.</p><p class="sc-9a00e533-0 eZyhnA">Democrats immediately tapped their newest member to back a petition to force a vote on legislation requiring the release of files related to the late paedophile financier Jeffrey Epstein. </p><p class="sc-9a00e533-0 eZyhnA">The petition will need to sit for seven legislative days before it can be called up for floor consideration - and then House leadership will be required to schedule a vote within two legislative days.</p><p class="sc-9a00e533-0 eZyhnA">House Speaker Mike Johnson surprised many on Wednesday and said he would schedule a vote for next week. </p></div><div data-component="subheadline-block" class="sc-3b6b161a-0 hNbOGD"><h2 class="sc-f98b1ad2-0 gXmhTb">What''s in the spending deal?</h2></div><div data-component="text-block" class="sc-3b6b161a-0 dPVOKT"><p class="sc-9a00e533-0 eZyhnA">The deal negotiated over the weekend extends funding for the federal government until 30 January.</p><p class="sc-9a00e533-0 eZyhnA">It also includes full-year funding for the Department of Agriculture, as well as funding for military construction and legislative agencies.</p><p class="sc-9a00e533-0 eZyhnA">Guarantees that all federal workers will be paid for time during the shutdown, and funding for the Supplemental Nutrition Assistance Program (SNAP) - which provides food aid to one in eight Americans - until next September are also included in the bill.</p><p class="sc-9a00e533-0 eZyhnA">The package includes an agreement for a vote in December on extending the healthcare subsidies which Democrats had been holding out for concessions on.</p><p class="sc-9a00e533-0 eZyhnA"></p></div><div data-testid="ad-unit" data-component="ad-slot" class="sc-1b734f04-0 kNNIux"><div data-testid="dotcom-mid_4" id="dotcom-mid_4" class="dotcom-ad"></div></div><figure><div data-component="image-block" class="sc-3b6b161a-0 GunZh"><div data-testid="image" class="sc-5340b511-1 cMIbKV"><img sizes="(min-width: 1280px) 50vw, (min-width: 1008px) 66vw, 96vw" srcset="https://ichef.bbci.co.uk/news/240/cpsprodpb/bac3/live/67a60360-beb0-11f0-8456-eff94716b162.png.webp 240w,https://ichef.bbci.co.uk/news/320/cpsprodpb/bac3/live/67a60360-beb0-11f0-8456-eff94716b162.png.webp 320w,https://ichef.bbci.co.uk/news/480/cpsprodpb/bac3/live/67a60360-beb0-11f0-8456-eff94716b162.png.webp 480w,https://ichef.bbci.co.uk/news/640/cpsprodpb/bac3/live/67a60360-beb0-11f0-8456-eff94716b162.png.webp 640w,https://ichef.bbci.co.uk/news/800/cpsprodpb/bac3/live/67a60360-beb0-11f0-8456-eff94716b162.png.webp 800w,https://ichef.bbci.co.uk/news/1024/cpsprodpb/bac3/live/67a60360-beb0-11f0-8456-eff94716b162.png.webp 1024w,https://ichef.bbci.co.uk/news/1536/cpsprodpb/bac3/live/67a60360-beb0-11f0-8456-eff94716b162.png.webp 1536w" src="https://ichef.bbci.co.uk/news/480/cpsprodpb/bac3/live/67a60360-beb0-11f0-8456-eff94716b162.png.webp" loading="eager" alt="A thin, grey banner promoting the US Politics Unspun newsletter. On the right, there is an image of the Capitol Building against a background of vertical red, grey and blue stripes. The banner reads: &quot;The newsletter that cuts through the noise.”" class="sc-5340b511-0 hLdNfA"></div></div></figure><div data-component="text-block" class="sc-3b6b161a-0 dPVOKT"><p class="sc-9a00e533-0 eZyhnA">Follow the twists and turns of Trump''s second term with North America correspondent Anthony Zurcher''s weekly <a target="_self" href="https://www.bbc.co.uk/news/world-us-canada-68093155" class="sc-f9178328-0 iCaRzc">US Politics Unspun</a> newsletter. Readers in the UK can <a target="_self" href="https://www.bbc.co.uk/newsletters/zgmn46f" class="sc-f9178328-0 iCaRzc">sign up here</a>. Those outside the UK can <a target="_self" href="https://cloud.email.bbc.com/US_Politics_Unspun_Newsletter_Signup" class="sc-f9178328-0 iCaRzc">sign up here</a>.</p></div><div data-component="tags" class="sc-3b6b161a-0 djqsWD"><div class="sc-6bf80075-0 lllwyY"><div data-testid="anchor-inner-wrapper"><a href="https://www.bbc.com/news/topics/cwnpxwzd269t" data-testid="internal-link" class="sc-57521d02-0 jsVxCb">US politics</a></div><div data-testid="anchor-inner-wrapper"><a href="https://www.bbc.com/news/topics/cwwlxznll4lt" data-testid="internal-link" class="sc-57521d02-0 jsVxCb">US Congress</a></div><div data-testid="anchor-inner-wrapper"><a href="https://www.bbc.com/news/topics/cx1m7zg01xyt" data-testid="internal-link" class="sc-57521d02-0 jsVxCb">United States</a></div></div></div>', NULL, NULL);
INSERT INTO lost_and_found VALUES(85, 85, 14, 7, 664, 1763020373989, NULL, 1763003527000, 1, 1763020373989, 'en-GB', '&#039;Stop touts fleecing fans&#039;: Dua Lipa and Coldplay urge quicker crackdown on ticket resales', 'https://www.bbc.com/news/articles/c33pygprx7zo?at_medium=RSS&at_campaign=rss', 'https://www.bbc.com/news/articles/c33pygprx7zo?at_medium=RSS&at_campaign=rss', NULL, '<div data-component="headline-block" class="sc-3b6b161a-0 hNbOGD"><h1 class="sc-f98b1ad2-0 idLnWK">Dua Lipa and Coldplay urge action on ticket touts</h1></div><div data-component="byline-block" class="sc-3b6b161a-0 dPVOKT"><div data-testid="byline-new" class="sc-7bfdb3c2-0 fYJjWP"><div class="sc-7bfdb3c2-1 jqWinX"><time datetime="2025-11-13T03:12:07.549Z" class="sc-7bfdb3c2-2 dQuPjg">5 hours ago</time><div class="sc-7bfdb3c2-3 dVvYwG"></div></div><span data-testid="byline-new-contributors" class="sc-7bfdb3c2-11 ljQVMv"><span class="sc-7bfdb3c2-7 djOqvY">Mark Savage</span><span data-testid="byline-new-contributors-contributor-0-role-location" class="sc-7bfdb3c2-8 gvcwmG">Music correspondent</span></span></div></div><div class="sc-7bfdb3c2-4 haycoC"></div><figure><div data-component="image-block" class="sc-3b6b161a-0 gtLOOD"><div data-testid="hero-image" class="sc-5340b511-1 cMIbKV"><img srcset="https://ichef.bbci.co.uk/news/240/cpsprodpb/bc53/live/4ddca780-bfce-11f0-b880-bdabe65471f0.jpg.webp 240w, https://ichef.bbci.co.uk/news/320/cpsprodpb/bc53/live/4ddca780-bfce-11f0-b880-bdabe65471f0.jpg.webp 320w, https://ichef.bbci.co.uk/news/480/cpsprodpb/bc53/live/4ddca780-bfce-11f0-b880-bdabe65471f0.jpg.webp 480w, https://ichef.bbci.co.uk/news/640/cpsprodpb/bc53/live/4ddca780-bfce-11f0-b880-bdabe65471f0.jpg.webp 640w, https://ichef.bbci.co.uk/news/800/cpsprodpb/bc53/live/4ddca780-bfce-11f0-b880-bdabe65471f0.jpg.webp 800w, https://ichef.bbci.co.uk/news/1024/cpsprodpb/bc53/live/4ddca780-bfce-11f0-b880-bdabe65471f0.jpg.webp 1024w, https://ichef.bbci.co.uk/news/1536/cpsprodpb/bc53/live/4ddca780-bfce-11f0-b880-bdabe65471f0.jpg.webp 1536w" src="https://ichef.bbci.co.uk/news/480/cpsprodpb/bc53/live/4ddca780-bfce-11f0-b880-bdabe65471f0.jpg.webp" alt="Getty Images Dua Lipa sings during a concert at Wembley Stadium" class="sc-5340b511-0 hLdNfA" /><span class="sc-5340b511-2 jVqbAn">Getty Images</span></div></div><div data-component="caption-block" class="sc-3b6b161a-0 Qwxkf"></div></figure><div data-component="text-block" class="sc-3b6b161a-0 dPVOKT"><p class="sc-9a00e533-0 eZyhnA">Pop stars including Dua Lipa, Coldplay, Sam Fender, Radiohead and The Cure have called on Sir Keir Starmer to honour his election promise to protect fans from online ticket touts.</p><p class="sc-9a00e533-0 eZyhnA">More than 40 musicians have signed a letter urging the UK prime minister to "stop touts from fleecing fans" and cap the price that can be charged when tickets are resold.</p><p class="sc-9a00e533-0 eZyhnA">The government launched a public consultation on the issue in January after complaints from fans, saying it would tackle touts who "are systematically buying up tickets on the primary market and reselling them to fans at often hugely inflated prices".</p><p class="sc-9a00e533-0 eZyhnA">But seven months after the consultation closed, there has been no indication of when legislation might be introduced.</p></div><div data-testid="ad-unit" data-component="ad-slot" class="sc-1b734f04-0 kNNIux"><div data-testid="dotcom-mid_1" id="dotcom-mid_1" class="dotcom-ad"></div></div><div data-component="subheadline-block" class="sc-3b6b161a-0 hNbOGD"><h2 class="sc-f98b1ad2-0 gXmhTb">''Ripped off''</h2></div><div data-component="text-block" class="sc-3b6b161a-0 dPVOKT"><p class="sc-9a00e533-0 eZyhnA">New research from Which? magazine found that some tickets to see Oasis at Wembley Stadium this summer were listed for as much as £4,442.</p><p class="sc-9a00e533-0 eZyhnA">According to analysis by the Competition and Market Authority (CMA), tickets sold on the resale market are typically marked up by more than 50%.</p><p class="sc-9a00e533-0 eZyhnA">In January, the government said it was considering a price cap of up to 30%.</p><p class="sc-9a00e533-0 eZyhnA">Dan Smith from indie-pop group Bastille said "it seems crazy" that fans aren''t protected from price hikes, when countries like Ireland and Australia have introduced caps on ticket resales.</p><p class="sc-9a00e533-0 eZyhnA">"It''s not surprising that the idea of a price cap has such widespread support from bands and artists," he said. </p><p class="sc-9a00e533-0 eZyhnA">"With the support of the government we can all move to a situation where people no longer get ripped off by touts and genuine fans can easily resell unwanted tickets for their original price."</p></div><div data-component="links-block" class="sc-3b6b161a-0 djqsWD"><div class="sc-666b6d83-0 sc-c4fb5674-0 jYmMqa doYqeg"><div data-testid="links-grid" class="sc-666b6d83-0 sc-c4fb5674-1 gEjRXC jkjVgq"><div data-testid="chester-card" data-indexcard="true" class="sc-225578b-0 ezQaGx"><div data-testid="anchor-inner-wrapper"><a href="https://www.bbc.co.uk/news/articles/c2kdxlv8x05o" data-testid="external-anchor" target="_self" class="sc-8a623a54-0 huZCWi"><div data-testid="chester-article" class="sc-cf565bcc-0 kwPVOm"><div class="sc-fa814188-1 iRoJZi"><div class="sc-fa814188-0 hPhBqv"><h2 data-testid="card-headline" class="sc-fa814188-3 iCfgww">Why do concert tickets now cost as much as a games console?</h2></div></div></div></a></div></div><div data-testid="chester-card" data-indexcard="true" class="sc-225578b-0 ezQaGx"><div data-testid="anchor-inner-wrapper"><a href="https://www.bbc.co.uk/news/articles/c04e9k1vllro" data-testid="external-anchor" target="_self" class="sc-8a623a54-0 huZCWi"><div data-testid="chester-article" class="sc-cf565bcc-0 kwPVOm"><div class="sc-fa814188-1 iRoJZi"><div class="sc-fa814188-0 hPhBqv"><h2 data-testid="card-headline" class="sc-fa814188-3 iCfgww">Touts employ overseas workers to bulk-buy gig tickets</h2></div></div></div></a></div></div><div data-testid="chester-card" data-indexcard="true" class="sc-225578b-0 ezQaGx"><div data-testid="anchor-inner-wrapper"><a href="https://www.bbc.co.uk/news/articles/cqxzqvw4lv8o" data-testid="external-anchor" target="_self" class="sc-8a623a54-0 huZCWi"><div data-testid="chester-article" class="sc-cf565bcc-0 kwPVOm"><div class="sc-fa814188-1 iRoJZi"><div class="sc-fa814188-0 hPhBqv"><h2 data-testid="card-headline" class="sc-fa814188-3 iCfgww">Ticketmaster agrees to better price information after Oasis complaints</h2></div></div></div></a></div></div><div data-testid="chester-card" data-indexcard="true" class="sc-225578b-0 ezQaGx"><div data-testid="anchor-inner-wrapper"><a href="https://www.bbc.co.uk/news/articles/cdx9x8v8p04o" data-testid="external-anchor" target="_self" class="sc-8a623a54-0 huZCWi"><div data-testid="chester-article" class="sc-cf565bcc-0 kwPVOm"><div class="sc-fa814188-1 iRoJZi"><div class="sc-fa814188-0 hPhBqv"><h2 data-testid="card-headline" class="sc-fa814188-3 iCfgww">Price of resale tickets to be capped under plans to tackle touts</h2></div></div></div></a></div></div></div></div></div><div data-testid="ad-unit" data-component="ad-slot" class="sc-1b734f04-0 kNNIux"><div data-testid="dotcom-mid_2" id="dotcom-mid_2" class="dotcom-ad"></div></div><div data-component="text-block" class="sc-3b6b161a-0 dPVOKT"><p class="sc-9a00e533-0 eZyhnA">A spokesperson for the Department for Culture said: "This government is fully committed to clamping down on touts and is going further to put fans back at the heart of live events.</p><p class="sc-9a00e533-0 eZyhnA">"We have carefully considered evidence provided in response to our consultation earlier this year and will set out our plans shortly."</p><p class="sc-9a00e533-0 eZyhnA">The government''s consultation also proposed limiting the number of tickets that resellers can offer.</p><p class="sc-9a00e533-0 eZyhnA">In the letter, artists including PJ Harvey, Mark Knopfler, Amy MacDonald, Iron Maiden and Nick Cave joined consumer organisations in urging the government to respond to the consultation "as soon as possible, and commit to include legislation on a price cap in the next King''s Speech".</p><p class="sc-9a00e533-0 eZyhnA">They said the move would "restore faith in the ticketing system" and "help democratise public access to the arts".</p></div><figure><div data-component="image-block" class="sc-3b6b161a-0 gXrNRM"><div data-testid="image" class="sc-5340b511-1 cMIbKV"><img srcset="https://ichef.bbci.co.uk/news/240/cpsprodpb/9a9c/live/79eb0920-bfce-11f0-ae46-bd64331f0fd4.jpg.webp 240w, https://ichef.bbci.co.uk/news/320/cpsprodpb/9a9c/live/79eb0920-bfce-11f0-ae46-bd64331f0fd4.jpg.webp 320w, https://ichef.bbci.co.uk/news/480/cpsprodpb/9a9c/live/79eb0920-bfce-11f0-ae46-bd64331f0fd4.jpg.webp 480w, https://ichef.bbci.co.uk/news/640/cpsprodpb/9a9c/live/79eb0920-bfce-11f0-ae46-bd64331f0fd4.jpg.webp 640w, https://ichef.bbci.co.uk/news/800/cpsprodpb/9a9c/live/79eb0920-bfce-11f0-ae46-bd64331f0fd4.jpg.webp 800w, https://ichef.bbci.co.uk/news/1024/cpsprodpb/9a9c/live/79eb0920-bfce-11f0-ae46-bd64331f0fd4.jpg.webp 1024w, https://ichef.bbci.co.uk/news/1536/cpsprodpb/9a9c/live/79eb0920-bfce-11f0-ae46-bd64331f0fd4.jpg.webp 1536w" src="https://ichef.bbci.co.uk/news/480/cpsprodpb/9a9c/live/79eb0920-bfce-11f0-ae46-bd64331f0fd4.jpg.webp" alt="Getty Images Chris Martin of Coldplay, surrounded by fans at Wembley Stadium" class="sc-5340b511-0 hLdNfA" /><span class="sc-5340b511-2 jVqbAn">Getty Images</span></div></div><div data-component="caption-block" class="sc-3b6b161a-0 Qwxkf"></div></figure><div data-testid="ad-unit" data-component="ad-slot" class="sc-1b734f04-0 kNNIux"><div data-testid="dotcom-mid_3" id="dotcom-mid_3" class="dotcom-ad"></div></div><div data-component="text-block" class="sc-3b6b161a-0 dPVOKT"><p class="sc-9a00e533-0 eZyhnA">The letter comes as Which? found prolific sellers in Brazil, Dubai, Singapore, Spain and the US hoovering up tickets for popular US events before relisting them at inflated prices on sites like StubHub and Viagogo.</p><p class="sc-9a00e533-0 eZyhnA">The findings echoed a <a target="_self" href="https://www.bbc.co.uk/news/articles/c04e9k1vllro" class="sc-f9178328-0 iCaRzc">BBC investigation this summer</a>, which discovered teams of overseas workers bulk-buying tickets for concerts in the UK to resell for profit.</p><p class="sc-9a00e533-0 eZyhnA">The watchdog found it was often difficult for fans to establish the seller''s identity or to contact them - despite the Competition and Markets Authority (CMA) securing a court order in 2018 requiring Viagogo to reveal the identity of traders.</p><p class="sc-9a00e533-0 eZyhnA">Which? also found evidence of speculative selling - when tickets are listed on secondary sites even though the seller has not bought them yet.</p></div><div data-component="text-block" class="sc-3b6b161a-0 dPVOKT"><p class="sc-9a00e533-0 eZyhnA">Which? consumer law expert Lisa Webb said the joint statement issued on Thursday "makes clear that artists, fan organisations and consumers reject the broken ticketing market that has allowed touts to thrive for too long".</p><p class="sc-9a00e533-0 eZyhnA">Resale sites like Viagogo and Stubhub claim a price cap could push customers towards unregulated sites and social media - putting them at increased risk of fraud.</p><p class="sc-9a00e533-0 eZyhnA">In football''s Premier League, where resales are forbidden because the sport must abide by stricter laws than music events in order to maintain segregation in stadiums, <a target="_self" href="https://www.bbc.co.uk/sport/football/articles/cvgr499wn4eo" class="sc-f9178328-0 iCaRzc">the BBC recently uncovered</a> a black market for match tickets, with some exchanging hands for tens of thousands of pounds.</p></div><div data-component="tags" class="sc-3b6b161a-0 djqsWD"><div class="sc-6bf80075-0 lllwyY"><div data-testid="anchor-inner-wrapper"><a href="https://www.bbc.com/news/topics/c50znx8v8rwt" data-testid="internal-link" class="sc-57521d02-0 jsVxCb">Keir Starmer</a></div><div data-testid="anchor-inner-wrapper"><a href="https://www.bbc.com/news/topics/c8gmm5d92n1t" data-testid="internal-link" class="sc-57521d02-0 jsVxCb">Live music</a></div><div data-testid="anchor-inner-wrapper"><a href="https://www.bbc.com/news/topics/cnq8dy29zqvt" data-testid="internal-link" class="sc-57521d02-0 jsVxCb">Coldplay</a></div><div data-testid="anchor-inner-wrapper"><a href="https://www.bbc.com/news/topics/crlw6nzk4v5t" data-testid="internal-link" class="sc-57521d02-0 jsVxCb">Bastille</a></div><div data-testid="anchor-inner-wrapper"><a href="https://www.bbc.com/news/topics/crr7mlg0dg1t" data-testid="internal-link" class="sc-57521d02-0 jsVxCb">Labour Party</a></div><div data-testid="anchor-inner-wrapper"><a href="https://www.bbc.com/news/topics/cxj88kmw6lgt" data-testid="internal-link" class="sc-57521d02-0 jsVxCb">Ticketing</a></div><div data-testid="anchor-inner-wrapper"><a href="https://www.bbc.com/news/topics/cz4pr2gd872t" data-testid="internal-link" class="sc-57521d02-0 jsVxCb">Music</a></div></div></div>', NULL, '<div data-component="headline-block" class="sc-3b6b161a-0 hNbOGD"><h1 class="sc-f98b1ad2-0 idLnWK">Dua Lipa and Coldplay urge action on ticket touts</h1></div><div data-component="byline-block" class="sc-3b6b161a-0 dPVOKT"><div data-testid="byline-new" class="sc-7bfdb3c2-0 fYJjWP"><div class="sc-7bfdb3c2-1 jqWinX"><time datetime="2025-11-13T03:12:07.549Z" class="sc-7bfdb3c2-2 dQuPjg">5 hours ago</time><div class="sc-7bfdb3c2-3 dVvYwG"></div></div><span data-testid="byline-new-contributors" class="sc-7bfdb3c2-11 ljQVMv"><div data-testid="byline-new-contributors-contributor-0" class="sc-7bfdb3c2-5 xGeVU"><div><span class="sc-7bfdb3c2-7 djOqvY">Mark Savage</span><span data-testid="byline-new-contributors-contributor-0-role-location" class="sc-7bfdb3c2-8 gvcwmG">Music correspondent</span></div></div></span><div class="sc-7bfdb3c2-4 haycoC"></div></div></div><figure><div data-component="image-block" class="sc-3b6b161a-0 gtLOOD"><div data-testid="hero-image" class="sc-5340b511-1 cMIbKV"><img sizes="(min-width: 1280px) 50vw, (min-width: 1008px) 66vw, 96vw" srcset="https://ichef.bbci.co.uk/news/240/cpsprodpb/bc53/live/4ddca780-bfce-11f0-b880-bdabe65471f0.jpg.webp 240w,https://ichef.bbci.co.uk/news/320/cpsprodpb/bc53/live/4ddca780-bfce-11f0-b880-bdabe65471f0.jpg.webp 320w,https://ichef.bbci.co.uk/news/480/cpsprodpb/bc53/live/4ddca780-bfce-11f0-b880-bdabe65471f0.jpg.webp 480w,https://ichef.bbci.co.uk/news/640/cpsprodpb/bc53/live/4ddca780-bfce-11f0-b880-bdabe65471f0.jpg.webp 640w,https://ichef.bbci.co.uk/news/800/cpsprodpb/bc53/live/4ddca780-bfce-11f0-b880-bdabe65471f0.jpg.webp 800w,https://ichef.bbci.co.uk/news/1024/cpsprodpb/bc53/live/4ddca780-bfce-11f0-b880-bdabe65471f0.jpg.webp 1024w,https://ichef.bbci.co.uk/news/1536/cpsprodpb/bc53/live/4ddca780-bfce-11f0-b880-bdabe65471f0.jpg.webp 1536w" src="https://ichef.bbci.co.uk/news/480/cpsprodpb/bc53/live/4ddca780-bfce-11f0-b880-bdabe65471f0.jpg.webp" loading="eager" alt="Getty Images Dua Lipa sings during a concert at Wembley Stadium" class="sc-5340b511-0 hLdNfA"><span class="sc-5340b511-2 jVqbAn">Getty Images</span></div></div><div data-component="caption-block" class="sc-3b6b161a-0 Qwxkf"></div></figure><div data-component="text-block" class="sc-3b6b161a-0 dPVOKT"><p class="sc-9a00e533-0 eZyhnA">Pop stars including Dua Lipa, Coldplay, Sam Fender, Radiohead and The Cure have called on Sir Keir Starmer to honour his election promise to protect fans from online ticket touts.</p><p class="sc-9a00e533-0 eZyhnA">More than 40 musicians have signed a letter urging the UK prime minister to "stop touts from fleecing fans" and cap the price that can be charged when tickets are resold.</p><p class="sc-9a00e533-0 eZyhnA">The government launched a public consultation on the issue in January after complaints from fans, saying it would tackle touts who "are systematically buying up tickets on the primary market and reselling them to fans at often hugely inflated prices".</p><p class="sc-9a00e533-0 eZyhnA">But seven months after the consultation closed, there has been no indication of when legislation might be introduced.</p></div><div data-testid="ad-unit" data-component="ad-slot" class="sc-1b734f04-0 kNNIux"><div data-testid="dotcom-mid_1" id="dotcom-mid_1" class="dotcom-ad"></div></div><div data-component="subheadline-block" class="sc-3b6b161a-0 hNbOGD"><h2 class="sc-f98b1ad2-0 gXmhTb">''Ripped off''</h2></div><div data-component="text-block" class="sc-3b6b161a-0 dPVOKT"><p class="sc-9a00e533-0 eZyhnA">New research from Which? magazine found that some tickets to see Oasis at Wembley Stadium this summer were listed for as much as £4,442.</p><p class="sc-9a00e533-0 eZyhnA">According to analysis by the Competition and Market Authority (CMA), tickets sold on the resale market are typically marked up by more than 50%.</p><p class="sc-9a00e533-0 eZyhnA">In January, the government said it was considering a price cap of up to 30%.</p><p class="sc-9a00e533-0 eZyhnA">Dan Smith from indie-pop group Bastille said "it seems crazy" that fans aren''t protected from price hikes, when countries like Ireland and Australia have introduced caps on ticket resales.</p><p class="sc-9a00e533-0 eZyhnA">"It''s not surprising that the idea of a price cap has such widespread support from bands and artists," he said. </p><p class="sc-9a00e533-0 eZyhnA">"With the support of the government we can all move to a situation where people no longer get ripped off by touts and genuine fans can easily resell unwanted tickets for their original price."</p></div><div data-component="links-block" class="sc-3b6b161a-0 djqsWD"><div class="sc-666b6d83-0 sc-c4fb5674-0 jYmMqa doYqeg"><div data-testid="links-grid" class="sc-666b6d83-0 sc-c4fb5674-1 gEjRXC jkjVgq"><div data-testid="chester-card" data-indexcard="true" class="sc-225578b-0 ezQaGx"><div data-testid="anchor-inner-wrapper"><a href="https://www.bbc.co.uk/news/articles/c2kdxlv8x05o" data-testid="external-anchor" target="_self" class="sc-8a623a54-0 huZCWi"><div data-testid="chester-article" class="sc-cf565bcc-0 kwPVOm"><div class="sc-fa814188-1 iRoJZi"><div class="sc-fa814188-0 hPhBqv"><h2 data-testid="card-headline" class="sc-fa814188-3 iCfgww">Why do concert tickets now cost as much as a games console?</h2></div></div></div></a></div></div><div data-testid="chester-card" data-indexcard="true" class="sc-225578b-0 ezQaGx"><div data-testid="anchor-inner-wrapper"><a href="https://www.bbc.co.uk/news/articles/c04e9k1vllro" data-testid="external-anchor" target="_self" class="sc-8a623a54-0 huZCWi"><div data-testid="chester-article" class="sc-cf565bcc-0 kwPVOm"><div class="sc-fa814188-1 iRoJZi"><div class="sc-fa814188-0 hPhBqv"><h2 data-testid="card-headline" class="sc-fa814188-3 iCfgww">Touts employ overseas workers to bulk-buy gig tickets</h2></div></div></div></a></div></div><div data-testid="chester-card" data-indexcard="true" class="sc-225578b-0 ezQaGx"><div data-testid="anchor-inner-wrapper"><a href="https://www.bbc.co.uk/news/articles/cqxzqvw4lv8o" data-testid="external-anchor" target="_self" class="sc-8a623a54-0 huZCWi"><div data-testid="chester-article" class="sc-cf565bcc-0 kwPVOm"><div class="sc-fa814188-1 iRoJZi"><div class="sc-fa814188-0 hPhBqv"><h2 data-testid="card-headline" class="sc-fa814188-3 iCfgww">Ticketmaster agrees to better price information after Oasis complaints</h2></div></div></div></a></div></div><div data-testid="chester-card" data-indexcard="true" class="sc-225578b-0 ezQaGx"><div data-testid="anchor-inner-wrapper"><a href="https://www.bbc.co.uk/news/articles/cdx9x8v8p04o" data-testid="external-anchor" target="_self" class="sc-8a623a54-0 huZCWi"><div data-testid="chester-article" class="sc-cf565bcc-0 kwPVOm"><div class="sc-fa814188-1 iRoJZi"><div class="sc-fa814188-0 hPhBqv"><h2 data-testid="card-headline" class="sc-fa814188-3 iCfgww">Price of resale tickets to be capped under plans to tackle touts</h2></div></div></div></a></div></div></div></div></div><div data-testid="ad-unit" data-component="ad-slot" class="sc-1b734f04-0 kNNIux"><div data-testid="dotcom-mid_2" id="dotcom-mid_2" class="dotcom-ad"></div></div><div data-component="text-block" class="sc-3b6b161a-0 dPVOKT"><p class="sc-9a00e533-0 eZyhnA">A spokesperson for the Department for Culture said: "This government is fully committed to clamping down on touts and is going further to put fans back at the heart of live events.</p><p class="sc-9a00e533-0 eZyhnA">"We have carefully considered evidence provided in response to our consultation earlier this year and will set out our plans shortly."</p><p class="sc-9a00e533-0 eZyhnA">The government''s consultation also proposed limiting the number of tickets that resellers can offer.</p><p class="sc-9a00e533-0 eZyhnA">In the letter, artists including PJ Harvey, Mark Knopfler, Amy MacDonald, Iron Maiden and Nick Cave joined consumer organisations in urging the government to respond to the consultation "as soon as possible, and commit to include legislation on a price cap in the next King''s Speech".</p><p class="sc-9a00e533-0 eZyhnA">They said the move would "restore faith in the ticketing system" and "help democratise public access to the arts".</p></div><figure><div data-component="image-block" class="sc-3b6b161a-0 gXrNRM"><div data-testid="image" class="sc-5340b511-1 cMIbKV"><img sizes="(min-width: 1280px) 50vw, (min-width: 1008px) 66vw, 96vw" srcset="https://ichef.bbci.co.uk/news/240/cpsprodpb/9a9c/live/79eb0920-bfce-11f0-ae46-bd64331f0fd4.jpg.webp 240w,https://ichef.bbci.co.uk/news/320/cpsprodpb/9a9c/live/79eb0920-bfce-11f0-ae46-bd64331f0fd4.jpg.webp 320w,https://ichef.bbci.co.uk/news/480/cpsprodpb/9a9c/live/79eb0920-bfce-11f0-ae46-bd64331f0fd4.jpg.webp 480w,https://ichef.bbci.co.uk/news/640/cpsprodpb/9a9c/live/79eb0920-bfce-11f0-ae46-bd64331f0fd4.jpg.webp 640w,https://ichef.bbci.co.uk/news/800/cpsprodpb/9a9c/live/79eb0920-bfce-11f0-ae46-bd64331f0fd4.jpg.webp 800w,https://ichef.bbci.co.uk/news/1024/cpsprodpb/9a9c/live/79eb0920-bfce-11f0-ae46-bd64331f0fd4.jpg.webp 1024w,https://ichef.bbci.co.uk/news/1536/cpsprodpb/9a9c/live/79eb0920-bfce-11f0-ae46-bd64331f0fd4.jpg.webp 1536w" src="https://ichef.bbci.co.uk/news/480/cpsprodpb/9a9c/live/79eb0920-bfce-11f0-ae46-bd64331f0fd4.jpg.webp" loading="lazy" alt="Getty Images Chris Martin of Coldplay, surrounded by fans at Wembley Stadium" class="sc-5340b511-0 hLdNfA"><span class="sc-5340b511-2 jVqbAn">Getty Images</span></div></div><div data-component="caption-block" class="sc-3b6b161a-0 Qwxkf"></div></figure><div data-testid="ad-unit" data-component="ad-slot" class="sc-1b734f04-0 kNNIux"><div data-testid="dotcom-mid_3" id="dotcom-mid_3" class="dotcom-ad"></div></div><div data-component="text-block" class="sc-3b6b161a-0 dPVOKT"><p class="sc-9a00e533-0 eZyhnA">The letter comes as Which? found prolific sellers in Brazil, Dubai, Singapore, Spain and the US hoovering up tickets for popular US events before relisting them at inflated prices on sites like StubHub and Viagogo.</p><p class="sc-9a00e533-0 eZyhnA">The findings echoed a <a target="_self" href="https://www.bbc.co.uk/news/articles/c04e9k1vllro" class="sc-f9178328-0 iCaRzc">BBC investigation this summer</a>, which discovered teams of overseas workers bulk-buying tickets for concerts in the UK to resell for profit.</p><p class="sc-9a00e533-0 eZyhnA">The watchdog found it was often difficult for fans to establish the seller''s identity or to contact them - despite the Competition and Markets Authority (CMA) securing a court order in 2018 requiring Viagogo to reveal the identity of traders.</p><p class="sc-9a00e533-0 eZyhnA">Which? also found evidence of speculative selling - when tickets are listed on secondary sites even though the seller has not bought them yet.</p></div><div data-component="text-block" class="sc-3b6b161a-0 dPVOKT"><p class="sc-9a00e533-0 eZyhnA">Which? consumer law expert Lisa Webb said the joint statement issued on Thursday "makes clear that artists, fan organisations and consumers reject the broken ticketing market that has allowed touts to thrive for too long".</p><p class="sc-9a00e533-0 eZyhnA">Resale sites like Viagogo and Stubhub claim a price cap could push customers towards unregulated sites and social media - putting them at increased risk of fraud.</p><p class="sc-9a00e533-0 eZyhnA">In football''s Premier League, where resales are forbidden because the sport must abide by stricter laws than music events in order to maintain segregation in stadiums, <a target="_self" href="https://www.bbc.co.uk/sport/football/articles/cvgr499wn4eo" class="sc-f9178328-0 iCaRzc">the BBC recently uncovered</a> a black market for match tickets, with some exchanging hands for tens of thousands of pounds.</p></div><div data-component="tags" class="sc-3b6b161a-0 djqsWD"><div class="sc-6bf80075-0 lllwyY"><div data-testid="anchor-inner-wrapper"><a href="https://www.bbc.com/news/topics/c50znx8v8rwt" data-testid="internal-link" class="sc-57521d02-0 jsVxCb">Keir Starmer</a></div><div data-testid="anchor-inner-wrapper"><a href="https://www.bbc.com/news/topics/c8gmm5d92n1t" data-testid="internal-link" class="sc-57521d02-0 jsVxCb">Live music</a></div><div data-testid="anchor-inner-wrapper"><a href="https://www.bbc.com/news/topics/cnq8dy29zqvt" data-testid="internal-link" class="sc-57521d02-0 jsVxCb">Coldplay</a></div><div data-testid="anchor-inner-wrapper"><a href="https://www.bbc.com/news/topics/crlw6nzk4v5t" data-testid="internal-link" class="sc-57521d02-0 jsVxCb">Bastille</a></div><div data-testid="anchor-inner-wrapper"><a href="https://www.bbc.com/news/topics/crr7mlg0dg1t" data-testid="internal-link" class="sc-57521d02-0 jsVxCb">Labour Party</a></div><div data-testid="anchor-inner-wrapper"><a href="https://www.bbc.com/news/topics/cxj88kmw6lgt" data-testid="internal-link" class="sc-57521d02-0 jsVxCb">Ticketing</a></div><div data-testid="anchor-inner-wrapper"><a href="https://www.bbc.com/news/topics/cz4pr2gd872t" data-testid="internal-link" class="sc-57521d02-0 jsVxCb">Music</a></div></div></div>', NULL, NULL);
INSERT INTO lost_and_found VALUES(85, 85, 14, 8, 2000, 1763020374593, NULL, 1763013611000, 1, 1763020374593, 'en-GB', 'Russia’s attacks have ramped up - Ukraine is fighting to hold on through another winter', 'https://www.bbc.com/news/articles/cly98qp99l8o?at_medium=RSS&at_campaign=rss', 'https://www.bbc.com/news/articles/cly98qp99l8o?at_medium=RSS&at_campaign=rss', NULL, '<div data-component="headline-block" class="sc-3b6b161a-0 hNbOGD"><h1 class="sc-f98b1ad2-0 idLnWK">Russia’s attacks have ramped up - Ukraine is fighting to hold on through another winter</h1></div><div data-component="byline-block" class="sc-3b6b161a-0 dPVOKT"><div data-testid="byline-new" class="sc-7bfdb3c2-0 fYJjWP"><div class="sc-7bfdb3c2-1 jqWinX"><time datetime="2025-11-13T06:00:11.235Z" class="sc-7bfdb3c2-2 dQuPjg">2 hours ago</time><div class="sc-7bfdb3c2-3 dVvYwG"></div></div><span data-testid="byline-new-contributors" class="sc-7bfdb3c2-11 ljQVMv"><span class="sc-7bfdb3c2-6 gBqcVx"><img srcset="https://ichef.bbci.co.uk/news/240/cpsprodpb/f82a/live/a8fa9220-bee4-11f0-8669-5560f5c90fbe.png.webp 240w, https://ichef.bbci.co.uk/news/320/cpsprodpb/f82a/live/a8fa9220-bee4-11f0-8669-5560f5c90fbe.png.webp 320w, https://ichef.bbci.co.uk/news/480/cpsprodpb/f82a/live/a8fa9220-bee4-11f0-8669-5560f5c90fbe.png.webp 480w, https://ichef.bbci.co.uk/news/640/cpsprodpb/f82a/live/a8fa9220-bee4-11f0-8669-5560f5c90fbe.png.webp 640w, https://ichef.bbci.co.uk/news/800/cpsprodpb/f82a/live/a8fa9220-bee4-11f0-8669-5560f5c90fbe.png.webp 800w, https://ichef.bbci.co.uk/news/1024/cpsprodpb/f82a/live/a8fa9220-bee4-11f0-8669-5560f5c90fbe.png.webp 1024w, https://ichef.bbci.co.uk/news/1536/cpsprodpb/f82a/live/a8fa9220-bee4-11f0-8669-5560f5c90fbe.png.webp 1536w" src="https://ichef.bbci.co.uk/news/480/cpsprodpb/f82a/live/a8fa9220-bee4-11f0-8669-5560f5c90fbe.png.webp" alt="James Landale profile image" class="sc-5340b511-0 hLdNfA" /></span><span class="sc-7bfdb3c2-7 djOqvY">James Landale</span><span data-testid="byline-new-contributors-contributor-0-role-location" class="sc-7bfdb3c2-8 gvcwmG">Diplomatic Correspondent</span></span></div></div><div class="sc-7bfdb3c2-4 haycoC"></div><figure><div data-component="image-block" class="sc-3b6b161a-0 eRlINq"><div data-testid="hero-image" class="sc-5340b511-1 cMIbKV"><img srcset="https://ichef.bbci.co.uk/news/240/cpsprodpb/cbc1/live/cce5d0a0-bfe3-11f0-8456-eff94716b162.jpg.webp 240w, https://ichef.bbci.co.uk/news/320/cpsprodpb/cbc1/live/cce5d0a0-bfe3-11f0-8456-eff94716b162.jpg.webp 320w, https://ichef.bbci.co.uk/news/480/cpsprodpb/cbc1/live/cce5d0a0-bfe3-11f0-8456-eff94716b162.jpg.webp 480w, https://ichef.bbci.co.uk/news/640/cpsprodpb/cbc1/live/cce5d0a0-bfe3-11f0-8456-eff94716b162.jpg.webp 640w, https://ichef.bbci.co.uk/news/800/cpsprodpb/cbc1/live/cce5d0a0-bfe3-11f0-8456-eff94716b162.jpg.webp 800w, https://ichef.bbci.co.uk/news/1024/cpsprodpb/cbc1/live/cce5d0a0-bfe3-11f0-8456-eff94716b162.jpg.webp 1024w, https://ichef.bbci.co.uk/news/1536/cpsprodpb/cbc1/live/cce5d0a0-bfe3-11f0-8456-eff94716b162.jpg.webp 1536w" src="https://ichef.bbci.co.uk/news/480/cpsprodpb/cbc1/live/cce5d0a0-bfe3-11f0-8456-eff94716b162.jpg.webp" alt="BBC A dual image of Russian President Vladimir Putin and flames at a thermal power plant in Ukraine" class="sc-5340b511-0 hLdNfA" /><span class="sc-5340b511-2 jVqbAn">BBC</span></div></div></figure><div data-component="text-block" class="sc-3b6b161a-0 dPVOKT"><p class="sc-9a00e533-0 eZyhnA"><b id="in-her-soviet-era-apartment-block-on-the-outskirts-of-eastern-kyiv,-oksana-zinkovska-boyarska-lives-with-daily-power-cuts.-the-lift-to-her-eighth-floor-apartment-often-stops,-the-lights-go-out-and-sometimes-the-pumps-maintaining-pressure-in-the-gas-central-heating-fail." class="sc-d16436d-0 gnUCoQ">In her Soviet-era apartment block on the outskirts of eastern Kyiv, Oksana Zinkovska-Boyarska lives with daily power cuts. The lift to her eighth-floor apartment often stops, the lights go out and sometimes the pumps maintaining pressure in the gas central heating fail.</b></p><p class="sc-9a00e533-0 eZyhnA">She has a big rechargeable battery pack to keep appliances going, but it costs €2,000 (£1,770) and it only lasts so long. Her husband Ievgen, a lawyer, often has to work by torchlight. Their two-year-old daughter Katia plays by candlelight too.</p><p class="sc-9a00e533-0 eZyhnA">Amid air raids and cold darkness, Oksana says she and Ievgen worry constantly for Katia. "I can''t describe with words the animal fear when you take your child to the shelter during the explosions.</p><p class="sc-9a00e533-0 eZyhnA">"I have never felt anything like that in my life and I wouldn''t want anyone to feel anything like that. The thought that she might be scared because there''s no light - this is terrible."</p></div><div data-testid="ad-unit" data-component="ad-slot" class="sc-1b734f04-0 kNNIux"><div data-testid="dotcom-mid_1" id="dotcom-mid_1" class="dotcom-ad"></div></div><figure><div data-component="image-block" class="sc-3b6b161a-0 gXrNRM"><div data-testid="image" class="sc-5340b511-1 cMIbKV"><img srcset="https://ichef.bbci.co.uk/news/240/cpsprodpb/dc40/live/d4c9f020-befe-11f0-8669-5560f5c90fbe.png.webp 240w, https://ichef.bbci.co.uk/news/320/cpsprodpb/dc40/live/d4c9f020-befe-11f0-8669-5560f5c90fbe.png.webp 320w, https://ichef.bbci.co.uk/news/480/cpsprodpb/dc40/live/d4c9f020-befe-11f0-8669-5560f5c90fbe.png.webp 480w, https://ichef.bbci.co.uk/news/640/cpsprodpb/dc40/live/d4c9f020-befe-11f0-8669-5560f5c90fbe.png.webp 640w, https://ichef.bbci.co.uk/news/800/cpsprodpb/dc40/live/d4c9f020-befe-11f0-8669-5560f5c90fbe.png.webp 800w, https://ichef.bbci.co.uk/news/1024/cpsprodpb/dc40/live/d4c9f020-befe-11f0-8669-5560f5c90fbe.png.webp 1024w, https://ichef.bbci.co.uk/news/1536/cpsprodpb/dc40/live/d4c9f020-befe-11f0-8669-5560f5c90fbe.png.webp 1536w" src="https://ichef.bbci.co.uk/news/480/cpsprodpb/dc40/live/d4c9f020-befe-11f0-8669-5560f5c90fbe.png.webp" alt="Xavier Vanpevenaege/BBC Oksana Zinkovska-Boyarska carries her young child and a candle" class="sc-5340b511-0 hLdNfA" /><span class="sc-5340b511-2 jVqbAn">Xavier Vanpevenaege/BBC</span></div></div><div data-component="caption-block" class="sc-3b6b161a-0 Qwxkf"></div></figure><div data-component="text-block" class="sc-3b6b161a-0 dPVOKT"><p class="sc-9a00e533-0 eZyhnA">All across Ukraine, families are bracing themselves for even tougher times ahead - a long, cold winter in which Russian President Vladimir Putin attempts to finish off his "special military operation" by striking Ukraine''s power supplies.</p><p class="sc-9a00e533-0 eZyhnA">Just last weekend, a massive drone and missile strike left much of the country for a time without power. Ukrainians are now enduring regular power cuts of up to 16 hours a day.</p><p class="sc-9a00e533-0 eZyhnA">In winter, temperatures in Ukraine can plummet as low as -20C. One senior government figure told me they expect the next few months to be brutal.</p><p class="sc-9a00e533-0 eZyhnA">"I think it will be the worst winter of our history," says the official. "Russia will destroy our energy, our infrastructure, our heating. All state institutions should be prepared for the worst scenario."</p><p class="sc-9a00e533-0 eZyhnA">Maxim Timchenko, the chief executive of DTEK, a large private energy company in Ukraine, says: "Based on the intensity of attacks for the past two months, it is clear Russia is aiming for the complete destruction of Ukraine''s energy system."</p></div><div data-testid="ad-unit" data-component="ad-slot" class="sc-1b734f04-0 kNNIux"><div data-testid="dotcom-mid_2" id="dotcom-mid_2" class="dotcom-ad"></div></div><figure><div data-component="image-block" class="sc-3b6b161a-0 gXrNRM"><div data-testid="image" class="sc-5340b511-1 cMIbKV"><img srcset="https://ichef.bbci.co.uk/news/240/cpsprodpb/ad83/live/be14e9b0-bfdb-11f0-8456-eff94716b162.jpg.webp 240w, https://ichef.bbci.co.uk/news/320/cpsprodpb/ad83/live/be14e9b0-bfdb-11f0-8456-eff94716b162.jpg.webp 320w, https://ichef.bbci.co.uk/news/480/cpsprodpb/ad83/live/be14e9b0-bfdb-11f0-8456-eff94716b162.jpg.webp 480w, https://ichef.bbci.co.uk/news/640/cpsprodpb/ad83/live/be14e9b0-bfdb-11f0-8456-eff94716b162.jpg.webp 640w, https://ichef.bbci.co.uk/news/800/cpsprodpb/ad83/live/be14e9b0-bfdb-11f0-8456-eff94716b162.jpg.webp 800w, https://ichef.bbci.co.uk/news/1024/cpsprodpb/ad83/live/be14e9b0-bfdb-11f0-8456-eff94716b162.jpg.webp 1024w, https://ichef.bbci.co.uk/news/1536/cpsprodpb/ad83/live/be14e9b0-bfdb-11f0-8456-eff94716b162.jpg.webp 1536w" src="https://ichef.bbci.co.uk/news/480/cpsprodpb/ad83/live/be14e9b0-bfdb-11f0-8456-eff94716b162.jpg.webp" alt="AFP via Getty Images A resident in a shop during a partial blackout" class="sc-5340b511-0 hLdNfA" /><span class="sc-5340b511-2 jVqbAn">AFP via Getty Images</span></div></div><div data-component="caption-block" class="sc-3b6b161a-0 Qwxkf"></div></figure><div data-component="text-block" class="sc-3b6b161a-0 dPVOKT"><p class="sc-9a00e533-0 eZyhnA">But according to one European envoy, it''s not just about people being cold at night or without light - there is more to Russia''s strategy.</p><p class="sc-9a00e533-0 eZyhnA">"[This] is also about them not getting any bread from the bakery in the morning and not being able to go to work because there is no power for the factory," says the envoy.</p><p class="sc-9a00e533-0 eZyhnA">As the official puts it: "The goal of the Russians is to kill our economy."</p><p class="sc-9a00e533-0 eZyhnA">So how exactly will this warfare tactic play out? And given that almost four years of war have taken their toll, what does the increasing use of this weapon in the war of attrition mean for Ukraine''s people - and the endpoint of this long, hard war?</p></div><div data-testid="ad-unit" data-component="ad-slot" class="sc-1b734f04-0 kNNIux"><div data-testid="dotcom-mid_3" id="dotcom-mid_3" class="dotcom-ad"></div></div><div data-component="subheadline-block" class="sc-3b6b161a-0 hNbOGD"><h2 class="sc-f98b1ad2-0 gXmhTb">Frozen assets and suspended diplomacy</h2></div><div data-component="text-block" class="sc-3b6b161a-0 dPVOKT"><p class="sc-9a00e533-0 eZyhnA">On the front line, the news is bleak. There are growing signs that the key eastern city of Pokrovsk may fall, giving Russian forces a boost in morale and a fresh platform to seize more of the Donetsk region.</p><p class="sc-9a00e533-0 eZyhnA">What''s more, for now, diplomatic efforts to end the war appear to be on hold.</p></div><figure><div data-component="image-block" class="sc-3b6b161a-0 gXrNRM"><div data-testid="image" class="sc-5340b511-1 cMIbKV"><img srcset="https://ichef.bbci.co.uk/news/240/cpsprodpb/9fce/live/c51f20e0-bfdb-11f0-8456-eff94716b162.jpg.webp 240w, https://ichef.bbci.co.uk/news/320/cpsprodpb/9fce/live/c51f20e0-bfdb-11f0-8456-eff94716b162.jpg.webp 320w, https://ichef.bbci.co.uk/news/480/cpsprodpb/9fce/live/c51f20e0-bfdb-11f0-8456-eff94716b162.jpg.webp 480w, https://ichef.bbci.co.uk/news/640/cpsprodpb/9fce/live/c51f20e0-bfdb-11f0-8456-eff94716b162.jpg.webp 640w, https://ichef.bbci.co.uk/news/800/cpsprodpb/9fce/live/c51f20e0-bfdb-11f0-8456-eff94716b162.jpg.webp 800w, https://ichef.bbci.co.uk/news/1024/cpsprodpb/9fce/live/c51f20e0-bfdb-11f0-8456-eff94716b162.jpg.webp 1024w, https://ichef.bbci.co.uk/news/1536/cpsprodpb/9fce/live/c51f20e0-bfdb-11f0-8456-eff94716b162.jpg.webp 1536w" src="https://ichef.bbci.co.uk/news/480/cpsprodpb/9fce/live/c51f20e0-bfdb-11f0-8456-eff94716b162.jpg.webp" alt="Global Images Ukraine via Getty Images Ukrainian servicemen with firearms in the snow" class="sc-5340b511-0 hLdNfA" /><span class="sc-5340b511-2 jVqbAn">Global Images Ukraine via Getty Images</span></div></div><div data-component="caption-block" class="sc-3b6b161a-0 Qwxkf"></div></figure><div data-testid="ad-unit" data-component="ad-slot" class="sc-1b734f04-0 kNNIux"><div data-testid="dotcom-mid_4" id="dotcom-mid_4" class="dotcom-ad"></div></div><div data-component="text-block" class="sc-3b6b161a-0 dPVOKT"><p class="sc-9a00e533-0 eZyhnA">Talk of a summit between US President Donald Trump and Russia''s Vladimir Putin are on the back burner after Moscow refused to budge from its maximalist war aims and the US imposed sanctions on Russian oil and gas.</p><p class="sc-9a00e533-0 eZyhnA">"There is currently a pause," a Kremlin spokesman said this week, "the situation is stalled."</p><p class="sc-9a00e533-0 eZyhnA">All the while, European nations deliberate over what to do with €180bn (£160bn) in frozen Russian assets. They plan to use the cash to raise a so-called "repatriation loan" for Ukraine, repaid only if Russia ever pays reparations after the end of the war. </p><p class="sc-9a00e533-0 eZyhnA">But a row over how to share the risk has left Kyiv''s coffers looking distinctly bare.</p></div><figure><div data-component="image-block" class="sc-3b6b161a-0 gXrNRM"><div data-testid="image" class="sc-5340b511-1 cMIbKV"><img srcset="https://ichef.bbci.co.uk/news/240/cpsprodpb/95ac/live/98e08af0-7120-11f0-8dbd-f3d32ebd3327.png.webp 240w, https://ichef.bbci.co.uk/news/320/cpsprodpb/95ac/live/98e08af0-7120-11f0-8dbd-f3d32ebd3327.png.webp 320w, https://ichef.bbci.co.uk/news/480/cpsprodpb/95ac/live/98e08af0-7120-11f0-8dbd-f3d32ebd3327.png.webp 480w, https://ichef.bbci.co.uk/news/640/cpsprodpb/95ac/live/98e08af0-7120-11f0-8dbd-f3d32ebd3327.png.webp 640w, https://ichef.bbci.co.uk/news/800/cpsprodpb/95ac/live/98e08af0-7120-11f0-8dbd-f3d32ebd3327.png.webp 800w, https://ichef.bbci.co.uk/news/1024/cpsprodpb/95ac/live/98e08af0-7120-11f0-8dbd-f3d32ebd3327.png.webp 1024w, https://ichef.bbci.co.uk/news/1536/cpsprodpb/95ac/live/98e08af0-7120-11f0-8dbd-f3d32ebd3327.png.webp 1536w" src="https://ichef.bbci.co.uk/news/480/cpsprodpb/95ac/live/98e08af0-7120-11f0-8dbd-f3d32ebd3327.png.webp" alt="REUTERS/Kevin Lamarque U.S. President Donald Trump and Russia''s President Vladimir Putin shake hands during a joint news conference" class="sc-5340b511-0 hLdNfA" /><span class="sc-5340b511-2 jVqbAn">REUTERS/Kevin Lamarque</span></div></div><div data-component="caption-block" class="sc-3b6b161a-0 Qwxkf"></div></figure><div data-testid="ad-unit" data-component="ad-slot" class="sc-1b734f04-0 kNNIux"><div data-testid="dotcom-mid_5" id="dotcom-mid_5" class="dotcom-ad"></div></div><div data-component="text-block" class="sc-3b6b161a-0 dPVOKT"><p class="sc-9a00e533-0 eZyhnA">Yet it is the energy crisis that is worrying the Ukrainian government most, according to those I spoke to. "People are tired after four years of the war," the official tells me.</p><p class="sc-9a00e533-0 eZyhnA">"I am afraid they will be demotivated."</p></div><div data-component="subheadline-block" class="sc-3b6b161a-0 hNbOGD"><h2 class="sc-f98b1ad2-0 gXmhTb">Insomnia, missiles and shifting morale</h2></div><div data-component="text-block" class="sc-3b6b161a-0 dPVOKT"><p class="sc-9a00e533-0 eZyhnA">Walk the streets of Kyiv and you''ll pass a sea of tired faces - people''s eyes are red from a lack of sleep, their rest broken by the air raid sirens.</p><p class="sc-9a00e533-0 eZyhnA">"I am tired of not sleeping enough," says Yana Kolomiets, 31, a casting director from Odesa. "But... people who fight on the front line are tired [too]."</p><p class="sc-9a00e533-0 eZyhnA">A recent scientific study suggested that people are three times more likely to suffer from insomnia in Ukraine than in countries at peace. </p><p class="sc-9a00e533-0 eZyhnA">It tracked the sleep patterns of around 100 Ukrainians over six months, and found the insomnia persisted even on quiet nights. (The research was published by Texty, a data journalism website based in Ukraine.)</p><p class="sc-9a00e533-0 eZyhnA">There have not been many quiet nights. Russia launched vast numbers of ballistic missiles at Ukraine in October - some 268 in all, the highest monthly total since the full-scale invasion, according to analysis published by the Oboz news site. The same month Russia launched 5,298 Shahed and other bomber drones.</p></div><div data-testid="ad-unit" data-component="ad-slot" class="sc-1b734f04-0 kNNIux"><div data-testid="dotcom-mid_6" id="dotcom-mid_6" class="dotcom-ad"></div></div><figure><div data-component="image-block" class="sc-3b6b161a-0 gXrNRM"><div data-testid="image" class="sc-5340b511-1 cMIbKV"><img srcset="https://ichef.bbci.co.uk/news/240/cpsprodpb/b984/live/8a9d2270-bff2-11f0-8669-5560f5c90fbe.jpg.webp 240w, https://ichef.bbci.co.uk/news/320/cpsprodpb/b984/live/8a9d2270-bff2-11f0-8669-5560f5c90fbe.jpg.webp 320w, https://ichef.bbci.co.uk/news/480/cpsprodpb/b984/live/8a9d2270-bff2-11f0-8669-5560f5c90fbe.jpg.webp 480w, https://ichef.bbci.co.uk/news/640/cpsprodpb/b984/live/8a9d2270-bff2-11f0-8669-5560f5c90fbe.jpg.webp 640w, https://ichef.bbci.co.uk/news/800/cpsprodpb/b984/live/8a9d2270-bff2-11f0-8669-5560f5c90fbe.jpg.webp 800w, https://ichef.bbci.co.uk/news/1024/cpsprodpb/b984/live/8a9d2270-bff2-11f0-8669-5560f5c90fbe.jpg.webp 1024w, https://ichef.bbci.co.uk/news/1536/cpsprodpb/b984/live/8a9d2270-bff2-11f0-8669-5560f5c90fbe.jpg.webp 1536w" src="https://ichef.bbci.co.uk/news/480/cpsprodpb/b984/live/8a9d2270-bff2-11f0-8669-5560f5c90fbe.jpg.webp" alt="Getty Images People stand near graves during memorial services at the Lychakiv military cemetery in Lviv, Ukraine (2024)" class="sc-5340b511-0 hLdNfA" /><span class="sc-5340b511-2 jVqbAn">Getty Images</span></div></div><div data-component="caption-block" class="sc-3b6b161a-0 Qwxkf"></div></figure><div data-component="text-block" class="sc-3b6b161a-0 dPVOKT"><p class="sc-9a00e533-0 eZyhnA">Diplomats suggest there is a geographic focus to Russia''s tactics, their strikes deliberately targeting gas and electricity transmission networks in eastern Ukraine, rather than power stations in the west of the country.</p><p class="sc-9a00e533-0 eZyhnA">"They are trying to cut Ukraine in two in terms of energy," one European envoy says. "They want anywhere east of the river Dnipro to be cold this winter."</p><p class="sc-9a00e533-0 eZyhnA">The aim, one government source told me, is to "instigate an insurrection, so that people go against the government in Kyiv… they are trying to destroy social cohesion."</p><p class="sc-9a00e533-0 eZyhnA">So concerned is the United Nations Office for the Coordination of Humanitarian Affairs it has already issued a formal warning, saying "the approaching winter poses new risks for Ukrainians... as intensified attacks on energy networks undermine efforts to maintain warmth in homes, schools and health centres".</p></div><div data-testid="ad-unit" data-component="ad-slot" class="sc-1b734f04-0 kNNIux"><div data-testid="dotcom-mid_7" id="dotcom-mid_7" class="dotcom-ad"></div></div><figure><div data-component="image-block" class="sc-3b6b161a-0 gXrNRM"><div data-testid="image" class="sc-5340b511-1 cMIbKV"><img srcset="https://ichef.bbci.co.uk/news/240/cpsprodpb/3899/live/d197e0a0-bfdb-11f0-8456-eff94716b162.jpg.webp 240w, https://ichef.bbci.co.uk/news/320/cpsprodpb/3899/live/d197e0a0-bfdb-11f0-8456-eff94716b162.jpg.webp 320w, https://ichef.bbci.co.uk/news/480/cpsprodpb/3899/live/d197e0a0-bfdb-11f0-8456-eff94716b162.jpg.webp 480w, https://ichef.bbci.co.uk/news/640/cpsprodpb/3899/live/d197e0a0-bfdb-11f0-8456-eff94716b162.jpg.webp 640w, https://ichef.bbci.co.uk/news/800/cpsprodpb/3899/live/d197e0a0-bfdb-11f0-8456-eff94716b162.jpg.webp 800w, https://ichef.bbci.co.uk/news/1024/cpsprodpb/3899/live/d197e0a0-bfdb-11f0-8456-eff94716b162.jpg.webp 1024w, https://ichef.bbci.co.uk/news/1536/cpsprodpb/3899/live/d197e0a0-bfdb-11f0-8456-eff94716b162.jpg.webp 1536w" src="https://ichef.bbci.co.uk/news/480/cpsprodpb/3899/live/d197e0a0-bfdb-11f0-8456-eff94716b162.jpg.webp" alt="Getty Images The memorial at Maidan Square honoring Ukrainian and foreign soldiers is covered in fresh snow" class="sc-5340b511-0 hLdNfA" /><span class="sc-5340b511-2 jVqbAn">Getty Images</span></div></div><div data-component="caption-block" class="sc-3b6b161a-0 Qwxkf"></div></figure><div data-component="text-block" class="sc-3b6b161a-0 dPVOKT"><p class="sc-9a00e533-0 eZyhnA">Uncertainty over the outcome of the various diplomatic initiatives hasn''t helped, either.</p><p class="sc-9a00e533-0 eZyhnA">And yet opinion polls suggest people in Ukraine may in fact be more hopeful, not less. </p><p class="sc-9a00e533-0 eZyhnA">Research by the Kyiv International Institute of Sociology, a pollster, suggested that in October 56% of 1,008 Ukrainians interviewed felt optimistic about the country''s future, up from 43% in May.</p><p class="sc-9a00e533-0 eZyhnA">Sasha, a Kyiv-based financier, explains that Ukrainian morale is volatile, swinging wildly between optimism and pessimism.</p><p class="sc-9a00e533-0 eZyhnA">"If people talk about an end to the war, they feel hopeful," he says. "But then when the talks fail, they despair."</p><p class="sc-9a00e533-0 eZyhnA">Oksana, though, is pragmatic: she says that for all the fears for her daughter, they have no choice but to endure it. </p><p class="sc-9a00e533-0 eZyhnA">"I always think it is much worse at the front line," she adds. "There are boys and girls on the front line who suffer much, much more. </p></div><div data-testid="ad-unit" data-component="ad-slot" class="sc-1b734f04-0 kNNIux"><div data-testid="dotcom-mid_8" id="dotcom-mid_8" class="dotcom-ad"></div></div><figure><div data-component="image-block" class="sc-3b6b161a-0 gXrNRM"><div data-testid="image" class="sc-5340b511-1 cMIbKV"><img srcset="https://ichef.bbci.co.uk/news/240/cpsprodpb/341f/live/2891b040-bff3-11f0-8669-5560f5c90fbe.png.webp 240w, https://ichef.bbci.co.uk/news/320/cpsprodpb/341f/live/2891b040-bff3-11f0-8669-5560f5c90fbe.png.webp 320w, https://ichef.bbci.co.uk/news/480/cpsprodpb/341f/live/2891b040-bff3-11f0-8669-5560f5c90fbe.png.webp 480w, https://ichef.bbci.co.uk/news/640/cpsprodpb/341f/live/2891b040-bff3-11f0-8669-5560f5c90fbe.png.webp 640w, https://ichef.bbci.co.uk/news/800/cpsprodpb/341f/live/2891b040-bff3-11f0-8669-5560f5c90fbe.png.webp 800w, https://ichef.bbci.co.uk/news/1024/cpsprodpb/341f/live/2891b040-bff3-11f0-8669-5560f5c90fbe.png.webp 1024w, https://ichef.bbci.co.uk/news/1536/cpsprodpb/341f/live/2891b040-bff3-11f0-8669-5560f5c90fbe.png.webp 1536w" src="https://ichef.bbci.co.uk/news/480/cpsprodpb/341f/live/2891b040-bff3-11f0-8669-5560f5c90fbe.png.webp" alt="Oksana and her young daughter pictured playing with toys at home" class="sc-5340b511-0 hLdNfA" /></div></div><div data-component="caption-block" class="sc-3b6b161a-0 Qwxkf"></div></figure><div data-component="text-block" class="sc-3b6b161a-0 dPVOKT"><p class="sc-9a00e533-0 eZyhnA">"I understand my child should not be raised in these conditions, because it is not normal in the civilised world. But we can hold on for as long as the front needs it."</p></div><div data-testid="ad-unit" data-component="ad-slot" class="sc-1b734f04-0 kNNIux"><div data-testid="dotcom-mid_9" id="dotcom-mid_9" class="dotcom-ad"></div></div><div data-component="subheadline-block" class="sc-3b6b161a-0 hNbOGD"><h2 class="sc-f98b1ad2-0 gXmhTb">Putin wants a victory he can ''sell''</h2></div><div data-component="text-block" class="sc-3b6b161a-0 dPVOKT"><p class="sc-9a00e533-0 eZyhnA">Earlier this week, thick fog enabled Russian troops to move further into Prokrovsk. </p><p class="sc-9a00e533-0 eZyhnA">The news out of the city is bleak with daily reports of Russian advances. If it fell, it would be the first major city seized by Russia since Avdiivka in February 2024. </p><p class="sc-9a00e533-0 eZyhnA">But Russian forces would still only be about 25 miles (40km) from where they began their full scale invasion in 2022, land gained at the cost of hundreds of thousands of lives.</p><p class="sc-9a00e533-0 eZyhnA">Ukrainian President Volodymyr Zelensky says the Russian high command is throwing so much at Pokrovsk not just because it is tactically significant, but because Putin wants a victory he can "sell" diplomatically to the White House.</p></div><figure><div data-component="image-block" class="sc-3b6b161a-0 gXrNRM"><div data-testid="image" class="sc-5340b511-1 cMIbKV"><img srcset="https://ichef.bbci.co.uk/news/240/cpsprodpb/e330/live/a56fdc80-bfdb-11f0-ae46-bd64331f0fd4.jpg.webp 240w, https://ichef.bbci.co.uk/news/320/cpsprodpb/e330/live/a56fdc80-bfdb-11f0-ae46-bd64331f0fd4.jpg.webp 320w, https://ichef.bbci.co.uk/news/480/cpsprodpb/e330/live/a56fdc80-bfdb-11f0-ae46-bd64331f0fd4.jpg.webp 480w, https://ichef.bbci.co.uk/news/640/cpsprodpb/e330/live/a56fdc80-bfdb-11f0-ae46-bd64331f0fd4.jpg.webp 640w, https://ichef.bbci.co.uk/news/800/cpsprodpb/e330/live/a56fdc80-bfdb-11f0-ae46-bd64331f0fd4.jpg.webp 800w, https://ichef.bbci.co.uk/news/1024/cpsprodpb/e330/live/a56fdc80-bfdb-11f0-ae46-bd64331f0fd4.jpg.webp 1024w, https://ichef.bbci.co.uk/news/1536/cpsprodpb/e330/live/a56fdc80-bfdb-11f0-ae46-bd64331f0fd4.jpg.webp 1536w" src="https://ichef.bbci.co.uk/news/480/cpsprodpb/e330/live/a56fdc80-bfdb-11f0-ae46-bd64331f0fd4.jpg.webp" alt="Libkos/Getty Images A woman carries a sack of potatoes by damaged residential buildings in Pokrovsk, Ukraine" class="sc-5340b511-0 hLdNfA" /><span class="sc-5340b511-2 jVqbAn">Libkos/Getty Images</span></div></div><div data-component="caption-block" class="sc-3b6b161a-0 Qwxkf"></div></figure><div data-testid="ad-unit" data-component="ad-slot" class="sc-1b734f04-0 kNNIux"><div data-testid="dotcom-mid_10" id="dotcom-mid_10" class="dotcom-ad"></div></div><div data-component="text-block" class="sc-3b6b161a-0 dPVOKT"><p class="sc-9a00e533-0 eZyhnA">The Russians hope to convince President Trump they are making battlefield gains that will put pressure on Kyiv to sue for peace.</p><p class="sc-9a00e533-0 eZyhnA">Vadym Prystaiko, Ukraine''s former foreign minister and ambassador in London, said Russia wanted to "force this feeling among Europe and westerners – as Russian propagandists have done before – that you can''t do anything with Russia, you can''t defeat Mother Russia. </p><p class="sc-9a00e533-0 eZyhnA">"They hope that our partners will force us to lose face and sign the Russian deal, whatever that is."</p><p class="sc-9a00e533-0 eZyhnA">When I asked President Zelensky if his people could survive the coming winter at a recent press conference, he was clear about the scale of the challenge.</p><p class="sc-9a00e533-0 eZyhnA">"I don''t know what winter will be but we have to prepare in any case," he answered. </p><p class="sc-9a00e533-0 eZyhnA">"We understand what we have to do, we understand what we need and our partners also know from us what, in the case of difficulties, what volume of electricity we have to import."</p></div><figure><div data-component="image-block" class="sc-3b6b161a-0 GunZh"><div data-testid="image" class="sc-5340b511-1 cMIbKV"><img srcset="https://ichef.bbci.co.uk/news/240/cpsprodpb/60c2/live/b1fd72b0-bfad-11f0-8456-eff94716b162.png.webp 240w, https://ichef.bbci.co.uk/news/320/cpsprodpb/60c2/live/b1fd72b0-bfad-11f0-8456-eff94716b162.png.webp 320w, https://ichef.bbci.co.uk/news/480/cpsprodpb/60c2/live/b1fd72b0-bfad-11f0-8456-eff94716b162.png.webp 480w, https://ichef.bbci.co.uk/news/640/cpsprodpb/60c2/live/b1fd72b0-bfad-11f0-8456-eff94716b162.png.webp 640w, https://ichef.bbci.co.uk/news/800/cpsprodpb/60c2/live/b1fd72b0-bfad-11f0-8456-eff94716b162.png.webp 800w, https://ichef.bbci.co.uk/news/1024/cpsprodpb/60c2/live/b1fd72b0-bfad-11f0-8456-eff94716b162.png.webp 1024w, https://ichef.bbci.co.uk/news/1536/cpsprodpb/60c2/live/b1fd72b0-bfad-11f0-8456-eff94716b162.png.webp 1536w" src="https://ichef.bbci.co.uk/news/480/cpsprodpb/60c2/live/b1fd72b0-bfad-11f0-8456-eff94716b162.png.webp" alt="A map showing where there is Russian military control" class="sc-5340b511-0 hLdNfA" /></div></div></figure><div data-testid="ad-unit" data-component="ad-slot" class="sc-1b734f04-0 kNNIux"><div data-testid="dotcom-mid_11" id="dotcom-mid_11" class="dotcom-ad"></div></div><div data-component="text-block" class="sc-3b6b161a-0 dPVOKT"><p class="sc-9a00e533-0 eZyhnA">Ukraine imports gas from across Europe, including Poland, Hungary, and Slovakia. But it also has massive storage facilities which Russia could target.</p><p class="sc-9a00e533-0 eZyhnA">Oleksandr Kharchenko, director of the Energy Industry Research Centre, says Ukraine is well placed to protect its energy supply from Russian attacks. "We are better trained, we know how to act, we have no panic," he says.</p><p class="sc-9a00e533-0 eZyhnA">"We have an understanding of what to do if something is damaged. It will be complicated, it will be a hard winter, there will be a lot of outages but it will be manageable."</p></div><div data-component="subheadline-block" class="sc-3b6b161a-0 hNbOGD"><h2 class="sc-f98b1ad2-0 gXmhTb">War fatigue versus strategic patience</h2></div><div data-component="text-block" class="sc-3b6b161a-0 dPVOKT"><p class="sc-9a00e533-0 eZyhnA">Ukraine''s prime minister is confident. Yulia Svyrydenko said Russia''s goal was "to plunge Ukraine into darkness. Ours is to preserve the light."</p><p class="sc-9a00e533-0 eZyhnA">Nonetheless, this may be harder to achieve if Trump focuses on other matters and turns his attention away from Ukraine - likewise if European voters elect governments that are less supportive of Kyiv and cannot wean themselves off Russian energy. </p></div><div data-testid="ad-unit" data-component="ad-slot" class="sc-1b734f04-0 kNNIux"><div data-testid="dotcom-mid_12" id="dotcom-mid_12" class="dotcom-ad"></div></div><figure><div data-component="image-block" class="sc-3b6b161a-0 gXrNRM"><div data-testid="image" class="sc-5340b511-1 cMIbKV"><img srcset="https://ichef.bbci.co.uk/news/240/cpsprodpb/c490/live/ac6ef020-bfdb-11f0-8456-eff94716b162.jpg.webp 240w, https://ichef.bbci.co.uk/news/320/cpsprodpb/c490/live/ac6ef020-bfdb-11f0-8456-eff94716b162.jpg.webp 320w, https://ichef.bbci.co.uk/news/480/cpsprodpb/c490/live/ac6ef020-bfdb-11f0-8456-eff94716b162.jpg.webp 480w, https://ichef.bbci.co.uk/news/640/cpsprodpb/c490/live/ac6ef020-bfdb-11f0-8456-eff94716b162.jpg.webp 640w, https://ichef.bbci.co.uk/news/800/cpsprodpb/c490/live/ac6ef020-bfdb-11f0-8456-eff94716b162.jpg.webp 800w, https://ichef.bbci.co.uk/news/1024/cpsprodpb/c490/live/ac6ef020-bfdb-11f0-8456-eff94716b162.jpg.webp 1024w, https://ichef.bbci.co.uk/news/1536/cpsprodpb/c490/live/ac6ef020-bfdb-11f0-8456-eff94716b162.jpg.webp 1536w" src="https://ichef.bbci.co.uk/news/480/cpsprodpb/c490/live/ac6ef020-bfdb-11f0-8456-eff94716b162.jpg.webp" alt="Oleh Tereshchenko / Ukrainian Ministry of Economy Yulia Svyrydenko, Ukraine''s First Deputy Prime Minister" class="sc-5340b511-0 hLdNfA" /><span class="sc-5340b511-2 jVqbAn">Oleh Tereshchenko / Ukrainian Ministry of Economy</span></div></div><div data-component="caption-block" class="sc-3b6b161a-0 Qwxkf"></div></figure><div data-component="text-block" class="sc-3b6b161a-0 dPVOKT"><p class="sc-9a00e533-0 eZyhnA">The danger is that war fatigue will overcome strategic patience.</p><p class="sc-9a00e533-0 eZyhnA">But for all the bleak realism of the official government source, even he remains confident. "This winter is the last opportunity for the Russians to defeat us," he said. "And if we make it to 1 April, we will win the war."</p><p class="sc-9a00e533-0 eZyhnA">I asked one western diplomat why Ukrainians were so unyielding. "They are just bloody-minded," the envoy said, and pointed to Ukraine''s long history of withstanding hardship. </p><p class="sc-9a00e533-0 eZyhnA">"They say they have survived the Germans, the Poles, the Turks, the Lithuanians and now they can survive the Russians."</p><p class="sc-9a00e533-0 eZyhnA">And yet for many in Ukraine, life is going on as usual - or as usual as it can. </p></div><div data-testid="ad-unit" data-component="ad-slot" class="sc-1b734f04-0 kNNIux"><div data-testid="dotcom-mid_13" id="dotcom-mid_13" class="dotcom-ad"></div></div><figure><div data-component="image-block" class="sc-3b6b161a-0 gXrNRM"><div data-testid="image" class="sc-5340b511-1 cMIbKV"><img srcset="https://ichef.bbci.co.uk/news/240/cpsprodpb/c6a2/live/a21b63c0-befe-11f0-ae46-bd64331f0fd4.png.webp 240w, https://ichef.bbci.co.uk/news/320/cpsprodpb/c6a2/live/a21b63c0-befe-11f0-ae46-bd64331f0fd4.png.webp 320w, https://ichef.bbci.co.uk/news/480/cpsprodpb/c6a2/live/a21b63c0-befe-11f0-ae46-bd64331f0fd4.png.webp 480w, https://ichef.bbci.co.uk/news/640/cpsprodpb/c6a2/live/a21b63c0-befe-11f0-ae46-bd64331f0fd4.png.webp 640w, https://ichef.bbci.co.uk/news/800/cpsprodpb/c6a2/live/a21b63c0-befe-11f0-ae46-bd64331f0fd4.png.webp 800w, https://ichef.bbci.co.uk/news/1024/cpsprodpb/c6a2/live/a21b63c0-befe-11f0-ae46-bd64331f0fd4.png.webp 1024w, https://ichef.bbci.co.uk/news/1536/cpsprodpb/c6a2/live/a21b63c0-befe-11f0-ae46-bd64331f0fd4.png.webp 1536w" src="https://ichef.bbci.co.uk/news/480/cpsprodpb/c6a2/live/a21b63c0-befe-11f0-ae46-bd64331f0fd4.png.webp" alt="Stuart Phillips/BBC People cheering at the football game" class="sc-5340b511-0 hLdNfA" /><span class="sc-5340b511-2 jVqbAn">Stuart Phillips/BBC</span></div></div><div data-component="caption-block" class="sc-3b6b161a-0 Qwxkf"></div></figure><div data-component="text-block" class="sc-3b6b161a-0 dPVOKT"><p class="sc-9a00e533-0 eZyhnA">At the Dynamo Stadium in Kyiv, floodlights are on full beam and a game of football is being played - Dynamo Kyiv versus Shakhtar Donetsk, a rough, partisan game, the hardcore fans, known as ultras, wear masks and chant at their opponents.</p><p class="sc-9a00e533-0 eZyhnA">One of the few signs that this is taking place in a city at war is the number of people there: the stadium can seat more than 16,000 people but only 4,300 fans are allowed in, owing to the capacity of the stadium''s bomb shelters. </p><p class="sc-9a00e533-0 eZyhnA">The fans have come from all parts of society – young and old, families and friends. Servicemen and women are there too, earning applause from the crowds, who part to let them pass through.</p></div><div data-testid="ad-unit" data-component="ad-slot" class="sc-1b734f04-0 kNNIux"><div data-testid="dotcom-mid_14" id="dotcom-mid_14" class="dotcom-ad"></div></div><figure><div data-component="image-block" class="sc-3b6b161a-0 gXrNRM"><div data-testid="image" class="sc-5340b511-1 cMIbKV"><img srcset="https://ichef.bbci.co.uk/news/240/cpsprodpb/a8db/live/c882c7d0-bfe7-11f0-8669-5560f5c90fbe.png.webp 240w, https://ichef.bbci.co.uk/news/320/cpsprodpb/a8db/live/c882c7d0-bfe7-11f0-8669-5560f5c90fbe.png.webp 320w, https://ichef.bbci.co.uk/news/480/cpsprodpb/a8db/live/c882c7d0-bfe7-11f0-8669-5560f5c90fbe.png.webp 480w, https://ichef.bbci.co.uk/news/640/cpsprodpb/a8db/live/c882c7d0-bfe7-11f0-8669-5560f5c90fbe.png.webp 640w, https://ichef.bbci.co.uk/news/800/cpsprodpb/a8db/live/c882c7d0-bfe7-11f0-8669-5560f5c90fbe.png.webp 800w, https://ichef.bbci.co.uk/news/1024/cpsprodpb/a8db/live/c882c7d0-bfe7-11f0-8669-5560f5c90fbe.png.webp 1024w, https://ichef.bbci.co.uk/news/1536/cpsprodpb/a8db/live/c882c7d0-bfe7-11f0-8669-5560f5c90fbe.png.webp 1536w" src="https://ichef.bbci.co.uk/news/480/cpsprodpb/a8db/live/c882c7d0-bfe7-11f0-8669-5560f5c90fbe.png.webp" alt="Stuart Phillips/BBC Rodion" class="sc-5340b511-0 hLdNfA" /><span class="sc-5340b511-2 jVqbAn">Stuart Phillips/BBC</span></div></div><div data-component="caption-block" class="sc-3b6b161a-0 Qwxkf"></div></figure><div data-component="text-block" class="sc-3b6b161a-0 dPVOKT"><p class="sc-9a00e533-0 eZyhnA">"It''s really important to continue to live," says Anatoliy Anatolich, the match announcer, a TV and social media host. </p><p class="sc-9a00e533-0 eZyhnA">In his view, coming to the football in itself is an act of defiance.</p><p class="sc-9a00e533-0 eZyhnA">"[It shows] everyone that we are not going to leave our country in this hard period… We''ve got to be here when we win."</p><p class="sc-9a00e533-0 eZyhnA">Five minutes before the end of the match, the chanting suddenly stops. The fans put their hands on their hearts and sing the national anthem.</p><p class="sc-9a00e533-0 eZyhnA">Soon the whole stadium was singing as one; a crowd divided by teams, but united by country.</p><p class="sc-9a00e533-0 eZyhnA"><i id="top-image-credit:-afp/getty-images" class="sc-d16436d-0 iVdNuz">Top image credit: AFP/Getty Images</i></p></div><div data-component="links-block" class="sc-3b6b161a-0 djqsWD"><div class="sc-666b6d83-0 sc-c4fb5674-0 jYmMqa doYqeg"><span data-testid="links-title" class="sc-c4fb5674-2 bBuHEW">More from InDepth</span><div data-testid="links-grid" class="sc-666b6d83-0 sc-c4fb5674-1 gEjRXC jkjVgq"><div data-testid="chester-card" data-indexcard="true" class="sc-225578b-0 ezQaGx"><div data-testid="anchor-inner-wrapper"><a href="https://www.bbc.co.uk/news/articles/cm2vr37yd4no" data-testid="external-anchor" target="_self" class="sc-8a623a54-0 huZCWi"><div data-testid="chester-article" class="sc-cf565bcc-0 kwPVOm"><div class="sc-fa814188-1 iRoJZi"><div class="sc-fa814188-0 hPhBqv"><h2 data-testid="card-headline" class="sc-fa814188-3 iCfgww">How Russia is quietly trying to win over the world beyond the West</h2></div></div></div></a></div></div><div data-testid="chester-card" data-indexcard="true" class="sc-225578b-0 ezQaGx"><div data-testid="anchor-inner-wrapper"><a href="https://www.bbc.co.uk/news/articles/c205jvyg3wjo" data-testid="external-anchor" target="_self" class="sc-8a623a54-0 huZCWi"><div data-testid="chester-article" class="sc-cf565bcc-0 kwPVOm"><div class="sc-fa814188-1 iRoJZi"><div class="sc-fa814188-0 hPhBqv"><h2 data-testid="card-headline" class="sc-fa814188-3 iCfgww">COP30: Trump and many leaders are skipping it, so does the summit still have a point?</h2></div></div></div></a></div></div><div data-testid="chester-card" data-indexcard="true" class="sc-225578b-0 ezQaGx"><div data-testid="anchor-inner-wrapper"><a href="https://www.bbc.co.uk/news/articles/cgeqj1q8gj4o" data-testid="external-anchor" target="_self" class="sc-8a623a54-0 huZCWi"><div data-testid="chester-article" class="sc-cf565bcc-0 kwPVOm"><div class="sc-fa814188-1 iRoJZi"><div class="sc-fa814188-0 hPhBqv"><h2 data-testid="card-headline" class="sc-fa814188-3 iCfgww">The race for the two miles-a-second super weapons that Putin says turn targets to dust</h2></div></div></div></a></div></div></div></div></div><figure><div data-component="image-block" class="sc-3b6b161a-0 GunZh"><div data-testid="image" class="sc-5340b511-1 cMIbKV"><img srcset="https://ichef.bbci.co.uk/news/240/cpsprodpb/5117/live/87b01450-a8eb-11f0-92db-77261a15b9d2.jpg.webp 240w, https://ichef.bbci.co.uk/news/320/cpsprodpb/5117/live/87b01450-a8eb-11f0-92db-77261a15b9d2.jpg.webp 320w, https://ichef.bbci.co.uk/news/480/cpsprodpb/5117/live/87b01450-a8eb-11f0-92db-77261a15b9d2.jpg.webp 480w, https://ichef.bbci.co.uk/news/640/cpsprodpb/5117/live/87b01450-a8eb-11f0-92db-77261a15b9d2.jpg.webp 640w, https://ichef.bbci.co.uk/news/800/cpsprodpb/5117/live/87b01450-a8eb-11f0-92db-77261a15b9d2.jpg.webp 800w, https://ichef.bbci.co.uk/news/1024/cpsprodpb/5117/live/87b01450-a8eb-11f0-92db-77261a15b9d2.jpg.webp 1024w, https://ichef.bbci.co.uk/news/1536/cpsprodpb/5117/live/87b01450-a8eb-11f0-92db-77261a15b9d2.jpg.webp 1536w" src="https://ichef.bbci.co.uk/news/480/cpsprodpb/5117/live/87b01450-a8eb-11f0-92db-77261a15b9d2.jpg.webp" alt="InDepth notifications banner" class="sc-5340b511-0 hLdNfA" /></div></div></figure><div data-component="text-block" class="sc-3b6b161a-0 dPVOKT"><p class="sc-9a00e533-0 eZyhnA"><a target="_self" href="https://www.bbc.co.uk/news/bbcindepth" class="sc-f9178328-0 iCaRzc"><i id="bbc-indepth" class="sc-d16436d-0 iVdNuz">BBC InDepth</i></a><i id="is-the-home-on-the-website-and-app-for-the-best-analysis,-with-fresh-perspectives-that-challenge-assumptions-and-deep-reporting-on-the-biggest-issues-of-the-day.-you-can-now-sign-up-for-notifications-that-will-alert-you-whenever-an-indepth-story-is-published--" class="sc-d16436d-0 iVdNuz"> is the home on the website and app for the best analysis, with fresh perspectives that challenge assumptions and deep reporting on the biggest issues of the day. You can now sign up for notifications that will alert you whenever an InDepth story is published - </i><a target="_self" href="https://www.bbc.co.uk/news/articles/cj6x46j8g5do" class="sc-f9178328-0 iCaRzc"><i id="click-here-to-find-out-how." class="sc-d16436d-0 iVdNuz">click here to find out how.</i></a></p></div><div data-component="tags" class="sc-3b6b161a-0 djqsWD"><div class="sc-6bf80075-0 lllwyY"><div data-testid="anchor-inner-wrapper"><a href="https://www.bbc.com/news/topics/c1vw6q14rzqt" data-testid="internal-link" class="sc-57521d02-0 jsVxCb">War in Ukraine</a></div><div data-testid="anchor-inner-wrapper"><a href="https://www.bbc.com/news/topics/c4vvr0ergrzt" data-testid="internal-link" class="sc-57521d02-0 jsVxCb">Volodymyr Zelensky</a></div><div data-testid="anchor-inner-wrapper"><a href="https://www.bbc.com/news/topics/ce1qrvlegnyt" data-testid="internal-link" class="sc-57521d02-0 jsVxCb">Russia</a></div><div data-testid="anchor-inner-wrapper"><a href="https://www.bbc.com/news/topics/cvenzmgywd4t" data-testid="internal-link" class="sc-57521d02-0 jsVxCb">Vladimir Putin</a></div><div data-testid="anchor-inner-wrapper"><a href="https://www.bbc.com/news/topics/cx1m7zg0gzdt" data-testid="internal-link" class="sc-57521d02-0 jsVxCb">Ukraine</a></div></div></div>', NULL, '<div data-component="headline-block" class="sc-3b6b161a-0 hNbOGD"><h1 class="sc-f98b1ad2-0 idLnWK">Russia’s attacks have ramped up - Ukraine is fighting to hold on through another winter</h1></div><div data-component="byline-block" class="sc-3b6b161a-0 dPVOKT"><div data-testid="byline-new" class="sc-7bfdb3c2-0 fYJjWP"><div class="sc-7bfdb3c2-1 jqWinX"><time datetime="2025-11-13T06:00:11.235Z" class="sc-7bfdb3c2-2 dQuPjg">2 hours ago</time><div class="sc-7bfdb3c2-3 dVvYwG"></div></div><span data-testid="byline-new-contributors" class="sc-7bfdb3c2-11 ljQVMv"><div data-testid="byline-new-contributors-contributor-0" class="sc-7bfdb3c2-5 xGeVU"><span class="sc-7bfdb3c2-6 gBqcVx"><img sizes="96vw" srcset="https://ichef.bbci.co.uk/news/240/cpsprodpb/f82a/live/a8fa9220-bee4-11f0-8669-5560f5c90fbe.png.webp 240w,https://ichef.bbci.co.uk/news/320/cpsprodpb/f82a/live/a8fa9220-bee4-11f0-8669-5560f5c90fbe.png.webp 320w,https://ichef.bbci.co.uk/news/480/cpsprodpb/f82a/live/a8fa9220-bee4-11f0-8669-5560f5c90fbe.png.webp 480w,https://ichef.bbci.co.uk/news/640/cpsprodpb/f82a/live/a8fa9220-bee4-11f0-8669-5560f5c90fbe.png.webp 640w,https://ichef.bbci.co.uk/news/800/cpsprodpb/f82a/live/a8fa9220-bee4-11f0-8669-5560f5c90fbe.png.webp 800w,https://ichef.bbci.co.uk/news/1024/cpsprodpb/f82a/live/a8fa9220-bee4-11f0-8669-5560f5c90fbe.png.webp 1024w,https://ichef.bbci.co.uk/news/1536/cpsprodpb/f82a/live/a8fa9220-bee4-11f0-8669-5560f5c90fbe.png.webp 1536w" src="https://ichef.bbci.co.uk/news/480/cpsprodpb/f82a/live/a8fa9220-bee4-11f0-8669-5560f5c90fbe.png.webp" loading="lazy" alt="James Landale profile image" class="sc-5340b511-0 hLdNfA"></span><div><span class="sc-7bfdb3c2-7 djOqvY">James Landale</span><span data-testid="byline-new-contributors-contributor-0-role-location" class="sc-7bfdb3c2-8 gvcwmG">Diplomatic Correspondent</span></div></div></span><div class="sc-7bfdb3c2-4 haycoC"></div></div></div><figure><div data-component="image-block" class="sc-3b6b161a-0 eRlINq"><div data-testid="hero-image" class="sc-5340b511-1 cMIbKV"><img sizes="(min-width: 1280px) 50vw, (min-width: 1008px) 66vw, 96vw" srcset="https://ichef.bbci.co.uk/news/240/cpsprodpb/cbc1/live/cce5d0a0-bfe3-11f0-8456-eff94716b162.jpg.webp 240w,https://ichef.bbci.co.uk/news/320/cpsprodpb/cbc1/live/cce5d0a0-bfe3-11f0-8456-eff94716b162.jpg.webp 320w,https://ichef.bbci.co.uk/news/480/cpsprodpb/cbc1/live/cce5d0a0-bfe3-11f0-8456-eff94716b162.jpg.webp 480w,https://ichef.bbci.co.uk/news/640/cpsprodpb/cbc1/live/cce5d0a0-bfe3-11f0-8456-eff94716b162.jpg.webp 640w,https://ichef.bbci.co.uk/news/800/cpsprodpb/cbc1/live/cce5d0a0-bfe3-11f0-8456-eff94716b162.jpg.webp 800w,https://ichef.bbci.co.uk/news/1024/cpsprodpb/cbc1/live/cce5d0a0-bfe3-11f0-8456-eff94716b162.jpg.webp 1024w,https://ichef.bbci.co.uk/news/1536/cpsprodpb/cbc1/live/cce5d0a0-bfe3-11f0-8456-eff94716b162.jpg.webp 1536w" src="https://ichef.bbci.co.uk/news/480/cpsprodpb/cbc1/live/cce5d0a0-bfe3-11f0-8456-eff94716b162.jpg.webp" loading="eager" alt="BBC A dual image of Russian President Vladimir Putin and flames at a thermal power plant in Ukraine" class="sc-5340b511-0 hLdNfA"><span class="sc-5340b511-2 jVqbAn">BBC</span></div></div></figure><div data-component="text-block" class="sc-3b6b161a-0 dPVOKT"><p class="sc-9a00e533-0 eZyhnA"><b id="in-her-soviet-era-apartment-block-on-the-outskirts-of-eastern-kyiv,-oksana-zinkovska-boyarska-lives-with-daily-power-cuts.-the-lift-to-her-eighth-floor-apartment-often-stops,-the-lights-go-out-and-sometimes-the-pumps-maintaining-pressure-in-the-gas-central-heating-fail." class="sc-d16436d-0 gnUCoQ">In her Soviet-era apartment block on the outskirts of eastern Kyiv, Oksana Zinkovska-Boyarska lives with daily power cuts. The lift to her eighth-floor apartment often stops, the lights go out and sometimes the pumps maintaining pressure in the gas central heating fail.</b></p><p class="sc-9a00e533-0 eZyhnA">She has a big rechargeable battery pack to keep appliances going, but it costs €2,000 (£1,770) and it only lasts so long. Her husband Ievgen, a lawyer, often has to work by torchlight. Their two-year-old daughter Katia plays by candlelight too.</p><p class="sc-9a00e533-0 eZyhnA">Amid air raids and cold darkness, Oksana says she and Ievgen worry constantly for Katia. "I can''t describe with words the animal fear when you take your child to the shelter during the explosions.</p><p class="sc-9a00e533-0 eZyhnA">"I have never felt anything like that in my life and I wouldn''t want anyone to feel anything like that. The thought that she might be scared because there''s no light - this is terrible."</p></div><div data-testid="ad-unit" data-component="ad-slot" class="sc-1b734f04-0 kNNIux"><div data-testid="dotcom-mid_1" id="dotcom-mid_1" class="dotcom-ad"></div></div><figure><div data-component="image-block" class="sc-3b6b161a-0 gXrNRM"><div data-testid="image" class="sc-5340b511-1 cMIbKV"><img sizes="(min-width: 1280px) 50vw, (min-width: 1008px) 66vw, 96vw" srcset="https://ichef.bbci.co.uk/news/240/cpsprodpb/dc40/live/d4c9f020-befe-11f0-8669-5560f5c90fbe.png.webp 240w,https://ichef.bbci.co.uk/news/320/cpsprodpb/dc40/live/d4c9f020-befe-11f0-8669-5560f5c90fbe.png.webp 320w,https://ichef.bbci.co.uk/news/480/cpsprodpb/dc40/live/d4c9f020-befe-11f0-8669-5560f5c90fbe.png.webp 480w,https://ichef.bbci.co.uk/news/640/cpsprodpb/dc40/live/d4c9f020-befe-11f0-8669-5560f5c90fbe.png.webp 640w,https://ichef.bbci.co.uk/news/800/cpsprodpb/dc40/live/d4c9f020-befe-11f0-8669-5560f5c90fbe.png.webp 800w,https://ichef.bbci.co.uk/news/1024/cpsprodpb/dc40/live/d4c9f020-befe-11f0-8669-5560f5c90fbe.png.webp 1024w,https://ichef.bbci.co.uk/news/1536/cpsprodpb/dc40/live/d4c9f020-befe-11f0-8669-5560f5c90fbe.png.webp 1536w" src="https://ichef.bbci.co.uk/news/480/cpsprodpb/dc40/live/d4c9f020-befe-11f0-8669-5560f5c90fbe.png.webp" loading="lazy" alt="Xavier Vanpevenaege/BBC Oksana Zinkovska-Boyarska carries her young child and a candle" class="sc-5340b511-0 hLdNfA"><span class="sc-5340b511-2 jVqbAn">Xavier Vanpevenaege/BBC</span></div></div><div data-component="caption-block" class="sc-3b6b161a-0 Qwxkf"></div></figure><div data-component="text-block" class="sc-3b6b161a-0 dPVOKT"><p class="sc-9a00e533-0 eZyhnA">All across Ukraine, families are bracing themselves for even tougher times ahead - a long, cold winter in which Russian President Vladimir Putin attempts to finish off his "special military operation" by striking Ukraine''s power supplies.</p><p class="sc-9a00e533-0 eZyhnA">Just last weekend, a massive drone and missile strike left much of the country for a time without power. Ukrainians are now enduring regular power cuts of up to 16 hours a day.</p><p class="sc-9a00e533-0 eZyhnA">In winter, temperatures in Ukraine can plummet as low as -20C. One senior government figure told me they expect the next few months to be brutal.</p><p class="sc-9a00e533-0 eZyhnA">"I think it will be the worst winter of our history," says the official. "Russia will destroy our energy, our infrastructure, our heating. All state institutions should be prepared for the worst scenario."</p><p class="sc-9a00e533-0 eZyhnA">Maxim Timchenko, the chief executive of DTEK, a large private energy company in Ukraine, says: "Based on the intensity of attacks for the past two months, it is clear Russia is aiming for the complete destruction of Ukraine''s energy system."</p></div><div data-testid="ad-unit" data-component="ad-slot" class="sc-1b734f04-0 kNNIux"><div data-testid="dotcom-mid_2" id="dotcom-mid_2" class="dotcom-ad"></div></div><figure><div data-component="image-block" class="sc-3b6b161a-0 gXrNRM"><div data-testid="image" class="sc-5340b511-1 cMIbKV"><img sizes="(min-width: 1280px) 50vw, (min-width: 1008px) 66vw, 96vw" srcset="https://ichef.bbci.co.uk/news/240/cpsprodpb/ad83/live/be14e9b0-bfdb-11f0-8456-eff94716b162.jpg.webp 240w,https://ichef.bbci.co.uk/news/320/cpsprodpb/ad83/live/be14e9b0-bfdb-11f0-8456-eff94716b162.jpg.webp 320w,https://ichef.bbci.co.uk/news/480/cpsprodpb/ad83/live/be14e9b0-bfdb-11f0-8456-eff94716b162.jpg.webp 480w,https://ichef.bbci.co.uk/news/640/cpsprodpb/ad83/live/be14e9b0-bfdb-11f0-8456-eff94716b162.jpg.webp 640w,https://ichef.bbci.co.uk/news/800/cpsprodpb/ad83/live/be14e9b0-bfdb-11f0-8456-eff94716b162.jpg.webp 800w,https://ichef.bbci.co.uk/news/1024/cpsprodpb/ad83/live/be14e9b0-bfdb-11f0-8456-eff94716b162.jpg.webp 1024w,https://ichef.bbci.co.uk/news/1536/cpsprodpb/ad83/live/be14e9b0-bfdb-11f0-8456-eff94716b162.jpg.webp 1536w" src="https://ichef.bbci.co.uk/news/480/cpsprodpb/ad83/live/be14e9b0-bfdb-11f0-8456-eff94716b162.jpg.webp" loading="lazy" alt="AFP via Getty Images A resident in a shop during a partial blackout " class="sc-5340b511-0 hLdNfA"><span class="sc-5340b511-2 jVqbAn">AFP via Getty Images</span></div></div><div data-component="caption-block" class="sc-3b6b161a-0 Qwxkf"></div></figure><div data-component="text-block" class="sc-3b6b161a-0 dPVOKT"><p class="sc-9a00e533-0 eZyhnA">But according to one European envoy, it''s not just about people being cold at night or without light - there is more to Russia''s strategy.</p><p class="sc-9a00e533-0 eZyhnA">"[This] is also about them not getting any bread from the bakery in the morning and not being able to go to work because there is no power for the factory," says the envoy.</p><p class="sc-9a00e533-0 eZyhnA">As the official puts it: "The goal of the Russians is to kill our economy."</p><p class="sc-9a00e533-0 eZyhnA">So how exactly will this warfare tactic play out? And given that almost four years of war have taken their toll, what does the increasing use of this weapon in the war of attrition mean for Ukraine''s people - and the endpoint of this long, hard war?</p></div><div data-testid="ad-unit" data-component="ad-slot" class="sc-1b734f04-0 kNNIux"><div data-testid="dotcom-mid_3" id="dotcom-mid_3" class="dotcom-ad"></div></div><div data-component="subheadline-block" class="sc-3b6b161a-0 hNbOGD"><h2 class="sc-f98b1ad2-0 gXmhTb">Frozen assets and suspended diplomacy</h2></div><div data-component="text-block" class="sc-3b6b161a-0 dPVOKT"><p class="sc-9a00e533-0 eZyhnA">On the front line, the news is bleak. There are growing signs that the key eastern city of Pokrovsk may fall, giving Russian forces a boost in morale and a fresh platform to seize more of the Donetsk region.</p><p class="sc-9a00e533-0 eZyhnA">What''s more, for now, diplomatic efforts to end the war appear to be on hold.</p></div><figure><div data-component="image-block" class="sc-3b6b161a-0 gXrNRM"><div data-testid="image" class="sc-5340b511-1 cMIbKV"><img sizes="(min-width: 1280px) 50vw, (min-width: 1008px) 66vw, 96vw" srcset="https://ichef.bbci.co.uk/news/240/cpsprodpb/9fce/live/c51f20e0-bfdb-11f0-8456-eff94716b162.jpg.webp 240w,https://ichef.bbci.co.uk/news/320/cpsprodpb/9fce/live/c51f20e0-bfdb-11f0-8456-eff94716b162.jpg.webp 320w,https://ichef.bbci.co.uk/news/480/cpsprodpb/9fce/live/c51f20e0-bfdb-11f0-8456-eff94716b162.jpg.webp 480w,https://ichef.bbci.co.uk/news/640/cpsprodpb/9fce/live/c51f20e0-bfdb-11f0-8456-eff94716b162.jpg.webp 640w,https://ichef.bbci.co.uk/news/800/cpsprodpb/9fce/live/c51f20e0-bfdb-11f0-8456-eff94716b162.jpg.webp 800w,https://ichef.bbci.co.uk/news/1024/cpsprodpb/9fce/live/c51f20e0-bfdb-11f0-8456-eff94716b162.jpg.webp 1024w,https://ichef.bbci.co.uk/news/1536/cpsprodpb/9fce/live/c51f20e0-bfdb-11f0-8456-eff94716b162.jpg.webp 1536w" src="https://ichef.bbci.co.uk/news/480/cpsprodpb/9fce/live/c51f20e0-bfdb-11f0-8456-eff94716b162.jpg.webp" loading="lazy" alt="Global Images Ukraine via Getty Images Ukrainian servicemen with firearms in the snow" class="sc-5340b511-0 hLdNfA"><span class="sc-5340b511-2 jVqbAn">Global Images Ukraine via Getty Images</span></div></div><div data-component="caption-block" class="sc-3b6b161a-0 Qwxkf"></div></figure><div data-testid="ad-unit" data-component="ad-slot" class="sc-1b734f04-0 kNNIux"><div data-testid="dotcom-mid_4" id="dotcom-mid_4" class="dotcom-ad"></div></div><div data-component="text-block" class="sc-3b6b161a-0 dPVOKT"><p class="sc-9a00e533-0 eZyhnA">Talk of a summit between US President Donald Trump and Russia''s Vladimir Putin are on the back burner after Moscow refused to budge from its maximalist war aims and the US imposed sanctions on Russian oil and gas.</p><p class="sc-9a00e533-0 eZyhnA">"There is currently a pause," a Kremlin spokesman said this week, "the situation is stalled."</p><p class="sc-9a00e533-0 eZyhnA">All the while, European nations deliberate over what to do with €180bn (£160bn) in frozen Russian assets. They plan to use the cash to raise a so-called "repatriation loan" for Ukraine, repaid only if Russia ever pays reparations after the end of the war. </p><p class="sc-9a00e533-0 eZyhnA">But a row over how to share the risk has left Kyiv''s coffers looking distinctly bare.</p></div><figure><div data-component="image-block" class="sc-3b6b161a-0 gXrNRM"><div data-testid="image" class="sc-5340b511-1 cMIbKV"><img sizes="(min-width: 1280px) 50vw, (min-width: 1008px) 66vw, 96vw" srcset="https://ichef.bbci.co.uk/news/240/cpsprodpb/95ac/live/98e08af0-7120-11f0-8dbd-f3d32ebd3327.png.webp 240w,https://ichef.bbci.co.uk/news/320/cpsprodpb/95ac/live/98e08af0-7120-11f0-8dbd-f3d32ebd3327.png.webp 320w,https://ichef.bbci.co.uk/news/480/cpsprodpb/95ac/live/98e08af0-7120-11f0-8dbd-f3d32ebd3327.png.webp 480w,https://ichef.bbci.co.uk/news/640/cpsprodpb/95ac/live/98e08af0-7120-11f0-8dbd-f3d32ebd3327.png.webp 640w,https://ichef.bbci.co.uk/news/800/cpsprodpb/95ac/live/98e08af0-7120-11f0-8dbd-f3d32ebd3327.png.webp 800w,https://ichef.bbci.co.uk/news/1024/cpsprodpb/95ac/live/98e08af0-7120-11f0-8dbd-f3d32ebd3327.png.webp 1024w,https://ichef.bbci.co.uk/news/1536/cpsprodpb/95ac/live/98e08af0-7120-11f0-8dbd-f3d32ebd3327.png.webp 1536w" src="https://ichef.bbci.co.uk/news/480/cpsprodpb/95ac/live/98e08af0-7120-11f0-8dbd-f3d32ebd3327.png.webp" loading="lazy" alt="REUTERS/Kevin Lamarque U.S. President Donald Trump and Russia''s President Vladimir Putin shake hands during a joint news conference " class="sc-5340b511-0 hLdNfA"><span class="sc-5340b511-2 jVqbAn">REUTERS/Kevin Lamarque</span></div></div><div data-component="caption-block" class="sc-3b6b161a-0 Qwxkf"></div></figure><div data-testid="ad-unit" data-component="ad-slot" class="sc-1b734f04-0 kNNIux"><div data-testid="dotcom-mid_5" id="dotcom-mid_5" class="dotcom-ad"></div></div><div data-component="text-block" class="sc-3b6b161a-0 dPVOKT"><p class="sc-9a00e533-0 eZyhnA">Yet it is the energy crisis that is worrying the Ukrainian government most, according to those I spoke to. "People are tired after four years of the war," the official tells me.</p><p class="sc-9a00e533-0 eZyhnA">"I am afraid they will be demotivated."</p></div><div data-component="subheadline-block" class="sc-3b6b161a-0 hNbOGD"><h2 class="sc-f98b1ad2-0 gXmhTb">Insomnia, missiles and shifting morale</h2></div><div data-component="text-block" class="sc-3b6b161a-0 dPVOKT"><p class="sc-9a00e533-0 eZyhnA">Walk the streets of Kyiv and you''ll pass a sea of tired faces - people''s eyes are red from a lack of sleep, their rest broken by the air raid sirens.</p><p class="sc-9a00e533-0 eZyhnA">"I am tired of not sleeping enough," says Yana Kolomiets, 31, a casting director from Odesa. "But... people who fight on the front line are tired [too]."</p><p class="sc-9a00e533-0 eZyhnA">A recent scientific study suggested that people are three times more likely to suffer from insomnia in Ukraine than in countries at peace. </p><p class="sc-9a00e533-0 eZyhnA">It tracked the sleep patterns of around 100 Ukrainians over six months, and found the insomnia persisted even on quiet nights. (The research was published by Texty, a data journalism website based in Ukraine.)</p><p class="sc-9a00e533-0 eZyhnA">There have not been many quiet nights. Russia launched vast numbers of ballistic missiles at Ukraine in October - some 268 in all, the highest monthly total since the full-scale invasion, according to analysis published by the Oboz news site. The same month Russia launched 5,298 Shahed and other bomber drones.</p></div><div data-testid="ad-unit" data-component="ad-slot" class="sc-1b734f04-0 kNNIux"><div data-testid="dotcom-mid_6" id="dotcom-mid_6" class="dotcom-ad"></div></div><figure><div data-component="image-block" class="sc-3b6b161a-0 gXrNRM"><div data-testid="image" class="sc-5340b511-1 cMIbKV"><img sizes="(min-width: 1280px) 50vw, (min-width: 1008px) 66vw, 96vw" srcset="https://ichef.bbci.co.uk/news/240/cpsprodpb/b984/live/8a9d2270-bff2-11f0-8669-5560f5c90fbe.jpg.webp 240w,https://ichef.bbci.co.uk/news/320/cpsprodpb/b984/live/8a9d2270-bff2-11f0-8669-5560f5c90fbe.jpg.webp 320w,https://ichef.bbci.co.uk/news/480/cpsprodpb/b984/live/8a9d2270-bff2-11f0-8669-5560f5c90fbe.jpg.webp 480w,https://ichef.bbci.co.uk/news/640/cpsprodpb/b984/live/8a9d2270-bff2-11f0-8669-5560f5c90fbe.jpg.webp 640w,https://ichef.bbci.co.uk/news/800/cpsprodpb/b984/live/8a9d2270-bff2-11f0-8669-5560f5c90fbe.jpg.webp 800w,https://ichef.bbci.co.uk/news/1024/cpsprodpb/b984/live/8a9d2270-bff2-11f0-8669-5560f5c90fbe.jpg.webp 1024w,https://ichef.bbci.co.uk/news/1536/cpsprodpb/b984/live/8a9d2270-bff2-11f0-8669-5560f5c90fbe.jpg.webp 1536w" src="https://ichef.bbci.co.uk/news/480/cpsprodpb/b984/live/8a9d2270-bff2-11f0-8669-5560f5c90fbe.jpg.webp" loading="lazy" alt="Getty Images People stand near graves during memorial services at the Lychakiv military cemetery in Lviv, Ukraine (2024)" class="sc-5340b511-0 hLdNfA"><span class="sc-5340b511-2 jVqbAn">Getty Images</span></div></div><div data-component="caption-block" class="sc-3b6b161a-0 Qwxkf"></div></figure><div data-component="text-block" class="sc-3b6b161a-0 dPVOKT"><p class="sc-9a00e533-0 eZyhnA">Diplomats suggest there is a geographic focus to Russia''s tactics, their strikes deliberately targeting gas and electricity transmission networks in eastern Ukraine, rather than power stations in the west of the country.</p><p class="sc-9a00e533-0 eZyhnA">"They are trying to cut Ukraine in two in terms of energy," one European envoy says. "They want anywhere east of the river Dnipro to be cold this winter."</p><p class="sc-9a00e533-0 eZyhnA">The aim, one government source told me, is to "instigate an insurrection, so that people go against the government in Kyiv… they are trying to destroy social cohesion."</p><p class="sc-9a00e533-0 eZyhnA">So concerned is the United Nations Office for the Coordination of Humanitarian Affairs it has already issued a formal warning, saying "the approaching winter poses new risks for Ukrainians... as intensified attacks on energy networks undermine efforts to maintain warmth in homes, schools and health centres".</p></div><div data-testid="ad-unit" data-component="ad-slot" class="sc-1b734f04-0 kNNIux"><div data-testid="dotcom-mid_7" id="dotcom-mid_7" class="dotcom-ad"></div></div><figure><div data-component="image-block" class="sc-3b6b161a-0 gXrNRM"><div data-testid="image" class="sc-5340b511-1 cMIbKV"><img sizes="(min-width: 1280px) 50vw, (min-width: 1008px) 66vw, 96vw" srcset="https://ichef.bbci.co.uk/news/240/cpsprodpb/3899/live/d197e0a0-bfdb-11f0-8456-eff94716b162.jpg.webp 240w,https://ichef.bbci.co.uk/news/320/cpsprodpb/3899/live/d197e0a0-bfdb-11f0-8456-eff94716b162.jpg.webp 320w,https://ichef.bbci.co.uk/news/480/cpsprodpb/3899/live/d197e0a0-bfdb-11f0-8456-eff94716b162.jpg.webp 480w,https://ichef.bbci.co.uk/news/640/cpsprodpb/3899/live/d197e0a0-bfdb-11f0-8456-eff94716b162.jpg.webp 640w,https://ichef.bbci.co.uk/news/800/cpsprodpb/3899/live/d197e0a0-bfdb-11f0-8456-eff94716b162.jpg.webp 800w,https://ichef.bbci.co.uk/news/1024/cpsprodpb/3899/live/d197e0a0-bfdb-11f0-8456-eff94716b162.jpg.webp 1024w,https://ichef.bbci.co.uk/news/1536/cpsprodpb/3899/live/d197e0a0-bfdb-11f0-8456-eff94716b162.jpg.webp 1536w" src="https://ichef.bbci.co.uk/news/480/cpsprodpb/3899/live/d197e0a0-bfdb-11f0-8456-eff94716b162.jpg.webp" loading="lazy" alt="Getty Images The memorial at Maidan Square honoring Ukrainian and foreign soldiers is covered in fresh snow" class="sc-5340b511-0 hLdNfA"><span class="sc-5340b511-2 jVqbAn">Getty Images</span></div></div><div data-component="caption-block" class="sc-3b6b161a-0 Qwxkf"></div></figure><div data-component="text-block" class="sc-3b6b161a-0 dPVOKT"><p class="sc-9a00e533-0 eZyhnA">Uncertainty over the outcome of the various diplomatic initiatives hasn''t helped, either.</p><p class="sc-9a00e533-0 eZyhnA">And yet opinion polls suggest people in Ukraine may in fact be more hopeful, not less. </p><p class="sc-9a00e533-0 eZyhnA">Research by the Kyiv International Institute of Sociology, a pollster, suggested that in October 56% of 1,008 Ukrainians interviewed felt optimistic about the country''s future, up from 43% in May.</p><p class="sc-9a00e533-0 eZyhnA">Sasha, a Kyiv-based financier, explains that Ukrainian morale is volatile, swinging wildly between optimism and pessimism.</p><p class="sc-9a00e533-0 eZyhnA">"If people talk about an end to the war, they feel hopeful," he says. "But then when the talks fail, they despair."</p><p class="sc-9a00e533-0 eZyhnA">Oksana, though, is pragmatic: she says that for all the fears for her daughter, they have no choice but to endure it. </p><p class="sc-9a00e533-0 eZyhnA">"I always think it is much worse at the front line," she adds. "There are boys and girls on the front line who suffer much, much more. </p></div><div data-testid="ad-unit" data-component="ad-slot" class="sc-1b734f04-0 kNNIux"><div data-testid="dotcom-mid_8" id="dotcom-mid_8" class="dotcom-ad"></div></div><figure><div data-component="image-block" class="sc-3b6b161a-0 gXrNRM"><div data-testid="image" class="sc-5340b511-1 cMIbKV"><img sizes="(min-width: 1280px) 50vw, (min-width: 1008px) 66vw, 96vw" srcset="https://ichef.bbci.co.uk/news/240/cpsprodpb/341f/live/2891b040-bff3-11f0-8669-5560f5c90fbe.png.webp 240w,https://ichef.bbci.co.uk/news/320/cpsprodpb/341f/live/2891b040-bff3-11f0-8669-5560f5c90fbe.png.webp 320w,https://ichef.bbci.co.uk/news/480/cpsprodpb/341f/live/2891b040-bff3-11f0-8669-5560f5c90fbe.png.webp 480w,https://ichef.bbci.co.uk/news/640/cpsprodpb/341f/live/2891b040-bff3-11f0-8669-5560f5c90fbe.png.webp 640w,https://ichef.bbci.co.uk/news/800/cpsprodpb/341f/live/2891b040-bff3-11f0-8669-5560f5c90fbe.png.webp 800w,https://ichef.bbci.co.uk/news/1024/cpsprodpb/341f/live/2891b040-bff3-11f0-8669-5560f5c90fbe.png.webp 1024w,https://ichef.bbci.co.uk/news/1536/cpsprodpb/341f/live/2891b040-bff3-11f0-8669-5560f5c90fbe.png.webp 1536w" src="https://ichef.bbci.co.uk/news/480/cpsprodpb/341f/live/2891b040-bff3-11f0-8669-5560f5c90fbe.png.webp" loading="lazy" alt="Oksana and her young daughter pictured playing with toys at home" class="sc-5340b511-0 hLdNfA"></div></div><div data-component="caption-block" class="sc-3b6b161a-0 Qwxkf"></div></figure><div data-component="text-block" class="sc-3b6b161a-0 dPVOKT"><p class="sc-9a00e533-0 eZyhnA">"I understand my child should not be raised in these conditions, because it is not normal in the civilised world. But we can hold on for as long as the front needs it."</p></div><div data-testid="ad-unit" data-component="ad-slot" class="sc-1b734f04-0 kNNIux"><div data-testid="dotcom-mid_9" id="dotcom-mid_9" class="dotcom-ad"></div></div><div data-component="subheadline-block" class="sc-3b6b161a-0 hNbOGD"><h2 class="sc-f98b1ad2-0 gXmhTb">Putin wants a victory he can ''sell''</h2></div><div data-component="text-block" class="sc-3b6b161a-0 dPVOKT"><p class="sc-9a00e533-0 eZyhnA">Earlier this week, thick fog enabled Russian troops to move further into Prokrovsk. </p><p class="sc-9a00e533-0 eZyhnA">The news out of the city is bleak with daily reports of Russian advances. If it fell, it would be the first major city seized by Russia since Avdiivka in February 2024. </p><p class="sc-9a00e533-0 eZyhnA">But Russian forces would still only be about 25 miles (40km) from where they began their full scale invasion in 2022, land gained at the cost of hundreds of thousands of lives.</p><p class="sc-9a00e533-0 eZyhnA">Ukrainian President Volodymyr Zelensky says the Russian high command is throwing so much at Pokrovsk not just because it is tactically significant, but because Putin wants a victory he can "sell" diplomatically to the White House.</p></div><figure><div data-component="image-block" class="sc-3b6b161a-0 gXrNRM"><div data-testid="image" class="sc-5340b511-1 cMIbKV"><img sizes="(min-width: 1280px) 50vw, (min-width: 1008px) 66vw, 96vw" srcset="https://ichef.bbci.co.uk/news/240/cpsprodpb/e330/live/a56fdc80-bfdb-11f0-ae46-bd64331f0fd4.jpg.webp 240w,https://ichef.bbci.co.uk/news/320/cpsprodpb/e330/live/a56fdc80-bfdb-11f0-ae46-bd64331f0fd4.jpg.webp 320w,https://ichef.bbci.co.uk/news/480/cpsprodpb/e330/live/a56fdc80-bfdb-11f0-ae46-bd64331f0fd4.jpg.webp 480w,https://ichef.bbci.co.uk/news/640/cpsprodpb/e330/live/a56fdc80-bfdb-11f0-ae46-bd64331f0fd4.jpg.webp 640w,https://ichef.bbci.co.uk/news/800/cpsprodpb/e330/live/a56fdc80-bfdb-11f0-ae46-bd64331f0fd4.jpg.webp 800w,https://ichef.bbci.co.uk/news/1024/cpsprodpb/e330/live/a56fdc80-bfdb-11f0-ae46-bd64331f0fd4.jpg.webp 1024w,https://ichef.bbci.co.uk/news/1536/cpsprodpb/e330/live/a56fdc80-bfdb-11f0-ae46-bd64331f0fd4.jpg.webp 1536w" src="https://ichef.bbci.co.uk/news/480/cpsprodpb/e330/live/a56fdc80-bfdb-11f0-ae46-bd64331f0fd4.jpg.webp" loading="lazy" alt="Libkos/Getty Images A woman carries a sack of potatoes by damaged residential buildings in Pokrovsk, Ukraine
" class="sc-5340b511-0 hLdNfA"><span class="sc-5340b511-2 jVqbAn">Libkos/Getty Images</span></div></div><div data-component="caption-block" class="sc-3b6b161a-0 Qwxkf"></div></figure><div data-testid="ad-unit" data-component="ad-slot" class="sc-1b734f04-0 kNNIux"><div data-testid="dotcom-mid_10" id="dotcom-mid_10" class="dotcom-ad"></div></div><div data-component="text-block" class="sc-3b6b161a-0 dPVOKT"><p class="sc-9a00e533-0 eZyhnA">The Russians hope to convince President Trump they are making battlefield gains that will put pressure on Kyiv to sue for peace.</p><p class="sc-9a00e533-0 eZyhnA">Vadym Prystaiko, Ukraine''s former foreign minister and ambassador in London, said Russia wanted to "force this feeling among Europe and westerners – as Russian propagandists have done before – that you can''t do anything with Russia, you can''t defeat Mother Russia. </p><p class="sc-9a00e533-0 eZyhnA">"They hope that our partners will force us to lose face and sign the Russian deal, whatever that is."</p><p class="sc-9a00e533-0 eZyhnA">When I asked President Zelensky if his people could survive the coming winter at a recent press conference, he was clear about the scale of the challenge.</p><p class="sc-9a00e533-0 eZyhnA">"I don''t know what winter will be but we have to prepare in any case," he answered. </p><p class="sc-9a00e533-0 eZyhnA">"We understand what we have to do, we understand what we need and our partners also know from us what, in the case of difficulties, what volume of electricity we have to import."</p></div><figure><div data-component="image-block" class="sc-3b6b161a-0 GunZh"><div data-testid="image" class="sc-5340b511-1 cMIbKV"><img sizes="(min-width: 1280px) 50vw, (min-width: 1008px) 66vw, 96vw" srcset="https://ichef.bbci.co.uk/news/240/cpsprodpb/60c2/live/b1fd72b0-bfad-11f0-8456-eff94716b162.png.webp 240w,https://ichef.bbci.co.uk/news/320/cpsprodpb/60c2/live/b1fd72b0-bfad-11f0-8456-eff94716b162.png.webp 320w,https://ichef.bbci.co.uk/news/480/cpsprodpb/60c2/live/b1fd72b0-bfad-11f0-8456-eff94716b162.png.webp 480w,https://ichef.bbci.co.uk/news/640/cpsprodpb/60c2/live/b1fd72b0-bfad-11f0-8456-eff94716b162.png.webp 640w,https://ichef.bbci.co.uk/news/800/cpsprodpb/60c2/live/b1fd72b0-bfad-11f0-8456-eff94716b162.png.webp 800w,https://ichef.bbci.co.uk/news/1024/cpsprodpb/60c2/live/b1fd72b0-bfad-11f0-8456-eff94716b162.png.webp 1024w,https://ichef.bbci.co.uk/news/1536/cpsprodpb/60c2/live/b1fd72b0-bfad-11f0-8456-eff94716b162.png.webp 1536w" src="https://ichef.bbci.co.uk/news/480/cpsprodpb/60c2/live/b1fd72b0-bfad-11f0-8456-eff94716b162.png.webp" loading="lazy" alt="A map showing where there is Russian military control " class="sc-5340b511-0 hLdNfA"></div></div></figure><div data-testid="ad-unit" data-component="ad-slot" class="sc-1b734f04-0 kNNIux"><div data-testid="dotcom-mid_11" id="dotcom-mid_11" class="dotcom-ad"></div></div><div data-component="text-block" class="sc-3b6b161a-0 dPVOKT"><p class="sc-9a00e533-0 eZyhnA">Ukraine imports gas from across Europe, including Poland, Hungary, and Slovakia. But it also has massive storage facilities which Russia could target.</p><p class="sc-9a00e533-0 eZyhnA">Oleksandr Kharchenko, director of the Energy Industry Research Centre, says Ukraine is well placed to protect its energy supply from Russian attacks. "We are better trained, we know how to act, we have no panic," he says.</p><p class="sc-9a00e533-0 eZyhnA">"We have an understanding of what to do if something is damaged. It will be complicated, it will be a hard winter, there will be a lot of outages but it will be manageable."</p></div><div data-component="subheadline-block" class="sc-3b6b161a-0 hNbOGD"><h2 class="sc-f98b1ad2-0 gXmhTb">War fatigue versus strategic patience</h2></div><div data-component="text-block" class="sc-3b6b161a-0 dPVOKT"><p class="sc-9a00e533-0 eZyhnA">Ukraine''s prime minister is confident. Yulia Svyrydenko said Russia''s goal was "to plunge Ukraine into darkness. Ours is to preserve the light."</p><p class="sc-9a00e533-0 eZyhnA">Nonetheless, this may be harder to achieve if Trump focuses on other matters and turns his attention away from Ukraine - likewise if European voters elect governments that are less supportive of Kyiv and cannot wean themselves off Russian energy. </p></div><div data-testid="ad-unit" data-component="ad-slot" class="sc-1b734f04-0 kNNIux"><div data-testid="dotcom-mid_12" id="dotcom-mid_12" class="dotcom-ad"></div></div><figure><div data-component="image-block" class="sc-3b6b161a-0 gXrNRM"><div data-testid="image" class="sc-5340b511-1 cMIbKV"><img sizes="(min-width: 1280px) 50vw, (min-width: 1008px) 66vw, 96vw" srcset="https://ichef.bbci.co.uk/news/240/cpsprodpb/c490/live/ac6ef020-bfdb-11f0-8456-eff94716b162.jpg.webp 240w,https://ichef.bbci.co.uk/news/320/cpsprodpb/c490/live/ac6ef020-bfdb-11f0-8456-eff94716b162.jpg.webp 320w,https://ichef.bbci.co.uk/news/480/cpsprodpb/c490/live/ac6ef020-bfdb-11f0-8456-eff94716b162.jpg.webp 480w,https://ichef.bbci.co.uk/news/640/cpsprodpb/c490/live/ac6ef020-bfdb-11f0-8456-eff94716b162.jpg.webp 640w,https://ichef.bbci.co.uk/news/800/cpsprodpb/c490/live/ac6ef020-bfdb-11f0-8456-eff94716b162.jpg.webp 800w,https://ichef.bbci.co.uk/news/1024/cpsprodpb/c490/live/ac6ef020-bfdb-11f0-8456-eff94716b162.jpg.webp 1024w,https://ichef.bbci.co.uk/news/1536/cpsprodpb/c490/live/ac6ef020-bfdb-11f0-8456-eff94716b162.jpg.webp 1536w" src="https://ichef.bbci.co.uk/news/480/cpsprodpb/c490/live/ac6ef020-bfdb-11f0-8456-eff94716b162.jpg.webp" loading="lazy" alt="Oleh Tereshchenko / Ukrainian Ministry of Economy Yulia Svyrydenko, Ukraine''s First Deputy Prime Minister" class="sc-5340b511-0 hLdNfA"><span class="sc-5340b511-2 jVqbAn">Oleh Tereshchenko / Ukrainian Ministry of Economy</span></div></div><div data-component="caption-block" class="sc-3b6b161a-0 Qwxkf"></div></figure><div data-component="text-block" class="sc-3b6b161a-0 dPVOKT"><p class="sc-9a00e533-0 eZyhnA">The danger is that war fatigue will overcome strategic patience.</p><p class="sc-9a00e533-0 eZyhnA">But for all the bleak realism of the official government source, even he remains confident. "This winter is the last opportunity for the Russians to defeat us," he said. "And if we make it to 1 April, we will win the war."</p><p class="sc-9a00e533-0 eZyhnA">I asked one western diplomat why Ukrainians were so unyielding. "They are just bloody-minded," the envoy said, and pointed to Ukraine''s long history of withstanding hardship. </p><p class="sc-9a00e533-0 eZyhnA">"They say they have survived the Germans, the Poles, the Turks, the Lithuanians and now they can survive the Russians."</p><p class="sc-9a00e533-0 eZyhnA">And yet for many in Ukraine, life is going on as usual - or as usual as it can. </p></div><div data-testid="ad-unit" data-component="ad-slot" class="sc-1b734f04-0 kNNIux"><div data-testid="dotcom-mid_13" id="dotcom-mid_13" class="dotcom-ad"></div></div><figure><div data-component="image-block" class="sc-3b6b161a-0 gXrNRM"><div data-testid="image" class="sc-5340b511-1 cMIbKV"><img sizes="(min-width: 1280px) 50vw, (min-width: 1008px) 66vw, 96vw" srcset="https://ichef.bbci.co.uk/news/240/cpsprodpb/c6a2/live/a21b63c0-befe-11f0-ae46-bd64331f0fd4.png.webp 240w,https://ichef.bbci.co.uk/news/320/cpsprodpb/c6a2/live/a21b63c0-befe-11f0-ae46-bd64331f0fd4.png.webp 320w,https://ichef.bbci.co.uk/news/480/cpsprodpb/c6a2/live/a21b63c0-befe-11f0-ae46-bd64331f0fd4.png.webp 480w,https://ichef.bbci.co.uk/news/640/cpsprodpb/c6a2/live/a21b63c0-befe-11f0-ae46-bd64331f0fd4.png.webp 640w,https://ichef.bbci.co.uk/news/800/cpsprodpb/c6a2/live/a21b63c0-befe-11f0-ae46-bd64331f0fd4.png.webp 800w,https://ichef.bbci.co.uk/news/1024/cpsprodpb/c6a2/live/a21b63c0-befe-11f0-ae46-bd64331f0fd4.png.webp 1024w,https://ichef.bbci.co.uk/news/1536/cpsprodpb/c6a2/live/a21b63c0-befe-11f0-ae46-bd64331f0fd4.png.webp 1536w" src="https://ichef.bbci.co.uk/news/480/cpsprodpb/c6a2/live/a21b63c0-befe-11f0-ae46-bd64331f0fd4.png.webp" loading="lazy" alt="Stuart Phillips/BBC People cheering at the football game" class="sc-5340b511-0 hLdNfA"><span class="sc-5340b511-2 jVqbAn">Stuart Phillips/BBC</span></div></div><div data-component="caption-block" class="sc-3b6b161a-0 Qwxkf"></div></figure><div data-component="text-block" class="sc-3b6b161a-0 dPVOKT"><p class="sc-9a00e533-0 eZyhnA">At the Dynamo Stadium in Kyiv, floodlights are on full beam and a game of football is being played - Dynamo Kyiv versus Shakhtar Donetsk, a rough, partisan game, the hardcore fans, known as ultras, wear masks and chant at their opponents.</p><p class="sc-9a00e533-0 eZyhnA">One of the few signs that this is taking place in a city at war is the number of people there: the stadium can seat more than 16,000 people but only 4,300 fans are allowed in, owing to the capacity of the stadium''s bomb shelters. </p><p class="sc-9a00e533-0 eZyhnA">The fans have come from all parts of society – young and old, families and friends. Servicemen and women are there too, earning applause from the crowds, who part to let them pass through.</p></div><div data-testid="ad-unit" data-component="ad-slot" class="sc-1b734f04-0 kNNIux"><div data-testid="dotcom-mid_14" id="dotcom-mid_14" class="dotcom-ad"></div></div><figure><div data-component="image-block" class="sc-3b6b161a-0 gXrNRM"><div data-testid="image" class="sc-5340b511-1 cMIbKV"><img sizes="(min-width: 1280px) 50vw, (min-width: 1008px) 66vw, 96vw" srcset="https://ichef.bbci.co.uk/news/240/cpsprodpb/a8db/live/c882c7d0-bfe7-11f0-8669-5560f5c90fbe.png.webp 240w,https://ichef.bbci.co.uk/news/320/cpsprodpb/a8db/live/c882c7d0-bfe7-11f0-8669-5560f5c90fbe.png.webp 320w,https://ichef.bbci.co.uk/news/480/cpsprodpb/a8db/live/c882c7d0-bfe7-11f0-8669-5560f5c90fbe.png.webp 480w,https://ichef.bbci.co.uk/news/640/cpsprodpb/a8db/live/c882c7d0-bfe7-11f0-8669-5560f5c90fbe.png.webp 640w,https://ichef.bbci.co.uk/news/800/cpsprodpb/a8db/live/c882c7d0-bfe7-11f0-8669-5560f5c90fbe.png.webp 800w,https://ichef.bbci.co.uk/news/1024/cpsprodpb/a8db/live/c882c7d0-bfe7-11f0-8669-5560f5c90fbe.png.webp 1024w,https://ichef.bbci.co.uk/news/1536/cpsprodpb/a8db/live/c882c7d0-bfe7-11f0-8669-5560f5c90fbe.png.webp 1536w" src="https://ichef.bbci.co.uk/news/480/cpsprodpb/a8db/live/c882c7d0-bfe7-11f0-8669-5560f5c90fbe.png.webp" loading="lazy" alt="Stuart Phillips/BBC Rodion" class="sc-5340b511-0 hLdNfA"><span class="sc-5340b511-2 jVqbAn">Stuart Phillips/BBC</span></div></div><div data-component="caption-block" class="sc-3b6b161a-0 Qwxkf"></div></figure><div data-component="text-block" class="sc-3b6b161a-0 dPVOKT"><p class="sc-9a00e533-0 eZyhnA">"It''s really important to continue to live," says Anatoliy Anatolich, the match announcer, a TV and social media host. </p><p class="sc-9a00e533-0 eZyhnA">In his view, coming to the football in itself is an act of defiance.</p><p class="sc-9a00e533-0 eZyhnA">"[It shows] everyone that we are not going to leave our country in this hard period… We''ve got to be here when we win."</p><p class="sc-9a00e533-0 eZyhnA">Five minutes before the end of the match, the chanting suddenly stops. The fans put their hands on their hearts and sing the national anthem.</p><p class="sc-9a00e533-0 eZyhnA">Soon the whole stadium was singing as one; a crowd divided by teams, but united by country.</p><p class="sc-9a00e533-0 eZyhnA"><i id="top-image-credit:-afp/getty-images" class="sc-d16436d-0 iVdNuz">Top image credit: AFP/Getty Images</i></p></div><div data-component="links-block" class="sc-3b6b161a-0 djqsWD"><div class="sc-666b6d83-0 sc-c4fb5674-0 jYmMqa doYqeg"><span data-testid="links-title" class="sc-c4fb5674-2 bBuHEW">More from InDepth</span><div data-testid="links-grid" class="sc-666b6d83-0 sc-c4fb5674-1 gEjRXC jkjVgq"><div data-testid="chester-card" data-indexcard="true" class="sc-225578b-0 ezQaGx"><div data-testid="anchor-inner-wrapper"><a href="https://www.bbc.co.uk/news/articles/cm2vr37yd4no" data-testid="external-anchor" target="_self" class="sc-8a623a54-0 huZCWi"><div data-testid="chester-article" class="sc-cf565bcc-0 kwPVOm"><div class="sc-fa814188-1 iRoJZi"><div class="sc-fa814188-0 hPhBqv"><h2 data-testid="card-headline" class="sc-fa814188-3 iCfgww">How Russia is quietly trying to win over the world beyond the West</h2></div></div></div></a></div></div><div data-testid="chester-card" data-indexcard="true" class="sc-225578b-0 ezQaGx"><div data-testid="anchor-inner-wrapper"><a href="https://www.bbc.co.uk/news/articles/c205jvyg3wjo" data-testid="external-anchor" target="_self" class="sc-8a623a54-0 huZCWi"><div data-testid="chester-article" class="sc-cf565bcc-0 kwPVOm"><div class="sc-fa814188-1 iRoJZi"><div class="sc-fa814188-0 hPhBqv"><h2 data-testid="card-headline" class="sc-fa814188-3 iCfgww">COP30: Trump and many leaders are skipping it, so does the summit still have a point?</h2></div></div></div></a></div></div><div data-testid="chester-card" data-indexcard="true" class="sc-225578b-0 ezQaGx"><div data-testid="anchor-inner-wrapper"><a href="https://www.bbc.co.uk/news/articles/cgeqj1q8gj4o" data-testid="external-anchor" target="_self" class="sc-8a623a54-0 huZCWi"><div data-testid="chester-article" class="sc-cf565bcc-0 kwPVOm"><div class="sc-fa814188-1 iRoJZi"><div class="sc-fa814188-0 hPhBqv"><h2 data-testid="card-headline" class="sc-fa814188-3 iCfgww">The race for the two miles-a-second super weapons that Putin says turn targets to dust</h2></div></div></div></a></div></div></div></div></div><figure><div data-component="image-block" class="sc-3b6b161a-0 GunZh"><div data-testid="image" class="sc-5340b511-1 cMIbKV"><img sizes="(min-width: 1280px) 50vw, (min-width: 1008px) 66vw, 96vw" srcset="https://ichef.bbci.co.uk/news/240/cpsprodpb/5117/live/87b01450-a8eb-11f0-92db-77261a15b9d2.jpg.webp 240w,https://ichef.bbci.co.uk/news/320/cpsprodpb/5117/live/87b01450-a8eb-11f0-92db-77261a15b9d2.jpg.webp 320w,https://ichef.bbci.co.uk/news/480/cpsprodpb/5117/live/87b01450-a8eb-11f0-92db-77261a15b9d2.jpg.webp 480w,https://ichef.bbci.co.uk/news/640/cpsprodpb/5117/live/87b01450-a8eb-11f0-92db-77261a15b9d2.jpg.webp 640w,https://ichef.bbci.co.uk/news/800/cpsprodpb/5117/live/87b01450-a8eb-11f0-92db-77261a15b9d2.jpg.webp 800w,https://ichef.bbci.co.uk/news/1024/cpsprodpb/5117/live/87b01450-a8eb-11f0-92db-77261a15b9d2.jpg.webp 1024w,https://ichef.bbci.co.uk/news/1536/cpsprodpb/5117/live/87b01450-a8eb-11f0-92db-77261a15b9d2.jpg.webp 1536w" src="https://ichef.bbci.co.uk/news/480/cpsprodpb/5117/live/87b01450-a8eb-11f0-92db-77261a15b9d2.jpg.webp" loading="lazy" alt="InDepth notifications banner" class="sc-5340b511-0 hLdNfA"></div></div></figure><div data-component="text-block" class="sc-3b6b161a-0 dPVOKT"><p class="sc-9a00e533-0 eZyhnA"><a target="_self" href="https://www.bbc.co.uk/news/bbcindepth" class="sc-f9178328-0 iCaRzc"><i id="bbc-indepth" class="sc-d16436d-0 iVdNuz">BBC InDepth</i></a><i id="is-the-home-on-the-website-and-app-for-the-best-analysis,-with-fresh-perspectives-that-challenge-assumptions-and-deep-reporting-on-the-biggest-issues-of-the-day.-you-can-now-sign-up-for-notifications-that-will-alert-you-whenever-an-indepth-story-is-published--" class="sc-d16436d-0 iVdNuz"> is the home on the website and app for the best analysis, with fresh perspectives that challenge assumptions and deep reporting on the biggest issues of the day. You can now sign up for notifications that will alert you whenever an InDepth story is published - </i><a target="_self" href="https://www.bbc.co.uk/news/articles/cj6x46j8g5do" class="sc-f9178328-0 iCaRzc"><i id="click-here-to-find-out-how." class="sc-d16436d-0 iVdNuz">click here to find out how.</i></a></p></div><div data-component="tags" class="sc-3b6b161a-0 djqsWD"><div class="sc-6bf80075-0 lllwyY"><div data-testid="anchor-inner-wrapper"><a href="https://www.bbc.com/news/topics/c1vw6q14rzqt" data-testid="internal-link" class="sc-57521d02-0 jsVxCb">War in Ukraine</a></div><div data-testid="anchor-inner-wrapper"><a href="https://www.bbc.com/news/topics/c4vvr0ergrzt" data-testid="internal-link" class="sc-57521d02-0 jsVxCb">Volodymyr Zelensky</a></div><div data-testid="anchor-inner-wrapper"><a href="https://www.bbc.com/news/topics/ce1qrvlegnyt" data-testid="internal-link" class="sc-57521d02-0 jsVxCb">Russia</a></div><div data-testid="anchor-inner-wrapper"><a href="https://www.bbc.com/news/topics/cvenzmgywd4t" data-testid="internal-link" class="sc-57521d02-0 jsVxCb">Vladimir Putin</a></div><div data-testid="anchor-inner-wrapper"><a href="https://www.bbc.com/news/topics/cx1m7zg0gzdt" data-testid="internal-link" class="sc-57521d02-0 jsVxCb">Ukraine</a></div></div></div>', NULL, NULL);
INSERT INTO lost_and_found VALUES(103, 103, 14, 11, 386, 1763020376547, NULL, 1763006913000, 1, 1763020376547, 'en-GB', 'Catherine&#039;s Christmas service to feature stars including Kate Winslet', 'https://www.bbc.com/news/articles/cwy1lg9kgnko?at_medium=RSS&at_campaign=rss', 'https://www.bbc.com/news/articles/cwy1lg9kgnko?at_medium=RSS&at_campaign=rss', NULL, '<div data-component="headline-block" class="sc-3b6b161a-0 hNbOGD"><h1 class="sc-f98b1ad2-0 idLnWK">Catherine''s Christmas service to feature stars including Kate Winslet</h1></div><div data-component="byline-block" class="sc-3b6b161a-0 dPVOKT"><div data-testid="byline-new" class="sc-7bfdb3c2-0 fYJjWP"><div class="sc-7bfdb3c2-1 jqWinX"><time datetime="2025-11-13T04:08:33.886Z" class="sc-7bfdb3c2-2 dQuPjg">4 hours ago</time><div class="sc-7bfdb3c2-3 dVvYwG"></div></div><span data-testid="byline-new-contributors" class="sc-7bfdb3c2-11 ljQVMv"><span class="sc-7bfdb3c2-7 djOqvY">Hafsa Khalil</span></span></div></div><div class="sc-7bfdb3c2-4 haycoC"></div><figure><div data-component="image-block" class="sc-3b6b161a-0 gtLOOD"><div data-testid="hero-image" class="sc-5340b511-1 cMIbKV"><img srcset="https://ichef.bbci.co.uk/news/240/cpsprodpb/5fdb/live/d49695b0-c05f-11f0-8669-5560f5c90fbe.jpg.webp 240w, https://ichef.bbci.co.uk/news/320/cpsprodpb/5fdb/live/d49695b0-c05f-11f0-8669-5560f5c90fbe.jpg.webp 320w, https://ichef.bbci.co.uk/news/480/cpsprodpb/5fdb/live/d49695b0-c05f-11f0-8669-5560f5c90fbe.jpg.webp 480w, https://ichef.bbci.co.uk/news/640/cpsprodpb/5fdb/live/d49695b0-c05f-11f0-8669-5560f5c90fbe.jpg.webp 640w, https://ichef.bbci.co.uk/news/800/cpsprodpb/5fdb/live/d49695b0-c05f-11f0-8669-5560f5c90fbe.jpg.webp 800w, https://ichef.bbci.co.uk/news/1024/cpsprodpb/5fdb/live/d49695b0-c05f-11f0-8669-5560f5c90fbe.jpg.webp 1024w, https://ichef.bbci.co.uk/news/1536/cpsprodpb/5fdb/live/d49695b0-c05f-11f0-8669-5560f5c90fbe.jpg.webp 1536w" src="https://ichef.bbci.co.uk/news/480/cpsprodpb/5fdb/live/d49695b0-c05f-11f0-8669-5560f5c90fbe.jpg.webp" alt="WireImage via Getty Images Kate is smiling and wearing dark green and a matching green hat. She has a green and navy checkered scarf around her neck." class="sc-5340b511-0 hLdNfA" /><span class="sc-5340b511-2 jVqbAn">WireImage via Getty Images</span></div></div><div data-component="caption-block" class="sc-3b6b161a-0 Qwxkf"></div></figure><div data-component="text-block" class="sc-3b6b161a-0 dPVOKT"><p class="sc-9a00e533-0 eZyhnA">The Princess of Wales'' annual Christmas carol service is to take place for the fifth year early next month, with British movie stars Kate Winslet, Chiwetel Ejiofor and Hannah Waddingham delivering readings at the event. </p><p class="sc-9a00e533-0 eZyhnA">The "power of love and togetherness" will be celebrated at the Together at Christmas event led by Catherine, who wants to recognise people across the country who contribute to society.</p><p class="sc-9a00e533-0 eZyhnA">Organisers said the theme was picked because people will be able to celebrate love in all forms in a world that can often feel fragmented and disconnected.</p><p class="sc-9a00e533-0 eZyhnA">The service -  which will be a mixture of traditional and modern elements to include people of all faiths and none - will be held in Westminster Abbey on 5 December.</p></div><div data-testid="ad-unit" data-component="ad-slot" class="sc-1b734f04-0 kNNIux"><div data-testid="dotcom-mid_1" id="dotcom-mid_1" class="dotcom-ad"></div></div><figure><div data-component="image-block" class="sc-3b6b161a-0 gXrNRM"><div data-testid="image" class="sc-5340b511-1 cMIbKV"><img srcset="https://ichef.bbci.co.uk/news/240/cpsprodpb/9616/live/0cea4870-c007-11f0-afbe-d35b6abd7bcd.jpg.webp 240w, https://ichef.bbci.co.uk/news/320/cpsprodpb/9616/live/0cea4870-c007-11f0-afbe-d35b6abd7bcd.jpg.webp 320w, https://ichef.bbci.co.uk/news/480/cpsprodpb/9616/live/0cea4870-c007-11f0-afbe-d35b6abd7bcd.jpg.webp 480w, https://ichef.bbci.co.uk/news/640/cpsprodpb/9616/live/0cea4870-c007-11f0-afbe-d35b6abd7bcd.jpg.webp 640w, https://ichef.bbci.co.uk/news/800/cpsprodpb/9616/live/0cea4870-c007-11f0-afbe-d35b6abd7bcd.jpg.webp 800w, https://ichef.bbci.co.uk/news/1024/cpsprodpb/9616/live/0cea4870-c007-11f0-afbe-d35b6abd7bcd.jpg.webp 1024w, https://ichef.bbci.co.uk/news/1536/cpsprodpb/9616/live/0cea4870-c007-11f0-afbe-d35b6abd7bcd.jpg.webp 1536w" src="https://ichef.bbci.co.uk/news/480/cpsprodpb/9616/live/0cea4870-c007-11f0-afbe-d35b6abd7bcd.jpg.webp" alt="PA Media From left to right, William, George, Charlotte, Louis and Catherine in Westminster Abbey. Males are wearing black suits, white shirts; William a patterned dark red tie and both boys a red tie. Charlotte is wearing a dark red dress coat and Catherine is wearing a red dress coat with a large black bow at the neck. They are all holding lit candles and carol books and are standing. Behind them are people at the other pews." class="sc-5340b511-0 hLdNfA" /><span class="sc-5340b511-2 jVqbAn">PA Media</span></div></div><div data-component="caption-block" class="sc-3b6b161a-0 Qwxkf"></div></figure><figure><div data-component="image-block" class="sc-3b6b161a-0 gXrNRM"><div data-testid="image" class="sc-5340b511-1 cMIbKV"><img srcset="https://ichef.bbci.co.uk/news/240/cpsprodpb/2252/live/df761fd0-c007-11f0-afbe-d35b6abd7bcd.jpg.webp 240w, https://ichef.bbci.co.uk/news/320/cpsprodpb/2252/live/df761fd0-c007-11f0-afbe-d35b6abd7bcd.jpg.webp 320w, https://ichef.bbci.co.uk/news/480/cpsprodpb/2252/live/df761fd0-c007-11f0-afbe-d35b6abd7bcd.jpg.webp 480w, https://ichef.bbci.co.uk/news/640/cpsprodpb/2252/live/df761fd0-c007-11f0-afbe-d35b6abd7bcd.jpg.webp 640w, https://ichef.bbci.co.uk/news/800/cpsprodpb/2252/live/df761fd0-c007-11f0-afbe-d35b6abd7bcd.jpg.webp 800w, https://ichef.bbci.co.uk/news/1024/cpsprodpb/2252/live/df761fd0-c007-11f0-afbe-d35b6abd7bcd.jpg.webp 1024w, https://ichef.bbci.co.uk/news/1536/cpsprodpb/2252/live/df761fd0-c007-11f0-afbe-d35b6abd7bcd.jpg.webp 1536w" src="https://ichef.bbci.co.uk/news/480/cpsprodpb/2252/live/df761fd0-c007-11f0-afbe-d35b6abd7bcd.jpg.webp" alt="PA Media left to right: Catherine, Gregory Porter, Olivia Dean, and Paloma Faith." class="sc-5340b511-0 hLdNfA" /><span class="sc-5340b511-2 jVqbAn">PA Media</span></div></div><div data-component="caption-block" class="sc-3b6b161a-0 Qwxkf"></div></figure><div data-testid="ad-unit" data-component="ad-slot" class="sc-1b734f04-0 kNNIux"><div data-testid="dotcom-mid_2" id="dotcom-mid_2" class="dotcom-ad"></div></div><div data-component="text-block" class="sc-3b6b161a-0 dPVOKT"><p class="sc-9a00e533-0 eZyhnA">Last Christmas, Catherine similarly focused on love, and the importance of giving and receiving empathy, following her cancer diagnosis earlier in the year. </p><p class="sc-9a00e533-0 eZyhnA">She <a target="_self" href="https://www.bbc.co.uk/news/articles/c1d7wk5d4ylo" class="sc-f9178328-0 iCaRzc">spoke of her relief</a> at completing her course of chemotherapy in September 2024, and revealed this year in January that she is <a target="_self" href="https://www.bbc.co.uk/news/articles/cx2m8g2vp41o" class="sc-f9178328-0 iCaRzc">in remission from cancer</a>.</p><p class="sc-9a00e533-0 eZyhnA">In 2021, <a target="_self" href="https://www.bbc.co.uk/news/uk-59786990" class="sc-f9178328-0 iCaRzc">she surprised guests with her piano-playing skills</a> alongside musician Tom Walker in a clip shown at the event, which was staged for people who supported their communities during the Covid pandemic.</p><p class="sc-9a00e533-0 eZyhnA">Guests at the event will be people who have been nominated by lord-lieutenants across the UK and charities linked to the royal family. Among them will also be guests who have been invited after having shown love and kindness this year.</p><p class="sc-9a00e533-0 eZyhnA">As well as the readings by the British acting stars, carols will be sung by the Westminster Abbey choir, alongside musical performances.</p><p class="sc-9a00e533-0 eZyhnA">A festive display based on the importance of nature in our lives, created by horticulturist Jamie Butterworth, will feature at the event. </p><p class="sc-9a00e533-0 eZyhnA">The Royal Horticultural Society is also set to donate wreaths made by their ambassadors and schoolchildren.</p><p class="sc-9a00e533-0 eZyhnA">Across the UK, 15 community carol services on the same theme of love and togetherness will also take place, including in a community farm in Gwent and an arts centre in Newbury.</p><p class="sc-9a00e533-0 eZyhnA">The Westminster Abbey service will air on ITV1 and ITVX on Christmas Eve and again on Christmas Day.</p></div><div data-component="links-block" class="sc-3b6b161a-0 djqsWD"><div class="sc-666b6d83-0 sc-c4fb5674-0 jYmMqa kGPvxx"><div data-testid="links-grid" class="sc-666b6d83-0 sc-c4fb5674-1 gEjRXC jkjVgq"><div data-testid="chester-card" data-indexcard="true" class="sc-225578b-0 ezQaGx"><div data-testid="anchor-inner-wrapper"><a href="https://www.bbc.co.uk/news/articles/c8xp00rrerdo" data-testid="external-anchor" target="_self" class="sc-8a623a54-0 huZCWi"><div data-testid="chester-article" class="sc-cf565bcc-0 kwPVOm"><div class="sc-fa814188-1 iRoJZi"><div class="sc-fa814188-0 hPhBqv"><h2 data-testid="card-headline" class="sc-fa814188-3 iCfgww">Kate sends emotional Christmas message of ''love, not fear''</h2></div></div></div></a></div></div><div data-testid="chester-card" data-indexcard="true" class="sc-225578b-0 ezQaGx"><div data-testid="anchor-inner-wrapper"><a href="https://www.bbc.co.uk/news/articles/cjdnl22pvnvo" data-testid="external-anchor" target="_self" class="sc-8a623a54-0 huZCWi"><div data-testid="chester-article" class="sc-cf565bcc-0 kwPVOm"><div class="sc-fa814188-1 iRoJZi"><div class="sc-fa814188-0 hPhBqv"><h2 data-testid="card-headline" class="sc-fa814188-3 iCfgww">Kate joined by children as she hosts carol service</h2></div></div></div></a></div></div></div></div></div><div data-component="tags" class="sc-3b6b161a-0 djqsWD"><div class="sc-6bf80075-0 lllwyY"><div data-testid="anchor-inner-wrapper"><a href="https://www.bbc.com/news/topics/c630drz91jyt" data-testid="internal-link" class="sc-57521d02-0 jsVxCb">Christmas</a></div><div data-testid="anchor-inner-wrapper"><a href="https://www.bbc.com/news/topics/c77jz3md4qwt" data-testid="internal-link" class="sc-57521d02-0 jsVxCb">UK Royal Family</a></div><div data-testid="anchor-inner-wrapper"><a href="https://www.bbc.com/news/topics/ck6z09186yet" data-testid="internal-link" class="sc-57521d02-0 jsVxCb">Westminster Abbey</a></div><div data-testid="anchor-inner-wrapper"><a href="https://www.bbc.com/news/topics/cz4pr2gd414t" data-testid="internal-link" class="sc-57521d02-0 jsVxCb">Catherine, Princess of Wales</a></div></div></div>', NULL, '<div data-component="headline-block" class="sc-3b6b161a-0 hNbOGD"><h1 class="sc-f98b1ad2-0 idLnWK">Catherine''s Christmas service to feature stars including Kate Winslet</h1></div><div data-component="byline-block" class="sc-3b6b161a-0 dPVOKT"><div data-testid="byline-new" class="sc-7bfdb3c2-0 fYJjWP"><div class="sc-7bfdb3c2-1 jqWinX"><time datetime="2025-11-13T04:08:33.886Z" class="sc-7bfdb3c2-2 dQuPjg">4 hours ago</time><div class="sc-7bfdb3c2-3 dVvYwG"></div></div><span data-testid="byline-new-contributors" class="sc-7bfdb3c2-11 ljQVMv"><div data-testid="byline-new-contributors-contributor-0" class="sc-7bfdb3c2-5 xGeVU"><div><span class="sc-7bfdb3c2-7 djOqvY">Hafsa Khalil</span></div></div></span><div class="sc-7bfdb3c2-4 haycoC"></div></div></div><figure><div data-component="image-block" class="sc-3b6b161a-0 gtLOOD"><div data-testid="hero-image" class="sc-5340b511-1 cMIbKV"><img sizes="(min-width: 1280px) 50vw, (min-width: 1008px) 66vw, 96vw" srcset="https://ichef.bbci.co.uk/news/240/cpsprodpb/5fdb/live/d49695b0-c05f-11f0-8669-5560f5c90fbe.jpg.webp 240w,https://ichef.bbci.co.uk/news/320/cpsprodpb/5fdb/live/d49695b0-c05f-11f0-8669-5560f5c90fbe.jpg.webp 320w,https://ichef.bbci.co.uk/news/480/cpsprodpb/5fdb/live/d49695b0-c05f-11f0-8669-5560f5c90fbe.jpg.webp 480w